INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01631', '분원백자자료관', '관광지', 37.49625742, 127.3034492, '경기도 광주시 남종면 산수로 1642-1', '조선시대 관영사기의 변천과 도자기역사의 발자취 감상', '경기');
