INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01634', '경안천습지생태공원', '관광지', 37.45920014, 127.3051169, '경기도 광주시 퇴촌면 산수로 1159', '다양한 수생식물 등 조류관찰과 자연학습의 장', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01635', '팔당물안개공원', '관광지', 37.50956344, 127.3174613, '경기도 광주시 남종면 산수로 1897', '시민의 숲, 희망의 숲, 코스모스길, 자전거길이 잘 조성된 공원', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01636', '중대물빛공원', '관광지', 37.40272258, 127.218054, '경기도 광주시 순암로 307', '장미터널, 연꽃로드, 아치목교 등이 있는 수변공원', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01637', '간월도playground', '관광지', 36.60625, 126.41775, '충청남도 서산시 부석면 간월도1길 119-29', '간월도 스카이워크 및 간월암', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01638', '장도청해진유적지', '관광지', 34.36012506, 126.7369503, '전라남도 완도군 완도읍 장좌리 787', '해상왕 장보고 대사가 828년 청해진을 설치하고 중구과 신라, 일본을 잇는 삼각 무역을 펼쳤던 우리나라 최초의 무역전진기지이자 군사 요충지이다. 사적 제308호이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01639', '장보고기념관', '관광지', 34.355097, 126.730164, '전라남도 완도군 완도읍 청해진로 1455', '장보고대사의 도전정신과 기상을 엿볼 수 있는 다양한 자료와 유물이 전시되어 있다. 특히 전시실은 보고 듣고 만지는 체험형 입체 관람 시스템을 갖추고 있어 흥미로운 관람이 가능하다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01640', '해양생태전시관', '관광지', 34.351532, 126.731489, '전라남도 완도군 완도읍 청해진로 1459', '기존 장보고기념관, 장도 등 청해진 유적지의 기존 문화·관광 시설과 연계하여 방문하는 관광객과 주민들에게 볼거리, 체험거리 제공 및 해양생태에 대한 교육의 장을 마련하고 해양치유 산업의 중요성을 제공하는데 그 의의가 있다. 1층과 2층으로 나뉘어 각 실마다 저마다의 주제를 가지고 완도의 역사, 생태계 현황, 다양한 해양 체험활동 등을 학습하고 경험할 수 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01641', '완도수목원', '관광지', 34.36065258, 126.6635321, '전라남도 완도군 군외면 초평1길 156', '국내 유일의 난대수목원으로 3,801종의 수목유전자원을 보유하고 있다. 난대성 목,초본 등 희귀식물 770여종이 자생하고 있는데 아열대,온대 교차지의 다양한 식물이 분포하여 학술적 가치가 높은 수목원이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01642', '청해포구촬영장', '관광지', 34.32293555, 126.6705189, '전라남도 완도군 완도읍 청해진서로 1161-8', '장보고대사를 소재로 한 최인호의 역사소설 (해신)을 원작으로 한 KBS 특별 드라마 (해신)의 촬영부대이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01643', '어촌민속전시관', '관광지', 34.307331, 126.688559, '전라남도 완도군 완도읍 화흥포길 149', '어촌의 생활사, 어획방법, 수산양식의 실태, 선박의 발달사 등 사진자료와 함께 전시하고있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01644', '슬로시티청산도', '관광지', 34.17179242, 126.8621742, '전라남도 완도군 청산면 청산로 132', '2007년 아시아 최초 슬로시티로 지정되었으며 영화 (서편제)와 드라마 (봄의왈츠)가 촬영된 곳으로 푸른바다, 푸른산, 구들장논, 돌담길 등 느림의 풍경이 가득한 곳이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01645', '보길윤선도원림', '관광지', 34.16247899, 126.5559442, '전라남도 완도군 보길면 부황길 57', '고산 윤선도가 직접 조성한 곳으로 특히, 세연정은 조선시대 대표적인 별서정원으로 우리나라 3대 정원중 하나다. 조선시대 가사문학의 백미 (어부사시사)가 이곳에서 창작되었다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01646', '모악산도립공원', '관광지', 35.72946608, 127.1098589, '전라북도 완주군 구이면 모악산길 91', '금산사를 안고있는 특히 봄의 풍경이 아름답기로 유명한 산', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01647', '고산자연휴양림', '관광지', 35.96224205, 127.2328719, '전라북도 완주군 고산면 고산휴양림로 246', '숲에서 산림욕을 즐길 수 있는 사계절 가족휴양지', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01648', '상관 공기마을 편백숲', '관광지', 35.737491, 127.2023884, '전라북도 완주군 상관면 죽림편백길 191-24', '10만그루의 빽빽한 편백나무가 우거진 숲', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01649', '대아수목원&대아호', '관광지', 35.97623865, 127.3003851, '전라북도 완주군 동상면 대아수목로 94-34', '대아저수지의 맑은 물과 수려한 자연경광 속에 자리하고 있는 곳', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01650', '비비정', '관광지', 35.90154901, 127.071693, '전라북도 완주군 삼례읍 비비정길 96-9', '만경강의 아름다운 풍경을 한눈에 조망할 수 있는 곳', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01651', '백제문화관광단지', '관광지', 36.30386704, 126.9007732, '충청남도 부여군 규암면 백제문로 400', '고유의 교육적 가치 제고 및 관광, 지역경제 활성화를 위한 슈요자 중심의 체류형 종합 관광단지', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01652', '대광해수욕장', '관광지', 35.10291276, 126.0725117, '전라남도 신안군 임자면 대광해수욕장길 179', '넓은 백사장과 주변 섬들의 경관 등 천혜의 자연환경을 지님', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01653', '심우장', '관광지', 37.5936268, 126.9916662, '서울특별시 성북구 성북로29길 24', '만해 한용운의 일제강점기 머물던 집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01654', '한국가구박물관', '관광지', 37.60037831, 126.9934492, '서울특별시 성북구 대사관로121', '소백산 자연환경을 배경으로 한 천년고찰 부석사를 직접 참여하고 머무르는 다양한 체험 및 관광활동 제공', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01655', '부석사playground', '관광지', 36.99435088, 128.6797054, '경상북도 영주시 부석면 부석사로 298', '해발 522.6m의 설산은 산 정상의 햐얀 규암이 멀리서 바라보면 눈처럼 하얗게 보여 설산(雪山)이라 불리어 지고 괘일봉에 걸린 눈부신 황혼은 곡성 8경에 속한다. 설옥리 목동마을을 지나 임도를 따라 10여분 정도 올라가면 설산 수도암이 품안에 아담하게 들어 앉아 있다. 설산 수도암은 신라시대 설두화상이 수도한 곳으로 전해지며 그 당시 건물은 없었고 1928년 임공덕보살이 창건한 건물이 지금까지 전해오고 있는 작은 암자이다. 수도암 앞 마당에는 지방문화재 자료 제84호로 지정된 잣나무가 있는데 잣나무는 수령이 200년 정도 된다고 한다. 설산을 오르면 수도암 뒷편 산길을 따라 20분 오르다 보면 커다란 두개의 바위가 수문장처럼 좌우로 나란히 서 있고 그 사이를 약간 내려가면 헬기장과 야묏동이 나타난다. 등산코스로 잘 알려진 설산은 헬기장에서 조금 올라 설산 정상에 이르면 책을 층층히 쌓아 놓은 것 같은 맞은편의 괘일산 기암괴석이 웅장하게 한눈에 들어오고 옥과방면의 올망졸망한 산들이 마치 군대에서 일열로 도열해 있는 듯하며 담야쪽을 바라다보면 날씨가 좋을 때는 멀리 광주 무등산까지 보이며 전북 순창군 풍산면 전체가 내려다 보이는 설산은 사시사철 소풍객과 등산객의 발길이 끊이지 않고 있다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01656', '설산', '관광지', 35.29950593, 127.1025224, '전라남도 곡성군 옥과면 설옥리 산 256-1', '곡성 제1고봉···섬진강과 보성강 가르는 맹주 통명산. 지금은 곡성의 제1명산을 동악산으로 꼽는 데에 이견이 없지만 동악산은 곡성 제1고봉이 아니다. 곡성의 제1고봉은 통명산이다. 물론 높다고 명산이 되는 것은 아니다. 동악산은 곡성의 배후산이자 도림사계곡은 삼남 제일의 암반계류 라 일컬어질 정도로 유명하고 특히 이곳 봄 벚꽃은 상춘객들에게 큰 기쁨을 주고 있다. 통명산은 지리상으로도 중요한 위치를 점하고 있다. 통명산을 주산으로 하는 통명산~주부산~곤명산 산괴가 바로 섬진강과 보성강을 가르고 있기 때문이다. 통명산 정상에 서면 곡성의 산악이 크게 동악산 산괴, 통명산 산괴, 봉두산 산괴, 그리고 동쪽으로 섬진강 건너 지리산에서 뻗어내린 천마산 산줄기와 서쪽으로 화순군 경계에 모후산 북쪽 줄기인 차일봉~한동산 산줄기로 나뉘는 것을 가늠할 수 있다. 곡성의 지세를 보려면 당연히 통명산에 올라봐야 하는 것이다. 곡성이 배출한 명장 중 신숭겸(申崇兼)과 마천목(馬天牧)은 각각 고려 초와 조선 초에 주군이 나라의 기초를 다지는 데 크게 기여한 장군들로 모두 통명산자락에서 태어났다. 당연히 두 장군에 대한 전설적인 이야기들이 산자락에 널리 있기도 하다. 특히 신숭겸장군의 사당인 덕양서원(오곡면 덕산리)과 마천목 장군의 묘와 사당(석곡면)이 바로 통명산 자락에 있다. 마 장군은 조선 초 제2차 왕자의 난 때 방간이 박포와 같이 난을 일으키자 박포를 잡아베어 난을 평정했다. 위태로운 사직을 구한 공로로 그는 상장군이 되어 나주목사, 전라병사, 병조판서를 거쳐 판돈영부중추원사까지 지냈다.(신숭겸 장군 이야기는 봉두산과 참조). 통명산에는 명당이 많다는 소문이 자자하다. 또한 지명이 풍수적 해석으로 붙은 곳도 여럿 있다. 통명산 남쪽, 죽곡면 봉정리의 이름도 그런 예 중의 하나다. 주부산에서 성주봉을 거쳐 짧은 지능선이 장군봉과 천덕산 사이를 비집고 내려선 그 아래에 있는 이 마을은 포란비봉(抱卵飛峰) 형국으로 장자등을 봉황의 몸통으로, 천덕산과 통명산을 봉황의 날개로, 주부', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01657', '통명산', '관광지', 35.20404024, 127.2592454, '전라남도 곡성군 삼기면 금계리 산 137-1', '조태일 시인(1941~1999년)은 곡성 태안사에서 대처승의 아들로 태어났으며, 1964년 경향신문 신춘문예에 ‘아침선박’의 당선으로 문단에 등단하였다.이후 1969년 시전문지 ‘시인’을 창간하였고, ‘식칼론’을 비롯하여 여덟권의 시집을 간행하였다.시문학기념관과 시집전시관은 문단에 길이 남을 민족시인 조태일의 문학세계를 기리고, 예비 문학도들의 창작 공간 마련을 위하여 2003년도에 건립 되었으며, 태안사를 찾는 관광객은 물론 전국의 많은 문학인들이 이곳을 찾고 있다.「조태일 시문학 기념관」은 조태일 시인의 유품과 작품, 시인을 기리는 문학 작품 등 2,000여점이 전시되어 있으며, 「시집전시관」은 우리나라 최초의 근대시집인 최남선의 ‘백팔번뇌’, 최초의 번역시집 ‘오뇌의 무도’ 등 희귀본에서 최근 작품까지 3,000여점의 시집이 전시되어 있다.소박미가 넘치는 시문학관 건물은 시인 이윤하(건축사사무소 노둣돌 대표)의 설계로 지어져, 제1회 대한민국 목조건축 대전에서 본상을 수상했다.어쩌면, 조태일 시문학관 그 자체가 조태일을 표현하는 한편의 시다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01658', '화진포 생태박물관', '관광지', 38.47218738, 128.4436214, '강원특별자치도 고성군 거진읍 화진포길 256', '지상 3층 규모로 층별 3개 전시관에서 화진포호와 관련한 생태계를 관찰, 학습할 수 있는 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01659', '송지호 관망타워', '관광지', 38.33623615, 128.5175989, '강원특별자치도 고성군 죽왕면 동해대로 6021', '5층 규모의 독특한 관망타워 형태로 송지호에 떼지어 이리저리 날아드는 철새들의 군무가 한눈에 내려다보이는 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01660', '어답산playground', '관광지', 37.59380861, 128.0575207, '강원특별자치도 횡성군 갑천면 어답산로 516', '왕의 발길만을 허락한 오지의 선경으로 임금이 친히 밟아본 산이라는 뜻의 어답산(御踏山)은 신라 박혁거세가 태기산의 태기왕을 뒤쫓다가 이 산에 들렀다 해서 붙여진 이름. 때묻지 않은 오지의 절경 속에 자연의 옛 모습 그대로를 고스란히 담아내는 어답산은 갑천면 삼거리저수지 동북쪽으로 병풍을 두른 듯 솟아 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01661', '유현문화playground', '관광지', 37.52903211, 127.8186829, '강원특별자치도 횡성군 서원면 경강로유현1길 30', '풍수원성당은 한국인 신부가 지은 최초의 성당이자 한국에서 네 번째로 지어진 유서깊은 성당으로서 1982년 지방문화재 제69호로 지정됐다. 횡성의 유명한 playground 중 하나로 풍수원 성당과 연계해 playground를 개발하여 방문하는 이들에게 많은 볼거리(유물전시관+산책로+성체현양대회 등)를 제공하고 있다', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01662', '도장포어촌체험마을', '관광지', 34.743449, 128.662475, '경상남도 거제시 남부면 도장포1길 76', '도장포 마을 인근에는 신선대와 바람의 언덕이 있다. 아름다운 풍경으로 새롭게 각광받고 있는 playground로 연인들에게 인기 만점이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01663', '쌍근어촌체험마을', '관광지', 34.762399, 128.589438, '경상남도 거제시 남부면 남부해안로 1094', '남부면의 왕조산 자락에 자리잡고 있으며，바닷가의 시원한 바람을 느낄 수 있는 전형적인 어촌마을이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01664', '씨라인', '관광지', 34.91111602, 128.7102346, '경상남도 거제시 덕포5길 32-3', '덕포해수욕장의 맑고 푸른 바다 위를 ’한마리 새처럼 자유롭고 짜릿하게 활강하면서 즐기는 체험시설’을 의미한다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01665', '오션어드벤처', '관광지', 34.843791, 128.702943, '경상남도 거제시 일운면 거제대로 2660', '소노캄 거제 내에 위치한 종합 유원시설로 여름철 물놀이를 즐길 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01666', '옥포대첩기념공원', '관광지', 34.902196, 128.714059, '경상남도 거제시 팔랑포2길 87', '임진왜란 발발 이후 충무공 이순신장군이 첫 승전한 옥포해전을 기념하고 충무공정신을 후세에 길이 계승하기 위하여 조성한 기념공원이다', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01667', '조선해양문화관', '관광지', 34.833694, 128.701885, '경상남도 거제시 일운면 지세포해안로 41', '어촌에 전해 내려오는 전통문화 및 어업변천사 등 보전 전시하여 청소년 교육의 장과 도시민의 휴식공간으로 활용', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01668', '지심도', '관광지', 34.81531906, 128.6750514, '경상남도 거제시 일운면 지심도길 56-12', '지심도 섬 전체가 거의 동백나무로 뒤덮여 있는 섬으로 장승포항에서 5km 쯤 떨어져 있다. 지심도 일주도로인 오솔길을 따라 걸으면 2~3시간이면 전부 감상 할 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01669', '칠천량해전공원', '관광지', 34.977629, 128.628247, '경상남도 거제시 하청면 칠천로 265-39', '임진왜란 당시 조선 수군의 최대 패전으로 기록된 칠천량 해전의 의미를 되새기는 기념공원이다', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01670', '철암탄광역사촌', '관광지', 37.11436554, 129.0372165, '강원특별자치도 태백시 동태백로 406', '1960년대의 한국을 보여줌으로써, 아련한 향수를 불러일으키는 곳. 바로 철암 탄광역사 촌이다. 현재의 문명은 전혀 느낄 길이 없이, 오롯이 60년대의 정서를 그대로 살린 역사 마을이라 할 수 있으며, 기념비에서도 옛사람들의 정신을 살펴볼 수 있다. 내용인즉슨, 「남겨야 하나, 부수어야 하나 논쟁하는 사이 한국 근현대사의 유구들이 무수히 사라져갔다.「인데, 이미 많이 사라져버린 것들에 대하여 다시금 생각할 수 있도록 하곤 한다. 탄광 지역 생활사의 흔적을 고스란히 느낄 수 있는 곳으로 체험여행으로 좋다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01671', '석탄박물관', '관광지', 37.11857739, 128.9505662, '강원특별자치도 태백시 천제단길 195', '석탄은 우리나라의 유일한 부존 에너지 자원으로서 생활연료 공급과 기간산업의 중추적인 역할로 국가 경제발전에 크게 기여해 왔으나 물질문명의 발달과 청정에너지 사용 증대로 그 수요가 급격히 줄어들고 있어 그간의 석탄산업 변천사와 석탄의 역사적 사실들을 한곳에 모아 귀중한 사료가 되도록 하고,후세들에게 열악한 작업환경 속에서도 산업역군으로서 석탄생산에 종사한 광산근로자들의 업적을 알리고 석탄산업 전반에 대하여 직접 체험할 수 있는 학습장으로 활용하여 석탄에 대한 기억을 되새기고자 함.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01672', '태백고생대자연사박물관', '관광지', 37.0948994, 129.0396319, '강원특별자치도 태백시 태백로 2249', '고생대 자연환경과 그 곳에 살았던 생물역사를 추적할 수 있는 다양한 화석 및 퇴적구조를 구문소지역 일대에서 체험학습을 겸한 교육효과 향상과 학자들의 자연사 연구에 기여하고자 고생대자연사박물관을 건립하게 되었다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01673', '후곡약수터', '관광지', 38.16733552, 128.0573744, '강원특별자치도 양구군 동면 약수터길 90-1', '두개의 샘이 나란히 있으며 철분성분으로 바닥이 붉게 물들어있다. 위장에 좋은 탄산이온, 규산이온, 불소성분이 많이 함우된 양질의 광천수로 주변의 수려한 경관과 함께 관광 휴양지로 주목 받고 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01674', '완도타워', '관광지', 34.31443839, 126.763267, '전라남도 완도군 완도읍 장보고대로 330', '완도타워는 첨탑까지 76m이며 지상2층과 전망층으로 구성되어 있다. 다도해의 아름다운 풍경을 조망할 수 잇으며 완도타워 외부에는 경관조명이 설치되어 있어 야간에는 환상적인 야경과 레이저쇼를 감상할 수 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01675', '화진포역사안보전시관', '관광지', 38.47250515, 128.4430602, '강원특별자치도 고성군 거진읍 화진포길 280', '화진포의 성, 이승만대통령 화진포 기념관, 이기붕부통령별장으로 이루어진 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01676', '화진포해양박물관', '관광지', 38.481345, 128.435682, '강원특별자치도 고성군 현내면 화진포길 412', '세계적으로 희귀한 각종 조개류, 갑각류, 박제 등 1,500여 종 40,000여 점을 전시한 패류박물관과 수중생물 125종 3,000여 마리를 보여주는 어류전시관으로 구성', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01677', '윤동주 유고 보존 정병욱 가옥', '관광지', 34.97075423, 127.759122, '전라남도 광양시 진월면 망덕길 249', '국가등록문화재 제341호', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01678', '느랭이골자연리조트', '숙박', 35.06003247, 127.7114041, '전라남도 광양시 토끼재길 119-32', '편백숲 삼림욕장, 글램핑장, 별빛축제', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01679', '구봉산전망대', '관광지', 34.93646837, 127.6427008, '전라남도 광양시 구봉산전망대길 155', '해발 473m 구봉산, 9.4m 봉수대, 광양만야경', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01680', '광양항해양공원', '관광지', 34.92127751, 127.6939636, '전라남도 광양시 중동 1894', '공연장, 포토존, 산책로', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01681', '해오름육교', '관광지', 34.93442662, 127.7061606, '전라남도 광양시 마동 1125', '중마동과 금호동을 연결하는 이순신 해변관광 테마거리 랜드마크 육교 (L=155.2m)', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01682', '배알도수변공원', '관광지', 34.959931, 127.7601849, '전라남도 광양시 태인동 1632-13', '가족단위 야영·캠핑장, 해변 데크산책로', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01683', '동악산', '쇼핑', 35.26726372, 127.2575047, '전라남도 곡성군 곡성읍 도림로 175', '삼남제일 암반계류 청류동 계곡 풍치 일품인 동악산 (위치 : 곡성읍~입면, 높이 : 736.8m)우선 動樂山을 동락산 이라 읽지 않고, 동악산 이라 읽는 까닭부터 밝혀야 이 산을 이해하는데 도움이 되겠다. 대개 樂 은 뒤에 딸려 나올 때 락으로 읽힌다. 도락산(道樂山)이니 진락산(眞樂山)이니 하는 것이 그런 경우인데, 이 경우는 즐거울 락의 경우다. 그러나 동악산의 경우에는 풍류 악으로 읽어야 한다. 천상의 노래, 즉 음악이 울린다(동한다)는 전설에서 비롯되기 때문이다. 유래는 이렇다. 이 산의 개산조인 원효대사가 성출봉(聖出峰 형제봉 동봉으로 동악산 최고봉) 아래에 길상암을 짓고 원효골(청류동 남쪽 골짜기)에서 도를 베풀고 있는데 하루는 꿈에 성출봉과 16아라한이 그를 굽어보는지라 깨어나 즉시 성출봉에 올라가 보았더니 1척 남짓한 아라한 석상들이 솟아났다는 것이다.원효가 열일곱 차례나 성출봉을 오르내리면서 아라한 석상들을 길상암에 모셔 놓으니 육시(六時) - 불교에서 하루를 여섯으로 나눈 염불독경의 시각으로 신조, 일중, 일몰, 초야, 중야, 후야- 만 되면 천상에서 음악이 들려 온 산에 퍼졌다 한다. 도림사 응진전에 봉안된 아라한상들이 당시의 것이라 전해지고 있으나 신빙성은 없다.마을 주민들은 곡성 마을에서 장원급제자가 탄생하게 되면 이 산에서 노래가 울려 펴졌다고도 한다. 남원 실상사 약사전의 약사여래상처럼 나라에 불길한 징후가 나타나면 땀을 흘리는 흉조를 나타내는 불상이 있는가 하면 동악산처럼 길조를 알리는 산도 있기 마련이다. 곡성의 진산인 동악산은 크게 두 산덩어리가 남북으로 놓여 있다. 각 산덩어리에는 비슷한 높이의 정상이 있는데 이 두 산덩어리를 가르는 것이 배넘이재이고, 남봉(형제봉·동봉과 서봉으로 형성돼 북봉에 동악산, 남봉에 형제봉 이라 표기해 놓고 있지만 최고봉은 형제봉이 된다. 산이름의 유래가 성출봉(형제봉 동봉)에서 유래됐다는 것과 주요 등산로가 형제봉을 중심으로 더 잘 나 있다는 점은 형제봉이 동악산의 주봉임을 뒷받침해 주고 있다.이', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01684', '봉두산', '쇼핑', 35.13195828, 127.3863807, '전라남도 곡성군 죽곡면 태안로 622-215', '천년사찰 구산선문 태안사 품은 명산.지형도에는 봉두산이라 표기돼 있지만, 이 산 안에 깃든 태안사 일주문 현액에는 桐裏山(동리산) 泰安寺(태안사) 라 되어 있다. 산이름이 언제 바뀌었는지는 몰라도 두 이름에 연관이 전혀 없는 것은 아니다. 봉황이 서식하는 나무가 오동나무이고 태안사가 자리잡은 곳을 둘러싼 주변 산세가 오동나무 줄기 속처럼 아늑해서 동리산이라 불렀으며 둘러싼 주변 산세의 최고점을 봉황의 머리 즉 봉두산이라 불렀을 가능성이 없지 않다. 봉두산 주변에는 곡성 특유의 내륙산지를 이루고 있어 정상에 올라서면 순천쪽 황학리의 작은 들판을 제외하고 주변 조망이 온통 산뿐이다. 남서쪽으로 삼산과 희야산 능선 넘어로 모후산이 오똑하고 북서쪽으로는 통명산 넘어 무등산까지 시야가 트인다. 동쪽으로는 둥주리봉과 자라봉, 그리고 지리산이 장막을 치고 있다. 이러한 내륙산지 조망이 산행의 맛으로는 제일이지만 봉두산은 태안사 여행에 초점을 맞추어도 좋을 산이다. 곡성~구례 간 17번 국도 상 압록(보성강이 섬진강에 합류하는 곳)에서 18번 국도쪽(서쪽)으로 방향을 틀면 마치 히말라야의 한 거대한 협곡에 들어선 듯한 기분이 들고 약 4km정도 강변 도로를 따라 산모퉁이를 돌아들면 태안사로 드는 다리가 나온다. 이 다리를 건너 약 5km 가면 태안사 입구에 닿는데, 강변을 따라 난 도로에 차량통행도 뜸해 드라이브코스로도 일품이다. 장승 한 쌍과 거대한 느티나무가 서 있는 입구서부터 다시 협곡을 비집고 낸 비포장길을 따라 들어서면 자유교 넘어 주차장이 마련돼 있다. 여기에 차를 놓고 정심교, 반야교, 해탈교를 건너 능파각에 이르는 길은 호젓하기 그지없고, 봄이면 벚꽃이 터널을 이룬다. 능파각은 계곡에 걸쳐 지은 고색창연한 다리겸 정자다. 경찰충혼탑이 나오면 태안사는 바로 그 위 넓은 터에 자리잡고 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01685', '노루생태관찰원', '관광지', 33.4443253, 126.6266934, '제주특별자치도 제주시 명림로 520(봉개동)', '100여 마리의 노루를 관찰할 수 있고, 자연학습과 생태체험, 오름산행을 즐길 수 있는 열린 시민의 공간입니다', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01686', '제주별빛누리공원', '관광지', 33.4445529, 126.5491863, '제주특별자치도 제주시 선돌목동길 60(오등동)', '천문우주과학분야에 대한 호기심을 해결 할 수 있는 문화공간', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01687', '팔봉산playground', '관광지', 37.703098, 127.695183, '강원특별자치도 홍천군 서면 한치골길 1124', '휴양과 레저, 골프 및 스키 등 국내 최대규모의 관광휴양단지', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01688', '소노벨비발디파크', '관광지', 37.65233706, 127.6873348, '강원특별자치도 홍천군 서면 한치골길 262', '우리나라에서 가장 북쪽에 위차한 전망대로, 천혜의 절경이라 할 금강산과 동해바다의 비경을 감상할수 있으며, 통일관, 통일전망타워 등 기타 시설을 관람할 수 있는 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01689', '통일전망대', '관광지', 38.51438609, 128.416703, '강원특별자치도 고성군 현내면 금강산로 481', '거제의 역사와 자료를 수집，정리，연구전시하고 있는 비영리 법인인 거제 문화재단의 사업기관', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01690', '거제박물관', '관광지', 34.894071, 128.686203, '경상남도 거제시 거제대로 3791(옥포동)', '지역실정에 맞는 농업기술과 지역소득작물을 연구개발 보급하여 농업인의 소득을 높이고，도시민에게는 농업 현장체험과 사계절 꽃 및 난지식물을 만날 수 있는 농업테마공원', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01691', '거제시농업개발원', '관광지', 34.856464, 128.579187, '경상남도 거제시 거제면 거제남서로 3577', '요트 산업의 활성화와 해양레저 스포츠 인구의 저변 확대는 물론 요트，윈드서핑을 비롯한 해양레저 스포츠의 철저한 교육 등 요트인구 저변 확대', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01692', '거제자연휴양림', '관광지', 34.785699, 128.625943, '경상남도 거제시 동부면 거제중앙로 325', '동부면 구천리 노자산 해발 565M 위치에 120ha 면적에 설치되었으며，산 정상에 전망대가 설치되어 거제전역과 한려해상국립공원의 크고 작은 섬들과 기암절병의 해안선을 관망할 수 있는 가족단위 휴양객들이 많이 찾고 있다', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01693', '계도어촌체험마을', '관광지', 34.974872, 128.517512, '경상남도 거제시 사등면 가조로 837', '가조도의 서북쪽에 위치 앞 바다에 닭모양의 닭섬이 있어 계도마을이라 하였다. 주요 특산물로는 미더덕 젓갈，미더덕，마른멸치，건홍합이 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01694', '다대어촌체험마을', '관광지', 34.73449995, 128.630513, '경상남도 거제시 남부면 다대5길 11', '남부면 다대리에 위치한 다대마을로서 갯벌체험을 할 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01695', '협재playground', '관광지', 33.39349585, 126.2385969, '제주특별자치도 제주시 한림읍 협재리 2450', '에메랄드 빛 바다색과 비양도 절경을 품고 있는 제주시 서부 대표 휴양지', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01696', '김녕playground', '관광지', 33.5548971, 126.7654535, '제주특별자치도 제주시 구좌읍 김녕리 497-5', '해양레져스포츠, 캠핑 등 즐길거리가 가득한 제주시 동부 대표 휴양지', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01697', '절물자연휴양림', '관광지', 33.44004881, 126.6252034, '제주특별자치도 제주시 명림로 584(봉개동)', '제주시에서 20분거리에 위치해 있으며, 50여년생 삼나무조림지와 자연림이 조화를 이루는 독특한 경관으로 전국 국립자연휴양림 중 매년 최다 방문객을 바랑하고 있다. 또한 유아숲체험원. 숲해설. 목공예 등 산림체험프로그램을 운영하고 있다', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01698', '노들섬', '관광지', 37.51766383, 126.9580365, '서울특별시 용산구 양녕로 445', '서울특별시 한강위에 있는 섬. 동작구와 용산구 사이에 있으며 섬 사이로 한강대교가 지나간다. 행정구역상으로는 용산구 이촌동에 속해 있다. 원래 이름은 중지도(中之島)였으나 1995년 역사바로세우기가 시행되면서 일본식 지명 개선사업이 이루어졌는데 이 때 노들섬으로 개명되었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01699', '소요산playground', '관광지', 37.94652177, 127.0693409, '경기도 동두천시 평화로2910번길 145', '가을 단풍이 아름다워 예부터 경기의 소금강이라 일컬어졌으며 자재암 원효폭포 등의 관광명소가 소재하고 있다', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01700', '율포해수욕장', '관광지', 34.67002926, 127.0890241, '전라남도 보성군 회천면 우암길 24', '2012년 전국3대 우수해변, 2016년 해양수산부가 추천하는 올 여름 바다여행지 10선에 선정된 율포솔밭해변은 폭 60m와 길이 1.2km에 이르는 은빛 모래밭에 50~60년생의 소나무들이 숲을 이뤄 운치를 더한다.  공해없는 청정해역이므로 깨끗한 바다를 즐길 수 있고 1991년 국민playground로 지정되어 각종 편의시설이 잘 갖춰져있다. 해수녹차 휴게센터와 해수풀장, 그리고 녹차탕까지 있어 어린이를 동반한 가족단위 피서지로 많은 관광객들이 여름철에 이곳을 찾고 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01701', '한국차문화공원', '관광지', 34.71987643, 127.0817099, '전라남도 보성군 보성읍 녹차로 775', '한국차박물관+세계차나무식물원+보성차품평관+다목적 야외공연장+차만들어보는 곳+청소년 수련원 등이 푸른녹차밭과 어우러져 있어 관람 및 휴식, 체험이 가능하다. 특히 한국차박물관은 천혜의 차밭 경관과 인접하고 차에 대한 풍부한 컨텐츠를 담은 차 전문 박물관으로 우리 차 문화의 올바른 정립 및 연구와 보급의 구심점 역할을 한다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01702', '호미곶관광단지', '관광지', 36.07608308, 129.5665319, '경상북도 포항시 남구 호미곶면 해맞이로 136', '호미곶의전경을 확인', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01703', '구드래playground', '관광지', 36.28718846, 126.9068136, '충청남도 부여군 부여읍 백강로 148', '백마강과 함께 가족단위 공원 심터 및 생활체육을 즐길수 있는 웰빙playground', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01704', '서동요역사playground', '관광지', 36.14594895, 126.8248464, '충청남도 부여군 충화면 충신로 618', '역사문화환경을 구축하여 부여 대표 관광명소', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01705', '청소년전통문화체험관', '관광지', 35.98879491, 127.261342, '전라북도 완주군 고산면 대아저수로 416', '전통문화를 기반으로 한 청소년들의 문화공간, 체험공간, 지역 내 전해 내려오는 역사의 흔적과 문화를 소재로 한 교육체험 공간', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01706', '놀토피아', '관광지', 35.98879491, 127.261342, '전라북도 완주군 고산면 대아저수로 416', '국내 최대규모(34종류)를 자랑하는 심신발달형 어린이 모험 놀이시설', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01707', '오성한옥마을', '관광지', 35.90695186, 127.2367573, '전라북도 완주군 소양면 오도길 73', '종남산과 위봉산이 병품처럼 둘러쌓고 있는 천혜의 자연경관에 한옥고택 등 전통한옥이 자리잡고 있는 곳', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01708', '무궁화오토캠핑장', '관광지', 35.97398132, 127.2315513, '전라북도 완주군 고산면 고산휴양림로 89', '문화체육관광부 국민여가캠핑장으로 조성된 공공야영장으로 52개 사이트와 캐러반 등 부대시설이 갖추어져 있는 곳', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01709', '송광사&벚꽃길', '관광지', 35.885763, 127.2417509, '전라북도 완주군 소양면 송광수만로 255-16', '송광사는 종남산 아래에 자리한 사찰로 신라시대에 도의선사가 창건한 것으로 전해진다', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01710', '위봉사&위봉폭포&위봉산성', '관광지', 35.9105769, 127.2572831, '전라북도 완주군 소양면 위봉길 53', '위봉사는 세마리 봉황이 날고 있는 자리에 절을 짓고 이름붙였다는 이야기가 전해져 오는 곳', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01711', '화암사', '관광지', 36.06629938, 127.2872339, '전라북도 완주군 경천면 화암사길 271', '세월의 흐름을 멋지게 담고있는 아름다운 사찰', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01712', '레인보우힐링playground', '관광지', 36.15635341, 127.7865137, '충청북도 영동군 영동읍 매천리 산 35-1', '영동의 아름다움을 볼 수 있는 7가지 테마가 있는 playground', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01713', '송호playground', '관광지', 36.12969079, 127.676367, '충청북도 영동군 양산면 송호로 105', '아름다운 금강변 옆 1400여 그루의 송림에서 캠핑을 즐기며+ 신선놀음을 하기 제격인 곳', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01714', '자갈치시장', '쇼핑', 35.09661444, 129.0305818, '부산광역시 중구 자갈치해안로 52', '부산의 대표적 명소이자 신선한 활어와 선어를 저렴하게 살 수있는 한국 최대의 전통 수산물시장', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01715', '40계단테마거리', '관광지', 35.10397225, 129.0346287, '부산광역시 중구 대청로135번길 13', '40계단을 중심으로 조성된 테마거리로 뻥튀기 아저씨,  물동이 진 아이 등의 조형물이 꾸며져있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01716', 'BIFF광장', '관광지', 35.09862035, 129.0287588, '부산광역시 중구 비프광장로 36', '세계적 영화제로 발돋움한 부산국제영화제의 태동지', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01717', '영도대교', '관광지', 35.09725344, 129.035681, '부산광역시 중구 태종로 8', '영도대교는 일제 강점기 시절 영도와 부산항 사이의 원활한 왕래를 위해 1934년 11월에 준공된 동양최조의 교량이자 국내 유일의 연륙교로써의 역사적인 의미를 지니고 있으며, 한국 전쟁 당시 헤어진 가족들의 기약 없는 이별의 종착지이자 이산가족들에겐 삶의 애환이 서려있는 장소이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01718', '김대중노벨평화상기념관', '관광지', 34.78285177, 126.3922506, '전라남도 목포시 삼학로 92번길 68', '김대중 前대통령의 업적 및 걸어온 길을 살펴볼 수 있는 곳이다. 평화의 메시지 보내기, 노르웨이 오슬로 시상식장 체험, 노벨평화상 단상 포토존 및 대통령 집무실을 그대로 옮겨놓은 집무실 체험공간에서 대통령이 되어보는 체험을 할 수 있다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01719', '목포자연사박물관', '관광지', 34.79372717, 126.4210674, '전라남도 목포시 남농로 135', '지구 46억년 자연사를 볼 수 있는 곳으로 다양한 생명체와 관람객이 공존하는 증강현실 사진관 체험,  박물관에 잠든 공룡알 화석을 부화시키는 게임형 AR 체험, 수생 생물이 살고 있는 연못 생태계 위를 거니는 콘텐츠등 다양한 VR, AR콘텐츠와 영상쇼를 제공한다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01720', '갓바위', '관광지', 34.79372717, 126.4210674, '전라남도 목포시 남농로 135', '갓바위는 두 사람이 나란히 삿갓을 쓰고 서 있는 모습의 바위로 관광객들이 즐겨찾는 명소이며, 예전에는 배를 타고 나가야만 볼 수 있었던 갓바위를 해상에서 직접 조망할 수 있는 보행교를 바다위에 설치하였다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01721', '청평사(춘천)', '관광지', 37.986071, 127.808407, '강원특별자치도 춘천시 북산면 오봉산길 810', '청평사 playground는 시내에서 19km 지점에 있으며 소양호 선착장에서 선박을 이용하여 10분 정도 가면 청평사 playground에 이른다. 계곡이 수려하여 등산객들이 즐겨 찾는 곳으로 계곡을 따라 오르다 보면 7m 높이의 아홉 가지 소리를 낸다는 구성폭포가 있다. 그밖에 청평사 고려 정원 영지, 청평사 회전문, 3층 석탑 등이 있다. 이곳을 계속 오르면 오봉산 등산로와 연결된다. 청평사 playground의 초입에는 다양한 먹거리가 있어 춘천의 토속음식들을 만나볼 수 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01722', '신영', '관광지', 37.747692, 127.7252549, '강원특별자치도 춘천시 동산면 종자리로 148-16', '일상의 스트레스를 벗고, 위대한 자연 속에서 휴식의 옷으로 갈아입는 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01723', '라비에벨', '관광지', 37.741217, 127.7578198, '강원특별자치도 춘천시 동산면 종자리로 436', '자연 원형의 생태가 그대로 살아 숨쉬고 최고의 코스와 함께 도전과 변화, 평온과 휴식을 동시에 만끽하실 수 있습니다', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01724', '맹종죽테마공원', '관광지', 34.967708, 128.650512, '경상남도 거제시 하청면 거제북로 700', '맹종죽을 이용한 창조적 활용과 보존을 통하여 죽림욕을 이용한 치유，바다경관과 환경예술을 접목한 경관치유，맹족죽을 이용한 체험놀이치유가 가능한 죽림테라피 공간입니다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01725', '대관령어흘리playground', '숙박', 37.719113, 128.7959193, '강원특별자치도 강릉시 성산면 삼포암길 17', '2014년 163천㎡를 playground로 지정받아, 도로, 주차장, 안내소, 화장실 등의 공공편익시설, 트리하우스, 게스트하우스 등 숙박·휴양문화시설이 조성', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01726', '예천포리playground', '관광지', 36.70015808, 128.514204, '경상북도 예천군 감천면 복골길 150', '내성천 지류가 자연석과 어울려 경관이 수려하며, 충효테마공원에서 충효 체험이 가능함.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01727', '예천삼강', '관광지', 36.56378393, 128.304509, '경상북도 예천군 풍양면 삼강리길 53-23', '자연과 문호, 사람과 역사가 함께 공존하는 예천의 신개념 문화체험공간', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01728', '구문소 playground', '관광지', 37.09296812, 129.0422636, '강원특별자치도 태백시 동태백로11(동점동)', '천연기념물인 구문소와 접목되어 자연환경적 특성을 부각하고 지질학습 및 화석 산출지의 탐방자원화, 체류형 관광시설 도입', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01729', '용연동굴', '관광지', 37.20888277, 128.9418601, '강원특별자치도 태백시 태백로 283-29', '「용연동굴」이란 이름은 용의 연못 속에 있던 용이 계곡을 따라 하늘로 승천했다는 뜻을 담고 있다. 용연동굴은 백두대간의 중추인 금대봉 하부능선 해발 920m에 위치하고, 약 1억5천~3억만 년 전에 생선된 것으로 알려져 있다. 동굴의 길이는 약 843m, 구조는 4개의 광장과 순환형 수평굴로 이루어져 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01730', '신륵사playground', '관광지', 37.29742583, 127.6599364, '경기도 여주시 신륵사길 73', '시원한 남한강을 따라 자전거도로, 각종 체육시설과 여주박물관, 도자세상, 농특산물 판매장이 있으며, 매년 여주도자기축제와 오곡나루축제가 이곳에서 개최되고 있다. 특히 남한강을 가르는 황포돛배(Yellow Sail boat)와 수상레저를 즐길 수 있는 가족 연인들의 나들이 공간이다', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01731', '동빙고 부군당', '관광지', 37.52214299, 126.996145, '서울특별시 용산구 서빙고로73길 24-27', '동빙고 부군당은 수백년 전부터 단군 할아버지와 할머니를 비롯해 여러 신을 함께 모시고 주민의 안전과 국태민안을 기원했던 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01732', '용산기지 옛 미군장교숙소(현 용산공원)', '관광지', 37.52300977, 126.989165, '서울특별시 용산구 서빙고로 221', '주한미군 장교들의 숙소가 있었던 곳이다. 정부는 용산기지의 본격적인 반환 이전 국민들이 용산공원 조성을 체감하고 용산공원의 과거와 현재 그리고 미래를 함께 논의하는 소통의 장으로 활용하고자 지난 2020년 7월 21일 옛 미군장교숙소를 국민들에게 개방됐다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01733', '김유신 장군 사당', '관광지', 37.523941, 127.000688, '서울특별시 용산구 서빙고로91길 28-15', '본래 관아에서 신령을 모시는 집인 부군당으로서 김유신 장군을 주신으로 모셨으며 이름을 명화전이라 부른다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01734', '보광동 무후묘', '관광지', 37.527058, 126.9973443, '서울특별시 용산구 장문로15나길 6', '서울 마을신앙인 부군당으로 제갈공명, 제갈공명부인, 산신, 청장군, 홍장군 무신도가 봉안되어있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01735', '새남터 순교성지', '관광지', 37.52512658, 126.9570717, '서울특별시 용산구 이촌로 80-8', '조선 말엽 네 번에 걸쳐 일어난 천주교 박해 때 천주교 신자들이 처형당하면서 천주교 순교성지로 알려지게 되었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01736', '남산&N서울타워', '관광지', 37.55112257, 126.9878678, '서울특별시 용산구 남산공원길 105', '남산서울타워는 효율적인 방송전파 송수신과 한국의 전통미를 살린 관광 전망시설의 기능을 겸비한 국내 최초의 종합전파 탑으로 방송문화와 관광산업의 미래를 위해 건립되었습니다. 세계 유명한 종합 탑들이 그 나라 또는 그 도시의 상징적인 존재가 된 것처럼 남산서울타워 역시 지난 40여 년간 대한민국의 대표적인 playground이자 서울의 상징물 역할을 해왔습니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01737', '순천만습지', '관광지', 34.88579701, 127.5092833, '전라남도 순천시 순천만길 513-25(대대동)', '75㎢가 넘는 해수역, 22.6㎢의 갯벌면적, 5.4㎢에 달하는 거대한 갈대군락과 겨울이면 흑두루미, 재두루미, 노랑부리저어새, 큰고니, 검은머리물떼새 등 순천만에서 발견되는 철새는 총 230여종으로 우리나라 전체 조류의 절반가량이나 되며 2003년 습지 보호지역, 2006년 람사르협약 등록, 2008년 국가지정문화재 명승 제41호로 지정된 순천만은 농게, 칠게, 짱뚱어 등과 같은 갯벌 생물들이 한데 어우러져 살아가고 있음.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01738', '낙안읍성', '관광지', 34.90640107, 127.3418227, '전라남도 순천시 낙안면 충민길 30(동내리)', '조선시대 상징적 계획도시인 읍성으로 주민이 실재 거주하는 대한민국 대표 민속마을-사적 제302호(1983.6.14.), 세계문화유산 잠정목록에 등재(2011.3.29.)', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01739', '뿌리깊은나무박물관', '관광지', 34.9036464, 127.3399827, '전라남도 순천시 낙안면 평촌3길 45', '2011년에 개관한 뿌리깊은나무박물관은 잡지뿌리깊은나무 창간자 故한창기 선생이 생전에 모은 6,500여점의 유물이 전시·보존 되어 있는곳입니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01740', '송광사', '관광지', 35.00236255, 127.2748706, '전라남도 순천시 송광면 송광사안길 100', '유구한 역사를 품은 힐링 사찰', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01741', '선암사', '관광지', 34.99618213, 127.327356, '전라남도 순천시 승주읍 선암사길 450', '선암사는 호남의 명산 조계산(884M)에 자리잡은 한국적인 절의 옛 모습을  가장 잘 보존한 천년의 고찰로 2018년 유네스코 세계문화유산에 등재된 국내의 명찰 가운데 하나', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01742', '에코촌유스호스텔', '숙박', 34.92310938, 127.5164423, '전라남도 순천시 해룡면 생태배움길 123', '세계5대 연안습지 순천만, 2013년 440만이 감동한 순천마 정원의 인근에 자리잡은 전국 최초 전통 한옥형 유스호스텔.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01743', '순천자연휴양림', '관광지', 35.04388083, 127.4744949, '전라남도 순천시 서면 청소년수련원길 170', '2011년 개장한 순천자연휴양림은 피톤치드가 풍부한 침엽수림으로 산책로가 길지않고 대부분이 평지여서 남녀노소 누구나 힐링할수 있는곳임', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01744', '기독교역사박물관', '관광지', 34.96043473, 127.4801207, '전라남도 순천시 매산길 61(매곡동)', '호남기독교 100년의 역사를 품은 순천시 기독교역사박물관은 한국 기독교 선교의 역사를 다양한 유물과 영상을 통해 알기 쉽게 전달하는 공립박물관입니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01745', '순천시청소년수련원', '관광지', 35.04652524, 127.4733227, '전라남도 순천시 서면 청소년수련원길 167', '물과 숲 그리고 자연과 사람이 어우러지는 청소년 수련원', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01746', '사라실 라벤더 단지', '관광지', 35.04162939, 127.270748, '전라남도 광양시 주암면 문길리 산 20-2', '라벤더마을, 라벤더 체험장', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01747', '광양 마로산성', '관광지', 34.966742, 127.619496, '전라남도 광양시 사곡리 산 254', '국가지정문화재 사적 제492호', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01748', '광양 궁시장', '쇼핑', 34.98778794, 127.5865036, '전라남도 광양시 광양읍 구산리 716', '도지정무형문화재 제12호', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01749', '매천황현생가', '관광지', 34.99341564, 127.561707, '전라남도 광양시 봉강면 서석길 14-3', '조선의 마지막 선비 우국지사 매천 황현선생 생가', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01750', '삼례문화예술촌', '관광지', 35.90623513, 127.0658535, '전라북도 완주군 삼례읍 삼례역로 81-13', '수탈의 상징인 양곡창고를 문화예술의 중심지로 탈바꿈시켜 역사적 의미와 문화가 공존하는 삼례만의 독특하고 절묘한 공간', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01751', '삼례책마을', '관광지', 35.90745719, 127.065756, '전라북도 완주군 삼례읍 삼례역로 68', '전시와 공연 토크콘서트 등 다양한 프로그램을 운영하고 있는 곳', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01752', '그림책미술관', '관광지', 35.90832046, 127.068059, '전라북도 완주군 삼례읍 삼례역로 48-1', '그림책을 보고, 듣고, 느낄 수 있는 공간', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01753', '대한민국술테마박물관', '관광지', 35.726048, 127.1361627, '전라북도 완주군 구이면 덕천전원길 232-58', '5만여 점의 유물을 통해 태곳적부터 현대까지 우리 술에 담긴 다양한 이야기를 오롯이 담고 있는 테마박물관', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01754', '완주전통문화체험장', '관광지', 35.98879491, 127.261342, '전라북도 완주군 고산면 대아저수로 416', '고즈넉한 한옥의 숨결을 느끼며 뛰어난 자연경관 속에 아늑한 휴식을 즐기기에 안성맞춤인 공간', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01755', '간현playground', '관광지', 37.36457641, 127.834038, '강원특별자치도 원주시 지정면 소금산길 12', '섬강과 삼산천 강물이 합수되는 지점에 위치하고 있어 빼어난 자연경관과 소금산 등반 등을 할 수 있음', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01756', '가덕도', '관광지', 35.05664068, 128.8316554, '부산광역시 강서구 동선길 10, (성북동)', '가덕도는 보개산이 바다 가운데 침몰되었다가 다시 솟아서 이루어 졌다는 전설이 있는 부산 최대의 섬이다. 최고봉인 연대산(459.4m)을 위시하여 수많은 산들이 펼쳐져 있으며, 해안선을 따라 동북쪽으로 눌차·동선 사이를 이어주는 주변 백사장에서부터 기도원앞 바닷가의 경관, 동남쪽으로 대항 새바지의 넓은 자갈밭과 용두암을 시작으로 펼쳐지는 동백숲과 아동섬일대와 동두말, 가덕도 등대 주위의 깎아지른 듯한 기암괴석, 서남쪽으로 돌아 외양포 해수욕장, 두문의 길게 뻗은 솔섬, 천수말 코바위 등 가덕도는 해금강 절경을 방불케 한다.(수용인원 제한 없음)', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01757', '낙동강제방(강서30리벚꽃길)', '관광지', 35.20985086, 128.9845591, '부산광역시 강서구 공항로 1246, (대저1동)', '낙동강제방을 시민공원화하여 산책인들에게 정서함양과 향토애를 고취하기 위해 1992년 강서구에서는 조경으로 철쭉동산 등을 조성하고 시비를 건립하였다. 그렇게 세워진 시비는 구포대교와 낙동대교 사이의 강서쪽 제방이 되는데 금수현 노래비와 이은상 시비는 1992년 2월에, 배재황 시비는 1992년 7월에 조지훈과 박목월 이주홍 시비는 1992년 8월에 제각각 특성을 지닌 아담한 조각으로 세워졌다.강서구의 아름다운 낙동강제방위에 마라톤코스를 조성하여 맥도생태공원과 연계한 시민들의 여가공간 확보 및 주민건강증진을 위하여 우리구에서는 명지동 I.C에서 구포대교까지 L=12.68km구간에 조깅코스를 조성하였다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01758', '대저생태공원', '관광지', 35.20985086, 128.9845591, '부산광역시 강서구 공항로 1246, (대저1동)', '대저생태공원은 대저수문부터 김해공항램프까지이며, 구포대교하류부부터 천연기념물 제179호(낙동강하구 철새도래지)로 지정되어 있으며, 신덕습지를 비롯한 습지 및 자연초지, 유채꽃단지와 체육시설인 축구장, 야구장등이 조성되어 있는 부산시민이 여가와 휴식을 즐길 수 있는 자연생태 친수공간이다.특히 공원에 조성된 유채꽃 단지(370,000㎡)에서 4월 개최되는 유채꽃 축제는 수많은 관광객을 불러 모으고 있어 새로운 관광 명소로 자리 잡아 시민의 여가와 휴식을 즐기는 곳이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01759', '맥도생태공원', '관광지', 35.15230906, 128.9549009, '부산광역시 강서구 공항로 500, (대저2동)', '맥도생태공원은 강서구 명지동(낙동강하구둑)부터 대저2동(공항램프)까지 하천내 자연적으로 형성된 둔치지역이며, 낙동강하구 천연기념물 179호(철새도래지)로 지정된 지역이다. 이곳은 과거부터 벼농사 등의 농경지로 이용되어 겨울철새들에겐 먹이터겸 쉼터로 활용되던 곳으로, 2006년의 정비사업 및 2009년의 4대강사업 추진 시에도 이를 고려하여 사업이 추진되어, 많은 곳이 겨울철새의 먹이터겸 쉼터로 관리되도록 하였다.한편, 겨울철새에 대한 배려 이외에도 생태공원의 특징을 살려 갈대밭, 연꽃단지, 수생식물원 등을 조성하여 시민들의 볼거리를 만들었고, 그밖에 축구장, 야구장 등 각종 체육시설(9종 22면)과 파고라, 정자 등 휴게시설이 구비되어 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01760', '괴강', '관광지', 36.80676203, 127.8252917, '충청북도 괴산군 괴산읍 충민로검승3길 10', '달천을 중심으로 괴강국민여가캥핑장 농업역사박물관, 각종 체육시설등이 조성된 playground', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01761', '수옥정', '관광지', 36.81361722, 128.036232, '충청북도 괴산군 연풍면 수옥정길 174, 수옥정playground관리사무소', '드라마 촬영등으로 유명한 수옥폭포와 수옥정, 한여름의 더위를 식혀주는 수옥정 물놀이장과 더불어 조령산, 깃대봉 등의 명산이 어우러져 자인이 만들어 낸 천혜의 playground', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01762', '고석정', '관광지', 38.18542141, 127.2874037, '강원도 철원군 동송읍 태봉로 1825', '1977년 국민playground로 지정된 고석정은 한탄강 중류에 위치한 철원구경의 하나로 강 중앙에 10m 높이의 거대한 기암이 우뚝 솟아 있는 것이 특이한 남한대륙의 유일한 현무암 분출지이며 조선조 초기 임꺽정의 활동무대로도 널리 알려져 있어 많은 전설이 전해지고 있다. 이 곳에서 상류로 약 2km 지점에 직탕폭포와 하류 약 2km 지점에 순담이 위치해 있으며 넓은 잔디광장과 유원시설 등이 있어 어느 때나 관광객이 즐겨 찾고 있다. 또한 시설물관리사업소가 있어 안보관광도 함께 할 수 있는 관광의 최적지이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01763', '명월사지흥국사', '관광지', 35.13886951, 128.8341451, '부산광역시 강서구 허왕후길 182, (지사동)', '<신증동국여지승람>에 의하면 명월사(明月寺)는 명월산에 있었다고 하고, 헌종 34년(1708) 승(僧)증원(證元)이 천한 <김해명월사사적비>에 명월사 내력이 자세히 기록되어 있다.명월사는 임진왜란때 불타버렸는데, 광해군 10년(1618)에 중건하였고, 그 뒤 또 다시중수(重修)할 때 「건강원년갑신삼월남색(健康元年甲申 三月藍色)」이라고 새겨진 기와장이 무너진 담장 아래서 발견되었는데, 건강원년은 수로왕 103년(144)이 되며 서역불교(西域佛敎)가 장유화상(長遊和尙)에 의해서 일찍이 이 땅에 전래된 것을 입증한다고 한다.흥국사 경내에 있는 명월사 사적비문(史蹟碑文)을 보면, 가락국 수로왕이 높은 산길 아래서 만전(滿殿)을 베풀어 허왕후를 맞이하였으며, 익일(翼日)에 궁으로 돌아갈 때에 허왕후가 입었던 비단바지를 벗어서 산신(山神)께 바쳤다고 전해오고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01764', '렛츠런파크 부산경남', '관광지', 35.15474347, 128.8819186, '부산광역시 강서구 가락대로 929, (범방동)', '전국 최대 말 테마파크로 더비랜드(사계절썰매장, 바닥분수, 렛츠런투어 등) 포니랜드(어린이승마장, 어린이놀이터, 바운싱돔) 에코랜드(테니스장, 족구장, 농구장, 축구장) 호스아일랜드(호수공원, 미니기차, 가족 자전거) 승마랜드(말 먹이주기체험, 승마체험, 힐링/재활 승마) 등 가족, 연인, 친구와 다양한 즐길거리의 시설이 갖춰져 있다. 금~일요일 경마일에 방문한다면, 공원 놀이시설 외에 관람대에서 실제 말이 뛰는 모습을 볼 수 있다. 또, 관람대 내 루키존에서는 다양한 콘텐츠(인생네컷, 농구게임, 다트, 초보경마교실 등)도 무료로 이용할 수 있다. 시즌 프로그램으로 더비랜드에서 여름을 시원하게 보낼 수 있는 워터파크도 운영되고 봄, 가을에는 문화행사와 축제도 꾸준히 운영되고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01765', '강서체육공원', '관광지', 35.21018443, 128.9723366, '부산광역시 강서구 체육공원로 43, (대저1동)', '강서체육공원은 강서구 대저1동에 부지면적 20만㎡로 2002, 6월에 완공되었다. 2002년 부산아시아경기대회 펜싱경기와 배드민턴경기가 열린 실내체육관과 2,000석 규모의 하키경기장, 500석 규모의 보조경기장, 그리고 양궁경기장 등으로 구성되어 있다. 강서체육공원은 종목별 경기장 뿐만 아니라 시민체육, 문화센터 등 여가시설을 위한 체육가족공원으로 조성되어 있으며, 천연잔디구장 2면은 부산아이콘스 및 유소년 축구클럽 전용연습장으로 사용하고 있다. 또한 4,189석의 관람석을 갖고 있는 실내체육관에서는 펜싱과 배드민턴 등 경기가 가능하며, 야간에는 주차장 일부를 폐쇄하여 인라인스케이트장으로 활용하고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01766', '서낙동강카누경기장', '관광지', 35.17013026, 128.9068188, '부산광역시 강서구 조정경기장길 120, (강동동)', '서낙동강 조정 카누 경기장은 강서구 강동교~남해 고속 도로 지선, 강서구 강동동 서낙동강 일대에 있다. 전국 체육 대회 등 국내 대회를 성공적으로 개최하여 조정·카누 인구의 저변 확대와 부산 체육 진흥에 크게 이바지하였다. 연중 해양 스포츠 아카데미를 개설·운영하여 조정, 카누, 래프팅 등을 배울 수 있으며, 다양한 해양 스포츠 체험을 할 수 있다. 매년 6월 중에는 강 스포츠 축제가 개최되고 있다.[네이버 지식백과] 서낙동강 조정 카누 경기장 [西洛東江漕艇-競技場] (한국향토문화전자대전)', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01767', '경산상대온천', '카페', 35.78037855, 128.7922287, '경상북도 경산시 남산면 상대로116길 18', '상대온천관광호텔은 경산 시내에서 자동차로 30분가량 걸리는 산속 마을에자리잡고 있어 처음 찾기는 어려우나, 수질이 좋아 한번 찾아온 사람은 반드시다시 찾아온다고 한다. 신라 시대부터 더운 바위샘온암정(溫巖井), 대추골 더운샘,온수골이라 불렸으며, 한겨울에도 물이 얼지 않아 빨래터로 이용했다. 수량이풍부한 데다 한국에서는 보기 드물게 알칼리성이 강한 황산천이다. 맑고 깨끗한온천수에 황산이온, 염소, 과망간산칼륨 등 2,500여 종의 각종 미네랄이 함유돼 있다.피부병·신경통·위장병·비뇨기질환·동맥경화증에 효과가 좋다고 알려져 있다. 특히위장병에 좋다고 해서 온천수를 그대로 마시는 사람들도 있다.객실은 양실과 한실로 구성돼 있으며, 연회장, 가족탕, 온천사우나, 토산품점, 예식홀,커피숍, 숲속 카페, 교육문화회관 등 부대시설을 갖추고 있다. 053)815-8001', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01768', '동의한방촌', '관광지', 35.79937497, 128.800141, '경상북도 경산시 남산면 삼성현공원로38', '자연치유및 한방치유 명품 한방문화체험관', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01769', '삼성현역사문화공원', '관광지', 35.80168834, 128.7966117, '경상북도 경산시 남산면 삼성현공원로59', '일연원효설총 세 성현분들의 역사를 기록한 박물관 및 체험시설', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01770', '자인계정숲', '관광지', 35.81784608, 128.8189958, '경상북도 경산시 자인면 계정길 68', '한장군놀이 전수회관 등 있으며 구릉지에 남아있는 천연숲', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01771', '황령산playground', '관광지', 35.155156, 129.102558, '부산광역시 수영구 황령산로 156 일원', '부산광역시 금련산청소년수련원 일대이며, 부산 도심 속 천혜의 황령산 자락에 위치하고 있어 부산의 랜드마크인 광안리 해수욕장, 광안대교, 해운대를 한눈에 바라볼 수 있음.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01772', '삼척해수욕장', '관광지', 37.47034344, 129.1647024, '강원특별자치도 삼척시 수로부인길 453', '길이 1㎞+폭 85m의 넓은 백사장+ 맑고 깨끗한 동해해수욕장+ 푸른 송림+소규모의 항포구+ 해안의 기암괴석과 모래+ 산이 분포되어 있으며+ 남쪽으로 해안선을 끼고 해안도로가 4.2KM 개설되어 관광객들로부터 많은 호응을 얻고 있음', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01773', '성륜사', '관광지', 35.29704978, 127.1208706, '전라남도 곡성군 옥과면 미술관로 287', '곡성군 옥과면 옥과리에 위치한 대한불교조계종 성륜사(聖輪寺)는 옥과의 진산인 설산(雪山)의 남쪽 설령골에 위치하였으며, 1988년 6월4일부터 중창불사 하여 현재에 이르렀다. 주변으로 괘일산과 갈산 등이 자리를 잡고, 설산에서 발원한 작은 계곡들이 흘러 안으로 굽은 산세가 성륜사를 외호(外護)하고 있다. 성륜사는 고려시대 사찰이었던‘나암사(羅巖寺)’의 맥을 잇는 터에 자리를 잡았다. 나암사는『신증동국여지승람(新增東國輿地勝覽)』,『동국여지지(東國輿地誌)』에 기록되어 있으며,『동여비고(東輿備考)』옥과현 지도에 나타난 나암사의 위치를 보면 지리적으로 현재 성륜사가 위치한 자리였음을 알 수 있다. 조선 중기 편찬된 『여지도서(輿地圖書)』부터는 사찰이 폐했다는 기록이 전해지나, 마을 주민들의 증언으로 현재 성륜사의 자리가 ‘절골’로 불렸다는 점, 성륜사에서 고려시대 기와와 조선시대 기와가 수집되었다는 점에서 현 성륜사 터에서 법등이 계속 이어져 왔음을 알 수 있다. 성륜사는 1986년 청화 대종사(淸華 大宗師)와 아산 조방원(雅山 趙邦元) 거사와의 인연으로, 10만평의 땅을 시주 받으면서 중창불사가 시작되었다. 현재 전해지고 있는 당우로 대웅전, 지장전, 조선당, 육화당, 안심당, 법성당, 설령각, 정운당, 범종각, 적멸보궁 등이 있다. 중창불사 당시 구례군에서 이축했던‘안심당’과 ‘육화당’은 1920년대 전라남도 건축 양식을 잘 유지하고 있으며 난간의 장식, 다락 구조 등의 건축학적 특징으로 현재 근대문화재로 평가받고 있다. 또한‘조선당’은 청화 대종사가 주석하시던 곳으로, 열반하신 후에는 스님을 기리는 공간으로 남아있다. 조선당 옆으로 청화 대종사의 부도와 비석, 청화 대종사의 은사 스님인‘금타 대화상’의 부도가 자리 잡고 있다. 그 밑으로는 부처님의 진신사리를 모신 ‘적멸보궁’이 자리 잡고 있다. 곡성 성륜사는 나암사의 전통과 청화 대종사가 중창불사한 실상염불선 수행의 맥을 있는 전통사찰이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01774', '관음사', '관광지', 35.21469614, 127.1653199, '전라남도 곡성군 오산면 성덕관음길 453', '전라남도 성덕산에 있는 관음사는 백제 분서왕 3년(300) 성덕보살이 세운 절이다. 절 이름은 성덕보살이 낙안포에서 금동관세음보살상을 모셔와 절을 짓고 이름을 ‘관음사’라 부른데서 비롯되었다고 한다.고려 공민왕 23년(1374) 5번째로 넓혀 지었고, 조선시대에는 임진왜란으로 피해를 입어 선조 37년(1604) 5년 동안 모든 건물을 복원하였다.근세에 와서는 1912년 영담화상이 전가람을 고쳐 세웠으나 한국전쟁으로 모두 불타버렸다. 이 때 국보로 지정되어 있던 원통전과 금동관음보살이 소실되었다.지금 있는 건물들은 최근에 새로 지은 것들로 금랑각을 지나면 가운데에 법당인 원통전이 있고 그 왼편과 오른편에 벽안당과 요사채 등이 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01775', '천태암', '관광지', 35.09395689, 127.2764599, '전라남도 곡성군 목사동면 대신로 381-336', '천태암은 곡성군 목사동면에 있는 아미산 정상 부근에 자리 잡고 있는 사찰로, 대한불교조계종 제19교구 화엄사의 말사이다. 천태암은 665년 혜암율사가 창건하여 주석하였던 고찰로서 고려 명종 25년(1195)에 보조국사 지눌 스님이 자연석굴에 16나한을 모시고 법당과 요사를 중창하여 후학들을 제접하였다고 한다. 국사는 이곳 산세가 중국의 불교성지인 아미산과 닮았다하여 아미산 천태암이라 이름하고 산신각 위 벼랑에 형성된 대에 앉아 선정을 닦았으니 이곳을 보조국사 좌선대라 전해진다.하루는 좌선대에서 나무새를 만들어 날려 보내니 조계산에 날아 앉는지라 지금의 송광사로 자리를 옮기고 직접 다리를 만들어 천태암과 송광사를 오고 갔다고 한다. 다리의 이름은 ‘토성칠교’로 오늘날에도 ‘토성칠교를 건너면 무병장수하고 극락왕생 한다’는 이야기가 전해지고 있다. 동사열전에 따르면 석곡 출신 용운처익 스님이 경신년(1806)과 신유년(1861)간에 곡성 천태암을 중수했다는 기록이 있고, 또한 근대에 동명선지 스님이 쓴 천태암중수화문에도 천태암 중수에 인연을 지을 것을 권하고 있어 천태암은 면면히 그 위상을 유지하고 있었음을 알 수 있다. 천태암은 정유년(1957) 화재 때 전각 일부가 피해를 입었음에도 불구하고 그 명맥을 이어오던 중 호연스님의 원력과 신도님들의 불심과 사회 각계 뜻 있는 분들의 동참으로 갑신년(2004)에 다시 중창되었으며, 경자년(2020)에 전통사찰 제 97호로 지정받았다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01776', '용산재', '쇼핑', 35.13103091, 127.3210133, '전라남도 곡성군 목사동면 신숭겸로 226', '고려의 개국 공신 신숭겸(∼927)의 탄생지를 중심으로 이루어진 장군의 유적이다.신숭겸은 왕건을 도와 궁예를 몰아내고 고려를 건국하는데 큰 공을 세워 개국 일등공신이 되었다. 고려 태조가 즉위한 몇 년 뒤 후백제의 견훤은 신라를 공격하였다. 이에 크게 분개한 태조는 군사를 거느리고 나가 싸웠으나 후백제군에 포위되어 위급하게 되었다. 이 때 신숭겸이 태조를 구하고 후백제군과 싸우다 전사하였다. 이 유적지에는 제사를 모시는 용산재와 구룡문, 유허비, 유허단 및 비각이 있으며 해마다 9월 중에 제사를 지낸다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01777', '아트빌리지(한옥마을)', '숙박', 37.64510127, 126.6946856, '경기도 김포시 모담공원로 170', '김포시 운양동 모담산 자락에 안겨 있는 김포아트빌리지는 모담산이 주는 소담한 자연의 아름다움이 느껴지는 자연친화적 문화 · 예술 공간으로서, 다양한 문화예술을 창작하고 체험할 수 있는 예술 공방, 전통한옥숙박체험관이 있고 지역문화예술 단체의 창작 활동 공간인 아트센터에는, 다목적홀, 전시관이 있으며 또한 천여 명의 관객을 수용할 수 있는 자연과 어우러지는 야외공연장으로 구성되어 있습니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01778', '오전약수playground', '관광지', 37.01209531, 128.7457209, '경상북도 봉화군 물야면 문수로 1541', '심산계곡에 자리잡은 약수탕은 선달산, 옥석산 아래 깊은 계곡에 위치하고 있고, 약수는 예부터 위장병과 피부병에 효험이 있다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01779', '보은 삼년산성', '관광지', 36.48993999, 127.7417752, '충청북도 보은군 보은읍 성주1길 104', '신라 삼국통일의 전초기지인 삼년산성은 축성연대는 물론 수축연대가 정확히 기록되어 있는 산성으로 중부권의 역사적 가치를 지닌 문화유산이다', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01780', '속리산 법주사', '관광지', 36.53993659, 127.8306346, '충청북도 보은군 속리산면 법주사로 379', '대한불교조계종 제5교구의 본사로 신라시대 의신 조사가 창건하였고 2018년 6월 유네스코세계문화유산에 등재 되어 세계문화를 인정 받았다', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01781', '동학농민혁명기념공원', '관광지', 36.51567136, 127.7591951, '충청북도 보은군 보은읍 동학로 236-22', '탐관오리에 대한 봉기와 외세에 대한 저항 의식을 일깨워 준 농민들의 자발적 혁명으로 3.1운동의 큰 밑거름이 되었다', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01782', '만리포 playground', '관광지', 36.79000781, 126.1465709, '충청남도 태안군 소원면 만리포2길 190-3', '만리포 해수욕장에 멋진 바다가 한눈에 보이고 항구가 많으니 놀거리 볼거리가 많아서 다양하게 관람할수 있음', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01783', '부평아트센터', '관광지', 37.4822383, 126.7049334, '인천광역시 부평구 아트센터로 166', '뮤지컬+음악회+전시회 등', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01784', '기후변화체험관', '관광지', 37.50932668, 126.7307645, '인천광역시 부평구 장제로 267', '생태교육프로그램 체험', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01785', '부평역사박물관', '관광지', 37.51214216, 126.7379081, '인천광역시 부평구 굴포로 151', '부평 역사관련 전시물 관람', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01786', '부평안전체험관', '관광지', 37.51098789, 126.7333177, '인천광역시 부평구 굴포로 110', '재난상황 시뮬레이션 체험', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01787', '인천나비공원', '관광지', 37.52026697, 126.6927245, '인천광역시 부평구 평천로 26-47', '살아있는 나비 등 관람', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01788', '서울 원효로 예수성심당', '관광지', 37.53420937, 126.9545934, '서울특별시 용산구 원효로19길 49', '1902년에 세워졌으며, 프랑스인 코스트 신부가 설계, 감독 했다. 19세기 말의 성당 건축을 상징적으로 보여준다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01789', '구 용산 수위관측소', '관광지', 37.533956, 126.947132, '서울특별시 용산구 청암동 169-1', '한강변에서는 최초로, 전국에서는 아홉번째로 건립된 자기 관측소로서 조위와 홍수위를 관측할 목적으로 건립되었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01790', '심원정 왜명강화지처비', '관광지', 37.53342496, 126.95186, '서울특별시 용산구 효창원로8길 28', '임진왜란 당시 명나라 장군 심유경과 왜군의 장수 고니시 유키나가 만나 강화회담을 벌였던 장소로 전해진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01791', '청암동 부군당', '관광지', 37.534803, 126.946373, '서울특별시 용산구 원효로 17-11', '부군당은 마을의 안녕과 복을 지켜주는 부군신을 모신 곳으로 서울의 대표적인 마을신앙이다. 청암동에는 12신 무신도를 모신 부군당과 이성계를 모시던 영당이 인접하여 존재했었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01792', '산천동 부군당', '관광지', 37.535662, 126.9531703, '서울특별시 용산구 효창원로15길 7', '부군당은 마을의 안녕과 복을 지켜주는 부군신을 모신 곳으로 서울의 대표적인 마을신앙이다. 산천동 부군당 제사는 봄, 가을에 지내왔으나 요즘은 가을에만 한 차례 지내고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01793', '춘천호반', '음식점', 37.825714, 127.659368, '강원특별자치도 춘천시 서면 경춘로 1401-25', '춘천댐은 신북면 용산리와 서면 오월리 사이의 북한강 본류에 건설된 수력 발전소로 높이는 무려 40m에 이르고 담수 면적은 총면적 17㎢인 거대한 댐이다. 화천으로부터 내려오는 물길을 막아 설립된 춘천호 주변은 맑은 물과 푸른 자연환경을 지니고 있어 아름다움을 자랑한다. 또한, 춘천댐의 위 물길과 아래 물길 일대에는 유원지가 만들어져서 식당, 방갈로, 원두막, 야영캠프장, 낚시터 등 편의시설이 되어 있어 관광객들이 애용하고 있다. 유원지 숲 곳곳에 가족소풍을 즐길 만한 공간도 있어 가족끼리의 여행 장소로 제격이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01794', '죽녹원', '관광지', 35.32535666, 126.9866155, '전라남도 담양군 담양읍 죽녹원로 119', '2003년 5월에 조성하여 약 31만㎡의 울창한 대나무숲이 펼쳐져 있음. 죽림욕을 즐길수 있는 2.4km의 산책로가 있으며, 가사문학의 산실 담양의 정자문화를 대표하는 6정자를 재현하하고, 밤에는 별을 보며 한옥을 체험할 수 있는 공간이 조성되어있음', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01795', '메타세쿼이아랜드', '카페', 35.32342607, 127.001993, '전라남도 담양군 담양읍 학동리 578-4', '아름다운 숲 전국대회 부문 대상등 3회 수상에 빛나는 메타세쿼이아 길은 현재 메타세쿼이아 랜드로 조례개정하여 메타세쿼이아 길 외 어린이프로방스, 호남기후변화체험관, 개구리생태공원, 에코허브센터, 곤충박물관, 카페테리아 등 유원시설을 운영 및 공사 중이다. 메타세쿼이아 길을 사색하며 걷는것 외에도 체험 및 어린이를 위한 시설확충으로 담양을 대표하는 유원지 중 하나임', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01796', '한국대나무박물관', '관광지', 35.30934367, 126.9764088, '전라남도 담양군 담양읍 죽향문화로 35', '1981년에 죽물박물관이 개관된 후 전국 유일의 죽제품 주산지로서 보존, 전시, 시연, 판매 등 종합기능을 수행할 공간을 갖추어 대나무공예문화 전통 계승과 대나무공예 진흥의 계기를 마련하고자 1998년에 현재의 위치에 확장 이전하여 2003년에 한국대나무박물관으로 명칭을 변경하여 운영', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01797', '한국가사문학관', '쇼핑', 35.18796216, 127.0054858, '전라남도 담양군 가사문학면 가사문학로 877', '가사문학 관련 문화유산의 전승, 보전과 현대적 계승, 발전을 위하여 2000년 10월 완공. 1만 6,556㎡의 부지에 2,022㎡ 규모의 한옥형 본관과 기획전시실(갤러리), 자미정, 세심정, 토산품전시장, 전통찻집 등의 부대시설을 갖추고 있음', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01798', '슬로시티삼지내마을', '관광지', 35.23522516, 127.0178498, '전라남도 담양군 창평면 돌담길 56-24', '담양은 예로부터의 고택이 많이 남아 있으며 아직도 인근에 문화재가 많이 있다. 도심 인근의 농촌인데도 전통문화가 많이 남아 있어 현대와 전통이 조화를 이루고 있는 대표적 마을이기도 하다. 특히 삼지천 마을의 고택, 한옥마을에 펼쳐진 돌담길에서의 여유로운 산책은 방문객들의 슬로라이프 체험의 장이기도 하다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01799', '인천도호부청사', '관광지', 37.4393787, 126.6868134, '인천광역시 미추홀구 매소홀로 589', '조선시대 행정기관의 하나로 상급기관인 목(牧)과 하급기관인 군(郡) · 현(縣) 사이에서 행정을 담당했던 관청', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01800', '순천만국가정원', '관광지', 34.92888588, 127.4999591, '전라남도 순천시 국가정원1호길 47', '대한민국 생태도시 순천은 세계 5대 연안습지인 순천만습지의항구적인 보전을 위해 정원을 조성하고 2013순천만국제정원박람회를 개최하였다. 그 이후 제1호 국가정원으로 지정됨으로써 순천만국가정원은 대한민국 정원문화산업의 메카로 자리매김하게 되었다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01801', '등명해변playground', '관광지', 37.70232906, 129.0161926, '강원특별자치도 강릉시 강동면 정동등명길 2', '소나무와 해변이 어우러져 아름다운 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01802', '화순온천', '관광지', 35.1624699, 127.0837781, '전라남도 화순군 백아면 옥리길 14-7', NULL, '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01803', '도곡온천', '관광지', 35.02470562, 126.903529, '전라남도 화순군 도곡면 온천2길 44', '온천휴양지', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01804', '운주사', '관광지', 34.92906333, 126.8825635, '전라남도 화순군 도암면 천태로 91-44', '군립운주사문화관, 운주사 사찰', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01805', '전쟁기념관', '관광지', 37.53731405, 126.9784661, '서울특별시 용산구 이태원로 29', '1994년 용산에 건립된 전쟁기념관은 외침을 극복하고 국민의 생명과 재산을 지켜온 대외항쟁사와 민족의 자주독립을 지켜온 국난극복사 등 전쟁에 관한 자료를 수집,보존하고, 전쟁의 교훈을 통해 전쟁을 예방하여 조국의 평화적 통일을 이룩하는데 이바지하기 위해 세워졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01806', '당고개 순교성지', '관광지', 37.53559012, 126.966963, '서울특별시 용산구 청파로 139-26', '이 일대는 조선후기에 처형장으로도 이용되었는데, 1839년 기해박해 당시 천주교 신자 10여명이 순교한 곳이다. 지금은 기해박해 당시 천주교 순교자들을 기리기 위해 당고개 순교성지가 들어서 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01807', '옛 풍국제과 공장(현 오리온)', '관광지', 37.53567207, 126.9695135, '서울특별시 용산구 백범로90다길 13', '풍국제과는 일제강점기 용산에 본사와 생산공장을 두었던 제과업체로 1934년 지금의 위치에 설립하였다. 해방 이후 풍국제과는 정부에 귀속되었다가 1956년 이양구가 인수해 동양제과공업 주식회사를 설립했다. 그 후 사업확장과 함께 2001년 제과업을 중심으로 하는 오리온 그룹이 동양그룹계열에서 분리되어 오늘날의 ㈜오리온이 되었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01808', '송도용궁구름다리', '관광지', 35.0619212, 129.021965, '부산광역시 서구 암남동 620-53', '「송도지구 복합해양휴양지 조성사업」일환으로 2017년에 완공된 「송도오션파크」는 관광객 및 주민들의 열린 공간인 축제의 광장과 힐링의 광장, 운동시설이 설치되어 있는 젊음의 광장이 조성되어 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01809', '구곡폭포', '관광지', 37.797033, 127.615852, '강원특별자치도 춘천시 남산면 강촌구곡길 254', '송도해수욕장의 동쪽 송림공원에서 거북섬을 연결했던 추억의 명물 송도구름다리가 2002년 태풍 셀마 때 파손돼 철거된 지 18년 만에 ‘송도용궁구름다리’로 재탄생하였습니다. 암남공원에서 바다건너 작은 무인도인 동섬 상부를 연결하는 길이 127m, 폭 2m의 송도용궁구름다리는 바다 위를 걷는 짜릿함과 시원스럽게 펼쳐지는 바다 풍광, 기암절벽이 빚어내는 천혜의 경관을 감상할 수 있으며, 야간경관조명이 설치돼 밤에는 바다에 떠있는 신기루와 같은 환상적인 분위기를 연출해 관광도시 부산 서구의 새로운 랜드마크로 자리매김 하고 있습니다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01810', '연곡해변playground', '관광지', 37.85990446, 128.8520583, '강원특별자치도 강릉시 연곡면 해안로 1282', '봉화산 근처 아홉구비를 돌아 떨어지는 구곡폭포와 탄성을 자아내는 하늘벽 바위 등 자연경관이 출중한 곳이며, 깔닥재를 넘으면 자연부락인 문배마을까지 볼 수 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01811', '감귤박물관', '관광지', 33.27159304, 126.6074285, '제주특별자치도 서귀포시 효돈순환로 441(신효동)', '길이 700m, 56000㎡의 넓은 백사장을 간직하고 있다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01812', '명승 거창 수승대', '카페', 35.760923, 127.8336763, '경상남도 거창군 위천면 은하리길 2', '제주감귤의 역사와 문화. 산업현장을 의미있는 관점에서 전시한 박물관으로. 감귤 관련 전시물과 다양한 감귤 품종 및 이국의 식물을 관람할 수 있음. 또한 감귤과 관련한 다양한 체험 프로그램도 준비되어 있으며. 최근 개장한 감귤카페 꿈나다에서 주변 경치를 구경하며 맛있는 감귤 음료. 디저트를 저렴한 가격에 즐길 수 있음.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01813', '가조온천', '관광지', 35.69875771, 128.0231044, '경상남도 거창군 가조면 온천길161', '거창군 위천면 황산리에 있는 영남 제일의 동천(洞天: 산천으로 둘러싸인 경치 좋은 곳)으로 알려진 ‘안의삼동(安義三洞)’ 중 하나로 원학동 계곡 한가운데 넓은 화강암 암반으로 이루어진 계곡이다. 이곳은 암반 위를 흐르는 계류와 숲이 어우러져 빼어난 자연경관을 이루고 있어 2008년에 명승 제53호로 지정[네이버 지식백과] 거창 수승대 [居昌搜勝臺] (한국민족문화대백과, 한국학중앙연구원)', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01814', '옥계해변playground', '관광지', 37.62673237, 129.0485254, '강원특별자치도 강릉시 옥계면 금진솔밭길 104-29', '온천수  - 수질 : 26.5℃ / PH 9.7(국내 최고의 강 알칼리성 수질)      ▶ 류머티즘, 알레르기성 피부염 등에 탁월한 효과', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01815', '주문진해변playground', '관광지', 37.91144947, 128.8177557, '강원특별자치도 강릉시 주문진읍 주문북로 222-30', '옥계해변playground는 깨끗하고 넓은 백사장과 오래된 송림지역을 갖추어 바라보는 경치가 매우 아름다운 곳임.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01816', '칠백의총', '관광지', 36.12942797, 127.492435, '충청남도 금산군 금성면 의총길 50', '주문진해변playground는 주문진읍 향호리에 위치하고 넓은 백사장과 수심이 얕고 바닷물이 맑아 가족 단위 피서지에 적합한 곳임.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01817', '태고사', '관광지', 36.13440357, 127.3251004, '충청남도 금산군 진산면 청림동로 440', '대둔산 최고봉 마천대 다음 제2봉우리 낙조대 아래 동북쪽에 자리 잡고 있는 금산의 고찰이다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01818', '개삼터', '관광지', 36.07533917, 127.4783939, '충청남도 금산군 남이면 개삼로 101', '신비의 영약 인삼의 시배지', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01819', '태조대왕태실', '관광지', 36.19976177, 127.4543633, '충청남도 금산군 추부면 마전리 산 1-86', '조선을 개국한 태조가 함경도 용연지역에 있는 자신의 태를 이 산에 옮겨와 태자의 태와 함께 안치하여 나라의 태평성대를 염원한데서 그 유래를 찾을 수 있다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01820', '보석사', '관광지', 36.054757, 127.4753969, '충청남도 금산군 남이면 보석사1길 30', '나무 천년, 절집 천년', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01821', '3.1운동 용산인쇄소 노동자 만세시위지', '관광지', 37.53543893, 126.9584156, '서울특별시 용산구 원효로41길 33', '나무 천년, 절집 천년', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01822', '이봉창 의사 집터', '관광지', 37.540313, 126.959653, '서울특별시 용산구 백범로 275', '1919년 3.1운동 당시 용산에서 만세시위가 일어난 곳으로, 용산인쇄소가 있던 자리이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01823', '백범김구기념관', '관광지', 37.54427794, 126.959253, '서울특별시 용산구 임정로 26', '백범김구기념관은 김구 선생의 삶과 사상을 널리 알리고 계승 발전시키기 위한 취지에서 2002년 10월 22일 개관하였다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01824', '이봉창 의사 역사울림관', '관광지', 37.54010272, 126.960852, '서울특별시 용산구 백범로 281-9', '용산구를 대표하는 독립투사인 이봉창의사를 추모하고 그의 삶과 독립정신을 기리기 위해 세워진 기념관이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01825', '남이장군 사당', '관광지', 37.536475, 126.958433, '서울특별시 용산구 효창원로 88-10', '구전에 의하면 이시애의 난을 토벌할 때 군병을 훈련시킨 곳이 둔지미(현 삼각지 부근)이고 한강변 새남터에서 처형되었기 때문에 용산에서 장군을 추모하는 사당을 세우고, 그의 원혼을 달래고자 공동제와 제의굿을 300년 동안 지내왔다고 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01826', '연복사탑중창비', '관광지', 37.5297718, 126.9647415, '서울특별시 용산구 한강대로21나길 7', '조선을 건국한 태조 이성계의 공덕으로 재건된 연복사 오층불탑의 건립내력을 담은 비석이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01827', '보강천 미루나무숲', '관광지', 36.78834006, 127.5810146, '충청북도 증평군 증평읍 송산리 649-45', '증평의 역사와 전통문화를 만날 수 있는 문화공간으로 증평의 문화재, 옛 사진, 출토유물, 고서, 민속품 등 다양한 문화유산을 관람할 수 있으며, 농경문화체험과 전시연계교육 등 종합적인 교육체험을 할 수 있음', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01828', '증평인삼문화센터', '관광지', 36.79588146, 127.5817602, '충청북도 증평군 증평읍 중부로 2451', '보강천 수변에 위치하고 형형색색 이국풍의 꽃과 풍차, 분수, 놀이터 등 다양한 휴식공간을 갖추며, 산책뿐만 아니라 사진을 찍으며 추억을 쌓기 좋은 곳, 증평인삼골 축제 개최', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01829', '에듀팜특구관광단지(벨포레리조트)', '숙박', 36.84514868, 127.5821182, '충청북도 증평군 도안면 벨포레길 346', '지역 농특산물인 인삼을 판매하는 대표 인삼판매장', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01830', '서울 한양도성(서울성곽)', '관광지', 37.551483, 126.9853756, '서울특별시 용산구 후암동 산1-2', '조선왕조 도읍지인 한성부의 경계를 표시하고 그 권위를 드러내며, 외부의 침입을 막기 위해 축조된 성이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01831', '일제 경성호국신사 계단(108계단)', '관광지', 37.546023, 126.982542, '서울특별시 용산구 신흥로22가길 33', '1951년 해병대 초대교회로 시작되었으며, 우리나라 군(軍)에 남아있는 교회 중에서 가장 오래된 교회이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01832', '찬바람재', '관광지', 37.534815, 126.987014, '서울특별시 용산구 녹사평대로 195', '일제강점기 경성호국신사에 참배하기 위해 오르던 진입로로, 완공까지 한국인들의 재산과 노동력이 동원되었다. 일제 말기 식민지 한국이 처했던 비극의 역사를 선명하게 보여주는 장소이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01833', '옛 남영동 대공분실(현 민주화운동기념관)', '쇼핑', 37.54101166, 126.9716345, '서울특별시 용산구 한강대로71길 37', '예전부터 겨울철 찬바람이 매섭게 몰아친다 하여 찬바람재 또는 한풍재라고도 불리던 곳이다. 현재는 이 일대를 푸른 풀이 무성한 들판이라는 뜻의 녹사평이라고 부르고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01834', '옛 용산공설시장(현 남영아케이드)', '쇼핑', 37.543723, 126.972924, '서울특별시 용산구 한강대로84길 7', '1970~80년대 민주주의를 억압하며 악명을 떨쳤던 남영동 대공분실은 1976년 지상5층 규모로 신축되어 치안본부 대공과 대공분실로 사용되었다. 2023년경 민주주의와 인권의 가치를 수호하는 민주인권기념관으로 정식 개관할 예정이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01835', '고씨굴 playground', '쇼핑', 37.13117779, 128.5352623, '강원특별자치도 영월군 김삿갓면 영월동로 1111', '1922년 일제가 설치한 시장으로 지금은 남영아케이드로 불리고 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01836', '스포원파크', '관광지', 35.28912108, 129.1070434, '부산광역시 금정구 체육공원로399번길 324', '천연기념물 제219호로 지정된 석회동굴 playground', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01837', '한국이슬람부산성원', '관광지', 35.25998626, 129.0922564, '부산광역시 금정구 금단로 113-13', '스포원파크는 기존의 경기장과는 달리 ‘공원’과 ‘개방’의 개념을 도입한 ‘공원형 경기장’으로서 쾌적한 환경여건을 가지고 있어 건강과 휴식을 위한 명소로 사랑받고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01838', '요산문학관', '관광지', 35.27236562, 129.085732, '부산광역시 금정구 팔송로 60-6', '부산의 유일한 한국이슬람 부산성원은 이슬람 신자들에게는 네트워킹 장이자 쉼터로, 지역민들에게는 이슬람 문화를 체험하고 강연을 접할 수 있는 장소로 자리 잡고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01839', '오륜대한국순교자박물관', '관광지', 35.24570172, 129.1009016, '부산광역시 금정구 오륜대로 106-1', '일제강점기의 잔인했던 시절 속 궁핍한 현실을 작품에 담은 요산 김정한 선생의 문학 정신과 삶을 기리는 문학관은 요산 선생의 생가와 연접해 그의 숨결을 더욱 깊이 느낄 수 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01840', '부산대젊음의거리', '관광지', 35.229587, 129.0888177, '부산광역시 금정구 장전온천천로 51', '한국 가톨릭 순교자들의 신념을 기억하기 위해 건립된 오륜대한국순교자박물관에는 한국 순교자들의 유물뿐만 아니라 역사적 의미가 있는 자료들도 함께 전시·보존하여 더욱 의미가 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01841', '금정산성마을', '관광지', 35.250339, 129.0561338, '부산광역시 금정구 산성로 452', '청춘들의 꿈, 열정, 자유가 넘치는 부산대 젊음의 거리는 색다른 문화공연과 프리마켓 등 다양한 행사가 날마다 이어진다. 골목골목 위치한 상점에서 청춘의 열기를 느낄 수 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01842', '도림사', '관광지', 35.26727743, 127.2575047, '전라남도 곡성군 곡성읍 도림로 175', '금정산성마을은 금정산 해발 400m의 분지에 아담히 자리잡은 산성마을로 금정산 능선이 병풍처럼 둘러싸고 있는 아름다운 자연환경을 갖추고 있어 휴일이면 이곳을 찾는 등산객들의 발길이 끊이지 않는다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01843', '천안종합휴양playground', '관광지', 36.75731215, 127.2240961, '충청남도 천안시 동남구 성남면 종합휴양지로 200', '곡성읍에서 서남쪽으로 4km 떨어진 동악산 줄기인 형제봉(성출봉) 중턱에 자리잡은 도림사는 신라 무열왕 7년(660)에 원효대사가 화엄사로부터 이주하여 지었다고 전해지며 현재는 응진당, 지장전, 칠성각, 요사채 등이 있고 절 입구에는 허백련 화백이 쓴 「도림사」라는 현판이 걸려있다. 도선국사, 사명대사, 서산대사 등 도인이 숲같이 많이 모여들었다 하여 도림사라 하는데, 인근에는 도림사 계곡이 있다. 해발 748.5m의 동악산 남쪽 골짜기를 흘러내리는 것으로 동악계곡, 성출계곡과 더불어 아홉구비마다 펼쳐진 반석 위로 맑은 물줄기가 마치 비단을 펼쳐 놓은 듯이 흐르고 수맥이 연중 그치치 않을 뿐만 아니라 노송, 계곡, 폭포들이 어우러져 절경을 이루고 있는 도림사 계곡은 지방 기념물 101호로 지정되어 있다.주변의 경치를 감상할 수 있는 반석들이 있어 예부터 풍류객들의 발길이 잦았으며 이곳 9개의 반석에는 선현들의 문구가 음각되어 있어 그들의 풍류를 엿볼 수 있고 한 아름 반석 위로 흐르는 계곡 물에 몸을 담그는 맛이 색다르다. 그리고 이 계곡 정상 부근에는 이곳에서 바라보는 전망이 좋아 신선이 쉬어 간다고 하는 높이 4m에 넓이 30평에 달하는 신선바위가 있으며 멀리 보이는 형제봉은 등산로 코스로 널리 알려져 있다. 인근에 도림사를 찾는 많은 관광객에게 좋은 휴식처가 되고 있는 도림사는 1984년 지방문화재자료 22호로 지정되었고 사찰내에는 도유형문화재 119호 괘불(掛佛)이 소장되어 있다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01844', '태조산playground', '관광지', 36.82207666, 127.1889559, '충청남도 천안시 동남구 태조산길 261', '중부권 최대의 온천playground로 워터파크, 휴양콘도, 천안예술의 전당이 있음.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01845', '광덕계곡playground', '관광지', 38.07630808, 127.4817356, '강원특별자치도 화천군 사내면 포화로 582', '유량동 태조산 아래에 자리잡힌 넓은 공원으로 천안시민들의 문화ㆍ휴식 공간', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01846', '용대playground', '숙박', 38.18568475, 128.3061965, '강원특별자치도 인제군 북면 십이선녀탕길 16', '광덕계곡은 백운산과 광덕산 사이에 위치하며 자연경관이 수려하고 오염되지 않은 작은폭포, 작은소 등 개끗한 물이 일품이다. 숙박시설이 마련되어 있어 여름 피서지로서 안성맞춤이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01847', '연희네슈퍼(영화 1987 촬영지)', '관광지', 34.78174519, 126.3773176, '전라남도 목포시 해안로 127번길 14-2', '설악산국립공원의 내설악지역에 위치하고 있으며 십이선녀탕, 만해마을, 백담사, 황태덕장, 하천 등이 playground 주변이 있음', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01848', '목포해상케이블카', '관광지', 34.79940179, 126.3700239, '전라남도 목포시 해양대학로 240', '목포춤추는바다분수는 매년 4월부터 11월까지 8개월간 목포 평화광장 앞바다에서 음악과 분수, 워터스크린, 레이저, 빔프로 젝트를 이용한 미디어 아트 작품을 선보이고 있다. 목포춤추는바다분수는 수반길이 150m, 높이 13.5m, 최대분사 높이 70m의 세계최초 초대형 부유식 바다음악분수이다.이에 더해 2021년 10월부터는 바다분수 앞에 설치한 해상무대에서 불꽃과 바다분수가 어우러진 환상적인 해상공연을 펼칠 예정이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01849', '산정호수', '쇼핑', 38.065669, 127.315722, '경기도 포천시 영북면 산정호수로411번길 5 일원', '삼학도 계류장을 출발하여 해상케이블카타워, 인어동상, 목포대교로 간다.잔잔한 목포 앞바다를 배를 타고 노니는것은 또 다른 경험이다. 오른쪽으로 높이오른 유달산과 목포대교의 일몰, 끝없이펼쳐진 다도해 그리고 고하도의 해안을감상할 수 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01850', '백운계곡', '관광지', 38.072165, 127.409889, '경기도 포천시 이동면 포화로 236-24 일원', '백운산에서 흘러내린 맑은 물이 계곡을 이룬곳으로 경관이 수려함', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01851', '용문산 playground', '관광지', 37.54529617, 127.583066, '경기도 양평군 용문면 용문산로 641', '명성산 밑에 위치한 호수로 경관이 둘레길이 잘 조성되어 있고, 가을 억새로 장관을 이룸', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01852', '두물머리', '관광지', 37.53362262, 127.3174715, '경기도 양평군 양서면 두물머리길 145', 'playground를 품에 안고 있는 용문산의 웅장한 산세와 기암괴석이 만들어 낸 절경은 금강산을 방불케 한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01853', '기독교선교100주년기념관', '숙박', 35.04305027, 127.6604508, '전라남도 광양시 진상면 성지로 399', '쉼을 주는 공원으로 맑은공기+ 숙박+ 치유+ 체험과 교육이 함께하는 전국 최초 산림문화 휴양단지', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01854', '섬진강 망덕포구', '관광지', 34.96787088, 127.7579265, '전라남도 광양시 진월면 망덕길 171', '기독교역사관, 유품전시관', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01855', '춘장대', '관광지', 36.16334922, 126.5243355, '충청남도 서천군 서면 춘장대길 20', '550리 섬진강과 남해바다가 만나는곳, 윤동주시인 유고보존 정병욱 가옥', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01856', '박경리기념관', '관광지', 34.802301, 128.4035792, '경상남도 통영시 산양읍 산양중앙로 173', '국내 유일의 해송림 해수욕장으로 캠핑장과 조개잡이 체험등 다양한 즐길거리와 인근 동백정 마량항등 볼거리도 풍부', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01857', '해저터널', '관광지', 34.83609021, 128.411698, '경상남도 통영시 당동 1-3', '통영이 낳은 대 소설가 박경리 선생님의 문학적 업적을 기리고 독창적이고 차별화된 문화콘텐츠를 육성하기 위해 기념관 건립함.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01858', '장사도해상공원', '관광지', 34.71373747, 128.5588706, '경상남도 통영시 한산면 장사도길 55', '동양 최초의 바다 밑 터널', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01859', '통영시립박물관', '관광지', 34.84075153, 128.4167887, '경상남도 통영시 중앙로 65', '바다위의 공원으로 배를 타고 입장.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01860', '삼도수군통제영', '관광지', 34.84715495, 128.423489, '경상남도 통영시 세병로 27', '통영시립박물관은 통여의 소중한 문화자산을 잘 보존, 전시하여 후대에까지 전하려고 합니다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01861', '운일암반일암', '관광지', 35.97596963, 127.408748, '전북특별자치도 진안군 주천면 동상주천로 1924', '이충무공의 숨결이 살아있는 통제영은 삼도수군통제영의 약칭으로 삼도수군통제사가 경상,전라,충청 3도의 수군을 지휘하던 본영을 말한다. 최초의 통제영은 임진왜란 당시 초대 통제사로 제수된 이순신장군의 한산 진영이였다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01862', '마이산도립공원 일원', '관광지', 35.75700898, 127.3938329, '전북특별자치도 진안군 마령면 마이산남로 182', '기암괴석과 크고 작은 폭포, 소가 어울려 빚어낸 절경', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01863', '용담호및주변시설', '관광지', 35.94593497, 127.5256742, '전북특별자치도 진안군 안천면 안용로 793', '마이산은 암마이봉(686m)과 수마이봉(680m)으로 진안읍 단양리와 마령면 동촌리 경계면에 걸쳐있다. 신라시대 서다산(西多山), 고려시대 용출산(聳出山), 조선 초 속금산(束金山)에서 현재는 말의 귀를 닮았다는 의미의 마이산(馬耳山)으로 불리고 있다. 1979년 전라북도 도립공원으로 지정되었고 2003년 10월 31일에는 마이산 권역 160여 ㎢가 명승 제12호 국가지정문화재로 승격되어 진안군수가 위탁 관리한다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01864', '운장산자연휴양림', '관광지', 35.89924607, 127.4211096, '전북특별자치도 진안군 정천면 휴향림길 77', '댐으로 만들어진 인공호수로써 높이 70m, 길이 498m, 저수량이 8억1,500톤에 이르고 댐주위로 난 이설도로를 따라 여러가지 볼거리가 구비되어 있다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01865', '데미샘자연휴양림', '관광지', 35.6569938, 127.4610402, '전북특별자치도 진안군 백운면 데미샘1길 172', '약7㎞에 달하는 운장산 계곡은 원시림과 옥류수가 연중 흐르고 순환임도와 연접하고 여러가지 기암바위들이 자연수목과 조화를 이룬다', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01866', '진안고원치유의숲', '관광지', 35.87516093, 127.4177407, '전북특별자치도 진안군 정천면 봉학로 171-22', '데미샘은 3개도 10개 시군에 걸쳐 218.6㎞를 흐르는 우리나라에서 4번째로 긴강인 섬진강의 발원지이다', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01867', '가위박물관', '음식점', 35.76592077, 127.4150023, '전북특별자치도 진안군 진안읍 마이산로 258', '전국 최초로 설립된 환경성질환 예방교육시설이다. 생활치료 공간으로 교육관과 생활관, 체험관, 유기농식당을 갖추고 있다. 방학과 주말은 물론 평일에도 아토피로 고통받는 어린이와 가족들이 함께행활하면저 치유할수 있다', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01868', '은파playground', '관광지', 35.95536227, 126.6890748, '전북특별자치도 군산시 은파순환길9 (나운동)', '세계유일의 가위박물관, 진안가위박물관, 마이산북부에 위치하고 세계 희귀 가위 1500여점을 소장', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01869', '금강호playground', '관광지', 36.01987856, 126.7653058, '전북특별자치도 군산시 성산면 철새로 120', '봄철이 되면 화사한 벚꽃길로 유명하여 시민들의 사랑을 받고 있다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01870', '꽃보라동산', '관광지', 35.88935018, 128.601059, '대구광역시 북구 산격동 1500-6', '국내 최대 철새도래지로서 자연과 문화가 어우러지는 사계절 playground로 거듭나고 있음', '대구');
