INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01873', '광양 옥룡사지', '관광지', 35.04701721, 127.6085305, '전라남도 광양시 옥룡면 추산리 산 35-1', '교육장, 야영장, 수영장, 산책로', '전남');
