INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01875', '산청중산playground', '숙박', 35.293297, 127.7549317, '경상남도 산청군 시천면 지리산대로 525', '숙박, 물놀이장, 야외공연장', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01876', '산청금서playground', '관광지', 35.394237, 127.847052, '경상남도 산청군 금서면 친환경로 1715', '수려한 자연경관과 지리산 천왕봉을 조망할 수 있는 산악형 playground', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01877', '신지명사십리해수욕장', '관광지', 34.327329, 126.8088597, '전라남도 완도군 신지면 명사십리길 85-105', '수려한 자연경관을 조망할 수 있는 가족단위 형태의 playground', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01878', '해조류센터', '관광지', 34.320789, 126.748793, '전라남도 완도군 완도읍 해변공원로 84', '모래 우는 소리가 십리 밖까지 들린다고 하여 울모래 또는 명사십리로 불리우며, 2019년 우리나라 최초로 블루플래그(친환경 안전해변)해변으로 지정되었다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01879', '예당playground', '관광지', 36.63801252, 126.799434, '충청남도 예산군 응봉면 예당관광로 161', '2014년 3월에 개관한 완도국제해조류박람회 주제관으로 특산품 홍보관과 해조류 전시실로 구성되어 있다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01880', '덕산온천관광단지', '관광지', 36.69075649, 126.659328, '충청남도 예산군 덕산면 온천단지2로 11', '예당호를 배경으로 예당호 출렁다리, 예당호 조각공원, 느린호수길, 캠핑장, 야영장이 조성되어 있어 가족단위 휴양객이 즐길수 있는 playground', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01881', '보수동책방골목', '관광지', 35.10323904, 129.0263248, '부산광역시 중구 대청로 57-1', '1917년 처음으로 탕을 이용한 온천으로 개장됐으며, 49도씨 이상의 천연중탄산나트륨 온천수로 전국 최고의 온천수로 인정받고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01882', '용두산공원', '관광지', 35.1009305, 129.0324434, '부산광역시 중구 용두산길 37-55', '보수동 책방골목은 국제시장 입구 대청로 사거리 건너 보수동쪽으로 난 사선 방향의 좁은 골목길에 집결된 책방을 말한다. 8.15광복 직후 오늘날의 국제시장이 태평양전쟁으로 주택가가 철거되어 빈터로 놓여 있을 때 일본인이 남기고 간 책을 난전을 벌여 팔았는데, 그 장소가 개인소유가 되자, 보수동 앞길로 책장사들이 한 두 사람 자리를 옮겨 앉게 되면서부터 오늘의 골목이 형성되는 바탕이 되었다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01883', '광복로', '관광지', 35.09947039, 129.0311659, '부산광역시 중구 광복중앙로 1', '부산의 역사가 살아 숨쉬고 있는 대표적 관광명소로서 부산의 상진인 120m 높이의 부산타워, 부산 시민의 종, 충무공 이순신 동상, 미술전시관 등이 조화롭게 조성되어 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01884', '부산영화체험박물관', '관광지', 35.10169342, 129.033594, '부산광역시 중구 대청로126번길 12', '부산영화체험박물관은 대한민국을 대표하는 영화체험 복합문화공간입니다. 전국 최초의 영화관련 전문전시체험시설로 지상지상 4층, 지하 3층으로 구성된 본 체험박물관은 영화의 원리를 이해하고 제작의 즐거움을 체험할 수 있는 다양한 전시시설 및 영화의 과거와 미래를 연결하는 하이테크 시네마를 갖추고 있습니다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01885', '운암지수변공원', '관광지', 35.93241418, 128.5674979, '대구광역시 북구 구암동 349', '대구광역시 북구 8경사진찍기좋은명소', '대구');
