INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01890', '침산정', '관광지', 35.897221, 128.5848591, '대구광역시 북구 침산남로9길 118', '대구광역시 북구 8경사진찍기좋은명소', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01891', '달성토성마을', '관광지', 35.87331563, 128.5753765, '대구광역시 서구 국채보상로 83길 21 (비산동) 일대', '대구광역시 북구 8경사진찍기좋은명소', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01892', '신라불교초전지', '숙박', 36.29090918, 128.3633378, '경상북도 구미시 도개면 도개다곡길 389-46', '고구려 승려 아도화상이 산라에 불교를 처음 전한 곳으로, 전통한옥숙박체험, 사찰음식체험(유료) / 신라불교초전기념관, 전시가옥(무료) 등 신라문화를 재현하여 체험할 수 있음', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01893', '마니산 국민playground', '관광지', 37.63245827, 126.4237957, '인천광역시 강화군 화도면 마니산로675번길 18', '백두산과 한라산의 중간지점에 위치하여 우리나라에서 기가 가장 센 곳이며 정상에 있는 참성단에서 매해 제례를 올리고 칠선녀가 전국 체육대회의 성화를 채화함', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01894', '롯데월드 부산', '관광지', 35.19603043, 129.2129711, '부산광역시 기장군 기장읍 동부산관광로 42', '부산광역시 기장군 기장읍 시랑리 산46에 위치한 테마파크. 줄여서 부롯이라 부른다. 오시리아관광단지 테마파크존 내에 조성된 핵심시설로, 서울에 있는 롯데월드 어드벤처와 부산 롯데월드 스카이프라자, 롯데월드 언더씨킹덤에 이은 롯데월드의 4번째 테마파크이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01895', '농월정', '관광지', 35.62464301, 127.7815571, '경상남도 함양군 안의면 농월정길 9-35', '안의 삼동 중에서 화려한 자연의 미를 간직한 곳이 화림동이다. 화림동은 안의에서 전북 장수군으로 통하는 국도 26호선을 따라 약 4km를 가면 굽이치는 물가에 아담한 마을하나를 발견할 수 있는데, 이 곳이 화림동의 정수 농월정이 있는 곳이다. 화림동은 남덕유산에서 발원하는 금천이 굽이치며 흘러 팔담팔정을 이루었다. 그래서, 옛부터 화림동을 정자문화의 보고라 한다. 지금도 농월정을 비롯한 4개의 고풍스런 정자가 남아 있다. 특히 농월정은 달을 희롱하며 논다는 옛날 우리 선조들의 풍류사상이 깃든 곳, 함양을 찾은 많은 시인과 묵객들이 필히 거쳐간 곳이다. 이 곳 녹수를 사이에 둔 양쪽 산기슭의 송림은 거문고 현을 퉁기는 듯하며, 길게 늘어선 수양버들은 천줄기의 실로 낚시질을 하는 듯 보인다. 맑은 물이 급한 굴곡을 이루는 곳에 커다란 반석이 펼쳐져 있다. 반석위를 흐르는 물이 달빛을 받아 금물결을 이루는 이 곳에 세워진 고색창연한 농월정은 이름 그대로 달을 희롱하고 있는 듯하다. 크기를 짐작할 수 없을 정도로 거대한 월연암이라 이름 붙은 너럭바위 위로 미끄럼타듯 물살이 세차게 흐르고, 물길따라 골이 깊게 패였다. 월연의 맑은 물에서 물장구치며 노는 개구쟁이들의 모습과 아름다운 풍경은 한 폭의 동양화가 되어 지나는 행인의 발걸음을 멈추게 한다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01896', '유달산', '관광지', 34.79142993, 126.3759183, '전라남도 목포시 유달로 180', '노령산맥의 맨 마지막 봉우리이자 다도해로 이어지는서남단의 땅 끝인 산 해발 228미터 기암괴석으로 이루어진 유달산은 노령산맥의 맨 마지막 봉우리이다. 정상에 올라 서면 목포 시내가 한눈에 내려다보이며 푸른 다도해의 경관이 시원스레 펼쳐져 있고 그 사이를 오고가는 크고 작은 선박들의 모습이 한폭의 동양화를 연상시킨다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01897', '서산동 시화골목', '관광지', 34.78174519, 126.3773176, '전라남도 목포시 해안로 127번길 14-2', '지역의 시인과 화가 그리고 주민들이 참여하여 생활적인 시와 벽화를 구성해 놓은 곳이다.개발되지 않은 1970 ~ 80 년대 해안가 마을의 골목길을 보존해 당시의 생활적 정서를 엿볼 수 있는 대표적인 레트로 공간이다. 초입에 1987의 촬영지 연희네 슈퍼가 있어 조화를 이루고 있다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01898', '대둔산도립공원', '관광지', 36.11708032, 127.3328815, '전라북도 완주군 운주면 대둔산공원길 23', '사계절이 모두 아름다운 완주의 자랑이자 보물인 산', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01899', '방화동가족휴가촌', '관광지', 35.59064179, 127.5268761, '전북특별자치도 장수군 번암면 방화동로 778', '전국 8대종산에 속하는 장안산 기슭을 따라 펼쳐지는 맑고 깨끗한 계곡을 끼고 조성된 국민 휴양지', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01900', '장사해수욕장playground', '관광지', 36.2824187, 129.3755938, '경상북도 영덕군 남정면 동해대로 3592', '해수욕장의 청정 자연자원과 장사상륙작전이라는 역사적 사건을 보존한 playground', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01901', '양천향교', '관광지', 37.572863, 126.839905, '서울특별시 강서구 양천로47나길 53', '조선 태종 11년(1411년)에 만들어졌으며 현재 서울에 남아있는 유일한 향교이다. 이름 때문에 양천구에 위치한 것으로 오해할 수 있으나 실제로는 강서구 가양동에 위치하고 있다. 인근에 위치한 서울 지하철 9호선 양천향교역 역시 이 곳의 이름을 따서 제정되었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01902', '약사사', '관광지', 37.58312625, 126.8050072, '서울특별시 강서구 금낭화로17길 261', '서울 강서구 관내 전통사찰 중 제1의 위상을 지닌 대한불교조계종 직할교구 사찰', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01903', '서울양천고성지', '관광지', 37.57425363, 126.8413319, '서울특별시 강서구 양천로47나길 52-54', '양천고성지는 양천향교의 뒷산인 궁산에 있는 옛 성터. 백제 22대 문주왕이 웅진으로 천도(475년)하기 전 강 건너 고구려 침입에 대비하기 위해 쌓은 성으로 조선 성종(1470년)까지 요새가 있었던 것으로 짐작된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01904', '허가바위', '관광지', 37.56983571, 126.8500301, '서울특별시 강서구 허준로5길 15', '옛날 석기 시대의 사람들이 이곳에서 살았으리라 짐작되는 혈거동굴로서 연구 가치가 매우 높다. 허준은 허가바위에서 『동의보감』을 완성했다고 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01905', '허준근린공원', '관광지', 37.56759867, 126.8537291, '서울특별시 강서구 허준로5길 42', '공원주위에는 서울 기념물 제11호인 허가바위가 있고 공원내에는 전설이 깃든 광주바위와 허준 선생이 앉아서 병자를 진료하는 인자한 모습의 동상 그리고 호수 정자 어린이 놀이 시설이 있으며 인근 주민들의 휴식공간으로 이용되고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01906', '궁산땅굴역사전시관', '관광지', 37.57266746, 126.8383649, '서울특별시 강서구 양천로49길 106', '궁산 땅굴은 태평양전쟁 말기 일제 강점기에 굴착된 곳으로, 무기나 탄약 등, 군수물 자를 저장하거나 김포 비행장을 감시하고, 공습 때에는 부대 본부로 사용하기 위한 곳이었다고 전해진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01907', '안성남사당공연장', '관광지', 37.03181804, 127.310053, '경기도 안성시 보개면 남사당로 198-2', '안성맞춤랜드 내 위치한 안성남사당 상설공연용 공연장', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01908', '안성맞춤랜드', '관광지', 37.0328236, 127.3078038, '경기도 안성시 보개면 남사당로 198', '안성의 최대규모 시민공원', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01909', '안성시사계절썰매장', '관광지', 37.0312917, 127.3114616, '경기도 안성시 보개면 남사당로 198-3', '사계절 운영하는 썰매장', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01910', '안성맞춤천문과학관', '관광지', 37.03291074, 127.3125372, '경기도 안성시 보개면 남사당로 198-9', '안성 유일한 천문과학관', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01911', '안성맞춤공예문화센터', '관광지', 37.03497838, 127.3108743, '경기도 안성시 보개면 남사당로 198-11', '공방체험 및 전시문화공간', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01912', '안성맞춤박물관', '관광지', 37.011318, 127.228354, '경기도 안성시 대덕면 서동대로 4726-15', '안성맞춤박물관은 안성유기를 중심테마로2002년 8월 1일에 개관한 시립박물관이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01913', '안성3.1운동기념관', '쇼핑', 37.06278592, 127.1752942, '경기도 안성시 원곡면 만세로 868', '3.1운동의 전국 3대 실력 항쟁지 중 한 곳으로 가장 극렬하게 만세항쟁을 펼쳐 일제를 몰아내고 2일 간의해방을 이뤄냈던 4.1만세 항쟁의 집결지였던 만세고개 일원을성역화하여 선열들의 숭고한 자주독립 정신을 발전시키고 후세들에게 나라사랑의 산 교육장으로 활용하기 위해 건립하였다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01914', '박두진문학관', '관광지', 37.03497856, 127.3108743, '경기도 안성시 보개면 남사당로 198-11', '안성출신 시인 박두진의 삶과 문학적 발자취를 소개하고 전시하는 곳이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01915', '회동수원지', '관광지', 35.24707332, 129.115753, '부산광역시 금정구 오륜대로258', '조선시대부터 아름다운 풍경으로 유명한 회동수원지는 금정구를 대표하는 도심 속 힐링 명소이다. 땅뫼산 황토숲길, 편백나무숲, 오륜대 전망대는 일상 속 휴식처가 되어 준다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01916', '서동미로시장', '쇼핑', 35.21586987, 129.102466, '부산광역시 금정구 서동로141번길 16', '서동미로시장은 아름다운 길(美路)이라는 의미이자 골목마다 형성된 상권이 미로같다 하여 이름 붙은 문화관광형 시장이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01917', '덕포진교육박물관', '관광지', 37.6506248, 126.5387862, '경기도 김포시 대곶면 덕포진로103번길 90', '분류 : 사적 제292호소재지 : 김포시 대곶면 덕포진로103번길 224-4시대 : 조선강화만을 거쳐 서울로 진입하는 길목인 손돌목에 천혜의 지형을 이용해 설치한 조선시대의 군영 덕포진은 신미양요와 병인양요 때 서구 열강과 치열하게 싸웠던 격전지로 역사적 가치와 유물사적 의의를 가진 곳이다.1981년 전 문화원장 김기송씨가 사비를 들여 발굴작업이 시작되었다. 현재는 포대와 파수대가 복원되었고 2007년 새 단장한 덕포진 유물전시관에는 조선 후기 사용했던 포의 위치와 포의 유효거리 등을 쉽게 이해할 수 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01918', '다도박물관', '쇼핑', 37.7375035, 126.5744366, '경기도 김포시 월곶면 애기봉로275번길 187-49', '지상3층 규모로 다도전시장과 조각공원, 다도체험장, 연못, 정자, 투호장 등 부대시설과 잔디광장을 갖춘 복합예술 공간으로 자연을 벗삼아 다도 및 전통예절, 민속놀이 체험을 할 수있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01919', '김포국제조각공원', '관광지', 37.72080378, 126.552204, '경기도 김포시 월곶면 용강로13번길 38', '통일을 주제로 조성된 테마공원으로 세계적인 조각의 작품 30여점이 전시되어 있다. 산책로를 따라 조각작품이 전시되어 있어 산림욕을 즐기면서 조각작품을 감상할 수 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01920', '경천대playground', '관광지', 36.45722382, 128.2478641, '경상북도 상주시 사벌국면 경천로 652', '낙동강 1300여 리 물길 중 강의 이름이 되었을 정도로 태고의 신비를 간직한 경천대는 깎아지른 절벽과 노송으로 이루어진 절경이 빼어난 곳으로 하늘이 스스로 내렸다고 해 자천대라고도 함', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01921', '회상나루playground', '관광지', 36.44187503, 128.2657793, '경상북도 상주시 중동면 갱다불길 97', '낙동강 회상나루의 새로운 해석과 재현을 통해 주막 · 역원 등을 소재로 전통한옥으로 지은 주막촌, 객주촌, 낙동강 문학관 등이 조성되어 관광객들에게 편의를 제공함', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01922', '용아생가', '관광지', 35.14942906, 126.7951682, '광주광역시 광산구 소촌로46번길 24', '김영랑·정지용·정인보 등과 문학 동인으로 활동하였던, 한국 서정시 발전에 선구적 역할을 한 용아 박용철(1904∼1938) 선생의 생가이다.', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01923', '호가정', '관광지', 35.08243286, 126.7871342, '광주광역시 광산구 동곡분토길 195', '조선시대 문신 설강 유사 선생이 지은 정자로 큰 소리로 노래 부른다라는 의미를 담고 있다고 하며 광산 8경 중 한 곳으로 선정될 만큼 풍광이 수려하고 유서깊은 곳이다.', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01924', '신창동 유적체험학습관', '관광지', 35.19348956, 126.8504632, '광주광역시 광산구 북문대로 396-2', '초기 철기의 생활에 대한 동영상 시청 등을 포함한 그 시대 체험 박물관', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01925', '가천박물관', '관광지', 37.41847997, 126.6576026, '인천광역시 연수구 청량로102번길 40-9', '인천지역 유일한 국보를 포함한 총소장품 18382점', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01926', '에버랜드', '관광지', 37.2940667, 127.202128, '경기도 용인시 처인구 포곡읍 에버랜드로 199', '경기도 용인시 처인구 포곡읍 에버랜드로 199에 위치한 테마파크. 현재까지 대한민국 최대 규모의 놀이공원 및 동물원이 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01927', '한국민속촌', '관광지', 37.25913189, 127.1225431, '경기도 용인시 기흥구 민속촌로 90', '한국의 전통문화와 민속적인 삶을 재현하고 있는 곳으로 이를 통해 조상들의 지혜와 생활 모습을 느낄 수 있는 곳이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01928', '공릉playground', '관광지', 37.74984994, 126.8335561, '경기도 파주시 조리읍 장곡로 218', '공릉호의 수려한 자연환경을 즐길 수 있으며 유원시설, 캠핑장, 산책로를 갖춘 playground', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01929', '임진각playground', '관광지', 37.88953876, 126.7401859, '경기도 파주시 문산읍 임진각로 177', '임진각playground는 6.25전쟁의 비극이 그대로 남아있는 대한민국 대표 평화playground로, 망배단, 6.25납북자기념관, 자유의다리 등이 소재하고 있으며, 3만평 규모의 평화누리공원이 조성되어 있음. 평화교육의 공간이자, 가족단위 나들이 장소로 매년 100만명이 방문하고 있음.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01930', '회산백련지', '관광지', 34.86008886, 126.5298981, '전라남도 무안군 일로읍 백련로 333', '동양 최대의 백련서식지, 수상유리온실, 수생식물생태관, 생태탐방로, 야외물놀이장, 오토캠핑장 등 다양한 시설을 갖추고 있어 체험과 관광을 동시에 즐길수 있음', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01931', '향일암', '관광지', 34.59379448, 127.8029861, '전라남도 여수시 돌산읍 향일암로 60', '우리나라 4대 관음기도도량 중 하나로 전국 최고의 일출명소이다. 644년 원효대사에 의해 창건되었다고 전해진다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01932', '여수해상케이블카', '관광지', 34.7402223, 127.7529197, '전라남도 여수시 자산4길 39', '여수 돌산과 자산공원을 잇는 1.5km구간의 국내 첫 해상케이블카로 바닥이 투명한 크리스탈 캐빈 15대(5인승)와 일반 캐빈 35대(8인승), 총 50대가 운행되고 있다. 아찔한 스릴감과 함께 맛보는 다도해의 전망과 여수밤바다 풍경이 한눈에 들어온다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01933', '여수세계박람회장', '관광지', 34.75218956, 127.7465005, '전라남도 여수시 박람회길 1', '2012년 여수세계박람회를 성공적으로 개최한 장소로 단순 공원이 아닌 관광부터 비즈니스까지 원스톱으로 즐길 수 있는 전천후 복합문화체험공단.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01934', '여수해양공원', '관광지', 34.73676698, 127.7484079, '전라남도 여수시 하멜로 96', '해안선을 따라 조성된 1.5km 구간 시민공원으로 아름다운 여수 밤바다를 만끽 할 수 있는 최고의 휴식공간이다. 하멜등대, 해양케이블카, 돌산대교, 거북선대교, 장군도 등이 한눈에 보여 밤바다를 거닐 수 있는 필수 데이트 코스이며, 또한 각종 공연 및 행사가 다채롭게 열려 볼거리가 많다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01935', '예술랜드리조트', '숙박', 34.69510702, 127.7769452, '전라남도 여수시 돌산읍 무술목길 142-1,', '전 객실 오션뷰, AR로 체험하는 국내 최대 테마형 3D트릭아트뮤지엄, +60미터 미디어 터널과 150미터 암반터널을 통해 만나는 조각공원, 바다를 바라보는 여수 최대규모 1500평 인피니티 풀로 새로운 종합playground로 자리잡았다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01936', '여수이순신대교', '관광지', 34.88923653, 127.704929, '전라남도 여수시 묘도7길 110', '세계최고의 높이를 자랑하는 주탑높이(270m)는 63빌딩보다 높고 주탑간 거리 1,545m는 충무공 이순신 장군의 탄신해인 1545년을 기념하기 위한 것으로 웅장함과 탁 뜨인 바다 전경이 일품이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01937', '서산류방택천문기상과학관', '관광지', 36.72736, 126.41315, '충청남도 서산시 인지면 무학로 1353-4', '천상열차분야지도를 제작한 충남 서산 출신 고려말 천문학자 류방택 선생의 뜻을 기려 설립된 과학관', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01938', '서산버드랜드', '관광지', 36.63124, 126.37809, '충청남도 서산시 부석면 천수만로 655-73', '철새도래시기에는 천수만에 도래하는 철새들을 탐조투어를 통해 볼 수 있고 특별프로그램 기간에는 각종 체험행사 등을 경험할 수 있으며 4D 영상 등의 볼거리가 있음', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01939', '용현자연휴양림', '관광지', 36.75188, 126.60764, '충청남도 서산시 운산면 마애삼존불길 339', '용현계곡 한가운데 자리해 심산유곡의 경치를 자랑하는 산림휴양의 적지', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01940', '해미읍성', '관광지', 36.71356, 126.55038, '충청남도 서산시 해미면 남문2로 143', '500년 옛모습을 잘 간직한 조선시대 석축 읍성', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01941', '유니온파크', '관광지', 37.54654783, 127.2205032, '경기도 하남시 미사대로 710', '기존의 노후화 된 소각장, 재활용선별장, 음식물처리장, 중계펌프장 등의 시설 개선과 미사지구와 같은 택지개발사업 등으로 환경기초시설 확충이 요구됨에 따라 국내최초로 지하에 폐기물처리시설과 하수처리시설을 함께 설치한 신개념 환경기초시설이다. 지하에는 소각처리시설, 재활용선별시설, 음식물자원화시설, 하수처리시설 등이 설치되어 있고, 지상에는 잔디광장, 어린이물놀이시설, 다목적체육관, 야외체육시설 등 다양한 주민친화시설이 있는 하남유니온파크와 한강·검단산 등 하남의 아름다운 경관을 한눈에 조망할 수 있는 하남유니온타워(105m)가 설치되어있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01942', '이성산성', '관광지', 37.52530687, 127.1847777, '경기도 하남시 춘궁동 산 36', '6세기 중반경에 신라가 쌓은 것으로 추정되는 신라시대 산성', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01943', '미사경정공원', '관광지', 37.55362591, 127.2132296, '경기도 하남시 미사대로 505', '86아시안게임 및 88 서울 올림픽 당시 조정, 카누경기를 위해 만들어진 공원으로 조정호수를 중심으로 축구장, 족구장 등 스포츠시설을 비롯하여 매점, 자전거 대여 등 편의시설과 놀이시설을 갖춘 시민들의 여가선용 장소임', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01944', '오동도', '관광지', 34.7443435, 127.764121, '전라남도 여수시 오동도로 222', '동백을 비롯하여 194종의 울창한 의귀수목과 기암절벽이 자연스럽게 조화를 이룬 섬으로 한려해상국립공원에 속해있다. 동백꽃으로 유명한 여수의 대표 playground이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01945', '산토끼노래동산', '관광지', 35.57772326, 128.38358, '경상남도 창녕군 이방면 이방로 623', '국민 동요 ‘산토끼’의 유래지역인 창녕군 이방면에 어른들에게는 어린 시절의 추억을 떠올리고, 어린이들에게는 생생한 체험학습의 장을 마련하고자 조성된 어린이 및 가족단위의 생태체험 여행playground이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01946', '창녕 영산 만년교', '관광지', 35.45282939, 128.5283272, '경상남도 창녕군 영산면 동리 433', '창녕 영산 만년교는 정조 4년 축조되어 고종 29년에 중수한 무지개다리로 조선 후기 홍예교를 세운 방법을 알 수 있는중요한 자료이며, 봄이면 수양벚꽃과 개나리가 만개하여 한폭의 그림을 보는듯하다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01947', '인천가스과학관', '관광지', 37.34875022, 126.6077146, '인천광역시 연수구 인천신항대로960', '옥외조형물 5종+실내전시물 23개코너+크린타워', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01948', '인천상륙작전기념관', '관광지', 37.42070925, 126.6531798, '인천광역시 연수구 청량로160번길 26', '전시관+야외전시장+야외공연장+영상실+휴게실+전망대+소공원', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01949', '인천도시역사관', '관광지', 37.39281227, 126.6358879, '인천광역시 연수구 인천타워대로 238', '고대 및 근대 전시관+인천 모형관+IFEZ모형관', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01950', '목포근대역사관 1관 (구, 일본영사관)', '관광지', 34.78769578, 126.3817942, '전라남도 목포시 영산로 29번길 6', '목포 최초의 서구적 근대 건축물로 건립당시의 내·외관을 거의 그대로 유지하고 있으며 목포 개항 이후 1900년 12월 일본영사관으로 지어져 광복 이후 목포시청, 시립도서관, 문화원으로 사용하다가 현재는 목포 근대역사관 1관으로 운영중에 있다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01951', '목포근대역사관 2관 (구,동양척식주식회사)', '관광지', 34.78596374, 126.3814912, '전라남도 목포시 번화로 18', '구 동양척식주식회사 목포지점이었던 근대역사관2관은 1920년 6월에 건립된 일제시대 건축물로 1999년 11월 20일 전라남도 기념물 제174호로 지정.동양척식주식회사 건물 복원기념으로 사진이 전시되고 있다 2층건물에는 주요 근대역사자료와 관련한 상설전시중이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01952', '성옥기념관', '관광지', 34.78698576, 126.3798645, '전라남도 목포시 영산로 11', '조선내화(주)창업자인 성옥 이훈동 선생의 미수를 기리기 위해 자녀들이 건립한 문화공간으로 선생이 수집한 근 · 현대 작품, 다양한 고미술작품과 도자기 등을 감상 할 수 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01953', '도립미술관', '관광지', 34.96887104, 127.5903033, '전라남도 광양시 순광로 680-4', '2017년 말 착공 예정', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01954', '광양와인동굴', '카페', 34.96130264, 127.6085909, '전라남도 광양시 광양읍 강정길 33', '바닥 트릭아트, 세계 와인 전시, 와인 카페테리아, 오브젝트 맴핑, VR체험관 등', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01955', '광양역사문화관', '관광지', 34.9757671, 127.5859802, '전라남도 광양시 광양읍 매천로 829', '광양의 역사, 문화, 인물 자료 전시·설명', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01956', '백암온천 playground', '관광지', 36.72132775, 129.343467, '경상북도 울진군 온정면 온천로 7', '백암산 온천수를 이용한 온천playground', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01957', '맹방playground', '관광지', 37.39591618, 129.2207941, '강원특별자치도 삼척시 근덕면 상맹방길 30-80', '해수욕장을 중심으로 한 해변playground로 동해의 맑은 물과 명사십리라 일컬어진 긴 백사장과 인접 농경지 사이에 평행하게 형성된 곰솔 등의 자연적 환경 요소를 갖춤', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01958', '장호playground', '관광지', 37.2868038, 129.3079336, '강원특별자치도 삼척시 근덕면 삼척로 2154', '운동오락시설+오토캠핑장+카라반+야영시설 등 관광객 편의시설이 조성되어 운영되고 있으며+해상로프웨이 및 조경휴게지 등의 자연경관 감상을 위한 시설이 조성되어 운영되어 해마다 많은 관광객들이 방문', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01959', '초당playground', '관광지', 37.37650408, 129.2047561, '강원특별자치도 삼척시 근덕면 미근로 1629', '자연환경과 더불어 수려한 자연 지형을 그대로 살린 친환경 골프장은 기후 영향을 비교적 덜 받아 사계절 체류형 playground의 면모를 지니고 있음', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01960', '국립국악원', '관광지', 37.47835156, 127.0090736, '서울특별시 서초구 남부순환로 2364', '전통음악 및 무용의 계승과 발전을 위해 설립된 국립 음악기관으로 각종 국악 공연 및 연구, 진흥사업 등 다양한 활동을 펼치고 있다. 산하에 정악단, 무용단, 민속악단, 창작악단 등 네개의 전속 예술단과 예악당, 우면당, 풍류사랑방, 연희마당 등의 공연장, 국악박물관, 국악연수관 등의 시설을 갖추고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01961', '헌인릉', '관광지', 37.46537744, 127.0837156, '서울특별시 서초구 헌인릉길 36-10', '사적 제 194호인 이곳은 동쪽의 헌릉과 서쪽의 인릉으로 구성되어 있다. 헌릉은 조선 제3대 태종과 원경왕후 민씨의 쌍봉릉이며, 인릉은 조선 제23대 순조와 순원왕후 김씨의 동원합동 형태이다. 또한 헌인릉 오리나무 숲은 생태계적으로 가치가 높은 지역이며, 다양한 습지성 식물들이 번성하고 서울시 보호종인 오색 딱다구리, 제비, 꾀꼬리, 박새 등이 출현하는 지역이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01962', '선바위playground', '관광지', 36.60854407, 129.0820141, '경상북도 영양군 입암면 영양로 883-16', '절벽과 강을 사이에 두고 바위를 깎아 세운 듯한 선바위를 볼 수 있음', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01963', '진해해양레포츠센터', '관광지', 35.14129989, 128.6883002, '경상남도 창원시 진해구 천자로 160', '편리한 접근성과 저렴한 이용요금, 스쿨 전용 해상교육장 및 국가대표 출신 강사진 등 우수한 시설을 구비하고 있다. 쉽게 접하기 힘든 크루즈, 딩기요트, 윈드서핑, 카약, 래프팅보트, 바나나보트 등을 운영하고 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01964', '무주 덕유산 리조트', '숙박', 35.889797, 127.731389, '전북특별자치도 무주군 설천면 만선로 185', '덕유산의 수려한 자연환경을 느낄 수 있으며, 오스트리아풍의 건물들로 이루어진 산악형 리조트', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01965', '월봉서원', '관광지', 35.23583653, 126.7451862, '광주광역시 광산구 광곡길 133', '조선 전기의 문신인 기대승(1527∼1572)선생의 위패를 모시고 있는 사당으로 그 시대에 조선의 명신들을 함께 배향하였던 ‘월봉서원’의 강당이다. 기대승 선생은 성리학의 대가로서 새 학설을 제시하여 학계에 주목을 받았으며 스승인 이황 선생과 사단칠정을 주제로 8년 간 서신왕래를 한 것으로도 유명하다.', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01966', '무양서원', '관광지', 35.21001305, 126.8400956, '광주광역시 광산구 산월로21번길 26', '고려 인종 때 어의이면서 명신인 장경공 최사전을 중심으로 그의 후손 4명을 모시고 있는 서원으로 1927년에 전국 유림의 호응을 얻어서 세운 서원이다. 서원의 이름은 광주의 옛 지명에서 따 왔다.', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01967', '창녕 우포늪', '관광지', 35.54456088, 128.4191195, '경상남도 창녕군 유어면 우포늪길 220', '천연보호구역인 창녕 우포늪은 국내 최대 규모(2,505천㎡)의 자연내륙습지로 다양한 동식물이 서식하고 있는 자연생태게의 보고로 람사르습지에 등록되어있으며, 우포늪생명길을 따라 걸으며 다양한 동식물들을 만날수있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01968', '화왕산', '관광지', 35.54419647, 128.5344873, '경상남도 창녕군 창녕읍 옥천리 산322', '봄에는 진달래, 여름에는 녹음과 계곡, 가을에는 은빛 억새 물결 그리고 겨울 설경이 아름다운 화왕산은 가파른 코스부터 완만한 코스까지 다양한 등산코스가 있어 남여노소 누구나 즐길 수 있는 창녕의 진산이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01969', '부곡온천관광특구', '관광지', 35.4361725, 128.5916371, '경상남도 창녕군 부곡면 원앙로 218', '국내 최고의 수온 78℃로 이름난 부곡온천관광특구 내에 위치한 부곡온천 르네상스관은 부곡온천수의 우수성을 널리 홍보하고 부곡온천의 역사를 알 수 있는곳으로 다양한 콘텐츠를 체험할 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01970', '낙동강 유채단지', '관광지', 35.384718, 128.4715696, '경상남도 창녕군 남지읍 남지리 835-25', '단일면적 전국 최대 규모(110만㎡)인 낙동강 유채단지는 유채꽃의 명소로 유채꽃이 만개하는 매년 4월 공연, 체험, 먹거리 등 풍성한 즐길 거리가 있는 창녕 낙동강 유채축제가 열린다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01971', '창녕 남지 개비리', '관광지', 35.3945598, 128.4405466, '경상남도 창녕군 남지읍 용산리 160-2', '창녕 남지 개비리는 낙동강을 따라 가파른 벼랑에 난 오솔길로 수만 그루의 대나무로 이루어진 죽림이 있으며 계절에 따라 피고 지는 야생화와 낙동강의 윤슬을 보며 걷기 좋은 도보여행의 명소이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01972', '추암', '관광지', 37.477063, 129.159196, '강원특별자치도 동해시 촛대바위길 28', '애국가 첫 소절의 배경화면으로 유명한 각종 기암괴석이 조화를 이루는 촛대바위, 이 바위에 걸리는 아침 해돋이가 가히 장관이라 할 수 있어 관광객들이 가장 선호하는 해돋이 명소이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01973', '용마폭포공원', '관광지', 37.57335201, 127.0891138, '서울특별시 중랑구 용마산로 250-12', '동양 최대의 인공폭포가 있는 명소', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01974', '망우리공원', '관광지', 37.59835362, 127.1148164, '서울특별시 중랑구 망우로 570', '우리나라 근현대사 주요인물들이 영면하고 계신 역사와 문화가 살아 숨 쉬는 서울의 대표 공원', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01975', '중랑캠핑숲', '관광지', 37.60495511, 127.1099608, '서울특별시 중랑구 망우로87길 110', '학생소풍 및 가족단위 피크닉을 주제로 한 체험형 공원(캠핑장)', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01976', '옹기테마공원', '관광지', 37.61265372, 127.0885194, '서울특별시 중랑구 신내로21길 116', '다양한 전통문화 체험프로그램 참여가 가능한 옹기를 테마로 조성된 공원', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01977', '좌구산휴양랜드', '관광지', 36.70556821, 127.6511216, '충청북도 증평군 증평읍 솟점말길 107', '증평의 명산 좌구산에 조성된 휴양랜드로서, 휴양림, 캠핑, 명상구름다리, 명상의 집, 줄타기체험, 사계절썰매장 등 다양한 체험시설과 아름다운 풍경을 한눈에 담을 수 있음', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01978', '좌구산 천문대', '관광지', 36.70370345, 127.6530963, '충청북도 증평군 증평읍 솟점말길 187', '356mm 굴절망원경을 갖추어 천체의 생생한 모습과 좌구산의 맑고 깨끗한 밤하늘을 관찰할 수 있음', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01979', '치산playground', '관광지', 36.04693281, 128.712821, '경상북도 영천시 신녕면 신암길 17', '수려하고 맑은물이 흐르는 치산계곡이 있어 여름철 30,000명 이상이 찾는 관광명소임', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01980', '천지연폭포', '관광지', 33.2447447, 126.5595511, '제주특별자치도 서귀포시 남성중로 2-15(서홍동)', '하늘과 땅이 만나는 곳의 연못이라는 뜻의 천지연은 난대식물지대로서 계곡전체가 천연보호구역으로 지정되어 있어 주변 경관이 수려함. 조명시설이 되어있어 오후 10시까지 야간 관람 가능함.(천연기념물 제163호 담팔수 자생지. 제379호 천지연 난대림. 제27호 무태장어 서식지)', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01981', '정방폭포', '관광지', 33.24474912, 126.5730486, '제주특별자치도 서귀포시 칠십리로214번길 37(동홍동)', '높이 23m. 너비 8m. 깊이 5m에 달하는 동양 유일의 해안폭포로서 폭포수가 바다로 직접 떨어지는 경관을 관람할 수 있음(명승 제43호)', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01982', '주상절리대', '관광지', 33.23799399, 126.4260174, '제주특별자치도 서귀포시 이어도로 36-30(중문동)', '주상절리는 주로 현무암질 용암류에 형성되는 수직절리를 말함. 중문·대포해안 주상절리대는 높이가 30~40m. 폭이 약 1km 정도로 우리나라 최대 규모로 육모꼴의 기둥이 병풍처럼 둘러쳐져 있어 자연의 신비를 만끽할 수 있음.(천연기념물 제 443호. 제주도지질공원)', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01983', '천제연폭포', '관광지', 33.2526783, 126.4183754, '제주특별자치도 서귀포시 천제연로 132(중문동)', '한라산에서 시작된 중문천이 바다로 흐르면서 형성된 폭포. 3개의 폭포로 나뉘어 지는데 주상절리 절벽에서 천제연(못)으로 떨어지는 1폭포. 천제연 물이 더 아래로 흐르면서 형성된 2. 3폭포가 있음. 옥황상제를 모시는 칠선녀가 목욕을 하다 간다는 전설이 있을만큼 빼어난 경관을 자랑함(천연기념물 제378호 천제연 난대림)', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01984', '산방산', '관광지', 33.23697818, 126.312306, '제주특별자치도 서귀포시 안덕면 산방로 218-11', '높이 395m의 거대한 종 모양의 화산체로서 설문대할망이 한라산 꼭대기를 뽑아 던져 놓았다는 전설이 있음. 해발고도 200m에 산방굴이라는 해식동굴이 있음. (명승 제77호. 천연기념물 제376호. 제주도지질공원)', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01985', '용머리해안', '관광지', 33.23342738, 126.3136956, '제주특별자치도 서귀포시 안덕면 사계남로216번길 24-30', '마치 바다속으로 들어가는 용의 머리를 닮았다 해서 용머리해안으로 불림. 수천만년 동안 층층이 쌓인 사암층 암벽이 파도에 깎여 기묘한 절벽을 이루고 있음. (천연기념물 제526호. 제주도지질공원)', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01986', '불회사', '관광지', 34.90877918, 126.8234812, '전라남도 나주시 다도면 다도로 1224-142', '사찰', '전남');
