INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01988', '도래마을(홍기옥 가옥)', '관광지', 34.9981825, 126.8223995, '전라남도 나주시 다도면 동력길 16', '중요민속문화재', '전남');
