INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI01999', '제천온천playground', '관광지', 36.92183352, 128.1819714, '충청북도 제천시 수산면 내리 산24', '청풍호반, 월악산등과 연계한 핵심 처류거점으로 한방도시 컨셉과 연계한 한방온천장으로 조성계획 playground', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02000', '교리playground', '숙박', 37.01656717, 128.1768531, '충청북도 제천시 청풍면 청풍호로 1798', '청풍호반 주변 관광시설과 연계한 핵심 체류 거점으로 청풍권 최고의 리조트 playground', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02001', '유당공원', '관광지', 34.97010442, 127.5924243, '전라남도 광양시 광양읍 백운로 14', '1528년 광양현감 박세후 조성', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02002', '서천무지개분수대', '관광지', 34.9735109, 127.5756854, '전라남도 광양시 광양읍 칠성리 729', '음악분수 퍼포먼스 공연', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02003', '소흥관(한중우호센터)', '관광지', 35.11507608, 129.0375502, '부산광역시 동구 초량중로 36', '소흥시와 동구의 우호계약을 맺은 기념으로 만들어진곳으로 한복과 치파오체험을 할수있다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02004', '만화체험관', '관광지', 35.13778041, 129.0497944, '부산광역시 동구 성북로 42-1', '관광객의 볼거리와 재래시장 활성화를 위해 조성된 웹툰거리 내에 위치한 체험관', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02005', '안용복기념 부산포개항문화관', '관광지', 35.13563677, 129.0529467, '부산광역시 동구 증산로 100', '부산포개항의 역사를 기억하고 독도를 수호한 안용복장군의 정신을 기리기위해 만들어진 문화관이다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02006', '좌천동굴', '관광지', 35.13325838, 129.0522683, '부산광역시 동구 고관로185번길 1', '일제강점기때 방공호이자 한국전쟁때 피난처였던 역사를 가진 좌천동의 동굴', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02007', '만화카페', '카페', 35.13675143, 129.0496096, '부산광역시 동구 성북로 31', '동구 전역의 산복도로, 북항을 열기구 형태의 VR로 체험할 수 있고, 웹툰 도서 읽을 수 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02008', '명란브랜드연구소', '관광지', 35.117117, 129.035016, '부산광역시 동구 영초윗길 22-1', '명란을 토대로 한 지역특화 미식관광 브랜딩 추진의 일환으로 지어진 공간이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02009', '168 더데크', '관광지', 35.117273, 129.036088, '부산광역시 동구 초량동 994-892', '대형스크린 및 헤드셋을 활용한 야외 영화 상영관이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02010', '망양로산복도로전시관', '관광지', 35.117653, 129.033231, '부산광역시 동구 망양로 488', '산복도로의 근현대사 생활사를 전시하고 및 문화주택 만들기 등 각종 체험프로그램을 운영하는 시설이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02011', '연천호로고루', '관광지', 37.98583872, 126.8596065, '경기도 연천군 장남면 원당리 1258', '임진강이 지류와 만나 형성된 삼각형의 대지위에 조성된 독특한 고구려성', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02012', '당포성', '관광지', 38.02350322, 126.9854182, '경기도 연천군 미산면 동이리 778', '삼국시대 성곽 천연 절벽을 이용하여 축조한 평지성', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02013', '연천전곡리유적', '관광지', 38.01564838, 127.0614526, '경기도 연천군 전곡읍 양연로 1510', '한탄강변에 있는 구석기시대으로 1978년 아슐리안형 주먹도끼가 발견된 이래 전 세계적으로 주목을 받고 있는 유적으로 사적 제268호', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02014', '은대리 문화벽돌공장', '관광지', 38.05106601, 127.0713677, '경기도 연천군 전곡읍 평화로940번길 72-27', '은대리에 위치한 폐벽돌공장을 리모델링한 복합문화공간', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02015', '사계고택', '관광지', 36.265691, 127.2719783, '충청남도 계룡시 두마면 사계로 122-4', '조선중기 유학의 대가 사계김장생 선생의고택', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02016', '모원재', '관광지', 36.254886, 127.2732753, '충청남도 계룡시 두마면 왕대2길6-10', '사계 김장생 선생의 5대 선친인 김국광의 재실', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02017', '염선재', '관광지', 36.2693923, 127.261851, '충청남도 계룡시 사계로1길 16', '사계 김장생 선생의 계배 순천김씨의 재실', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02018', '이심원충신정려현판', '관광지', 36.280034, 127.2470773, '충청남도 계룡시 금암1 길 7(금암동)', '효령대군의 증손인 이심원선생의 충직함을 기리기 위한 현판', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02019', '신원재', '관광지', 36.255245, 127.2705257, '충청남도 계룡시 두마면 왕대2길43', '사계 김장생 선생의 9번째 아들인 김비 선생의 재실', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02020', '광명동굴', '관광지', 37.42467857, 126.8634321, '경기도 광명시 가학로 85번길 142', '1912년 일제가 자원수탈을 목적으로 개발을 시작한 광명동굴(구.시흥광산)은 일제강점기 징용과 수탈의 현장이자 해방 후 근대화ㆍ산업화의 흔적을 고스란히 간직한 산업유산이다. 1972년 폐광된 후 40여 년간 새우젓 창고로 쓰이며 잠들어 있던 광명동굴을 2011년 광명시가 매입하여 역사ㆍ문화 관광명소로 탈바꿈시켰다. 광명동굴은 산업유산으로서의 가치와 문화적 가치가 결합된 대한민국 최고의 동굴테마파크라는 평가를 받고 있으며 연간 100만 명 이상의 관광객이 찾는 세계가 놀란 폐광의 기적을 이루었다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02021', '대전문화예술단지', '관광지', 36.366496, 127.3880154, '대전광역시 서구 둔산대로 169', NULL, '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02022', '으능정이문화의거리', '관광지', 36.32934665, 127.428337, '대전광역시 중구 중앙로 170', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02023', '유성온천', '관광지', 36.3547298, 127.3375865, '대전광역시 유성구 계룡로60', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02024', '이바구공작소', '관광지', 35.11709939, 129.0338233, '부산광역시 동구 망양로486번길 14-13', '산복도로 사람들의 삶과 지역문화를 전시하는 아카이브센터이다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02025', '장기려더나눔센터', '관광지', 35.11853593, 129.0326526, '부산광역시 동구 영초윗길 48', '장기려박사의 뜻을 기리는 기념관이다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02026', '168계단 부대시설', '관광지', 35.1176995, 129.0353474, '부산광역시 동구 영초윗길26번길 14', '초량168계단이 보이고 경사형엘리베이터 종점부에 위치하고 현재는 청년 창업공간으로 사용하고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02027', '김민부전망대', '관광지', 35.1176995, 129.0353474, '부산광역시 동구 영초윗길26번길 14', '부산 동구출신의 김민부 시인을 기리기위해 만들어진 전망대이다. 현재는 청년 창업공간으로 사용하고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02028', '유치환의 우체통', '관광지', 35.12209588, 129.0338423, '부산광역시 동구 망양로580번길 2', '청마유치환선생을 기리기 위해 지어진곳 3층에 그리움이있는 느린우체통이 명소이다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02029', '대가야생활촌', '숙박', 35.7118532, 128.269244, '경상북도 고령군 대가야읍 신남로 81', '역사적 고증과 현대적 상상을 바탕으로 대가야의 역사와 문화의 과거, 현재, 미래의 모습을 볼 수 있도록 재현한 대가야생활촌입니다. 대가야생활촌에는 1500년 전 대가야시대로 안내해주는 인트로영상관, 대가야 의식주 생활상을 재현한 인줄마을, 대가야를 대표하는 철기문화를 직접 체험할 수 있는 불묏골, 대가야의 토기문화와 교역물품을 알아볼 수 있는 골안마을, 아름다운 경관을 감상 할 수 있는 상가라도못, 짚라인을 즐길 수 있는 놀이터가 있는 메나릿골, 여름철 시원한 물놀이가 가능한 물놀이장, 대가야 철의 원정대 일원이 되어 원정선 하지호에 승선할 수 있는 주산성전시관, 기와마을과 초가마을로 이루어진 숙박시설 한기촌 등이 있어 학습체험과 관광숙박을 한 곳에서 즐길 수 있습니다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02030', '대가야역사테마playground', '관광지', 35.72008263, 128.2596761, '경상북도 고령군 대가야읍 대가야로 1216', '찬란하게 꽃 피웠던 대가야의 토기와 철기, 가야금 문화 등 대가야의 역사를 테마로 하여 조성된 playground입니다. 대가야에 대하여 배워볼 수 있는 전시관들 및 대가야탐방숲길이 있으며, 아이들이 즐겁게 즐길 수 있는 레일썰매장, 물놀이장을 운영하고 있습니다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02031', '한탄강playground', '관광지', 38.00887699, 127.0588604, '경기도 연천군 전곡읍 선사로 76', '한탄강이 내려다보이는 천혜의 위치에 자리잡은 playground', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02032', '연천재인폭포', '관광지', 38.07672631, 127.142345, '경기도 연천군 연천읍 부곡리 193', '18.5m 높이의 폭포로 연천군 대표적인 명승지', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02033', '금월봉playground', '숙박', 37.04384263, 128.1736527, '충청북도 제천시 금성면 청풍호로 1316', '청풍호의 수려한 자연경관과 기암괴석(금월봉)을 배경으로 유휴지를 최대한 활용한 체류형 관공시설(호텔, 콘도 등) 조성', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02034', '계산playground', '관광지', 37.017861, 128.130911, '충청북도 제천시 청풍면 계산리 9-4', '수상레저 및 수상마리나 등 수상연계관광 인프라 조성 및 비봉산모노레일 등과 연계 관광 인프라조성 목적 playground', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02035', '만남의광장', '관광지', 37.01083356, 128.1811895, '충청북도 제천시 청풍면 청풍호로50길 6', '청풍호반 주변 관광시설과 연계한 핵심 관광거점으로 각종 관광시설이 집중된 제천관광의 중심지', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02036', '제천 성내playground', '관광지', 37.03366403, 128.1751729, '충청북도 제천시 금성면 청풍호로 1482', '청풍호반의 뛰어난 장소적 특성을 활용한 문화영상 테마지구로 한류와 연계 국내외 영상테마 playground', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02037', '사성암', '관광지', 35.18012828, 127.480644, '전라남도 구례군 문척면 사성암길 303', '2014년 명승 제111호로 지정된 사성암은 해발 531m의 오산 정상에 위치해 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02038', '운조루', '관광지', 35.20594498, 127.5152886, '전라남도 구례군 토지면 운조루길 59', '운조루는 조선 영조 52년(1776년) 당시 삼수 부사를 지낸 류이주가 99칸(현 존 73칸)으로 지은품자형의 대규모 저택으로 조선 후기 건축양식을 따르고 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02039', '한국압화박물관', '관광지', 35.19664998, 127.4599106, '전라남도 구례군 구례읍 동산1길 29', '대한민국 압화대전의 대통령상 수상작 등 국내외 작가들의 작품 600여 점이 전시 되어 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02040', '지리산역사문화관', '관광지', 35.24408524, 127.4837599, '전라남도 구례군 마산면 화엄사로 377-36', '지리산권의 다양한 역사, 문화자원이 전시된 곳으로,강따라(기획전시), 산따라(상설전시), 길따라(체험전시) 등 총 3개관으로 구성되어 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02041', '섬진강어류생태관', '관광지', 35.18745224, 127.5465226, '전라남도 구례군 간전면 간전중앙로 47', '섬진강 민물고기 자원에 대한 체계적인 보전과 생태전시를 위한 전시관이다.강따라(기획전시), 산따라(상설전시), 길따라(체험전시) 등 총 3개관으로 구성되어 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02042', '동구릉', '관광지', 37.6171286, 127.136334, '경기도 구리시 동구릉로 197', '유네스코 세계유산이자 사적 제193호로 지정된 「구리 동구릉(東九陵)」은 ‘도성(都城)의 동(東)쪽에 있는 아홉(九) 기의 왕릉’이라 하여 동구릉이라 붙여짐', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02043', '지리산허브밸리', '관광지', 35.435092, 127.548617, '전북특별자치도 남원시 운봉읍 바래봉길 214', '국내 최대의 철쭉 군락지를 보듬고 있는 지리산 바래봉해발 600m 지역인 남원시 운봉읍 용산리 일대에 자리하고 있으며,2005년 정부로부터 지리산 웰빙 허브산업특구로 지정받은 지역입니다.지리산의 자연 속에서 허브의 모든 것을 즐길 수 있는 지리산허브밸리는대한민국 허브산업의 중심지입니다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02044', '남원백두대간생태교육장전시관', '카페', 35.397328, 127.5079302, '전북특별자치도 남원시 운봉읍 운봉로 151', '지리산의 상징성과 백두대간의 역사·생태·보존의 최적지인 남원에 백두대간 생태교육장 전시관이 조성되었습니다. 전시관은 한반도 지도 형상을 본 따 만든 곡선의 전시관 지붕외관에서부터 우리나라의 중심축인 백두대간의 모든 것을 알고 보고 체험 할 수 있는 갖가지 내용물 등이 전시되어 있습니다. 전시관 주요시설로는 상설전시실, 기획전시실, 호남 최초로 시도하는 5D서클영상관, 카페테리아 등이 있으며 부대시설로는 야외공연장, 곤충온실, 체육시설 등이 있습니다', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02045', '만인의총', '관광지', 35.420404, 127.377325, '전북특별자치도 남원시 만인로 3', '만인의총은 정유재란(1597년)때 남원성 전투에서 순절한 민·관·군 1만여 의사들의 호국의 얼이 서려있는 성스러운 곳이다', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02046', '아담원', '관광지', 35.440571, 127.476826, '전북특별자치도 남원시 이백면 목가길 193', '아담원은 본래 나무를 키우던 조경농원이었던 곳으로 지난 10년간 정성으로 가꾸어 아름다운 정원으로 재탄생 하였습니다. 나무 한 주, 풀 한포기까지 엄선하여 심고, 관리하여 지리산자락의 비경과 함께 훌륭한 힐링의 장을 제공해 줄 것입니다. 아무쪼록 방문하시어 편안한 휴식을 만끽하시길 바랍니다', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02047', '남원playground', '관광지', 35.402481, 127.386137, '전북특별자치도 남원시 양림길 12', '남원하면 떠오르는 모든 상징물과 위락시설들을 모아 놓은 종합관광단지이다. 남원시 어현동 일대에 자리하고 있다. 한국관광공사가 조성한 남원관광단지에는 춘향전과 관련된 춘향테마파크, 춘향문화예술회관을 비롯해 국립민속국악원, 남원향토박물관 등의 문화시설이 있다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02048', '송도해수욕장', '관광지', 35.07682117, 129.0180502, '부산광역시 서구 송도해변로 100', '우리나라 제1호 해수욕장. 동양의 나폴리로 불리며 60,80년대 송도의 추억으로 잘 알려진 송도해수욕장이 아름다운 해안선을 자랑하며 사계절 즐길 수 있는 해변공원으로 새롭게 태어났다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02049', '암남공원', '관광지', 35.0616574, 129.0149368, '부산광역시 서구 암남공원로 185', '암남공원(岩南公園)은 부산시 서구 진정산 일대에 조성된 자연생태공원이다. 이곳에는 약 1억 년 전 형성된 퇴적암, 100여 종의 야생화와 370여 종의 식물 등 도심에서 보기 드문 자연생태가 군락을 이루고 있다. 산책로 1.9km, 해안 산책로 1.2km를 포함한 총 면적이 55만 3277㎡로 아름다운 해안 경치와 울창한 산림이 조화를 이룬 천혜의 자연 경관을 자랑한다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02050', '구덕문화공원', '관광지', 35.12641369, 129.005742, '부산광역시 서구 꽃마을로 163번길 73', '구덕산 자락 숲속에 자리하였으며 교육역사관에는 조선시대부터 개화기, 일제강점기, 한국전쟁기, 그리고 현재에 이르기까지 약 640여점의 교육 사료가 전시되어있으며 최근 다목적관에 어린이복합문화공간인 서구 숲속놀이터가 조성되었다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02051', '중앙공원', '관광지', 35.121591, 129.0161785, '부산광역시 서구 대신공원로 37-18', '1968년 2월 21일 대신공원이란 이름으로 일반인이 즐기는 중앙 근린공원 으로 지정되었다. (건설부고시 제360호) 1900년 구덕산과 엄광산의 계곡에 2곳의 수원지를 축조하면서 삼나무, 편백, 벚꽃나무 등의 수목을 심고 주위를 정비한 후 수원지의 수원보호를 위해 일반인의 출입을 금지하였다. 1944년에는 수원지 일대를 자연공원 으로 고시하였는데 역시 일반인의 출입을 통제하였다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02052', '부산공동어시장', '쇼핑', 35.08990091, 129.0263675, '부산광역시 서구 충무대로 202', '부산 공동어시장은 5개의 수산업협동조합이 공동으로 운영하고 있다. 1일 최대 3200톤(16만 상자) 규모의 우리나라 제일의 산지 어시장으로 새벽부터 경매사와 수산물 중도매인들의 열기가 뜨거운 곳이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02053', '천마산조각공원', '관광지', 35.08903987, 129.0174786, '부산광역시 서구 천마산로 209번길 94', '남항에서 서쪽으로 바라보이는 해발 324m의 아담한 산에 조성된 1만 6천㎡에 이르는 공원이다. 하늘에서 말이 내려왔다는 전설의 천마 바위와 44점의 아름다운 조각 예술 작품이 운해의 바다 속에서 그 평화로움을 선보인다. 공원 주변에는체육시설과 산책로, 쉼터 등이 조성되어 문화공간으로 각광받고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02054', '구덕운동장', '관광지', 35.11659638, 129.0145297, '부산광역시 서구 망양로 57 (씨름체육관 서구 꽃마을로 156번길12)', '1920년 9월 조그만 동물원을 곁에 둔 넓은 빈터로 마을 체육대회 장소로 사용하다가 1928년 9월에 부산공설운동장으로 건립되었다가 1982년 사직운동장이 건립되어 그해 6월에 구덕운동장으로 개칭되었다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02055', '임시수도기념관', '관광지', 35.10374876, 129.0175954, '부산광역시 서구 임시수도기념로 45', '6.25 당시 임시수도로서 국난극복의 역사적 현장을 길이 보전하여,후세에 물려줌으로서 민족사의 암울한 시기를 깨닫게 하고 조국통일과 번영의 산교육장으로 활용하고 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02056', '고구려대장간마을', '관광지', 37.56080787, 127.1109492, '경기도 구리시 우미내길 41', '국내유일의 고구려 박물관으로 아차산에서 출토된 유물을 전시하고 있으며 고구려모습을 보여주는 야외전시관을 운영', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02057', '춘향테마파크', '관광지', 35.401464, 127.386902, '전북특별자치도 남원시 양림길 14-9', '남원시 양림길 남원playground내에 소재한 곳(3만 5천평 규모)으로 임권택 감독의 영화 [춘향뎐]의 촬영 장소를 포함하여 사랑의 테마가 있는 playground로 조성한 곳이다. [춘향뎐]의 지고지순한 사랑을 오늘을 살아가는 이들의 마음속에 담아내 과거의 사랑과 이제 사랑을 시작하는 이들이 사랑의 추억을 만들 수 있도록 조성돼 있고 만남의 장, 맹약의 장, 춘향뎐 영화세트장, 축제의 장 등 사랑의 5개 마당으로 춘향테마의 일대기를 재현하고 있다. 또한 철저한 고증을 거쳐 완성된 동헌, 관아, 내아, 월매집, 부용당, 옥사정을 비롯해 조선 중기 서민들의 삶이 깃든 고건물들이 들어서 있어 조선 중기 서민문화와 춘향의 삶을 제대로 이해할 수 있도록 조성되어 있다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02058', '남원항공우주천문대', '관광지', 35.399194, 127.387388, '전북특별자치도 남원시 양림길 48-63', '남원항공우주천문대는 2009년 10월 9일에 개관하여 서남권 관광문화의 중심 도시인 남원 및 인근지역 어린이, 청소년에게 천문우주 및 첨단 항공과학 체험 기회를 제공하고 또한 가족 단위와 단체가 함께 즐길 수 있는 가족 체험시설로 관광수요 창출 및 지역경제 활성화에 기여하고 있습니다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02059', '남원시립김병종미술관', '카페', 35.398706, 127.389555, '전북특별자치도 남원시 함파우길 65-14', '전북특별자치도 남원시 춘향테마파크 내에 위치한 남원시립김병종미술관은 2018년 3월 2일에 개관하였습니다. 남원시에서 직접 운영하는 공립미술관으로서 시민들의 문화예술 향유를 통한 삶의 질 향상과 지역 출신 작가들의 전시 공간 마련을 통해 지역 미술의 특성을 알리는데 설립 목적이 있습니다. 특히 남원 출신의 김병종(b.1953) 작가가 본인의 대표작을 남원시에 대량 기증하면서 콜렉션의 기반을 갖추었습니다. 숲으로 둘러싸인 남원시립김병종미술관은 전원형(田園形) 미술관으로서 바쁜 일상에 지친 현대인들이 찾아와 미술작품 뿐 아니라 자연을 감상하고, 마음을 치유하는 복합 문화시설입니다. 또한 문학인으로 유명한 김병종 작가가 기증한 각종 문학 관련 자료들을 선보여, 미술과 문학이 공존하는 공간이기도 합니다. 약 2,000권의 미술·문학·인문학 관련 도서가 비치된 북카페도 이 같은 미술관의 독특한 역할에 일조하고 있습니다', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02060', '혼불문학관', '관광지', 35.481096, 127.319992, '전북특별자치도 남원시 사매면 노봉안길 52', '현대 문학의 백미라고 할 수 있는 소설 “혼불”과 작가 최명희 선생의 문학정신을 널리 선양하고 전승, 보존하기 위하여 2004년 10월에 국고와 지방비 포함 49억을 들여서 이곳 노봉마을에 혼불문학관을 개관하게 되었습니다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02061', '국악의 성지', '관광지', 35.459997, 127.569101, '전북특별자치도 남원시 운봉읍 비전길 69', '민족의 영산 지리산 자락 운봉에 위치하고 있는 국악의 성지는 우리 민족의 전통과 혼이 담긴 국악의 본 고장이요, 성지임을 널리 알리기 위해 국악을 사랑하는 모든 분들의 염원을 모아 조성하였다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02062', '능강playground', '숙박', 36.99002277, 128.1956764, '충청북도 제천시 수산면 옥순봉로 1248', '청풍호 경관자원과 연계 한국 최고의 스위스형 테마 및 산악 휴양형 핵심 체류 거점 리조트', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02063', '노고단', '관광지', 35.23629045, 127.5547986, '전라남도 구례군 토지면 반곡길 42-237', '천왕봉, 반야봉과 함께 지리산 3대 주봉으로 꼽힌다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02064', '지리산정원', '관광지', 35.28722643, 127.4388392, '전라남도 구례군 광의면 온동2길 124', '사계절 다양한 식생을 관찰할 수 있는 야생화테마랜드와 자생식물원,생태숲, 자연휴양림, 수목원이 있으며, 자연속 힐링공간인 숲속수목가옥은 인기가 높다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02065', '섬진강대숲길', '관광지', 35.18633781, 127.4652531, '전라남도 구례군 구례읍 원방리 1', '섬진강변 대숲길은 강 풍경과 어우러져 마음을 평온하게 한다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02066', '화엄사', '관광지', 35.25731602, 127.4977197, '전라남도 구례군 마산면 화엄사로 239', '대한 불교조계종 제 19교구 본사인 화엄사는 사적 제 505호로 지정(2009년) 되어있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02067', '천은사', '관광지', 35.27309271, 127.476325, '전라남도 구례군 광의면 노고단로 209', '신라 흥덕왕 3년(828년)에 덕운선사가 창건하였다고 전해지며 경내에 이슬처럼 맑고 찬 샘이 있어 처음에는 절 이름을 감로사(甘露寺)라 하였다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02068', '다부동전적기념관', '관광지', 36.046443, 128.518875, '경상북도 칠곡군 가산면 호국로 1486', '구국의 정신과 평화의 소중함을 전하는 역사가 흐르는 기념관', '경북');
