INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02070', '칠곡보오토캠핑장', '관광지', 36.020591, 128.394566, '경상북도 칠곡군 약목면 강변서로 110-43', '산과 강이 어우러진 오토캠핑장', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02071', '칠곡호국평화기념관', '관광지', 36.017918, 128.404032, '경상북도 칠곡군 석적읍 강변대로 1580', '낙동강 55일간의 전투를 재조명하고 다채로운 체험 통해 호국체험공간', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02072', '칠곡양떼목장', '관광지', 35.984545, 128.48874, '경상북도 칠곡군 지천면 창평로 209-42', '양떼를 체험해볼수 있는 어린이를 위한 체험장', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02073', '가산수피아', '관광지', 36.086109, 128.485044, '경상북도 칠곡군 가산면 학하들안2길 105', '2019년 4월에 개장한 국내최대 민간정원', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02074', '국립칠곡숲체원', '관광지', 36.063539, 128.466183, '경상북도 칠곡군 석적읍 유학로 532', '청소년 및 가족 단체를 위한 숲체험 산림교육프로그램과 산림치유프로그램 운영', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02075', '곡성섬진강천문대', '관광지', 35.22666779, 127.3691674, '전라남도 구례군 구례읍 섬진강로 1234', '2007년 9월 19일 개관한 곡성섬진강천문대는 아름답고 깨끗한 섬진강이 흐르는 강변에 위치하고 있으며, 한국천문연구원에서 우리나라 순수 과학기술로 제작한 600mm 천체망원을 설치한 주관측실을 비롯하여 정밀도를 자랑하는 다양한 망원경들이 설치되어 있는 보조관측실, 8m 원형돔 스크린을 갖춘 천체투영실, 그리고 각종 천문자료 등을 전시해 놓은 학습공간으로 구성되어 있어, 별에 대한 옛 추억을 되새기고 미래 우주시대 주인공이 되기 위한 꿈과 미래를 찾아 떠나는 우주여행의 길잡이 역할을 충실히 할 것이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02076', '섬진강도깨비마을', '쇼핑', 35.25424902, 127.363209, '전라남도 곡성군 고달면 호곡도깨비길 119-99', '곡성에도 여느 고장처럼 무수한 도깨비 이야기가 전해져 내려오고 있지만, 그중 태종임금, 이방원의 심복이었던 마천목 장군과 도깨비살 전설이 가장 유명하여 애니메이션으로 제작되어 기차마을 요술랜드에서도 상영하고 있다. 돌로 바다나 강물을 막고 그곳에 나뭇가지를 촘촘히 박아서 고기가 빠져나가지 못하게 한 다음, 물고기를 잡는 전통 어로방식을 어살이라고 한다. 그런데 물살이 드센 강을 커다란 돌로 막는다는 것이 보통 어려운 일은 아니다.[효성이 지극한 마천목 장군이 어머니에게 고기를 잡아드리기 위해서 강가에 나갔다가, 푸른빛이 도는 돌을 주워온다. 그 돌이 도깨비 두목이었던 것이다. 도깨비들이 집으로 찾아와 두목을 돌려주면 무슨 소원이든 들어주겠다고 하자, 마천목장군은 어살을 막아달라고 했다. 그래서 도깨비들이 하룻밤사이에 어살을 막아주었는데, 섬진강에는 아직도 그 자취가 남아있다.]도깨비와 관련된 각종 자료와 전시품들이 박물관 수준 이상으로 일목요연하게 전시되어 있어 우리가 몰랐던 도깨비에 대한 상식들을 많이 알수 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02077', '압록유원지', '관광지', 35.19196269, 127.3775123, '전라남도 곡성군 죽곡면 섬진강로 1012', '강을 통한 운송이 수송의 중요한 역할을 담당했던 시절, 두 강이 만나는 합수지점은 물산과 사람이 모이는 교통의 요지 구실을 했다. 섬진강과 대황강(보성강)이 합쳐지는 곡성 압록포구도 그런 곳이었다. 옛 사람들이 일컬은 곡성팔경중 압록의 귀범(歸帆)이라는 표현만 보더라도 그것을 알 수 있다.섬진강과 보성강이 합류한 기점인 이 곳은 3만여평의 드넓은 백사장이 펼쳐있는 한여름 피서지로 널리 알려진 자연유원지다. 여름에는 모기가 없어 가족단위 캠핑장소로 각광을 받고 있으며, 반월교와 철교가 나란히 강을 가로질러 놓여있어 운치가 뛰어나다. 특히, 보성강 하류의 유명 낚시터가 산재해 있어 강태공들에게는 인기가 높다. 강변에는 압록의 별미인 참게탕, 은어회, 매운탕을 맛볼 수 있는 향토음식점이 즐비해 있어 또다른 즐거움을 준다.또한 이곳 압록유원지에는 「모기전설」 이 전해 내려오고 있는데 「강감찬 장군이 어머니를 모시고 여행을 하다 이 곳 압록유원지에서 노숙을 하였는데 극성스런 모기 때문에 어머님이 잠을 청하지 못하자, 강감찬장군이 고함을 질러 모기의 입을 봉하였다.」고 한다. 그런 연유에서인지 아니면 섬진강의 시원한 강줄기 때문인지 다른 지역에 비해 여름에 모기가 별로 없다고 한다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02078', '하동레일파크', '관광지', 35.11333681, 127.8929765, '경상남도 하동군 북천면 경서대로 2446-6', '1968년 2월 7일 보통역으로 영업을 개시, 2017년 현재는 하동레일파크가 오픈하고 레일바이크 매표소로 이용되고 있다. 주변 행사로는 5월에는 북천 꽃 양귀비 축제가 열리며, 가을이면 역 주변에 코스모스와 메밀꽃이 만발해 7월 부터 코스모스 메밀꽃 축제를 개최한다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02079', '지리산역사관', '관광지', 35.2896912, 127.646527, '경상남도 하동군 화개면 화개로 1438', '지리산을 안고 살아온 우리조상들의 생활상 이해공간 제공', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02080', '하동코리아짚와이어', '관광지', 34.98260917, 127.894714, '경상남도 하동군 금남면 경충로 493-9', '금오산 정상 해발 849m에서 경사도 27, 최대 시속 120km/h로, 마치 하늘에서 떨어져 내리는 듯한 짜릿함과 금오산, 다도해의 아름다운 정경을 함께 만끽하는 아시아 최장 3.42km의 활강체험 레포츠이다', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02081', '하동 플라이웨이 케이블카', '관광지', 34.98070015, 127.8953015, '경상남도 하동군 금남면 경충로 461-7', '총연장 2,556m의 선로와 40대의 캐빈으로 해발 849m 금오산 정상까지 운행하는 하동 플라이웨이 케이블카는 하루 최대 9,800명이 탑승할 수 있으며, 한려해상국립공원의 다도해와 금오산 절경을 동시에 조망할 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02082', '직탕', '관광지', 38.2069247, 127.2690548, '강원도 철원군 갈말읍 직탕길 32', '천혜의 자연환경을 자랑하는 한탄강 상류지역으로 강을 횡단하여 떨어지는 수직 낙하 폭이 80m의 절벽으로 이루어진 직탕폭포가 있는 곳으로 맑고 깨끗한 풍부한 수량, 빼어난 주상절리 협곡, 절경을 감상하며 뛰어내리는 태봉대교 번지점프, 자연의 맛이 살아 있는 매운탕이 유명한 곳이다. 한탄강 국가지질공원으로 지정받은 지질명소이기도 하다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02083', '가산산성', '관광지', 36.021011, 128.590851, '경상북도 칠곡군 동명면 남원리 32-78', '임진왜란과 병자호란을 겪은후 잇따른 외침에 대비하기 위해 세원진 산성', '경북');
