INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02094', '송정playground', '관광지', 34.7231451, 128.0249667, '경상남도 남해군 미조면 미송로 483', '해수욕장이 넓게 분포되어 있으며, 해수욕장을 조금만 벗어나면 몽돌과 기암괴석이 뒤섞인 단애의 해안을 구경할 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02095', '평택호관광단지', '관광지', 36.914825, 126.912951, '경기도 평택시 현덕면 평택호길 48', '문화와 예술이 살아숨쉬는 친환경 문화관광단지', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02096', '성기동', '관광지', 34.75653201, 126.6291224, '전라남도 영암군 군서면 왕인로 440', '성기동은 왕인박사의 탄생지로 추정되는 곳으로 왕인박사유적지와 함께 탄생지, 문산재, 양사재, 상대포, 회사정 등 왕인박사 관련 관광자원이 분포되어 있다. 매년 4월이면 왕인문화축제가 열리고 있어 다양한 체험 및 관람을 즐길 수 있다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02097', '마한문화', '관광지', 34.89539241, 126.5859196, '전라남도 영암군 시종면 남해당로 65', '영산강 유역에 분포되어 있는 고대 옹관 고분을 이해함으로써 영산강 유역의 독자성이 가득한 고대사를 조명하기 위해 조성', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02098', '영산호playground', '관광지', 34.776135, 126.4577774, '전라남도 영암군 삼호읍 녹색로 653-11', '1981년 영산강 하굿둑이 준공되면서 만들어진 인공호수인 영산호를 중심으로 조성된 휴양지이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02099', '정양늪생태공원', '관광지', 35.55322772, 128.162786, '경상남도 합천군 대양면 대야로 730', '자연을 직접 느끼고 경험할 수 있는 생태playground', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02100', '해인사 소리길', '관광지', 35.76749785, 128.1365362, '경상남도 합천군 가야면 가야산로 1160', '트래킹코스로 사랑받고, 다양한 꽃길을 보유한 소리길', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02101', '합천호회양관광단지', '관광지', 35.524398, 128.016537, '경상남도 합천군 대병면 회양리 700-27', '자연 경관이 뛰어난 호반 유원지', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02102', '무릉계곡', '관광지', 37.463551, 129.0146909, '강원특별자치도 동해시 삼화로 584', '신선이 노닐었다는 무릉계곡명승지 일명 무릉도원이라 불리는 무릉계곡 명승지는 두타산과 청옥산을 배경으로 이루어진 계곡으로 수많은 기암괴석과 절경들이 장관을 이루고 있어 마치 현존하는 선경에 와있는 듯한 느낌을 준다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02103', '망상', '숙박', 37.59225327, 129.0896922, '강원특별자치도 동해시 동해대로 6270-10', '눈앞에 바로 펼쳐지는 깨끗한 백사장과 맑고 푸른 바다, 상쾌한 바닷바람과 해가 뜨는 드넓은 수평선을 느낄 수 있는 해수욕장과 오토캠핑리조트등이 있다', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02104', '수동playground', '관광지', 37.75797919, 127.2753596, '경기도 남양주시 수동면 비룡로 1635', '몽골문화촌', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02105', '난지섬playground', '관광지', 37.047036, 126.4242087, '충청남도 당진시 석문면 난지1길 67', '바다가 맑고 한적한 섬 해수욕장', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02106', '마곡사playground', '관광지', 36.55617136, 127.0205918, '충청남도 공주시 사곡면 운암리 731-2', '천년고찰 마곡사 playground', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02107', '공주문화playground', '관광지', 36.47022166, 127.1117007, '충청남도 공주시 웅진동 431', '백제역사 유적playground', '충남');
