INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02109', '동춘당', '관광지', 36.36537889, 127.4412933, '대전광역시 대덕구 동춘당로 80', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02110', '허심청', '관광지', 35.221157, 129.0826889, '부산광역시 동래구 온천장로107번길 32 (온천동)', '허심청은 종래의 위락 시설과는 달리 편안하고 즐거운 온천욕과 휴식 및 체력단련을 통한 건강증진을 추구하는 새로운 유형의 도시형 온천건강랜드이다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02111', '복천박물관', '관광지', 35.20877662, 129.0911741, '부산광역시 동래구 복천로 63(복천동)', '삼한시대부터 삼국시대까지 부산의 역사를 보여주는 고고전문박물관으로서, 현재 7차에 걸친 발굴조사로 밝혀진 169기의 유구와 각종 토기 및 철기류 등의 유물을 종합 전시하고있다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02112', '충렬사', '관광지', 35.199577, 129.0959922, '부산광역시 동래구 충렬대로 345', '충렬사는 임진왜란 때 순절한 동래부사 송상현 공을 모시기 위해 1605년(선조 38년) 당시의 동래부사 윤훤(尹暄)이 동래읍성 남문 근처의 농주산에 송공의 위패를 모신 송공사(宋公祠)를 지어 매년 제사를 지낸 것이 그 시초이다. 그 후 1624년(인조 2년) 선위사(宣慰使) 이민구의 청으로 충렬사라는 사액(賜額)이 내려짐에 따라 송공사는 충렬사로 이름이 바뀌었다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02113', '해양자연사박물관', '관광지', 35.2219498, 129.075647, '부산광역시 동래구 우장춘로 175 (온천동)', '1994년 6월 10일 동래구 온천동 금강공원 내에 개관한 부산해양자연사박물관은 전국 최초, 최대규모의 해양자연사분야의 전문박물관으로', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02114', '서창한옥문화관', '관광지', 35.11523537, 126.8300424, '광주광역시 서구 눌재로 420', '서창한옥문화관은 방문객들에게 전통문화의 우수성과 아름다움을 안내하는 역할을 하면서 동시에 우리나라의 전통가옥인 한옥에 대한 의미를 알리는 곳으로 연중 전통문화강좌, 민속놀이, 예절학당, 한옥스테이 등 다채로운 프로그램을 운영하고 있다. 인근의 playground로는 서구8경 중 3경인 만귀정, 용두동지석묘, 들녘낙조가 있어 한옥의 운치와 볼거리를 더한다', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02115', '비슬산playground', '관광지', 35.69334231, 128.5058006, '대구광역시 달성군 유가읍 휴양림길 236', '비슬산 참꽃 군락지와 대견사 및 암괴류 등 자연과 함께 휴양 가능한 힐링공간 제공', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02116', '화원playground', '관광지', 35.81277123, 128.4806365, '대구광역시 달성군 화원읍 사문진로1길40-14', '도심 속 자연을 느끼고 낙동강변 경관을 감상할 수 있는 playground', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02117', '해인사', '관광지', 35.801504, 128.0976255, '경상남도 합천군 가야면 해인사길 122', '합천 대표 playground이자 한국관광공사가 선정한 한국관광100선에 4회 연속 선정된 역사 그대로의 유산', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02118', '대장경테마파크', '관광지', 35.76749785, 128.1365362, '경상남도 합천군 가야면 가야산로 1160', '해인사 팔만대장경을 비롯한 각종 기록의 문화를 총집합 해놓은 복합테마파크', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02119', '오도산 자연휴양림', '관광지', 35.67233319, 128.0553007, '경상남도 합천군 봉산면 오도산휴양로 398', '웰니스 playground로 선정된 대표 힐링 playground', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02120', '합천박물관', '관광지', 35.58042271, 128.2829423, '경상남도 합천군 쌍책면 황강옥전로 1558', '합천의 살아숨쉬는 역사와 문화가 담긴 playground', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02121', '황매산군립공원', '관광지', 35.48184913, 128.0037495, '경상남도 합천군 가회면 황매산공원길 4', '사계절 색이 바뀌는 도화지로 풍경이 일품인 대표playground', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02122', '영상테마파크&청와대세트장', '관광지', 35.54877253, 128.0728984, '경상남도 합천군 용주면 합천호수로 757', '국내 최대 영화, 드라마세트장으로 많은 프로그램이 촬영된 장소', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02123', '황계폭포', '관광지', 35.51135706, 128.071173, '경상남도 합천군 용주면 황계2길 30', '떨어지는 폭포소리와 그 풍경이 예술인 자연의 신비', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02124', '정양레포츠공원', '관광지', 35.55690191, 128.1668052, '경상남도 합천군 대양면 동부로 39-13', '남녀노소 즐길거리가 다양한 여름 대표 휴가지', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02125', '반월호수', '관광지', 37.32458238, 126.8899642, '경기도 군포시 호수로 92', '순환산책로가 조성되어 있고 아름다운 풍경으로 유명한 장소이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02126', '초막골 생태공원', '관광지', 37.35410097, 126.9191417, '경기도 군포시 초막골길 216', '수리산이 가진 자연적 환경과 조선시대 역사유적 등의 문화유산을 겸비한 생태문화공간이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02127', '철쭉동산', '관광지', 37.35543392, 126.924967, '경기도 군포시 산본동 1152-14', '빈틈없이 심긴 철쭉꽃이 만개한 모습은 많은 사람들에게 사랑을 받으며 군포의 대표축제로 자리매김하였다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02128', '수리사', '관광지', 37.35443607, 126.8967938, '경기도 군포시 속달로 347-181', '진흥왕 때 세워진 수리사는 6.25전쟁을 거치며 모든 건물들이 소실되었다가 꾸준히 복원되어 오늘에 이르고 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02129', '물누리체험관', '관광지', 37.32136505, 126.8996775, '경기도 군포시 호수로 170-85', '물과 관련된 다양한 체험프로그램이 있는 물누리체험관', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02130', '누리천문대', '관광지', 37.33028283, 126.9153444, '경기도 군포시 대야2로 139', '천체관측실, 천문우주체험관. 4D입체상영관, 플라네타리움 등 유익하고 알찬 시설을 갖춘 천문과학문화 공간, 군포시 대야도서관 4층, 5층에 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02131', '표충비', '관광지', 35.471582, 128.6520376, '경상남도 밀양시 무안면 동부동안길4', '표충비는 국가의 중대사가 있을때를 전후하여 비면에 자연적으러 땀방울이 맺혀서 마치 구슬처럼 흐르는데 이것을 두고 사람들은 나라와 겨례를 염려하는 사명대사의 영험이라고 신성시 하고 있음', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02132', '작원관지', '관광지', 35.39853126, 128.8665763, '경상남도 밀양시 삼랑진읍 작원관지길 77', '김해와 낙동강 유역에 창궐하던 왜적들의 침공을 방비하던 요새지', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02133', '예림서원', '관광지', 35.46605971, 128.7299691, '경상남도 밀양시 부북면 예림서원로128', '예림서원은 영남유림의 종장인 점필재 김종직을 사숙하던 후학들의 교육기관', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02134', '밀양향교', '관광지', 35.50660573, 128.7545381, '경상남도 밀양시 밀양향교3길 19 (교동)', '밀양향교는 고려시대(1100년경)때 창립되어 임진왜란때 불타 버린것을 1602년 부사 최기가 중건하여 지금까지 현존하고 있는 건물임', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02135', '밀양관아', '관광지', 35.49429512, 128.754331, '경상남도 밀양시 중앙로348', '조선시대 밀양부 관아의 창건연대는 정확히 알 수 없으며, 1612년에 원유남 부사가 부임하면서 원래 자리에 관아를 복원 하였음', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02136', '밀양영남루', '관광지', 35.49154522, 128.755608, '경상남도 밀양시 중앙로324', '우리나라 3대 누각중에 하나이며 보물제147호임', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02137', '만어사', '관광지', 35.454932, 128.846222, '경상남도 밀양시 삼랑진읍 만어로776', '해발674m의 만어산 8부 능선에 위치하고 있는 만어사는 가라국 수로왕이 창건한 유서 깊은 사찰', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02138', '표충사', '관광지', 35.532294, 128.959045, '경상남도 밀양시 단장면 표충로1338', '표충사는 유생들을 교육하고 성현들이 제사하는 표충서원이 사찰영역안에있어 불교와유교가 한자리에 공존하는 특색있는 사찰', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02139', '내원사계곡(내원사)', '관광지', 35.44578536, 129.1104508, '경상남도 양산시 하북면 내원로 207', '내원사 아래 울창한 숲 사이로 흐르는 이 계곡은 예로부터 소금강 또는 제2의 금강산으로 불릴만큼 자연경관이 빼어난 곳으로 계곡 곳곳에 독특한 바위가 특징이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02140', '대운산자연휴양림', '관광지', 35.41784975, 129.2088996, '경상남도 양산시 탑골길 270', '대운산 서북쪽 자락에 위치하여 깊고 웅장하면서도 물이 맑아 고요한 숲의 분위기를 느끼며 자연에서의 특별한 하루를 보낼 수 있는 휴양처다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02141', '법기수원지', '관광지', 35.34825271, 129.1079758, '경상남도 양산시 동면 법기로 198-13', '부산 금정구 일원의 식수원 역할을 하는 상수원으로 가장 오래된 파란 취수탑이 있으며 청정한 자연과 수려한 풍광을 자랑한다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02142', '양산시립박물관', '관광지', 35.35849531, 129.0490358, '경상남도 양산시 북정로 78', '양산의 역사와 문화를 담고 있으며 역사실, 고분실 등 주제에 맞는 공간들과 함께 다양한 전시를 볼 수 있는 문화 예술 행사와 교육의 장이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02143', '양산타워', '관광지', 35.32591877, 129.0239276, '경상남도 양산시 동면 강변로 264', '자원 회수 시설의 굴뚝을 전망타워화하여 양산 전체를 조망할 수 있고 홍보관에서는 양산의 역사를 한눈에 볼 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02144', '에덴밸리', '숙박', 35.42905699, 128.9844664, '경상남도 양산시 원동면 어실로 1206', '국내 최남단 스키장이 있는 곳으로 리조트로 스키, 루지 등 다양한 레저를 즐길 수 있는 playground이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02145', '임경대', '관광지', 35.32243455, 128.9778074, '경상남도 양산시 원동면 원동로 285', '통일신라시대 학자 최치원이 머무르며 시를 읊었던 곳으로 오봉산 기슭에 위치하여 하늘을 품고 드넓게 펼쳐진 낙동강의 풍경이 특징이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02146', '통도사', '관광지', 35.47540912, 129.0563672, '경상남도 양산시 하북면 통도사로 108', '세계문화유산으로 등재된 우리나라 3대 사찰중 하나로 부처님의 진신사리와 가사를 봉안한 불보사찰이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02147', '최참판댁', '관광지', 35.15590905, 127.688408, '경상남도 하동군 악양면 평사리길 66-7', '소설 토지의 최참판댁을 복원하여 전통 건축물 등을 관람 할 수 있음', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02148', '화개장터', '관광지', 35.18798946, 127.6240666, '경상남도 하동군 화개면 쌍계로 15', '영호남 교통의 길목이며 물류이동의 중심지로서 화개장터가 조성됨', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02149', '삼성궁', '관광지', 35.23870093, 127.7054288, '경상남도 하동군 청암면 삼성궁길 2', '환인, 환웅, 단군을 모신 궁이며 돌탑 등을 관람 할 수 있음', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02150', '이병주문학관', '관광지', 35.09720238, 127.8942256, '경상남도 하동군 북천면 이명골길 14-28', '문학인 이병주선생의 작품 및 작품활동을 엿볼수 있음', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02151', '불정자연휴양림', '관광지', 36.62128207, 128.1365074, '경상북도 문경시 불정길 180', '불정동 마을 안쪽에 위치한 나트막한 봉우리인 수정봉 (해발 487m, 약수산)과 조봉 사이에 자리잡고 있으며 연중 인기리에 운영 중임', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02152', '오월드', '관광지', 36.28749807, 127.3985061, '대전광역시 중구 사정공원로 70', NULL, '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02153', '뿌리공원', '관광지', 36.28537962, 127.3883, '대전광역시 중구 뿌리공원로 79', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02154', '엑스포과학공원', '관광지', 36.37662561, 127.3871992, '대전광역시 유성구 대덕대로 480', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02155', '한밭수목원', '관광지', 36.36646857, 127.3880154, '대전광역시 서구 둔산대로 169', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02156', '계족산황톳길', '관광지', 36.40406651, 127.4297932, '대전광역시 대덕구 장동로 59', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02157', '대청호반', '관광지', 36.47362538, 127.4735679, '대전광역시 대덕구 대청로 607', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02158', '장태산휴양림', '관광지', 36.21596913, 127.3412778, '대전광역시 서구 장안로 461', 'Y', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02159', '죽성드림세트장', '관광지', 35.24113258, 129.2479302, '부산광역시 기장군 기장읍 죽성리 134-7', '죽성리 바닷가에 세워진 드라마 세트장이다. 드림세트장은 유럽의 건축물을 옮겨놓은 듯한 이국적 분위기로 많은 여행객이 찾는다 세트장 근처에 고산윤선도 선생이 귀양살이를 하면서 가끔 찾아 시를 읊펴다는 황학대가 있으며 300년 이상된 죽성리 해송이 있다 죽성 드림세트장 에오면 죽성리 바다를 한눈에 조망할수있다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02160', '박태준기념관', '관광지', 35.316877, 129.261226, '부산광역시 기장군 장안읍 임랑해안길 1', '대한민국 근현대사에 큰 족적을 남긴 청암 박태준의 업적을 기리고 그의 철학과 사상을 엿볼수있다 2021년 대한민국 공간문화대상을 수상하며 지역의 아름다운 공간으로 인정받았으며 수준높은 문화 콘텐츠를 제공하는 문화예술의 장으로도 사랑받고 있다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02161', '달음산자연휴양림', '관광지', 35.291977, 129.213303, '부산광역시 기장군 일광읍 화용길 299-106', '달음산 서쪽 자락에 위치하고 있으며, 부산시 최초의 국립 자연휴양림으로 산과 바다를 모두 즐길 수 있는 최적의 휴양림이다. 휴양림에서는 숙박은 물론, 숲 해설 프로그램과 목공예 체험 활동이 가능하다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02162', '홍성스카이타워', '관광지', 36.576682, 126.464427, '충청남도 홍성군 서부면 남당항로 689', '홍성스카이타워 총높이는 65m로 전망층과 옥상층으로 이루어져 있으며 옥상층에서는 보령, 태안, 서산까지 펼쳐진 서해 갯벌과 천수만의 리아스식 해안을 한눈에 담아 볼 수 있는 특별함을 가지고 있다. 특히 전망층에서는 둘레 66m의 파노라마식 스카이워크가 설치되어 천혜의 경관과 아찔한 스릴을 동시에 느껴볼 수 있으며 야간에는 천수만의 천년노을과 함께 야간 경관 연출이 홍성스카이타워에서만 느껴볼 수 있는 감동을 선사한다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02163', '남당항 해양분수공원', '관광지', 36.538115, 126.473753, '충청남도 홍성군 서부면 남당항로 171', '남당항 해양분수공원은 대하, 새조개, 바다송어로 유명한 남당항에 ‘23년도 조성한 핫 플레이스로 공원 총면적이 55,000㎡에 달하며 주간에는 국내 최대의 물놀이형 음악분수를 직접 몸으로 체험하여 즐길 수 있으며 야간에는 천수만 밤바다를 배경으로 레이저쇼 등 다양한 조명 연출의 음악 분수를 감상할 수 있다. 또한 2층 구조의 해양권 최초 네트어드벤처가 조성되어 있어 물놀이와 함께 다양한 레포츠를 체험할 수 있으며 공원 곳곳에 입체 음영 및 색으로 표현한 총 280m 규모의 트릭아트존 등 다양한 포토존들이 조성되어 있어 SNS 인생샷을 남길 수 있다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02164', '서포리playground', '관광지', 37.2232919, 126.1169337, '인천광역시 옹진군 덕적면 덕적남로606번길 3', '100년이 넘는 노송이 울창한 숲을 이루고 있고 완만한 경사와 넓이 300m 길이 3km의 넓은 백사장은 매년 10만 명이 넘는 관광객들의 휴식처가 되고 있는 곳이다. 200여 년은 족히 됐다는 소나무 8백여 본이 심어져 있는 소나무 숲은 단체야영에 제격이다. 거기에 넓은 운동장, 바닷가 놀이터, 테니스장, 음식점, 노래방, 자전거 대여소도 있으니 웬만한 레저시설은 다 준비되어 있는 셈이다. 주변의 갯바위에서는 우럭과 놀래미가 잘 잡혀 바다 낚시를 즐기는 관광객들의 발길이 끊이지 않고 있다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02165', '왕궁보석테마 playground', '관광지', 35.99061279, 127.1025486, '전북특별자치도 익산시 왕궁면 호반로 8', '익산 보석박물관', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02166', '소래포구', '관광지', 37.3988308, 126.7403795, '인천광역시 남동구 포구로 2-9(논현동)', '실제 어선이 드나드는 수도권 유일의 재래포구', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02167', '소래습지생태공원', '관광지', 37.40736572, 126.7463366, '인천광역시 남동구 소래로 154번길 77(논현동)', '갯벌과 옛 염전지역을 다양한 생물군락지와 철새도래지로 복원시킨 생태공원', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02168', '소래철교', '관광지', 37.3988308, 126.7403795, '인천광역시 남동구 포구로 2-9(논현동)', '수인선 협궤열차가 다니던 철로교량으로 길이 126미터의 소래철교는 1994년 열차운행이 중단된 후 통행로로 이용', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02169', '장도포대지', '관광지', 37.39790186, 126.7382687, '인천광역시 남동구 논현동 111-13', '인천광역시 문화재자료 제19호로 조선시대인 1877년 일본이 서해안 개항지를 물색하자 고종이 어영대장 신정희로 하여금 설치하였음', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02170', '소래역사관', '관광지', 37.39816347, 126.7375992, '인천광역시 남동구 아암대로 1605(논현동)', '소래의 역사와 문화 그리고 아름다운 옛모습을 보존하고자 2012년 6월에 개관한 남동구 최초의 공립박물관', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02171', '산청전통한방휴양playground', '관광지', 35.441066, 127.829361, '경상남도 산청군 금서면 동의보감로555번길 45-6', '엑스포주제관, 한의학박물관, 동의전 등 머무를 수 있는 체류형 playground', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02172', '문경 오미자테마터널', '관광지', 36.65989315, 128.1286031, '경상북도 문경시 마성면 문경대로 1356-1', '경북 8경 중 제1경으로 꼽히는 진남교반 고모산성 아래에 있는 오미자테마터널, 과거에 석탄을 실어나르던 문경선 내 석현터널을 개발함', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02173', '고모산성, 토끼비리', '관광지', 36.66292256, 128.1290151, '경상북도 문경시 마성면 고모산성길 60', '삼국시대의 성곽. 문경시 마성면 신현리 고모산(姑母山)에 있는 포곡식 산성', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02174', '문경짚라인', '관광지', 36.62285644, 128.1367824, '경상북도 문경시 불정길 174', '불정 자연휴양림 내에 위치한 짚라인, 난이도 및 코스길이가 다른 9개의 코스로 운영', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02175', '문경 종합온천', '관광지', 36.72937376, 128.1089547, '경상북도 문경시 문경읍 온천2길 24', '중탄산 온천수 및 알칼리성 온천수 등 신진대사를 촉진하는 2가지 온천수가 있음', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02176', '문경 활공랜드', '관광지', 36.7362239, 128.1538507, '경상북도 문경시 문경읍 활공장길 80', '문경읍(문경온천)에서 동쪽방향으로 4km쯤 떨어진 고요리 단산에 위치하며 이륙장 2개소와 착륙장 3개소를 갖추고 있음', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02177', '성삼문 선생 유허지', '관광지', 36.64524478, 126.7310363, '충청남도 홍성군 홍북읍 매죽헌길 403-12', '성삼문 선생 유허지) : 국가유산', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02178', '홍주성 역사관', '관광지', 36.60019877, 126.6609204, '충청남도 홍성군 홍성읍 아문길 20', '홍주성 역사관 : 홍성 역사 연구, 발굴, 조사, 전시, 교육 기관', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02179', '충남보훈관', '쇼핑', 36.602981, 126.660651, '충청남도 홍성군 홍성읍 상하천로', '충남보훈관 : 호국보훈을 기리는 전시장', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02180', '홍주의사총', '관광지', 36.6048297, 126.6708805, '충청남도 홍성군 홍성읍 의사로 79', '홍주의사총 : 1973년 12월 24일 충청남도기념물로 지정', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02181', '결성동헌', '관광지', 36.551381, 126.611921, '충청남도 홍성군 흥남서로 738번길', '결성동헌 : 조선시대 관아 1989년 4월 20일 충남문화재 지정', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02182', '통도환타지아', '관광지', 35.4999924, 129.0831299, '경상남도 양산시 하북면 통도7길 68', '영축산 아래 위치한 테마공원으로 다양한 행사와 놀거리, 볼거리 등을 제공하고 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02183', '홍룡폭포(홍룡사)', '관광지', 35.39699967, 129.0864895, '경상남도 양산시 상북면 홍룡로 372', '원효산 골짜기에 위치한 폭포로 떨어지는 모습이 꼭 용이 무지개를 타고 승천하는 것과 같다는 의미로 이름붙였고 상중하 세단계에 걸쳐 떨어지는 독특한 형태가 특징이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02184', '황산공원', '관광지', 35.30173083, 128.9895949, '경상남도 양산시 물금읍 황산공원5길 13', '낙동강을 따라 조성된 양산의 대표 도심 속 자연친화적인 수변공원으로 체육시설, 캠핑장, 자전거길, 산책로 등 다양한 공간이 있어 시민들의 휴식처가 되고 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02185', '대천해수욕장', '관광지', 36.31554012, 126.5108563, '충청남도 보령시 머드로 123', '대천해수욕장은 젊음과 낭만+안락함과 자연미가 함께 어우러져 있는 곳이다. 젊은 연인들에게는 추억 만들기의 장소로서 또 가족 단위의 휴식처로서 해양스포츠의 메카로서 제반 요건을 충분히 갖추고 있다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02186', '무창포해수욕장', '관광지', 36.24457737, 126.5365426, '충청남도 보령시 웅천읍 열린바다1길 10', '1928년 서해안에서 최초로 개장된 해수욕장으로 백사장 길이 1.5km 수심 1 ~ 2m+백사장 50m+수온 섭씨 22도+경사도 4도의 해수욕장으로 주변에는 송림이 울창하여 해수욕과 산림욕을 함께 즐길 수가 있다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02187', '가우도', '관광지', 34.53639111, 126.7910468, '전라남도 강진군 대구면 중저길 31-27', '곰솔나무 등 태고적 숨결이 가득한 함께해길그리고 바다를 걷는 출렁다리삶의 여유가 묻어나는 섬 가우도에서는 건강함도 함께한다', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02188', '영랑생가', '관광지', 34.64209922, 126.7655711, '전라남도 강진군 강진읍 영랑생가길 15', '구수한 남도 사투리로 현대 서정시의 새로운 지평을 열었던 영랑 김윤식 선생의 생가를 원형 그대로 보존한 곳으로 영랑의 시혼과 그 발자취를 엿볼 수 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02189', '다산초당', '관광지', 34.5807211, 126.7449445, '전라남도 강진군 도암면 다산초당길 68-35', '다산초당은 조선 후기 실학 사상을집대성한 다산 정약용 선생이 18년간의 유배기간 중 10여년간 생활하며후학을 양성하고 ’’’’목민심서’’’’를 비롯하여 500여권의 책을 저술했던 조선실학의 산실이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02190', '고려청자박물관', '관광지', 34.50866203, 126.8008374, '전라남도 강진군 대구면 청자촌길 33', '고려청자의 체계적인 관리와 연구를 위해1997년 고려청자박물관을 개관,운영하여청자의 연구는 물론 누구나 쉽게 청자를접하고 이해할 수 있도록 하고 있다.', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02191', '백련사', '관광지', 34.58775658, 126.747892, '전라남도 강진군 도암면 백련사길 145', '신라말에 창건되어 1211년 원묘국사요세에 의해 중창된 백련사는 1236년백련결사문을 발표하고 백련결사운동을주창하였으며 고려 8국사와 조선 8대사를배출하여 명찰로 알려지게 되었다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02192', '진주성', '관광지', 35.19043229, 128.0802214, '경상남도 진주시 남강로 626(본성동)', '8년 연속 한국관광100선에 선정된 진주의 대표적인 playground이자 사적지이다. 진주목사 김시민 장군이 임진왜란 때 3800여명의 적은 군사로 2만여 명의 왜군을 물리친 임진왜란 3대첩지의 하나로 다양한 유물과 유적이 성내에 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02193', '진양호', '관광지', 35.17660992, 128.0362677, '경상남도 진주시 남강로1번길 130(판문동)', '지리산을 바라볼 수 있는 아름다운 자연 경관과 어우러진 진양호는 시원하게 탁 트인 전망 속 호반의 물안개와 황홀한 저녁노을로 많은 사랑을 받고 있다.  진양호공원ㆍ 휴게전망대ㆍ소원계단ㆍ동물원ㆍ진주전통소싸움경기장ㆍ남강댐물문화관ㆍ어린이 교통공원ㆍ진양호 일주도로 등의 다양한 볼거리가 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02194', '경상남도 수목원', '관광지', 35.15719862, 128.2957346, '경상남도 진주시 이반성면 수목원로 386', '경상남도 수목원은 산림과 동식물에 대한 자연생태 종합학습교육장이다. 3340여 종의 식물을 보유하고 있으며 테마별로 전시관과 식물원이 조성되어 있어 나들이장소와 데이트 코스로 사랑받고 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02195', '월아산 숲속의 진주', '관광지', 35.199915, 128.1941257, '경상남도 진주시 진성면 달음산로 313', '월아산을 중심으로 조성된 복합 산림복지시설로 우드랜드ㆍ 산림레포츠ㆍ 자연휴양림 등 도심지와 가까운 곳에서 다양한 산림휴양을 즐길 수 있는 명소로 사랑받고 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02196', '물빛나루쉼터(김시민호)', '관광지', 35.18657405, 128.0788814, '경상남도 진주시 망경로 195', '물빛나루쉼터는 전통 목구조 건축 방식의  현대적 재현을 목표한 건축물로 2022 대한민국 목조건축대전ㆍ2023 캐나다 우드 디자인 앤 빌딩 어워드등에서 수상을 하였다. 김시민호는 남강의 운행하는 유람선으로 특히 야간에 선상에서 바로보는 진주성과 음악분수대의 화려한 조명 분수는 김시민호만의 매력 포인트이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02197', '일호광장진주역', '관광지', 35.17816441, 128.0893466, '경상남도 진주시 진주대로879번길 18(강남동)', '일호광장 진주역은 2024년 대한민국 공간문화대상에서 대통령상을 수상한 철도문화공원 내 위치하고 있다. 상설 및 기획 전시를 통해 철도와 관련된 기록을 공유함으로써 과거의 흔적과 옛 감성을 느낄 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02198', '방동playground', '관광지', 37.94387136, 128.3962628, '강원특별자치도 인제군 기린면 방동약수로 89-59', '기린면 방동지역에 위치하고 있음', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02199', '진주목공예전수관', '관광지', 35.24702277, 128.0417914, '경상남도 진주시 명석면 광제산로 367', '경남무형유산을 비롯하여 소목장의 고장으로 명석면에 위치하고 있으며 역사와 전통이 있는 진주소목의 가치를 알리고자 자체개발한 일일체험과 다양하고 전문적인 주ㆍ야간 목공 교육프로그램 및 전시실 운영으로 진주의 우수한 목공예 문화를 발전 계승한다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02200', '진주시립이성자미술관', '관광지', 35.17580996, 128.1427403, '경상남도 진주시 에나로 128번길 14(충무공동)', '진주시립이성자미술관은 진주 출신 이성자 작가의 376점의 작품을 기증받아 2015년 7월 16일에 개관하였다. 동녘의 여대사라고 불릴 만큼 세계적인 작가였던 이성자는 여성으로서 한국 최초의 프랑스 유학을 떠났으며 동양철학으로 서양의 문화를 재해석하여 자신만의 독창적인 작업세계를 펼쳤다. 진주시는 이성자 작가의 예술적 업적과 삶을 기리기 위해 작품에 대한 연구ㆍ수집ㆍ보존ㆍ전시ㆍ교육을 운영하고 있으며 현재 진주혁신도시 영천 강변에 위치한 미술관은 “나의 미술관이 지어진다면, 강을 조망할 수 있는 곳이면 좋겠다”라는 작가의 바램을 담은 공간이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02201', '진주익룡발자국전시관', '관광지', 35.1686382, 128.1396863, '경상남도 진주시 영천강로68번길 22(충무공동)', '천연기념물 진주 충무공동 익룡 새 공룡발자국 화석산지에 건립된 박물관으로 1억여년전 살았던 익룡을 비롯한 많은 생명체들의 흔적들이 화석으로 남아있다. 화석산지 현장이 그대로 보존된 보호각과 경남진주혁신도시 조성공사 중 발굴된 화석이 전시되어 있으며 화석과 관련된 다양한 체험이 마련되어 있어 가족 모두가 보고 즐길 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02202', '진주청동기문화박물관', '쇼핑', 35.22437983, 127.9619637, '경상남도 진주시 대평면 호반로 1353', '남강댐 확장에 따라 수몰된 국내 청동기시대 최대 유적지인 대평마을에 만들어진 청동기시대 전문박물관으로 상설전시관과 기획전시관ㆍ입체영상관과 야외전시장ㆍ수변산책로 및 물놀이 시설 등을 갖추고 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02203', '진주남강유등전시관', '관광지', 35.18180059, 128.0772058, '경상남도 진주시 망경로 207', '진주를 대표·상징하는 유등을 주제로 한 다양한 전시와 프로그램을 운영하고 야외 옥외정원에 유등을 상시 전시하여 관람객들이 예술과 소통할 수 있는 공간으로 자리잡고 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02204', '벽계playground', '관광지', 35.42604967, 128.2080942, '경상남도 의령군 궁류면 벽계로 201', '주변경관이 수려하며 물놀이장, 공연장, 캠프파이어장을 갖추고 있음', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02205', '우수영playground', '관광지', 34.57257374, 126.3101147, '전라남도 해남군 문내면 관광레저로 1', '이순신장군의 명량대첩의 감동이 살아있는 playground', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02206', '땅끝playground', '관광지', 34.29471348, 126.5250233, '전라남도 해남군 송지면 땅끝마을길 100', '한반도의 최남단이자 삼천리 금수강산의 시작점으로 희망을 상징하는 playground', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02207', '오색playground', '관광지', 38.077061, 128.5128997, '강원특별자치도 양양군 서면 가라피리 165', '설악산과 오색령에 아름다운 자연경관을 볼수 있음', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02208', '지경playground', '관광지', 37.927413, 128.794861, '강원특별자치도 양양군 현남면 지리 5-1', '동해안 해안절경 감상', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02209', '설해원(양양국제공항)', '관광지', 38.055556, 128.664198, '강원특별자치도 양양군 손양면 동호리 510-28', '장기체류형 종합 스포츠레저단지', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02210', '오수의견playground', '관광지', 35.54520338, 127.3326779, '전북특별자치도 임실군 오수면 충효로 2096-16', '재정비 공사중(24.12월까지)', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02211', '사선대playground', '관광지', 35.672357, 127.2746265, '전북특별자치도 임실군 관촌면 사선2길 68-7', '경관이 수려하고 편의시설이 있음', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02212', '해운대해수욕장', '관광지', 35.15910698, 129.1602838, '부산광역시 해운대구 해운대해변로 264', '6월부터 9월까지 해수욕장을 개장하여 해수욕을 즐길 수 있다. 수심이 얕고 조수의 변화가 심하지 않아 해마다 천만 명이 넘는 피서색이 찾는다. 또한 매년 해수욕장 개장에 맞춰 다양한 행사와 축제가 개최된다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02213', '달맞이동산지구', '관광지', 35.15768146, 129.1825429, '부산광역시 해운대구 달맞이길 190', '벚나무와 송림이 울창하게 들어찬 오솔길로 드라이브 코스로 유명하다. 달맞이 고개 일대에서는 다양한 예술작품을 만날 수 있고, 특히 보름날 달빛에 어우러진 바다 정취는 데이트 코스로 유명하다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02214', '변산해수욕장', '관광지', 35.67999179, 126.5309105, '전북특별자치도 부안군 변산면 변산로 2086', '국립공원 변산반도에 위치한 노을이 아름다운 해수욕장', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02215', '위도해수욕장', '관광지', 35.60583098, 126.2853294, '전북특별자치도 부안군 위도면 위도로 366', '산들이 감싸고 있는 아담한 모래사장과 맑은 물이 아름다운 위도의 해수욕장', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02216', '모항해수욕장', '관광지', 35.5831428, 126.5082098, '전북특별자치도 부안군 변산면 모항길 23-1', '아담한 백사장과 소나무 밭이 조화를 이루는 해수욕장', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02217', '주남저수지', '관광지', 35.30732964, 128.6779306, '경상남도 창원시 의창구 동읍 주남로 101번길 26', '해마다 찾아오는 수만 마리의 철새들과 텃새들의 서식지로 다양한 수생식물, 수서곤충 등을 만나볼 수 있으며 철새들의 자유로운 곡예비행을 생생하게 관찰할 수 있는 곳이다. 천연기념물 16여종과 환경부 멸종위기 10여종 등 다양한 철새들을 직접 볼 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02218', '마금산온천', '관광지', 35.35464845, 128.6094168, '경상남도 창원시 의창구 북면 천주로 1167', '마금산온천은 약알칼리성 수질로 평균 수온이 55℃ 이상을 유지하고 있으며, 나트륨, 철, 칼슘, 라듐 등 20여종의 광물질을 포함하고 있다. 운동욕장, 수영장, 노천탕 등 보양온천 시설을 갖추고 치료와 요양, 휴양이 가능하다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02219', '창원과학체험관', '관광지', 35.230268, 128.6617774, '경상남도 창원시 성산구 충혼로 72번길 16', '미래 과학자의 소중한 꿈을 키워 나갈 수 있도록 자라나는 꿈나무들에게 과학을 쉽고 재미있게 즐기면서 배울 수 있는 과학체험관이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02220', '마산해양레포츠센터', '관광지', 35.19529973, 128.5738199, '경상남도 창원시 마산합포구 제2부두로 56', '배를 타고 들어와 해양체험을 즐길 수 있는 이색적인 해양레포츠센터이다. 요일별 체험 프로그램을 진행하고 있으며', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02221', '웅천도요지전시관', '관광지', 35.12738997, 128.8155983, '경상남도 창원시 진해구 두동도요로 198', '웅천도요지 출토품을 비롯한 80여점의 유물이 전시되어 있는 전시실과 도자기를 직접 만들어 볼 수 있는 체험공방을 운영하고 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02222', '속초해수욕장', '관광지', 38.19014884, 128.6035305, '강원특별자치도 속초시 해오름로 186', '해안선 길이 약2km, 백사장 길이 약 500m이며 수심이 얕아 가족단위 관광객이 선호하는 속초시 대표 playground이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02223', '척산온천', '관광지', 38.19020313, 128.5407019, '강원특별자치도 속초시 관광로 327', '1971년 설립된 온천장으로 지하 4,000km 심도에서 발생한 온천수를 이용하며 설악산과 근접한 위치에 자리잡고 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02224', '설악한화리조트', '숙박', 38.21030036, 128.5287214, '강원특별자치도 속초시 미시령로 2983번길 111', '천연 온천수를 이용한 온천시설과 물놀이 시설을 갖춘 종합 테마파크이며, 설악 워터피아 등 다양한 부대시설은 완비하고 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02225', '은평역사한옥박물관', '관광지', 37.64033246, 126.9380102, '서울특별시 은평구 연서로50길 8', '은평구의 문화유산과 한옥의 전통을 소개하는 박물관', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02226', '금성당', '관광지', 37.63513547, 126.92538, '서울특별시 은평구 진관2로 57-23', '세종대왕 6째 아들 금성대군을 모신 당', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02227', '우장춘기념관', '관광지', 35.213515, 129.0720181, '부산광역시 동래구 우장춘로62번길 7(온천동)', '씨 없는 수박으로 우리 모두에게 잘 알려진 세계적 육종학자인 故우장춘박사의 탄생 1백주년을 맞아 그의 생전 연구 활동 유적지', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02228', '장영실과학동산', '관광지', 35.20916308, 129.0896688, '부산광역시 동래구 동래역사관길 18(복천동)', '동래출신 조선시대 세종당시 최고의 과학자인 장영실이 만든 세계최고의 옛 천문의기 18종 19점을 동래읍성북문광장 1,177㎡에 시비 5억을 투입하여 2009. 6. 16.부터 2009.10.15.까지 4개월에 걸쳐 사업을 완료하였다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02229', '박차정의사생가', '관광지', 35.20169645, 129.090397, '부산광역시 동래구 명륜로 98번길 129-10(칠산동)', '박차정의사 생가 복원사업은 항일독립운동가이자 한국여성해방운동의 선구자인 박차정의사의 남편 김원봉(임시정부국무위원, 북한노동상, 국가검열상)의 사회주의적 성향으로 군사정부시절 대우를 받지 못하다가 1995년 광복 40주년에 문민정부로부터 “대한민국 건국훈장 독립장”을 추서받은 지 10년만인 2005년 7월 8일 완공하였다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02230', '금강공원', '관광지', 35.21962513, 129.075758, '부산광역시 동래구 우장춘로 155 (온천동)', '울창한 숲과 기암절벽, 골짜기 마다 흐르는 맑은 시냇물 등이 신선경에 들어선 느낌을 주며, 봄철부터 겨울철에 이르기까지 인적이 끊이지 않는 근린공원으로서 남녀노소 누구나가 즐길 수 있는 휴식처로 사랑을 받고 있다', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02231', '장계playground', '관광지', 36.37753534, 127.6350074, '충청북도 옥천군 안내면 장계1길 57', '아름다운 대청호반이 한눈에 내려다보이며, 향토자료 및 시문학 작품을 감상할 수 있음', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02232', '금정산', '관광지', 35.28304264, 129.0676208, '부산광역시 금정구 범어사로 250', '금정산은‘산마루에 우물이 있어 한 마리 금빛 나는 물고기가 오색구름을 타고 하늘에서 내려 와 우물 속에 놀았다’는 이야기에서 유래하여 이름 붙은 부산의 진산이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02233', '범어사', '관광지', 35.28304308, 129.0676212, '부산광역시 금정구 범어사로 250', '범어사는 역사적으로 많은 고승대덕을 길러내고 선승을 배출한 수행사찰로 오랜 전통과 많은 문화재가 보존되어 있는 한국 불교계의 중심지 중 하나이다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02234', '곡성 섬진강 기차마을', '쇼핑', 35.27753157, 127.3082867, '전라남도 곡성군 오곡면 기차마을로 232', '증기소리가 둔탁하지만 촌스럽지 않고, 많은 사람들의 관심을 받지만 혼자만의 공간이 있는곳.증기기관차와 레일바이크체험, 음악분수, 엔터테인먼트 놀이공간까지 옛 추억과 테마가 있는 새로움과 익숙함이 공존하는 새로운 개념의 테마파크이다.인기 playground로 각광을 받고 있는 기차마을의 첫 관문은 옛 곡성역 건물을 그대로 기차마을 정문으로 사용하고 있다. 그래서 그곳을 통과하면 아련한 추억이 기다리고 있을 것 같다.1960년대를 고스란히 옮겨 놓은 것 같은 플랫폼으로 기차가 들어오자 내리는 승객들과 그것을 배경으로 사진을 찍어 추억을 남기고 , 플랫폼에는 수형이 아름다운 두 그루의 소나무가 있는데 소나무를 배경으로 나란히 서서 단체사진을 찍어도 멋지다.관람은 반 시계 방향으로 돌면서 관람시설과 놀이시설을 하나씩 섭렵해가는 것이 가장 효과적인데 기차 체험 공간 치치뿌뿌 놀이터, 오감으로 느끼는 4D 영상관, 커다란 도깨비가 방망이를 치켜들고 서 있는 재미있는 요술 랜드를 차례로 돌아보는 동안 우리는 어느덧 동심의 세계에 흠뻑 빠져들수 있다. 전통체험관에서 칼에 글귀를 새기는 무형문화재 낙죽장도 전시관도 볼 수 있다.기차마을 최고의 포토존으로 알려진 장미공원은 기차마을 안에 있으면서도 별도의 공원이나 다름없는 매우 특별한 공간이다. 장미공원은 무려 3만 7천여주, 1004종의 장미와 세계 몇 안 되는 희귀종도 수십종을 보유중이다.그리고 그 명성을 유지하기 위해 숙련된 원예 전문가들이 일년 내내 정성을 다하여 관리하고 있는데 5월 장미 축제때는 이곳의 장미들이 일제히 개화를 하면서 대단한 장관이 펼쳐진다.이때 우리나라 최고로 꼽히는 장미의 향연을 즐기기 위해서 전국에서엄청난 관광객들이 몰려드는데 곡성 장미공원의 5월 장미는 꼭 봐야할 명소이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02235', '기차마을 장미공원', '관광지', 35.27753157, 127.3082867, '전라남도 곡성군 오곡면 기차마을로 232', '섬진강기차마을 단지 내에 위치한 장미공원은 대한민국 최고의 장미공원을 목표로 사랑의 상징 ‘천사’와 음이 같은 1,004 품종을 수집하여 40,000㎡의 부지에 독일, 프랑스, 영국 등 유럽의 우수한 장미품종들을 수집, 전국에서 가장 많은 1,004종의 장미를 식재하여 조성되었다. 장미와 다양한 수목, 연못 등이 아름다운 경관을 이루고 있으며, 그 밖에 분수, 미로원, 야외공연장, 파고라 등 다양한 시설을 갖추고 있다. 독특하고 다양한 장미품종들을 정성스럽게 관리하여 5~11월 계속해서 장미꽃을 감상할 수 있고, 매년 5월에서 6월 사이 세계장미축제를 개최하여 많은 관광객들을 맞이하고 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02236', '섬진강 침실습지', '쇼핑', 35.27503038, 127.3335915, '전라남도 곡성군 고달면 고달길 192-6', '제22호 국가기정습지로서 천혜의 자연환경이 잘 보전되어 있다. 수달, 흰꼬리수리, 삵 등 멸종위기 동물의 서식지이다. 이른 아침 물안개와 일출, 그리고 일몰풍경 등 시시각각 변하는 풍경이 한 폭의 동양화를 연상시킨다.침실 습지는 섬진강 유역인 곡성군 고달면 고달교에서 오곡면 오지1교까지 서울 여의도 면적과 비슷한 규모의 광활한 강 습지로서 물버들 군락이 이룬 가운데, 강변에는 울창한 갈대숲이 형성되어 있다.수달, 고라니, 오소리를 비롯한 포유류와 다양한 조류들이 서식 하는 생태계의 보고로 2016.11.7 국가습지보호구역으로 지정되었다.침실 습지는 언제 어느 때 찾아도 섬진강이 자아내는 아름다움의 진수를 만날 수 있지만 특히 이른 아침 무렵에 찾아가면 겨울에는 상고대, 이른 봄과 가을에는 물안개가 그려내는 비경을 만날 수 있다.버드나무와 갈대숲 그리고 크고 작은 섬들이 어우러져 아름다운 경관을 자랑한다.빼어난 풍경과 생물 다양성을 인정받아 2016년 11월에 강 중류 하도습지로는 유일하게 환경부로부터 22번째 국가습지로 지정되었다. 특히 일교차가 심한 새벽이면 물안개가 피어오르면서 환상적인 장면을 연출한다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02237', '곡성아트빌리지', '카페', 35.23004949, 127.3677915, '전라남도 곡성군 오곡면 섬진강로 1455', '곡성아트빌리지는 섬진강 증기기관차가 운행하는 가정역에 위치해 있으며 아트갤러리, 유리공예 체험장, 야외공연장, 캡슐호텔과 목조펜션, 카페굴리엘모 등으로 이루어져 있어 가정역에서 머무르며 향기 가득한 차 한잔과 함께 낭만 가득한 섬진강을 느껴볼 수 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02238', '삽교호playground', '관광지', 36.88890544, 126.8247541, '충청남도 당진시 신평면 삽교천3길 100', '서해대교를 비롯, 호수와 바다가 한눈에 들어오는 곳', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02239', '왜목마을playground', '쇼핑', 37.04493276, 126.5246154, '충청남도 당진시 석문면 왜목길 15-5', '서해 최고의 일출, 일몰 감상지', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02240', '청도레일바이크', '관광지', 35.58811543, 128.7661723, '경상북도 청도군 청도읍 하지길 46-51', '청도천변 주변으로 폐선된 옛 철길을 테마로 왕복 5km의 레일바이크를 체험할 수 있다. 자동화시스템을 이용해 오르막도 편하게 오를 수 있다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02241', '청도자전거공원', '관광지', 35.5881145, 128.7661742, '경상북도 청도군 청도읍 하지길 46-51', '청도레일바이크 옆에 조성된 공원으로 군내 최대 규모의 자전거공원이다. MTB지원센터에서 자전거를 대여해 체험을 즐길 수 있어 초봅자 부터 마니아까지 많이 찾는 곳이다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02242', '청도신화랑풍류마을', '관광지', 35.71750257, 128.9207343, '경상북도 청도군 운문면 신화랑길 1', '화랑의 세속오계 정신을 연출한 체험형 복합관광단지로 화랑정신발상지기념관, 대강상, 명상실, 국궁장, 스카이트레일, 짚라인, 콘도, 카라반 등의 시설을 갖췄다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02243', '새마을운동발상지기념공원', '숙박', 35.60012971, 128.7661487, '경상북도 청도군 청도읍 새마을1길 34', '새마을운동의 발상지인 신도리에 건립되었따. 새마을운동의 탄생배경, 과정 등을 알 수 있는 전시실이 있고 숙박시설, 신거역, 대통령 전용열차 등 70~80시대를 실감나게 재현해 놨다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02244', '청도소싸움경기장', '관광지', 35.6867346, 128.7251449, '경상북도 청도군 화양읍 남성현로 348', '세계 최초 돔형식(개폐식) 소싸움경기장으로 전통 민속문화인 소싸움을 매주 주말 11시부터 경기를 관전할 수 있다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02245', '와인터널', '관광지', 35.71513567, 128.7205341, '경상북도 청도군 화양읍 송금길 100', '대한제국 말기 완공되어 용도없이 방치되어온 터널을 정비하여 감와인 숙성저장고로 활용하고 있다. 터널 내부 온도는 섭씨 13~15도를 유지하고 있어 여름에는 피서용, 겨울에는 피한용으로 제격이다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02246', '김포평화누리길 1코스', '관광지', 37.6535376, 126.5533799, '경기도 김포시 대곶면 대명리 561(대명항)', '김포 평화누리길은 대명항에서 시작하여 문수산, 애기봉 입구를 지나 전류리포구까지 3코스(총39km)로 나뉘어 조성되어 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02247', '김포평화누리길 2코스', '관광지', 37.73869766, 126.5484911, '경기도 김포시 월곶면 성동리 산49(문수산성)', '김포 평화누리길은 대명항에서 시작하여 문수산, 애기봉 입구를 지나 전류리포구까지 3코스(총39km)로 나뉘어 조성되어 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02248', '김포평화누리길 3코스', '관광지', 37.70077831, 126.6622045, '경기도 김포시 하성면 전류리 43-4(전류리 포구)', '김포 평화누리길은 대명항에서 시작하여 문수산, 애기봉 입구를 지나 전류리포구까지 3코스(총39km)로 나뉘어 조성되어 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02249', '김포 장릉', '관광지', 37.6107519, 126.7126583, '경기도 김포시 장릉로 79(풍무동)', '유네스코 세계문화유산으로 등재된 장릉(사적 제202호)은 조선 16대  인조대왕의 생부인 원종과 부인 인헌왕후 구씨를 모신 곳이다. 능 주위가 공원으로 꾸며져 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02250', '애기봉 평화생태공원', '관광지', 37.75316598, 126.5942484, '경기도 김포시 월곶면 평화공원로 289', '병자호란 때 끌려간 평안감사를 그리워하다 죽은 애기의 한이 강 하나를 사이에 두고 오가지 못하는 이산가족의 한과 같다고 하여 애기봉이라 명명한 곳으로 우리나라에서 북한을 제일 가까이에서 볼 수 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02251', '문수산성', '관광지', 37.7429948, 126.5467533, '경기도 김포시 월곶면 성동리 산50', '1694년(숙종20)에 외적을 막고 강화도 방어를 위해 쌓은 산성으로 병인양요 때 프랑스근과 치열한 격전을 벌인 곳으로 유명하다  현재는 총길이 6km 중 성곽의 일부 979m를 보수하여 4km의 성곽이 남아있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02252', '김포함상공원', '관광지', 37.6406387, 126.539261, '경기도 김포시 대곶면 대명항1로 110-36', '52년간 바다를 지켜오다 2006년 12월 퇴역한 상륙함(운봉함)을 활용하여 조성한 수도권 유일의 함상공원으로 다양한 전시품 감상 및 함상 체험활동을 할 수 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02253', '진하해수욕장', '관광지', 35.38384823, 129.3460154, '울산광역시 울주군 서생면 진하해변길 77', '수심이 얕고 파도가 잔잔하여 가족단위 해수욕에 알맞은 울산의 대표적 해수욕장', '울산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02254', '영남알프스 복합웰컴센터', '관광지', 35.55645417, 129.0679842, '울산광역시 울주군 상북면 알프스온천5길 103-8', '울주 서쪽에 자리하고 있는 1,000m높이의 산들이 유럽 알프스와 견주어도 손색이 없어 많은 등산객들이 방문하고 있음', '울산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02255', '외고산옹기마을', '관광지', 35.435094, 129.2795067, '울산광역시 울주군 온양읍 외고산 3길 36', '전국 최대 규모의 옹기 집성촌으로 옹기를 만드는 공방과 전통 옹기 가마를 볼 수 있다.', '울산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02256', '울주 대곡리 반구대 암각화', '관광지', 35.60863087, 129.172957, '울산광역시 울주군 언양읍 반구대안길 285', '태화강의 한 지류인 대곡천의 너비 10m, 높이 3m바위에 새겨진 그림으로 신석기 시대부터 여러시대에 걸쳐 제작된 것으로 보인다. 국보 285호', '울산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02257', '노무현대통령생가', '관광지', 35.31448783, 128.7712136, '경상남도 김해시 진영읍 봉하로129', '故 노무현 대통령이 1946년 9월 1일 태어나 8살까지 살았던 집, 전통적인 초가집 형태로 본채에 방 2칸과 부엌, 아래채에 헛간과 옛날식 화장실이 있다', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02258', '김해수로왕릉', '관광지', 35.23487875, 128.8772054, '경상남도 김해시 왕릉길 26(서상동)', '가락국의 시조인 김수로왕의 릉으로 김해의 상징적인 문화유적이다', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02259', '불갑사playground', '관광지', 35.199675, 126.550047, '전라남도 영광군 불갑면 불갑사로 450', '유서깊은 불교문화의 역사와 수려한 자연경관를 간직한 불갑사 지구의 관광명소이며 관광수요에 능동적으로 대처할 수 있는 휴식공간 제공', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02260', '함평해수찜', '관광지', 35.10050068, 126.4648643, '전라남도 함평군 손불면 석산로 61', '온천과 약찜의 효능을 한꺼번에 즐길수 있음', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02261', '함평자연생태공원', '관광지', 35.13500123, 126.5057, '전라남도 함평군 대동면 학동로 1398-77', '사계절 탐방학습과 생태체험', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02262', '함평양서파충류생태공원', '관광지', 35.13834076, 126.4937003, '전라남도 함평군 신광면 학동로 1398-9', '국내 최대 양서파충류 전문 전시관', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02263', '함평엑스포공원', '관광지', 35.05813923, 126.5226056, '전라남도 함평군 함평읍 곤재로 27', '아시아생태문화playground', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02264', '일강김철선생기념관', '관광지', 35.18893103, 126.4801235, '전라남도 함평군 신광면 일강로 873-12', '독립운동가 김철선생의 애국정신을 재조명하는 교육의 장', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02265', '꽃무릇공원', '관광지', 35.18352786, 126.5452774, '전라남도 함평군 해보면 용천사길 209', '한국의 백경중 일경에 속하는 40여만평의 꽃무릇과 나비, 꽃무릇공원을 배경으로 매년 9월 꽃무릇큰잔치가 열리고 있습니다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02266', '함평자동차극장', '관광지', 35.05813923, 126.5226056, '전라남도 함평군 함평읍 함장로 1162', '최신 영화를 자동차에서 편하게 관람하실 수 있습니다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02267', '프로방스 포토랜드', '관광지', 35.68397476, 128.7187441, '경상북도 청도군 화양읍 이슬미로 272-28', '프랑스의 정감 있는 프로방스마을을 그래도 재현했다. 밤이되면 1000만여개의 화려한 조명과 자신만의 감각을 살려 사진을 찍을 수 있는 셀프스튜디오가 있다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02268', '김해가야테마파크', '관광지', 35.25163508, 128.8937494, '경상남도 김해시 가야테마길 161', '가야의 역사를 놀이, 체험, 전시를 통해 보고 듣고 느낄 수 있는 오감 체험형 테마파크', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02269', '김해낙동강레일파크', '카페', 35.37177644, 128.8208387, '경상남도 김해시 생림면 마사로473번길 41', '밀양시 삼랑진역과 광주시 광주송정역을 잇는 경전선으로 레일바이크, 와인동굴, 열차카페, 철교 전망대를 조성', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02270', '가야랜드', '관광지', 35.25817158, 128.9024348, '경상남도 김해시 인제로 368(삼방동)', '가야테마파크 건너편에 자리한 어드벤처 놀이동산', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02271', '김해천문대', '관광지', 35.25306424, 128.887298, '경상남도 김해시 가야테마길 254(어방동)', '밀레니엄 기념사업의 일환으로 2002년 2월 1일 개관한 영남지역 유일의 시민 천문대', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02272', '롯데워터파크', '관광지', 35.17891121, 128.8285605, '경상남도 김해시 장유로 555(신문동)', '남태평양 폴리네시아를 콘셉트로 2만여 명을 동시에 수용할 수 있는 국내 최대 규모의 워터파크', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02273', '클레이아크김해미술관', '관광지', 35.25086479, 128.7457858, '경상남도 김해시 진례면 분청로 25', '세계 최초의 건축도자 전문 미술관', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02274', '김해한옥체험관', '관광지', 35.23436297, 128.8766847, '경상남도 김해시 왕릉길 40(봉황동)', '소박한 전통의 멋과 편리한 현대적인 편의시설을 두루 갖춘 한옥 체험관', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02275', '곡성기차당 뚝방마켓', '쇼핑', 35.27976851, 127.2984376, '전라남도 곡성군 곡성읍 곡성로 856', '곡성역 그리고 러브트레인이 설치된 곡성 기차마을 후문과 곡성읍 사이에는 곡성천으로 연결되어 있다. 깔끔하게 정비된 곡성천 제방위로 예쁜 길이 나있다.이길은 뚝방길이라 불리우며 곡성사람들의 산책로로 이용되고 있다.이 길을 알려 곡성섬진강기차마을과 곡성읍을 연결하자는 의미로 이곳에 플리마켓 즉 누구나 판매자가 되고 소비자가 될 수 있는 벼룩시장을 연 것이다. 2016년 5월에 곡성에서 열리는 세계 장미축제의 개최와 함께 최초로 문을 연 뚝방마켓회를 거듭할수록 곡성 주민 뿐만 아니라, 인근 지역에서 일부러 뚝방마켓을 구경하러 찾아올 정도로 인기를 끌고 있다. 그리고 뚝방길을 알리는 효과를 넘어서 이제는 곡성을 대표하는 문화 현상으로 자리 잡았다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02276', '가정역(섬진강출렁다리)', '관광지', 35.23018353, 127.3682034, '전라남도 곡성군 오곡면 섬진강로 1465', '가정역은 기차마을을 떠나 13km를 달려온 증기기관차와 침곡 약을 출발하여 5.2km를 굴러온 레일바이크의 종착역이다.원래 전라선 철로에는 없었던 역인데 증기기관차 운행과 함께 순수한 관광 목적으로 지어졌다. 통나무집을 연상케 하는 가정역의 외관은 마치 알프스 산악 기차역 같은 모습을 하고 있어 관광객들의 눈길을 끈다.섬진강 출렁다리는 국내 보도 현수교 중 가장 긴, 길이 200m, 폭 3m의 규모라 한다. 주 케이블에 보조 케이블을 매달아 보도 강판을 지탱하는 보강 거더(girder)에 연결했다. 따라서 바람에 흔들리거나 많은 사람들이 건너게 되면 출렁거리도록 제작되었다.증기기관차로 가정역에 도착하면 출발시간까지 30 남짓 여유시간이 주어진다. 이곳에 머무는 이들을 ’추억과 향수’에 젖어들게 하기엔 충분한 시간이다.가정역이 ’아름다운 역’으로 기억될 수 있는 것은 지척에 우리나라 사람들에게 고향의 강으로 여겨지는 섬진강이 흐르고 있어서다. 가정역에 내린 승객들은 강을 가로지르는 출렁다리를 건너가서 자연스럽게 섬진강을 만난다.그리고 강변을 산책하면서 더 가까이서 섬진강 풍경을 감상하게 된다. 따라서 이곳을 처음 찾는 이들에게 가정역은 섬진강과 동의어로 여겨진다. 강을 건너올 때는 사람만 다닐 수 있는 출렁다리를 이용하지만, 다시 가정역으로 건너갈 때는 대개, 아래쪽에 설치된, 사람과 차량이 함께 통행할 수 있는 두계 세월교를 이용한다. 이 다리는 강물이 불으면 물속에 잠기게 되는 잠수교다. 가정역에서 기다리고 있는 증기기관차가 긴 기적소리를 울리면 출발시간이 임박했음을 알리는 신호다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02277', '도림사오토갬핑리조트', '숙박', 35.26209959, 127.2668616, '전라남도 곡성군 곡성읍 도림로 74', '도림사관광단지 내에 위치하고 있는 캠핑장으로 가족단위의 새로운 개념의 숙박시설로캐러밴 4인 4대 / 캐러밴 6인 21대 / 편백하우스 14동 / 캠핑장 40면과 취사장, 샤워장, 화장실 등캠핑에 필요한 시설이 마련되어 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02278', '청계동솔바람야영장', '관광지', 35.31107436, 127.2623887, '전라남도 곡성군 곡성읍 청계동로 415', '청계동 솔바람 야영장 일원은 섬진강과 인접해 있어 경치가 아름답고 계곡의 물과 주변에 울창한 숲이 우거져 계곡 피서지로는 절정의 인기를 누리는 곳이다.계곡 곳곳에는 자연속의 풀장, 어린이 놀이터, 잔디광장, 의병 체험장, 산책로 등이 조성되어어린이를 동반한 가족 단위 피서객들의 편안한 휴식처이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02279', '대황강자연휴식체혐장야영장', '관광지', 35.12497878, 127.2550756, '전라남도 곡성군 석곡면 유정리 37', '저희 대황강 자연휴식체험캠핑장은 여가 및 레저수요에 대응한 수변관광시설을 조성하고 기존 자원과의 연계를 통한 치유의 자연휴식 체험장 조성으로 관광객 증대 및 지역 활성화 도모하고 있습니다. 석곡면은 곡성군의 서남쪽에 위치하며, 동쪽으로는 죽곡면과 목사동면, 서쪽으로는 화순군 북면, 남쪽으로는 순천시 주암면, 북쪽으로는 삼기면과 경계를 이루고 있으며 통명산, 국사봉, 한동산 등이 사방에서 솟아 있으며, 대황강(보성강)이 지역의 남쪽에서 북쪽으로 흐르고 있어서 온수천이 남류하는 유역과 연반천과 당월천이 합류하여 남쪽으로 흐르는 석곡천 유역에 소평야가 조성되어 있어 토질이 비옥하고 수리가 안전합니다.또한 호남고속도로 (석곡 나들목)와 국도 27호선이 서로 연결되어 있어 교통이 편리하며 대황강을 중심으로 목사동면과 경계를 이루고 있어서 대황강 자연휴식체험캠핑장 접근이 용이합니다. 대황강 곳곳에는 자연속의 물놀이장, 어린이 놀이터, 잔디광장, 체험장, 산책로 등이 조성되어 어린이를 동반한 가족 단위 피서객들의 편안한 휴식처가 될 것입니다.가족 및 친구, 연인들과 행복한 추억을 만들 수 있는 이곳 대황강 자연휴식체험캠핑장이 여러분을 기다립니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02280', '청계동계곡', '관광지', 35.31375081, 127.2525557, '전라남도 곡성군 곡성읍 신기리 산 190-1', '곡성읍과 입면 사이로 동악산이 큰 용처럼 달려오다 강줄기를 만나 멈춘 곳이다. 또한 기암괴석으로 이루어진 남원시의 한봉과 순자강을 사이에 두고 서로 손으로 모으고 만나는 듯한 도계(道界)지역으로써 예부터 주변 경관이 빼어나 마치 삼청의 진경을 옮겨 놓은 듯 하다는 명승지이다.여름에는 맑은 물이 계곡 사이로 흐르고, 울창한 소나무 숲이 우거져 시원한 그늘이 많다. 계곡바닥에 깔려있는 바위와 돌들은 매끄럽고 부드러워 앉아서 놀기가 매우 좋다. 4km쯤 되는 긴 계곡으로 주변에 크고 작은 산 골짜기가 수없이 많고 골짜기를 따라 군데군데 작은 폭포들이 있는 아담한 곳이다. 계곡을 오르는 산책길의 경사도는 평지와 같이 완만하여 여름철이면 피서지로 최상의 휴식지이다.청계동 계곡은 도로와 접해 있어 접근이 쉽고, 수량이 풍부하여 물놀이하기에 최고의 조건을 갖추고 있어 여름이면 계곡 피서지로서 절정의 인기를 누린다. 섬진강과 연결되는 계곡 하류 쪽에 넓은 자연풀장이 형성되어 있어 어린이를 동반한 가족피서지로도 각광을 받고 있다. 청계동 입구에서부터 소나무사이로 난오솔길을 따라가다 보면, 무수한 계곡 쉼터를 발견할 수 있고 약 2km 거리에 청계폭포가 있다.이 곳은 임진왜란시 금산전투에 참가하여 장렬하게 전사한 최초의 의병장 청계 양대박 장군이, 왜군에게 동래성이 함락 당했다는 비보를 접하고, 즉시 낙향하여 의병을 모아 이 계곡에 진을 치고 군사를 조련했다고 하여 그의 호를 따서 청계동이라 부르게 되었다고 한다. 그래서인지 청계동 계곡에서 만나는 풍경마다엔 양대박 장군의 호연지기가 서려있는 듯하다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02281', '도림사계곡', '관광지', 35.26724907, 127.2575171, '전라남도 곡성군 곡성읍 도림로 175', '해발 748.5m의 동악산 남쪽 골짜기를 흘러내리는 것으로 동악계곡, 성출계곡과 더불어 아홉구비마다 펼쳐진 반석 위로 맑은 물줄기가 마치 비단을 펼쳐 놓은 듯이 흐르고 수맥이 연중 그치치 않을 뿐만 아니라 노송, 계곡, 폭포들이 어우러져 절경을 이루고 있는 도림사 계곡은 지방 기념물 101호로 지정되어 있다.주변의 경치를 감상할 수 있는 반석들이 있어 예부터 풍류객들의 발길이 잦았으며 이곳 9개의 반석에는 선현들의 문구가 음각되어 있어 그들의 풍류를 엿볼 수 있고 한 아름 반석 위로 흐르는 계곡 물에 몸을 담그는 맛이 색다르다.선현들이 이곳에서 시를 짓고 노래를 불렀을 그 자취와 흔적들이 지금까지 도림사 계곡암반 위에 고스란히 남아있다. 무엇보다 선비들이 이곳을 즐겨 찾았던 또 다른 의미는 이 계곡에 성리학이 이상향으로 삼는 청류구곡의 형상이 구현되어 있다고 믿었기 때문이다. 그래서 계곡의 와폭(臥瀑)과 담(潭), 소(沼), 대(臺) 등의 암반을 아홉 구간 즉 구곡으로 구분하여 각각의 골짜기에 맞는 경구를 새겨놓고, 도림사 계곡에 머무는 그 자체를, 성리학적 이념을 되새기는 행위로 여겼다. 따라서 도림사 계곡은 성리학을 포함한 유불선의 정신이 살아있는 경전과 같은 역할을 하게 된다. 도림사 계곡이 갖는 이러한 의미는 한일합방 이후 독립운동가들에 의하여 항일운동의 이념적 거점으로 삼으려는 시도와도 연결된다.그리고 이 계곡 정상 부근에는 이곳에서 바라보는 전망이 좋아 신선이 쉬어 간다고 하는 높이 4m에 넓이 30평에 달하는 신선바위가 있으며 멀리 보이는 형제봉은 등산로 코스로 널리 알려져 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02282', '태안사계곡', '관광지', 35.13195828, 127.3863807, '전라남도 곡성군 죽곡면 태안로 622-215', '섬진강으로 흘러드는 보성강은 잔잔한 물줄기지만 다른 곳에 비해 덜 알려져 자연 그대로의 모습을 간직하고 있다. 보성강으로 흘러드는 태안사계곡은 이런 보성강의 아기자기한 특징을 잘 드러내주는 계곡이다.태안사 입구에서 절까지 걸어가는 2㎞쯤 되는 계곡길은 여느 계곡길보다 짧지만 이런 기대를 충족시켜주기에 충분한 자격을 갖고 있다. 고로쇠나무, 떡갈나무, 단풍나무, 소나무가 우거져 있고, 차가운 계곡에 발을 담그면 한여름의 무더위는 순식간에 사라진다.태안사의 현관 역할을 하는 능파각(凌波閣)의 운치있는 다리겸 누각도 계곡의 풍광을 즐기기 좋은 곳이다. 태안사계곡은 아주 빼어난 바위봉들은 없어도 아늑하고 편안한 분위기만으로 충분히 더위를 잊을 수 있는 곳이다.능파각(凌波閣)이라는 말은 아름다운 여인의 우아하고 가벼운 걸음걸이를 뜻한다고 한다. 능파각은 서기 850년 혜철선사가 태안사를 창건할때부터 지어졌던 목조 건물로서 몇 번의 복원과 보수끝에 지금의 모습을 유지하고 있는 것이다.능파각을 건너 숲으로 접어들면 이내 일주문이 나오면서 태안사의 정경이 한눈에 들어온다. 태안사는 지금은 규모가 그리 크지 않지만 구산선문의 유서 깊은 절로 한때 화엄사를 거느리기도 했었다. 경내에는 지름 40m쯤 되는 큰 연못 가운데 부처님 사리를 모셨다는 삼층석탑이 있어 색다른 느낌이 든다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02283', '태안사', '관광지', 35.13195828, 127.3863807, '전라남도 곡성군 죽곡면 태안로 622-215', '태안사는 통일신라 경덕왕 원년(742)에 이름모를 스님 세 분이 세웠다고 전한다. 고려시대에는 광자대사가 크게 늘려 지었는데 이 때 절의 규모는 총 40여 동에 110칸이었고, 법당에는 높이 1.4m되는 약사여래철불좌상을 모셨던 듯하다. 고려 고종 10년(1223)에는 당시 집권자인 최우가 고쳐 지었으며, 조선시대에는 숙종 10년(1684)에 주지 각현이 창고를 새로 지었다는 기록이 보이고 있다. 특히 조선초에 태종의 둘째 아들 효령대군이 이곳에 머물렀던 인연이 있는 곳이다. 한국전쟁때 많은 피해를 입어서 지금 있는 건물은 대부분이 복원된 것이다.경내에는 혜철선사의 부도인 적인선사조륜청정탑(보물 제273호), 윤다의 부도인 광자대사탑(보물 제274호), 광자대사비(보물 제275호), 승무를 출 때 사용하던 태안사대바라(보물 제956호), 태안사동종(보물 1349호), 태안사일주문(전라남도 유형문화재 제83호), 태안사삼층석탑(문화재자료 제170호) 등이 있다. 은빛모래와 하늘이 비치는 맑은 물의 섬진강을 끼고 곡성읍에서 17호선의 국도를 따라 16km가다보면 섬진강과 보성강이 합류하는 압록유원지가 나온다. 이곳에서 보성강을 끼고 국도 18호선을 따라 6km정도 가다보면 태안사로 들어가는 태안교를 접하게 되고 다리를 건너 다시 6km정도 가다보면 죽곡면 원달리에 위치한 태안사에 다다를 수 있다.동리산 자락에 위치한 태안사는 신라 경덕왕 원년(742년)에 동리산파를 일으켜 세 선승에 의하여 창건한 것으로 알려져 있는데, 처음에는 대안사로 불리웠으며 이 나라 불교의 선문 아홉가지의 하나인 동리산파의 본산지로 선암사, 송광사, 화엄사, 쌍계사 등을 거느리고 꽤 오랫동안 영화로움을 누렸던 사찰로 혜철선사와 도선국사가 득도한 정량수도의 도량이다.고려시대에 들어와서 광자선사가 32칸으로 넓혀 지었으나 고려시대 중기에 송광사가 조계종의 본산지로 지위를 굳혀 따로 제금났고, 조선시대에는 불교를 억누르는 정책 바람을 탈 수 밖에 없었으나 효령대군이 머물며 왕가의 원당으로 삼기도', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02284', '안개 농촌체험 휴양마을', '관광지', 35.29052093, 127.3419816, '전라남도 곡성군 고달면 고산로 39-18', '‘곡성안개마을’은 곡성군 고달면 목동리 연꽃방죽 옆에 위치하고 있으며 국가보호습지로 지정된 섬진강 ‘침실습지’를 바라보는 장소에 위치한 체험휴양마을입니다.아침이면 강변 습지에 물안개가 피어오르고 강변을 따라 이어지는 섬진강 자전거길의 풍경은 오염되지 않은 청정자연 그대로의 강의 모습을 고스란히 간직하고 있으며 강 건너 기차마을의 증기기관차의 기적소리가 향수를 불러일으키는 곳입니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02285', '가정 농촌체험 휴양마을', '관광지', 35.22727591, 127.3704119, '전라남도 곡성군 고달면 가정마을길 65', '곡성 가정마을은 녹색농촌체험마을이다. 청소년 야영장과 인접해 있고, 섬진강과 시골의 향취를 마음껏 느낄 수 있다. 가정마을에서 체험할수 있는 프로그램들도 다양한데 그 중에서 먹거리체험으로는 인절미 떡메치기와 전통 손두부,콩비지도넛 만들기 체험이다. 계절에 따라 고사리꺾기,매실따기,복숭아따기,자두,살구,감,배등 각종 수확체험이 단연 인기체험이다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02286', '죽산 농촌체험 휴양마을', '관광지', 35.23352336, 127.1752282, '전라남도 곡성군 겸면 죽산하늘재길42', '곡성 죽산사과마을은 농촌체험휴양마을이다. 목화공원과 인접한 곳으로 시골의 향취를 마음껏 느낄 수 있다.죽산사과마을에서 체험할수 있는 프로그램들도 다양한데 그 중에서 먹거리체험으로는 인절미 떡메치기 체험있고. 계절에 따라 사과따기 감따기등 각종 수확체험이 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02287', '용암 농촌체험 휴양마을', '관광지', 35.12878212, 127.3134337, '전라남도 곡성군 목사동면 용사용암길 8-2', '곡성 용암마을은 목사동면에 위치한 농촌체험휴양마을입니다.계절별 팜놀이를 통해서 아이와 어른이 함께 즐길수 있는데 특히 여름에는 은어잡기체험을 진행하고 있습니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02288', '칠봉 농촌체험 휴양마을', '관광지', 35.24620059, 127.1802226, '전라남도 곡성군 겸면 칠봉길 89', '곡성 겸면 칠봉마을은 옛 전통이 그대로 살아 있은 농촌 체험마을입니다.마을 뒤로는 일곱 봉우리기 평풍처럼 둘러 쌓여 있고 앞으로는 동계동천을 이루어 신선이 사는 곳으로써 마을 한복판에 체험마을이 자리 잡고 있습니다.철 따라 감자캐기,땅콩캐기.고구마캐기등 농사체험이 있고 감잎차,뽕잎차.연잎차 만들기 체험이 있으며 칠봉산 등산체험은 어린이,장년,노인들 모두 즐길수 있는 인기 체험이며 목화공원의 목화체험(목화따기,목화 꽃다발 만들기,무명실 뽑기등) 이 다른 고장과 차별화 되는 체험꺼리가 있습니다.또한 미풍양속을 지키는 마을로써 구정에 합동세배,삼월삼일 칠봉 큰샘제,추석절 윳놀이행사등 민속놀이 행사를 꾸준히 하고있는 마을 입니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02289', '봉정 농촌체험 휴양마을', '관광지', 35.19394727, 127.3107811, '전라남도 곡성군 죽곡면 봉정길 43-137', '‘봉정마을’은 날던 봉황이 보금자리에 들어 알을 품은 모습같아하여 봉정(鳳停)이라고 불렸습니다.쌀엿의 향기가 가득한 마을 안쪽으로는 두 팔을 벌려도 안을 수 없는 느티나무와 선인들의 배움에 대한 열정이 남아 있는 영류재가 있고, 뒤쪽에는 넓은 논밭과 저수지 위로 이어진 아름다운 편백나무 산책로가 있습니다.다양한 체험과 함께하는 최고의 힐링 깨끗한 자연 환경 속의 농산물을 만날 수 있는 봉정농촌체험휴양마을로 오세요', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02290', '대신주말농장 정보화마을', '관광지', 35.29488111, 127.3237142, '전라남도 곡성군 곡성읍 신리길 24-1', '섬진강 자연분지 양지바른 곳에 자리한 대신주말농장마을섬진강변의 기름지고 넓은 평지에 맑은 물과 깨끗한 공기를 간직한 자연그대로의 환경을 보존한 마을로 환경농업을 실천하고 미래를 준비하는 농촌체험형 녹색의 전원마을이다.300여 농가가 옹기종기 모여 사는 이곳은 곡성읍 대평리 1,2,3구와 신리 4개의 행정마을로 구성되어 있으며 대평리와 신리의 첫 자를 따 대신주말농장마을이라 하였다.주민 70이상이 시설하우스에서 지역의 특산물인 딸기, 멜론, 화훼를 생산하고 있으며 우수한 맛이 인정되어 딸기와 메론, 화훼를 일본등 외국에 수출하고 있다.대신주말농장마을 주변은 전라선 철도, 호남고속도로, 국도 4개 노선이 지나고 광주, 순천, 남원과 인접한 편리한 교통지역으로 증기기관차와 레일바이크 체험, 음악분수, 1004장미공원, 놀이공간을 갖춘 섬진강기차마을이 인접하고 있어 갖가지 체험관광을 즐길수 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02291', '오-월드', '관광지', 36.28749924, 127.3985039, '대전광역시 중구 사정공원로 70(사정동)', '주랜드 + 플라워랜드 + 조이랜드”를 복합적으로 구성하여 온가족이 함께 즐길 수 있는 테마공원 *수용인원:제한없음', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02292', '아쿠아리움', '관광지', 36.31005741, 127.4209439, '대전광역시 중구 보문산공원로 469(대사동)', '전쟁에 대비해 지하방공호로 활용하던 대전 도심의 천연동굴을 변화시킨 수족관으로 국내최초이자 최대인 담수어 아쿠아리움  *수용인원:제한없음', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02293', '매헌 윤봉길의사 기념관', '관광지', 37.4730498, 127.0369771, '서울특별시 서초구 매헌로 99', '윤봉길의사의 업적과 살신성인 정신의 높은 뜻을 선양하고 계승 발전시키키 위하여 1988년 준공되었다. 지하 1층부터 지상 3층에 이르는 규모로 기념관 1층에는 유품과 생애사진이 전시되어 있으며, 2층에는 사무처, 매헌연구원, 세미나실, 윤봉길 도서관 등을 갖추고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02294', '고투몰', '쇼핑', 37.50622031, 127.0050517, '서울특별시 서초구 신반포로 지하200', '고속터미널 지하상가를 일컫는 고투몰은 카페, 음식점, 꽃시장 등 다양한 먹거리와 볼거리를 선사하는 곳이다. 의류, 신발, 각종 액세서리 등을 싸게 구입할 수 있어 많은 관광객들이 북적거리는 곳이다. 최근 고투몰은 고터·세빛 관광특구로 지정되었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02295', '세빛섬· 반포대교 달빛무지개분수', '관광지', 37.5124362, 126.9959623, '서울특별시 서초구 올림픽대로 2085-14', '세빛섬은 세 개의 빛나는 섬이라는 의미로, 세계 최초로 물 위에 떠 있는 부체 위에 건물을 짓는 플로팅 형태의 건축물이다. 가빛섬, 채빛섬, 솔빛섬 등 3개의 섬이 다리로 연결되어 있고 미디어아트갤러리 예빛섬이 함께 조화를 이루고 있으며 컨벤션홀, 공연, 전시, 레스토랑 시설 등을 갖춘 복합문화공간이다. 최근 세빛섬과 반포한강공원 일대는 고터·세빛 관광특구로 지정되었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02296', '금마playground', '관광지', 36.0015063, 127.0570781, '전북특별자치도 익산시 금마면 고도9길 41-14', '익산 서동공원 일원', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02297', '미륵사지playground', '관광지', 36.01154232, 127.0287139, '전북특별자치도 익산시 금마면 미륵사지로 362', '미륵사지 절터 및 전시실', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02298', '섬진강변 자전거하이킹', '관광지', 35.27753393, 127.3082912, '전라남도 곡성군 오곡면 기차마을로 232', '천혜의 자연경관을 가진 섬진강과 보성강변의 아름다운 도로와 경치좋은 산길(임도)를 따라 달려볼 수 있는 코스입니다.에코레일(Eco-Rail)자전거 열차를 통해 전국의 동호인들이 찾고 있습니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02299', '두계 농촌체험 휴양마을', '관광지', 35.24354627, 127.3790396, '전라남도 곡성군 고달면 두계길 126', '곡성 두계외갓집체험마을은 천마산에서 섬진강으로 8km에 이어지는 계곡이 있고, 외갓집 같은 포근함과 옛 정취가 물씬 풍기는 자연경관이 가득한 조용한 시골 마을입니다.곡성관광을 마치고 조용히 휴식과 휴양을 할 수 있는 한옥팬션이 준비되어 있으며 다양한 체험프로그램들이 있지만 연중 가능한 인절미 떡메치기와 시골두부만들기 체험이 있고 봄철에 식용 야생꽃을 이용하여 추억을 한 가득 담아갈 수 있는 토란화전만들기 체험이 있습니다. 그 밖에 단감따기, 고추따기 등 다양한 농사체험이 있습니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02300', '상한 농촌체험 휴양마을', '관광지', 35.16105726, 127.3987916, '전라남도 곡성군 죽곡면 상한길 240', '하늘처럼 깨끗한 산골마을인 하늘나리마을은 천혜자원인 해발 753고지 봉두산 아래에 위치하여 작은 골짜기를 사이로 맑은 물이 흐르고 골짜기를 따라 등산로가 있습니다.깊은 산속에는 고로쇠나무가 자생하여 이른 봄이면 고로쇠 수액을 채취하고 또한 집집마다 시골민박을 운영하고 있는 정겨운 산골마을입니다.마을에서 채취한 갖가지 산나물과 버섯을 활용한 시골밥상은 정겨운 시골의 옛맛을 그대로 느낄수 있으며, 마을주민 전체가 공동체를 이뤄 체험마을 활동에 참여하고 있습니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02301', '무창 농촌체험 휴양마을', '관광지', 35.28642041, 127.1520961, '전라남도 곡성군 옥과면 금의길 59', '무창마을은 전남 곡성군의 북서쪽에 위치한 전형적인 시골마을입니다.200여 농가가 모여있는 마을로 호남고속도로가 지나고 옥과 IC과 있어 광주와 인접해 교통이 편리한 농촌마을입니다.섬진강의 맑은 물과 깨끗한 공기와 더불어 점토질 량이 높아 기름지고 넓은 황등들을 중심으로 황등쌀과 사과.포도.송화버섯 수확체험이 가능한 체험마을입니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02302', '문경새재 도립공원', '관광지', 36.76160207, 128.0769905, '경상북도 문경시 문경읍 새재로 932', '문경새재는 새도 날아서 넘기 힘든 고개라는 뜻으로, 조령(鳥嶺)이라고도 한다. 풀이 우거진 고개[草岾] 또는 하늘재와 이우리재[伊火峴] 사이에 있는 고개라는 뜻에서 새재로 했다는 설과 새로[新] 생긴 고개라는 뜻에서 새재로 지었다는 설도 전해진다.1966년 문경관문이 사적 147호로 지정된 뒤, 1974년에는 주흘산(1,106m)과 조령관문 일원이 경상북도지방기념물 18호로 지정되었다. 1979년 경상북도 제1호 국민playground, 1982년 문화재보호구역으로 각각 지정되었다. 1997년 문경새재박물관을 개관한 데 이어, 2000년과 2002년에 각각 KBS 촬영장과 문경새재 야외공연장을 개장하였다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02303', '문경 에코랄라(석탄박물관 포함)', '관광지', 36.65420039, 128.0613259, '경상북도 문경시 가은읍 왕능길 112', '백두대간 생태자원이라는 핵심 콘텐츠와 친환경 녹색문화의 중심 문경에서 영상문화 콘텐츠를 결합한 생태 녹색 에너지환경 테마의 휴양문화공간으로 조성되어 모든 연령층이 함께 즐길 수 있는 문화 콘텐츠 테마파크', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02304', '문경 철로자전거(진남역)', '관광지', 36.65438526, 128.1283486, '경상북도 문경시 마성면 진남1길 155', '전국 최초의 철로자전거, 영화의 촬영지로 쓰여도 좋을 만큼 예쁜 진남역을 출발해 진남교반의 절경을 감상하며 불정역까지 갔다가 돌아오는 코스', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02305', '문경 철로자전거(구랑리역)', '관광지', 36.66102501, 128.0993075, '경상북도 문경시 마성면 구랑로 20', '진남역을 출발해 야생화를 감상하며 달리다 어두운 터널을 통과하는 독특한 체험을 할 수 있는 구랑리역 코스', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02306', '문경 철로자전거(가은역)', '관광지', 36.64931827, 128.0607306, '경상북도 문경시 가은읍 대야로 2445', '석탄박물관에서 가까운 가은역에서 출발해 구랑리역까지 갔다가 돌아오는 코스', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02307', '남당항', '관광지', 36.53886252, 126.4716002, '충청남도 홍성군 서부면 남당항로213번길 1', '대하 우럭 새조개 꽃게 등 사시사철 싱싱한 수산물을 맛볼수 있으며 잔잔한 은빛 수면으로 석양이 아름다움을 느낄 수 있음', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02308', '백야 김좌진 장군 생가', '관광지', 36.59786571, 126.5471345, '충청남도 홍성군 갈산면 백야로 546번길 12', '백야 김좌진 장군 생가 : 일제강점기 독립운동가 김좌진 의 생가터. 충청남도 기념물 제76호', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02309', '한용운선생생가지', '관광지', 36.56214158, 126.5529499, '충청남도 홍성군 결성면 만해로 318번길 83', '한용운선생생가지 : 1989년 12월 29일 충청남도 기념물 제75호 지정', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02310', '용호 Sea-Side playground', '관광지', 35.10045118, 129.1185343, '부산광역시 남구 용호동 산205', '현재 playground 조성계획 승인 단계', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02311', '영도관광안내센터', '관광지', 35.09454127, 129.0387847, '부산광역시 영도구 봉래나루로 79', '부산의 새로운 관광명소로 각광받고있는 영도대교의 도개모습을 감상하고 영도관광에 필요한 종합서비스를 제공받을 수 있다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02312', '한려수도조망케이블카', '관광지', 34.82665041, 128.4251243, '경상남도 통영시 발개로 205', '통영 미륵산에 설치된 한려수도 조망 케이블카는 한국에서 유일한 2선(bi-cable) 자동순환식 곤돌라 방식으로 스위스의 최신기술에 의해 설치되었으며, 그 길이도 1975m로 국내 일반관광객용 케이블카 중에서는 가장 길다. 특히, 그렇게 긴 길이에도 불구하고 친환경적인 설계에 의해 중간지주는 1개만 설치하여, 환경보호는 물론 탑승객에게 아주 편안한 승차감을 제공한다. 또한, 8인승 곤돌라 48대가 연속적으로 탑승객을 운송함으로써 지체 없이 탑승이 가능하며, 가까운 사람끼리 오붓하게 아름다운 한려수도의 경치를 감상할 수 있다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02313', '한산도 제승당', '관광지', 34.79264032, 128.4759648, '경상남도 통영시 한산면 한산일주로 70', '선조26년(1593년) 이순신장군이 삼도수군통제사를 제수받고 이 곳에 진영을 설치했고, 1976년 지금의 제승당과 충무사, 한산정, 수루 등을 새로 짓고 경내를 정화하여 오늘에 이름.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02314', '화암playground', '관광지', 37.35092374, 128.7896216, '강원특별자치도 정선군 화암면 화암동굴길 12-13', '천혜의 경관과 자연적 역사문화적 특성을 관광자원화하였음', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02315', '아우라지 playground', '관광지', 37.47574407, 128.7243663, '강원특별자치도 정선군 여량면 아우라지길 69', '천혜의 경관과 자연적 역사문화적 특성을 관광자원화하였음', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02316', '청도박물관', '관광지', 35.6942561, 128.6865383, '경상북도 청도군 이서면 이서로 567', '폐교를 새단장하여 만든 청도 최초의 종합박물관으로 고대부터 근현대까지 청도의 다양한 역사 문화자료를 수집 전시하고 있다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02317', '한국코미디타운', '관광지', 35.69358927, 128.6863109, '경상북도 청도군 이서면 이서로 565', '한국코미디역사를 재조명하고 관련 자료를 체계적으로 보존하고 있다. 주말이면 코미디 공연 등이 열려 사람들에게 웃음을 선사한다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02318', '청도소싸움미디어체험관', '관광지', 35.68529236, 128.7242012, '경상북도 청도군 화양읍 남성현로 346', '소싸움의 유래부터 오늘날의 소싸움까지 알수 있다. 체험장, 4D영화관, 유아놀이관 등 편의시설을 갖추고 있다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02319', '곡성집라인', '관광지', 35.23192974, 127.3698908, '전라남도 곡성군 오곡면 섬진강로 1492', '공중 비행의 스릴감과 천혜의 자연 경관으로 유명한 섬진강변의 수려한 경치가 주는 경이로움을 모두 느낄 수 있는 곡성 집라인입니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02320', '대황강 출렁다리', '관광지', 35.15035107, 127.3286414, '전라남도 곡성군 죽곡면 태평리 783', '대황강출렁다리는 대황강을 가로질러 죽곡면 태평리와 목사동면 구룡리를 연결하는 185m 길이의 인도교로 국내하천에 설치된 최장거리 다리이다.그동안 접근이 불편했던 강건너편 7km가량의 트레킹 코스가 출렁다리와 연결되면서 대황강의 빼어난 경관을 한 눈에 감상할 수 있고, 안전하면서도 사람이 지나가면 위아래로 30cm 가량 출렁이기 때문에 출렁다리를 건너는 스릴이 있어 이곳을 찾는 이들에게 즐거움을 안겨준다. 트레킹코스는 소나무숲길, 대나무 숲길, 삼나무숲길로 구성되어 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02321', '반구정습지', '관광지', 35.11550817, 127.2453298, '전라남도 곡성군 석곡면 봉전리 34-1', '대황강을 굽어보는 언덕 위에 서있는 ‘반구정’ 이라는 정자이름을 따서 대황강 만곡부에 형성된 습원을 반구정 습지로 부른다.김감선생은 문무를 두루 겸비한 조선 인조 때의 명신이었다. 병자호란이 일어나 인조임금이 남한산성으로 피신하자 선생은 두 아들과 함께 의병을 조직하여, 임금을 구출하고 오랑케를 물리치기 위해서 그곳으로 진격하지만, 인조임금의 항복소식을 접하고 비탄에 젖어 고향 석곡으로 내려와 은거한다. 선생은 강 언덕에 올라, 이곳의 빼어난 경치를 감상하는 것을 즐겼다.시를 짓고 노래하며 세상에 초연한 삶을 추구하였다. 그리고 그곳에 작고 소담한 정자 반구정을 앉혔다고 전한다. 애초에 김감선생이 지은 반구정은 주춧만 남아있을 뿐이라서, 지금 정자는 최근에 지어진 것이다.이곳에 제방이 들어서고, 주암댐으로 물길이 막히면서 반구정 습지의 많은 부분이 농경지로 개간되었고, 김감 선생의 시심을 불러일으키던 아름다운 옛 모습은 많이 훼손되었지만 반구정 습지는 아직도 온갖 종류의 조류들이 날아들고 무수한 동식물이 서식하는 생태계의 보고다. 반구정 습지는 산책 데크가 잘 갖추어져 있어, 도보 혹은 자전거를 타고 둘러볼 수 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02322', '대황강자연휴식공원', '쇼핑', 35.12890532, 127.2559931, '전라남도 곡성군 석곡면 석곡리 246-12', '석곡의 순 우리말 이름은 ’돌실’이다. 석곡주변 대황강에 멋진 바위들이 많아 유래된 이름이다. 석곡 소재지 인근 대황강 주변에 넓게 조성된 공원이 석곡 대황강 휴식공원 또는 돌실 대황강 휴식공원이다.특히 이곳에는 코스모스로 가득 채워져 있어 꽃이 피는 매년 9월말이면 코스모스 축제가 열리고, 광주, 순천 등 인근 도시에서 수많은 관광객들이 몰려와 공원과 강변을 가득채운 코스모스의 향연을 즐긴다.석곡의 돼지 숯불구이가 점점 유명해지면서, 이곳을 찾아오는 관광객들의 발걸음이 꾸준히 이어지고, 카누를 비롯한 수상 레포츠를 즐길 수 있는 시설도 잘 갖추어져 있다.대황강 휴식공원 산책로에서는 봄에는 벚꽃이 피고, 여름에는 백일홍이, 가을에는 코스모스가 핀다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02323', '섬진강변 철쭉길', '관광지', 35.26690786, 127.3325028, '전라남도 곡성군 오곡면 섬진강로 2068', '섬진강변따라 만개하는 불타는듯 화려한 철쭉의 향연을 차, 자전거, 도보 그리고 섬진강레일바이크로 즐길 수 있다.봄이 무르익는 4월에서 5월 무렵이 환상의 드라이브 코스인 섬진강 17번 국도가 가장 아름다운 시기다. 그 무렵 이 길을 벚꽃과 철쭉으로 그리고 연두색 신록으로 화려하게 치장한다.섬진강변 예전 철길을 따라 빼곡하게 늘어선 철쭉이 병풍처럼 늘어서 있어서 드라이브하기에 안성맞춤이다.벚꽃이 지면 철쭉의 계절이 된다 . 연두색 신록이 새얼굴로 치장한듯 모든게 새로운 계절에 짙은 빨란물감이라도 뿌려놓은듯한 강력한 철쭉이 섬진강변을 따라 모두를 반겨주듯 꽉찬 배열로 연호하고 있다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02324', '석정온천playground', '관광지', 35.43111098, 126.7405968, '전북특별자치도 고창군 고창읍 석정2로 173', '게르마늄 온천을 이용한 온가족이 함께 즐길 수 있는 사계절 휴양 playground', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02325', '창원단감테마공원', '관광지', 35.29915488, 128.6632468, '경상남도 창원시 의창구 동읍 동읍로 359번길 27', '전국 최초로 단감을 소재로 조성한 테마공원으로 아이들이 뛰어놀 수 있는 드넓은 잔디광장에 대형 데크무대와 단감그네, 바람개비 조형물 등이 설치되어 있어 공원을 찾는 방문객들에게 다양한 즐길거리를 선사한다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02326', '창원의집', '관광지', 35.24444959, 128.6813533, '경상남도 창원시 의창구 사림로 16번길 59', '순흥 안씨 안택영의 5대조인 퇴은 두철 선생이 거주하던 집으로 우리 고유의 한옥을 이해하고 조상들의 생활풍습과 지혜를 새롭게 조명할 수 있는 공간이다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02327', '큰한강 부군당(한남제1부군당)', '관광지', 37.531338, 127.0103972, '서울특별시 용산구 한남대로8길 9-9', '부군당은 마을의 안녕과 복을 지켜주는 부군신을 모신 곳으로 서울의 대표적인 마을신앙이다. 큰한강 부군당은 조선 후기에 건립된 것으로 추정된다. 부군신 내외, 삼장군, 삼장군부인, 삼불제석, 산신, 백마장군의 무신도가 모셔져 있고, 용궁당에는 용궁할아버지, 용궁할머니, 용궁애기씨의 무신도가 모셔져 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02328', '작은한강 부군당(한남제2부군당)', '관광지', 37.529112, 127.0047267, '서울특별시 용산구 장문로49길 17-10', '부군당은 마을의 안녕과 복을 지켜주는 부군신을 모신 곳으로 서울의 대표적인 마을신앙이다. 작은한강 부군당은 태조 이성계를 주신으로 모시고 있으며 당안에는 이성계와 그 부인의 신상 2점이 있고 좌우벽면에 용장군, 산신할아버지, 울당 할머니 신상이 모셔져 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02329', '이슬람 중앙성원', '관광지', 37.5332513, 126.997615, '서울특별시 용산구 우사단로10길 39', '이슬람교 한국 선교의 총본산으로 1976년 5월 21일에 설립된 국내 최초이자 최대의 이슬람사원(모스크)이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02330', '서빙고동 부군당', '관광지', 37.520454, 126.993114, '서울특별시 용산구 서빙고로59길 3-6', '부군당은 마을의 안녕과 복을 지켜주는 부군신을 모신 곳으로 서울의 대표적인 마을신앙이다. 부군당의 정면에는 당의 주신인 조선 태조 이성계와 그 부인의 화분이 나란히 모셔져 있고, 그 왼쪽 벽면에는 삼불재석이 모셔져 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02331', '커피파머', '카페', 37.667523, 126.72817, '경기도 고양시 일산서구 대화로 61', '6회에서 김은희(한예리)와 안효석(이종원)이 윤태형(김태호)의 은신처에서 서울로 돌아갈 때 이 카페에 들린다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02332', '셀렉토커피 남양주호평점', '카페', 37.663558, 127.24748, '경기도 남양주시 천마산로 21', '10회에서 하라(배윤경)는 은희(한예리)에게 이 커피숍에서 만나자고 메시지를 보낸다. 그녀는 은희에게 곧 미국으로 돌아간다고 알리고 건주(신동욱)에 대한 이야기를 이어간다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02333', '카페 그루비', '카페', 37.293983, 127.05538, '경기도 수원시 영통구 센트럴파크로127번길 148', '안효석(이종원)은 바리스타로, 김은주(추자현)는 단골손님이다. 1화에서 이진숙(원미경)이 자녀와 사위에게 폭탄을 떨어뜨리는 장면이 나온다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02334', '미리내 성지', '관광지', 37.146102, 127.25865, '경기도 안성시 양성면 미리내성지로 420', '시누이 도혜지(황우슬혜)는 남편이 가문의 회사를 상속받을 수 있도록 그녀가 길을 잃지 않기를 바라는 한편, 세리의 비서 홍씨(고규필)과 동시에 그녀가 가능한 한 빨리 발견되기를 기도한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02335', '초은당', '관광지', 37.611484, 127.35397, '경기도 양평군 서종면 북한강로814번길 46-6', '김은희(한예리)와 동료 서경옥(가득희)은 1회에서 작가 의뢰인을 만나기 위해 이 한옥을 방문한다. 추후 은희는 여기로 돌아와 작가의 명상 세션에 참여합니다. 은희는 눈을 감고 자신의 인생에서 가장 긴 날인 2016년 3월 10일을 회상한다. 세션이 끝난 후 동생 김지우(신재하)와 소원해진 절친 박찬을 보고 놀란다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02336', '임진각평화누리', '관광지', 37.892963, 126.74435, '경기도 파주시 문산읍 마정리 1355', '10회 P&F에서 계약 체결 후 박찬혁(김석)은 김은희(한예리)에게 그가 가고 싶은 곳이 있다고 말한다. 은희는 찬혁에게 함께 가자고 말한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02337', '지혜의 숲', '관광지', 37.7082492, 126.686674, '경기도 파주시 회동길 145', '15회에서 김은희(한예리)가 이 도서관에서 독립출판사 되기 세미나에 참석하는 모습과 건주 (신동욱)이 화자로 밝혀졌다. 세미나가 끝난 후 두 사람은 대화를 나누는데, 건주는 자신이 그녀의 계획을 따랐다고 말하며 그녀는 이를 반박한다. 그런 다음 그는 그녀가 직장을 그만두기 전에 미국에서 교육 프로그램을 신청해야 한다고 제안합니다. 그들은 밖으로 나갔고 건주는 은희가 해명하지 않으면 기분이 나쁠까 걱정하며 하라와 함께 그 주를 언급한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02338', '카페 종이와 나무', '카페', 37.720328, 126.69388, '경기도 파주시 회동길 445-1', '다구 회장(이덕화 분)이 가장 좋아하는 일일 드라마의 촬영 장소 중 하나로 등장, 회장 자신이 이곳에서 조유정(서혜원)의 어머니 진채림(김영아)과 만나 조유정(서혜원)의 손자 강태무(안효섭)와 딸이 서로를 만나기 시작했다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02339', '퀸즈파크 청담점', '음식점', 37.52592, 127.04159, '서울특별시 강남구 압구정로60길 22', '김은희(한예리), 그녀의 동료 친구 서경옥(가득희), 그리고 그녀의 새로운 지인 전하라(배윤경)는 8회에서 쇼핑을 마치고 이 식당에서 저녁을 먹기로 결정했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02340', '혜심정', '음식점', 37.67139, 127.00698, '서울특별시 강북구 삼양로181길 178', '13회에서 쉬는 날 박찬혁(김지석 분)을 자발적으로 초대해 이 식당에 함께 간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02341', '가든포에트', '카페', 37.55016, 126.9237, '서울특별시 마포구 와우산로14길 12', '9화에서 이진숙(원미경)과 딸 김은주(추자현)가 찾아온 카페이다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02342', '구룡근린공원', '관광지', 37.582996, 126.88385, '서울특별시 마포구 월드컵북로 456', '12회에서 김지우(신재하 분)와 윤서영(신혜정/혜정 분)이 이 공원에서 회사 제품 화보 촬영을 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02343', '월드컵공원', '관광지', 37.5708905, 126.878429, '서울특별시 마포구 하늘공원로 86', '김상식(정진영)은 12회에서 아내 이진숙(원미경)을 데리고 이 계단으로 나와 아이들에게 커피 테이크아웃을 시켜준다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02344', '소월로 계단 3번', '관광지', 37.547514, 126.98424, '서울특별시 용산구 소월로 168', '김은희(김지석)는 이곳을 지나가다가 학생들이 걸어가는 방향을 피해서 김은희(예한) 학생들을 붙잡는다. 그리고 나서 그는 그녀의 손을 잡을 기회를 잡는다. 잠시 말문이 막힌 은희가 어색하지 않게 손을 뗀다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02345', '대학로11길', '관광지', 37.582193, 127.00092, '서울특별시 종로구 대학로11길 13', '김상식(정진영)은 온라인에서 나이 많은 커플들의 좋은 데이트 장소로 검색해 아내 이진숙(원미경)을 데려왔다. 그는 온라인에서 읽은 데이트 조언에 따라 커피를 마시면서 휴대 전화에 사진을 보여줍니다. (진심어린 대화로 상황이 더 진지해질 때까지.)', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02346', '커피한약방 혜화점', '카페', 37.580861, 127.0048, '서울특별시 종로구 동숭2길 9', '12화에서 바리스터 안효석(이종원)이 김은주(추자현)에게 작별인사를 하고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02347', '포시즌스호텔', '숙박', 37.57065, 126.9754, '서울특별시 종로구 새문안로 97', '김은희(한예리)는 4년 만에 만난 박찬혁(김지욱)과 저녁을 먹기 위해 이 주차장에 차를 주차했다. 저녁식사 후, 그는 주차비를 지불하고 그녀를 배웅해 준다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02348', '이비스 스타일 앰배서더 명동', '관광지', 37.56169, 126.9894, '서울특별시 중구 삼일대로 302', '계약 체결 중 박찬혁(김지석)은 그날 밤 김은주(추자현)로부터 만나자고 연락을 받는다. 그는 이 술집에서 은주를 만난다. 은주의 결혼 사진과 가족 문제에 대해 이야기한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02349', '덕수궁 돌담길', '관광지', 37.565924, 126.97501, '서울특별시 중구 세종대로 99', '10회 방송에서는 술 취한 찬혁(김지석)과 술 취한 은희(한예리)가 20대 가을의 추억을 되새기기 위해 이 산책로를 찾았다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02350', '목남갤러리카페', '카페', 37.563753, 127.00979, '서울특별시 중구 퇴계로68길 16', '카페의 옥상(실은 이곳이 옥상)에서 그녀에게 고백을 하고 두 사람은 이별의 키스로 저녁을 마무리한다. 은희는 언니의 차가 도착하는 것을 보고 갑자기 자신의 심장이 방금 키스한 사람이 아니라 다른 사람을 위해 뛰고 있다는 걸 깨닫는다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02351', '그랜드 하얏트 인천', '관광지', 37.440449, 126.45747, '인천광역시 중구 영종해안남로321번길 208', '1회에서 김은희(한예리)사 P&F 북의 신임 부사장 임건주(신동욱)를 위한 환영 만찬은 펼쳐진다. 안으로 들어서자 결혼 1주년을 맞아 아내가 도착하기를 기다리는 전 남자친구 이종민(최웅 분)과 마주친다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02352', '고흥우주발사전망대', '관광지', 34.585051, 127.49236, '전라남도 고흥군 영남면 해맞이로 840', '은신처로 가는 길에 윤태형(김태훈)은 5화에서 전망을 보기 위해 이 전망대 전망대에 잠시 들른다. 6회에서는 김은희(한예리)와 박찬혁(김지석)도 태형(은희의 처남)을 찾기 위해 이곳에 들르는 모습이 그려졌다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02353', '파도리해수욕장', '관광지', 36.738979, 126.13356, '충청남도 태안군 소원면 파도길 63-12', '김은주(추자현)가 윤태형(김태훈)을 깜짝 찾아오자 두 사람은 이 해변을 찾아오며 최종 16회를 마무리 짓는다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02354', '카우카우펍 합정점', '관광지', 37.548497, 126.914483, '서울특별시 마포구 독막로 10', '그녀에게 끌리는 오싹한 선배 지수와 함께 밥을 먹는다. 실수로 언니의 셔츠에 소스를 바르고, 동생이 닦자고 손을 뻗기도 전에 같은 반 친구 이연남(김민규)이 그녀를 데리고 화장실로 가자고 한다. 연남은 충남에게 아침 일찍 장난을 쳤던 것에 대해 사과하고, 둘은 서로에게 별 감정 없음을 확인하고 친구가 되기로 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02355', '데코아발림 본점', '카페', 37.548376, 126.92179, '서울특별시 마포구 독막로15길 13-6', '충남이 카페의 용암초콜릿 케이크가 먹고 싶었다. SNS에 올라온 부정적인 댓글 때문에 자신이 부족하다고 느끼지만, 연남은 그녀에게 자신을 격려한다. 시크릿가든 스타일로 충남과의 키스를 꿈꾸는 연남이도 여기에 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02356', '공간비틀즈', '음식점', 37.555019, 126.92838, '서울특별시 마포구 와우산로29길 27 B1', '1화에서 소름 끼치는 선배 지수가 저녁 식사 후 충남에게 집까지 태워주려 하고, 연남이 대신 걸어주겠다고 제안하는 모습이 나온다. 2화에서 연남은 술에 취한 충남이 지수와 함께 떠났다는 사실을 알고 급히 식당을 나선다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02357', '율곡로3길', '카페', 37.577811, 126.98239, '서울특별시 종로구 율곡로3길', '7회(전체 2회)에서 카페에서 애프터눈 티를 먹은 후 정서현(노을, 전 레인보우)과 홍대영(김성규)이 이 거리를 산책한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02358', '사천진해수욕장', '관광지', 37.842094, 128.874568, '강원도 강릉시 사천면 사천진리 266-2', '이재인(하식진)이 김다현(전소민)과 계약이 끝나기 전 마지막 데이트를 위해 데려온 곳이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02359', '보헤미안박이추커피', '카페', 37.846843, 128.86688, '강원도 강릉시 사천면 해안로 1107', '14회에서 이재인(하석진)과 김다현(전소민)이 해변 데이트를 마치고 이곳에 왔다. 다음 날 각자의 길을 갈 때 어떻게 할 것인지 이야기하고(계약기간이 끝나기 때문에) 재인은 다현에게 목걸이를 선물한다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02360', '인터컨티넨탈 알펜시아 평창 리조트', '숙박', 37.658254, 128.66975, '강원도 평창군 대관령면 솔봉로 325', '이 호텔은 이재인(하식진)이 운영하는 성현그룹 소속 호텔이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02361', '라꼼마빌딩', '카페', 37.548951, 126.92088, '서울특별시 마포구 어울마당로 44-1', '김다현(전소민)은 이 카페에서 지수(백승헌)를 만난다. 2회에서 그녀는 팬클럽 회장이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02362', '서울역', '관광지', 37.554719, 126.97065, '서울특별시 용산구 한강대로 405', '안서연(박시은 분)과 고민재(윤찬영 분)는 1회에서 이 역에서 지하철을 타고 집으로 돌아온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02363', '소토보체', '관광지', 37.74281, 128.00877, '강원도 홍천군 화촌면 군업안말길 153-15', '12회에서 한밤중 수영을 못하는 정다정(김하늘)이 한 곳에 걸려 넘어지고, 고우영(이도현), 예지훈(위하준)은 그녀를 구하기 위해 직접 물속으로 뛰어들었다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02364', '오페라 디바스', '음식점', 37.59965, 126.81624, '경기도 고양시 덕양구 행주산성로 141', '1회에서 홍대영(윤상현)이 두 자녀 홍시아(노정의), 홍시우(려운)와 함께 이 식당에서 점심을 먹었다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02365', '서울대공원', '관광지', 37.427542, 127.01701, '경기도 과천시 대공원광장로 102', '홍대영(윤상현)은 두 아이 홍시아(이남경)과 홍시우(오자훈)는 4회에서 어려서 인연을 맺지 못한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02366', '모로미쿠시 광교카페거리점', '카페', 37.294673, 127.05381, '경기도 수원시 영통구 센트럴파크로127번길 48', '18회에서 절친 고덕진(김강현)과 이 이자카야에서 하트 투 하트 토크를 나눴다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02367', '파머스테이블', '관광지', 37.7902235, 126.695397, '경기도 파주시 탄현면 헤이리마을길 59-77', '18회에서 홍대영(윤상현)과 정다정(김하늘)은 두 자녀 홍시아(노정의), 홍시우(려운)와 함께 이곳에서 가족 회식을 가졌다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02368', '화이트블럭', '관광지', 37.7889189, 126.699592, '경기도 파주시 탄현면 헤이리마을길 72', '최일권(이기우)은 5화에서 정다정(김하늘)과 만나 파티 친구들과의 내기에서 이기기 위한 작전을 세우고 홍대영(이도현)은 멀리서 이 광경을 지켜본다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02369', '퍼스트가든', '관광지', 37.7321551, 126.793933, '경기도 파주시 탑삭골길 260', '12화에서 예지훈(위하준)을 모델로 한 고고플레이의 신작 ''스파르타 - 전쟁의 왕'' 게임은 이 정원에서 런칭된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02370', '엘빈에비뉴라운지', '관광지', 37.4990249, 127.02849, '서울특별시 강남구 강남대로92길 13', '12회에서 추애린(이미도)이 고덕진(김강현)을 불러 이 술집에 술을 들이키는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02371', '태그호이어 청담점', '관광지', 37.5258, 127.0402, '서울특별시 강남구 선릉로 828', '7, 9회에서 이 건물의 외관은 최일권(이기우)이 정기적으로 선생님과 학부모 간담회를 하는이 클럽의 하나로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02372', 'C156', '관광지', 37.546081, 127.06649, '서울특별시 광진구 동일로 156', '이 장소는 2회에서 정다정(김하늘)과 절친 추애린(이미도)이 술을 마시러 왔다가 그날 저녁 아르바이트생으로 오빠를 도와주는 일권과 마주치는 최일권(이기우)의 동생이 운영하는 레스토랑 바로 등장한다..', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02373', '벌스가든', '관광지', 37.565239, 126.92054, '서울특별시 마포구 성미산로23길 44', '12회에서 정다정(김하늘)은 홍대영(윤상현)과 함께 입구 옆 쉼터를 찾았던 순간을 회상한다. 그리고 그는 우산과 꽃을 들고 돌아오기 위해 잠시 떠납니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02374', '성미산로29길', '관광지', 37.564235, 126.92285, '서울특별시 마포구 성미산로29길 3', '고우영(이도현)과 홍시우(려운)는 18회7화에서 정다정(김하늘)과 추애린(이미도)을 마주치고, 우영은 애린이 자신의 정체를 밝혀내는 것을 두려워한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02375', '누리꿈스퀘어빌딩', '관광지', 37.579272, 126.89028, '서울특별시 마포구 연남동 396', '추애린(이미도)이 일하는 방송사로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02376', '곤밥', '음식점', 37.54516, 126.92256, '서울특별시 마포구 토정로 105', '8회에서 예지훈(위하준)이 정다정(김하늘)을 저녁식사로 이 식당에 데려온다. 그리고 그들이 떠날 때 여사장님(박은영 카메오)과 지훈은 모두 다정에게 사인을 부탁한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02377', '올드문래', '음식점', 37.5138911, 126.8942605, '서울특별시 영등포구 도림로 433-6', '8회에서 정다정(김하늘)은 절친 추애린(이미도)을 이 식당에서 만났다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02378', '클럽메카', '숙박', 37.531482, 126.99078, '서울특별시 용산구 녹사평대로 140 크라운호텔 지하1층', '5화에서 일권이 정다중(김하늘)을 유혹하겠다는 내기를 수락했다는 것이 밝혀지는 장면이 나온다. 7회에서 일권은 이 클럽에서 사모회를 열고 정다중(김하늘)과 고덕진(김강현)의 아들이 들어갈 수 있도록 돈을 갈취하려 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02379', '더리버', '관광지', 37.507108, 126.98472, '서울특별시 용산구 용산동6가 451', '8회에서 홍대영(윤상현)은 이 거리에서 아버지 홍주만(이병준)과의 결별의 순간을 회상한다. 그의 아버지가 철로를 건너는 동안 그는 뒤에 머물렀다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02380', '이촌로29길', '음식점', 37.525257, 126.96103, '서울특별시 용산구 이촌로29길', '정다정(김하늘 분)과 고우영/홍대영(이도현 분)이 함께 점심을 먹은 후, 다시 12화 이 장소에서 그랜드 메르큐어 호텔의 문을 통해 식당을 빠져나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02381', '서울드래곤시티', '관광지', 37.531844, 126.96306, '서울특별시 용산구 청파로20길 95', '14회에서 오해가 풀린 후 홍대영(이도현)은 정다정(김하늘)과 이 곳에서 키스를 나눈다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02382', '창신동 채석장 전망대', '관광지', 37.578223, 127.01164, '서울특별시 종로구 낙산5길 51', '1회에서 젊은 홍대영(이도현)과 정다정(한소은)이 젊은 부모가 되는 것이 무엇을 의미하는지 토론하는 곳으로 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02383', '낙산공원', '관광지', 37.580667, 127.00746, '서울특별시 종로구 낙산길 41', '홍씨 가족은 이 아파트에 살고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02384', '경희궁3길', '관광지', 37.57329, 126.96731, '서울특별시 종로구 사직동 경희궁 3길', '8회에서 홍대영(윤상현 분)은 아들 홍시우(려은 분)와 길을 건너던 이 거리에서 자신이 아이들과 얼마나 소원해졌는지 회상하며 특정 순간을 회상한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02385', '청계천', '관광지', 37.569205, 126.97791, '서울특별시 종로구 서린동 148', '정다정(김하늘)과 청소년 홍대영(이도현)은 15회에서 밤에 이 다리와 다리 사이를 건너며 데이트한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02386', '시우식당', '음식점', 37.577713, 126.96952, '서울특별시 종로구 필운대로 18', '12회에서 정다정(김하늘)은 이 식당에 점심식사를 초대받았다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02387', '파로그랜드', '숙박', 37.567435, 126.98516, '서울특별시 중구 을지로5길 26', '8회에서 추애린(이미도)의 전 남자친구(허정민)가 그녀를 이 호텔로 데려와 이야기를 나눈다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02388', '송도센트럴파크호텔', '숙박', 37.3904903, 126.637203, '인천광역시 연수구 테크노파크로 193', '영화 1987 초반부 김윤석이 차례를 지내는 곳', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02389', '임진각', '카페', 37.889542, 126.740176, '경기도 파주시 문산읍 임진각로 164', '영화 1987에 나온 부산역 카페', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02390', '민주인권기념관', '관광지', 37.541025, 126.971672, '서울특별시 용산구 한강대로71길 37', '1987 촬영지이자 박종철이 고문으로 사망한 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02391', '천주교 서울대교구 주교좌명동대성당', '관광지', 37.5632772, 126.986827, '서울특별시 중구 명동길 74', '1987에서 김승훈 신부가 성명서를 발표한 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02392', '서울특별시청', '관광지', 37.566291, 126.977931, '서울특별시 중구 세종대로 110 ', '영화 1987 마지막 장면의 배경이 된 장소', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02393', '청남대', '관광지', 36.46255, 127.4906, '충청북도 청주시 상당구 문의면 청남대길 646 ', '1987에서 문성근과 김윤석이 만나는 곳', '충북');
