INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02762', '서강대교', '관광지', 37.536911, 126.92495, '서울특별시 영등포구 여의도동 서강대교', '각계각층의 10인, 그러나 지형주(이준혁)와 신가현(남지현)을 포함해 일종의 트라우마를 겪은 이들은 모두 ''시안 클리닉''으로 소환된다. 인생을 1년 전으로 되돌릴 수 있는 기회를 제공하고 운명을 바꿀 수 있는 능력을 갖게 되면서 시간 여행이 시작된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02763', '모나무르 복합문화공간 아산', '숙박', 36.750552, 126.99246, '충청남도 아산시 순천향로 624', '드라마의 ''서울호텔''로 등장. 2회에서 신지현(남규리)이 송이경(이요원)의 몸으로 직장 증명서를 받는 모습이 그려졌다. 호텔을 산책하던 중 그녀는 약혼자의 외도를 알게 된다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02764', '그랜드머큐어앰배서더 창원', '관광지', 35.239262, 128.65532, '경상남도 창원시 성산구 원이대로 332', '이 건물은 신인정(서지혜)의 직장으로 등장.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02765', 'DMC첨단산업센터', '카페', 37.584874, 126.88568, '서울특별시 마포구 성암로 330', '드라마 등장인물인 한강(조현재)이 운영하는 천국카페로 등장한다. 한강 건축사무소는 이 건물 1층에 있습니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02766', '필운대로5가', '관광지', 37.579512, 126.96846, '서울특별시 종로구 필운대로5가길', '2회에서 잠에서 깨어난 송이경(이요원)의 몸으로 이 거리를 걷던 신지현(남규리)은 갑자기 스케줄러(정일우)가 나타나 누군가의 몸을 빌릴 때의 법칙을 상기시킨다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02767', '대룡시장', '쇼핑', 37.782373, 126.28007, '인천광역시 강화군 교동면 대룡리 1103-11', '23회에서 거북당에서 박주현(장영함)이 오태석(주석래)에게 선물로 자켓을 사고 싶어하는 ''영천시장''으로 등장한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02768', '마이산탑사', '관광지', 35.758494, 127.411297, '전라북도 진안군 마령면 마이산남로 367', '11회에서 한강(조현재)은 암살자를 찾으러 이 절에 온다.', '전북');
