INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02770', '합천 영상 테마파크', '관광지', 35.5489346, 128.072475, '경상남도 합천군 용주면 합천호수로 757', '국회 폭발 직후의 장면이 이곳에서 촬영됐다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02771', '국립대전현충원', '관광지', 36.369464, 127.294854, '대전광역시 유성구 현충원로 251', '5회에서 ''국회의사당 폭탄 테러 희생자 추도식''이 열리는 곳이 바로 이 묘지다.', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02772', '한강 공원 여의도 지구', '관광지', 37.5290674, 126.936218, '서울특별시 영등포구 여의동로 290', '윤찬경(배종옥 분)은 5회에서 이 공원에서 운동을 하는데, 그 뒤를 따라가지 못하는 비서가 따라온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI02773', '탑골공원', '관광지', 37.57139, 126.98877, '서울특별시 종로구 종로 99', '3회에서 탈북자들이 국회 폭탄 테러 배후에 있다는 소문을 선동자들이 퍼뜨리는 곳이 바로 이 공원 앞이다.', '서울');
