INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03023', '궁남지', '관광지', 36.269619, 126.91224, '충청남도 부여군 부여읍 궁남로 52', '10화에서 이영(이동건)은 이 연못에서 신채경(박민영)에게 강제 키스를 한다. 한편 이역(연우진)은 멀리서 현장을 지켜보고 있다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03024', '리븐델 게스트하우스', '숙박', 37.702514, 127.51666, '경기도 가평군 청평면 고재길 262-46', '정서연(조여정)과 남편 홍인표(정웅인)는 친구 윤희주(오나라)와 남편 이재의 초청으로 주말 별장에 초대된다. 술에 취한 희주가 서연을 얕잡아보는 저녁, 상황이 어색해지면서 서연도 가차 없이 대답한다. 4회(2회)에서는 강태우(김강우)가 집주인에게 말을 걸기 위해 찾아와 말을 꺼리는 모습이 그려졌다. 태우는 별장에서 차를 몰고 나온 여자가 짐작대로 관리인의 딸이 아니라는 사실을 알게 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03025', '안성팜랜드', '관광지', 36.9904684, 127.194467, '경기도 안성시 공도읍 대신두길 28', '2회(전체 1회)에서 강태우(김강우)는 임시 십자가에 묶인 채 등장한다. ', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03026', '호텔엔트라', '숙박', 37.52403, 127.0485, '서울특별시 강남구 도산대로 508', '1회에서 정서연(조여정)은 친구 윤희주(오나라)의 남편 이재훈(이지훈)과 비밀리에 만나기 위해 이 호텔에 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03027', '일산호수공원', '관광지', 37.658769, 126.76252, '경기도 고양시 일산동구 호수로 731', '1화에서 홍난희(수애)와 변형태(이정진)가 조깅을 하러 온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03028', 'N서울타워', '관광지', 37.551168, 126.98824, '서울특별시 용산구 남산공원길 105', '평생 친구였던 홍난희(수애)와 변형태(이정진)는 당시 정해진 관계가 아닌 서른이 되기 전에 이곳에서 함께 섣달 그믐날을 보내기로 약속했었다. 1화에서 남산타워에 있는 자신들을 발견하고 난희는 형태에게 이곳에서 결혼하라고 말한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03029', '고브리또스커피', '카페', 37.449734, 126.70342, '인천광역시 남동구 인주대로 600', '이곳은 최민우(주지훈)가 약혼자 서은하(수애)를 물에 빠뜨린 수영장으로 나온다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03030', '마이랜드', '관광지', 37.474812, 126.59889, '인천광역시 중구 월미로234번길 7', '9화에서 최민우(주지훈)가 변지숙(수애)을 데려온다. 그는 그녀가 이곳에 와서 바람 소리와 새소리를 듣고 정신을 맑게 하는 방법을 설명하고 지숙의 미래 계획과 꿈을 묻는다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03031', '벽초지수목원', '관광지', 37.800977, 126.873712, '경기도 파주시 광탄면 부흥로 242', '6회에서 지숙의 형이 온 직후 민우도 그 자리를 찾아 화장실 청소를 하고 있는 지숙을 발견하고 당장 일을 그만두라고 명령한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03032', '루카511', '관광지', 37.526961, 127.04688, '서울특별시 강남구 도산대로81길 40', '변지숙(수애)의 어머니는 간 이식 수술을 위해 이곳에 입원했다. 17화에서 어머니는 최미연(유인영 분)의 방해로 제때 이식을 받지 못해 그녀 앞에서 사망한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03033', '코스콤빌딩', '관광지', 37.521626, 126.92837, '서울특별시 영등포구 여의나루로4길 21', '1화에서 강동하(이현진)의 직장으로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03034', '담양 관방제림', '관광지', 35.3234778, 126.991321, '전라남도 담양군 담양읍 객사7길 37', '강을 건널 때 민우는 어머니의 죽음에 죄책감을 느끼고 그 이후로 물을 건널 수 없다고 고백한다. 그녀는 그들이 한 단계씩 함께 나아가면서 시도할 것을 제안합니다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03035', '제이딘주얼리', '관광지', 35.817134, 127.14442, '전라북도 전주시 완산구 전라감영4길 19', '약혼을 앞둔 황희태(이도현)와 이수련(금새록)은 이모(김현)의 손에 이끌려 장보기로 나선다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03036', '신세계백화점 본점', '쇼핑', 37.560999, 126.98109, '서울특별시 중구 소공로 63', '8회에서 저녁 데이트를 위해 찾아왔지만 보름달이라 떠나야 한다고 말하며 그녀의 눈앞에서 곧 사라진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03037', '얼큰이네토종순대국전문점 본점', '음식점', 37.5690699, 126.9130881, '경기도 고양시 덕양구 권율대로 892', '영화 가장 보통의 연애에서 순대국 먹은 곳', '경기');
