INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03039', '월스트리트', '관광지', 37.5082595, 127.0552221, '서울특별시 강남구 테헤란로83길 13', '영화 가장 보통의 연애에서 회식 장면을 찍은 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03040', '마포진짜원조최대포본점', '음식점', 37.544649, 126.951868, '서울특별시 마포구 마포대로 112-4', '김래원과 공효진이 소주잔을 기울인 돼지고기 구이집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03041', '마포나루 아크로점', '카페', 37.5412579, 126.9467487, '서울특별시 마포구 마포대로 68 마포아크로타워 지하 1층', '김래원의 취중 고백신을 찍은 문정동 카페', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03042', 'ZIO커피 문정점', '카페', 37.4827568, 127.1224215, '서울특별시 송파구 새말로 97 문정동 카센터', '공효진과 김래원의 취중진담신을 찍은 술집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03043', '코코로', '음식점', 37.5694964, 126.9130871, '서울특별시 송파구 올림픽로32길 41', '김래원의 고백신을 찍은 닭갈비 집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03044', '연탄불', '관광지', 37.5259645, 126.8914759, '서울특별시 영등포구 양산로17길 17', '공효진과 김래원이 술게임을 즐긴 수제 맥주 펍', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03045', '이목구비', '관광지', 37.519097, 126.903283, '서울특별시 영등포구 영신로32길 19 ', '영화 가장 보통의 연애에서 회사 워크샵으로 온 산', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03046', '롯데캐슬아이비', '관광지', 37.520206, 126.93181, '서울특별시 영등포구 국제금융로 86', '9회에서 나영원(정소민)과 유지성(김지석)이 직장 설문조사를 하러 이 사찰을 찾았다. 두 사람은 함께 일을 잘하기로 결정한다. 자성은 이 사찰과 관련이 있는 속담이 있는데, ''합심하면 폐허에도 꽃이 핀다''는 말이 있다고 한다. 이어 그녀는 “거대한 산불로 인해 폐허가 된 곳인데, 이렇게 견고하게 복원된 모습을 보니 딱 들어맞는 표현인 것 같다”고 말했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03047', '삼순이 계단', '관광지', 37.554717, 126.98177, '서울특별시 중구 남산공원길 649', '13회에서 봉해령(김소연)은 저녁을 먹기 위해 이곳으로 갑니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03048', '낙산사', '관광지', 38.124649, 128.62804, '강원도 양양군 강현면 낙산사로 100', '기가 봉삼식(윤다훈)과 봉삼숙(지수원)이 행복한 집(가화만사성)(MBC, 2016)에서 일하는 곳입니다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03049', '커피 스미스 홍대점', '카페', 37.551719, 126.92362, '서울특별시 마포구 와우산로 82', '봉준호 가족이 사는 행복한 집으로 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03050', '운현궁 양관', '관광지', 37.576111, 126.987749, '서울특별시 종로구 삼일대로 460', '서관의 정면은 기서회의 이시용 백작(안석환)과 이화경 백작부인(김정난)의 저택이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03051', '크랙킨', '관광지', 37.669845, 126.77736, '경기도 고양시 일산동구 무궁화로141번길 8-8', '6회에서 양혜선(김한나)가 보낸 문자를 본 후 혜선이 도착하자마자 도재진(김도완)이 땅에 물을 뱉어내고 놀란다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03052', 'pino', '관광지', 37.673828, 126.79219, '경기도 고양시 일산동구 애니골길 72', '11화에서 도재진(김도완)과 양혜선(김한나)이 데이트를 하러 이곳을 찾았다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03053', '웨스턴돔', '관광지', 37.654629, 126.77282, '경기도 고양시 일산동구 정발산로42번길 24', '4화에서 같은 임무를 맡은 도재진(김도완)과 양혜선(김한나)과 마주치게 되고 결국 함께 영화를 보게 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03054', '더드림핑 글램핑', '관광지', 37.652579, 127.37022, '경기도 남양주시 화도읍 북한강로 1630-18', '최종회 16회에서 주인공인 신우여(장기용), 이담(혜리), 양혜선(강한나)이 이 곳에서 축하연을 펼친다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03055', '수원화성박물관', '관광지', 37.282658, 127.01881, '경기도 수원시 팔달구 창룡대로 21', '6화에서 이담(걸스데이 혜리)의 실망스러운 미팅 이후, 신우여(장기용)는 그녀를 응원하기 위해 이 (폐쇄된) 박물관으로 순간이동하여 개인 방문할 수 있도록 해준다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03056', '떼레노시떼', '카페', 37.22733, 127.1067, '경기도 용인시 기흥구 기흥단지로 81-2', '4회에서는 이담(걸스데이 혜리)과 계선우(배인혁)가 카페를 찾아 과제를 진행하였다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03057', '아지동 테마파크', '관광지', 37.791748, 126.69639, '경기도 파주시 탄현면 헤이리마을길 70-21 헤이리예술마을', '신우여(장기용)의 역사시대 전생의 일부 장면이다. ', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03058', '문경새재촬영장 (오픈세트장)', '관광지', 36.771097, 128.073937, '경상북도 문경시 문경읍 새재로 1037', '1화에서 신우여(장기용)가 트레이드타워와 코엑스를 지나 이 길을 드라이브한다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03059', '영동대로', '관광지', 37.51369, 127.0605, '서울특별시 강남구 삼성동', '신우여(장기용)는 1회에서 여기서 혼자 술을 마신다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03060', '호텔 인나인', '숙박', 37.515605, 127.06003, '서울특별시 강남구 영동대로 618', '서점에서 책을 찾던 중 의문의 백인 남자(스페셜 게스트)와 우연히 마주쳤다. 고경표에게 조심하라고 경고한다. 바로 그때 신우여(장기용)가 나타나지만 그 남자는 어디에도 보이지 않는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03061', '오리지널시카고피자 홍대본점', '음식점', 37.5500682, 126.9197235, '서울특별시 마포구 독막로7길 51 3층', '6회에서 이담(걸스데이 혜리), 최수경(박경혜), 도재진(김도완)이 담의 소개팅에 대한 이야기를 듣기 위해 이 곳에서 식사를 했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03062', '가온문화공원', '관광지', 37.58181, 126.88765, '서울특별시 마포구 상암동 1594', '이담은 13회에서 자신과 계선우(백인혁 분)를 묶는 ''빨간 실''을 끊으려다 이 공원 주변을 걷는다. 갑자기 그녀는 다른 곳으로 이동하여 산신(고경표)과 마주친다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03063', '성미산로23길', '관광지', 37.565007, 126.92083, '서울특별시 마포구 성미산로23길', '5회에서 이 거리에서 이담(혜리)과 신우여(장기용)가 포창마차(텐트바)를 발견하고, 우여는 함께 술을 마시며 기세를 올리자고 제안한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03064', '어울마당로', '관광지', 37.55003, 126.92113, '서울특별시 마포구 어울마당로', '15화에서 이담(걸스데이 혜리)과 신우여(장기용)는 무엇을 먹을지 고민하며 와우산로 35길 끝자락을 걷는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03065', '콜린', '카페', 37.549176, 126.9204, '서울특별시 마포구 어울마당로 45', '4회에서 이담(걸스데이 혜리)과 최수경(박경혜)은 이 카페에서 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03066', '목포낙지마을', '관광지', 37.562449, 126.90539, '서울특별시 마포구 월드컵로32길 11', '최종회 16화에서 신우여(장기용)와 이담(걸스데이 혜리)이 문어볶음집(본명 ''할머니낙지볶음'')에 합류한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03067', '월드컵북로54길', '음식점', 37.581631, 126.88829, '서울특별시 마포구 월드컵북로54길 25 상암DMC 푸르지오시티', '2화에서 신우여(장기용)가 이담(걸스데이 혜리)을 위해 피자를 포장하고 이 길을 걷고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03068', '무대륙', '카페', 37.545927, 126.91843, '서울특별시 마포구 토정로5길 12', '6회에서 이담(걸즈데이 혜리)과 소개팅을 식사를 마치고 이 카페로 향하는데, 신우여(장기용)도 여기에 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03069', '카페 할아버지공장', '카페', 37.541101, 127.05482, '서울특별시 성동구 성수이로7가길 9', '7회에서 걸스데이 이담(걸스데이 혜리)이 신우여(장기용)를 만나자고 하는 ''핫플레이스''의 모습이 그려졌다. 그가 카페에서 한 잔 하자고 제안한 후 그날 저녁, 이전에 교제했던 여성과 관련된 미스터리한 살인 사건을 조사하다가 늦게 나타난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03070', '원효대교', '관광지', 37.527046, 126.94571, '서울특별시 영등포구 여의도동 원효대교', '5회에서 이담(걸스데이 혜리)과 신우여(장기용)는 이 다리 근처에서 한강을 따라 오후를 즐겼다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03071', '아이파크몰', '쇼핑', 37.528802, 126.96453, '서울특별시 용산구 한강대로23길 55', '4회에서 이담(걸스데이 혜리)은 이 카페에서 신우여(장기용)를 발견한다. 3화의 시뮬레이션 데이트 장소이기도 하다. 감정을 참지 못한 담이 다가와 자신의 테이블에 앉아 우여에게 예전처럼 편안하게 소통하고 싶다고 말한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03072', '카페포엠 북촌점', '카페', 37.579235, 126.98384, '서울특별시 종로구 북촌로5길 19-4', '3회에서 이담(걸스데이 혜리)과 신우여(장기용)는 이 카페로 향한다. 계선우(백인혁)가 그 뒤를 이었다. 선우가 담에게 손을 뻗으려 하자 우여는 본능적으로 선우를 끌어당겨 보호한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03073', '광한루원', '관광지', 35.403918, 127.379758, '전라북도 남원시 요천로 1447', '1화에서 이담(걸스데이 혜리)은 이 거리 인생사진관 바로 바깥에 위치한 빨간 포르쉐 위에 쓰러져 있는 취한 도재진(김도완)을 발견한다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03074', '태조로', '카페', 35.814171, 127.15061, '전라북도 전주시 완산구 태조로 37', '1회에서 이담(걸스데이 분)과 신우여(장기용 분)가 카페를 나온 뒤 이 거리를 걷는다. .', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03075', '향교길', '관광지', 35.812052, 127.15541, '전라북도 전주시 완산구 향교길 105', '1회에서 걸스데이 이담(혜리)이 술에 취한 도재진(김도완)을 업고 이 거리를 걷고 있다. 그녀가 그의 무게로 쓰러지고, 재진은 몸을 일으켜 거리를 뛰쳐나가는데 이담이 뒤를 쫓는다.', '전북');
