INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03112', '일산문화광장', '관광지', 37.65839, 126.7704, '경기도 고양시 일산동구 중앙로 1271-4', '10회 엔딩에서 전진호(이민호)는 이 공원 야외 포장마차에서 동료 노상준(정성화), 김태훈(임슬옹)과 함께 술을 마시며 자신의 짝사랑 나혜미(최은미)를 두고 진호에게 도전한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03113', '푸르지오 써밋', '관광지', 37.504567, 127.06475, '서울특별시 강남구 영동대로 337', '이 건물은 최도빈(류승룡) 감독의 담미술관 일명 DAAM 프로젝트로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03114', '코엑스', '관광지', 37.510177, 127.05866, '서울특별시 강남구 영동대로 513', '1회 엑스포에서 공개됐다. 동시에 전진호(이민호)와 한창렬(김지석)이 함께하는 이 컨벤션홀에서 ''드림아트센터'' 건립을 위한 건축사 간 입찰이 진행된다. 각 회사의 입찰자입니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03115', '응봉산 팔각정', '관광지', 37.547805, 127.029886, '서울특별시 성동구 독서당로60길 13-1', '“사람들은 이렇게 높은 곳에 오르면 마음이 가벼워집니다. 그래서 그들은 고백할 용기를 얻습니다. 나중에 프러포즈 받고 싶으면 이런 곳으로 가세요.” - 8화에서 전진호(이민호)가 박개인(손예진)에게 이 곳에 대해 한 말이다. 그녀에게 간접적으로 좋아한다고 말한 것이다.', '서울');
