INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03147', '메이즈랜드', '음식점', 33.488697, 126.800866, '제주특별자치도 제주시 구좌읍 비자림로 2134-47', '걸스데이 유라와 소진이 소개한 제주도 숨은 맛집', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03148', '소노캄 고양', '음식점', 37.661963, 126.75097, '경기도 고양시 일산동구 태극로 20', '최종회 32회(전체 16회)에서는 팀을 추적하던 용의자가 이 호텔에 있었던 것으로 밝혀져 붙잡혔다. 한편 강현(박은석)은 성진그룹의 변호사 윤태준(홍서준)을 만나기 위해 식당에서 만나자고 제안을 거절한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03149', '대림아크로텔', '관광지', 37.36281, 127.10749, '경기도 성남시 분당구 성남대로 295', '27회에서 강현(박은석)은 이 건물 뒤에서 한 통의 전화를 받고 법의학 수사관 백범(정재영)의 아버지인 것으로 밝혀졌다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03150', 'Gramps Ground', '관광지', 37.36184, 127.1063, '경기도 성남시 분당구 정자일로 132', '19회 플래시백에서 강현(박은석)과 서정민(백승훈)이 술을 마시러 온다. 강현은 정민에게 생일 선물을 주고, 강현은 정민이가 돌아가신 양언니 소희의 생일이기도 하다고 언급한다. 21화에서는 강현이 수상한 사람이 다른 테이블에서 자신들을 보고 있었다는 사실을 깨닫는 플래시백이 또 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03151', '정자역엠코헤리츠', '관광지', 37.362227, 127.10629, '경기도 성남시 분당구 정자일로 136', '검사 은솔(정유미)이 입주하고, 그 옆에는 법의학박사 백범(정재영)이 살고 있다. 11회에서는 강현(박은석), 강동식(박준규), 천미호(박희진)가 은솔의 새로운 집에 찾아오지만 실수로 옆집의 벨을 누르는 바람에 백범이 대신 문을열고 나오자 집단 충격에 휩싸인다. ', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03152', '누리슈퍼', '관광지', 37.737943, 126.82394, '경기도 파주시 조리읍 삼릉로 10', '강현(박은석)이 검사를 그만둔 후 찾아온 어머니의 가게이다. 31-32회에서 백범(정재영)은 엄마를 만나기 위해 하루 쉬고 같이 식사한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03153', '김포국제공항', '관광지', 37.558655, 126.79228, '서울특별시 강서구 하늘길 112', '13회에서 메르스 피해자로 의심되는 사람이 이곳에 상륙하는 장면이 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03154', '가산디지털단지역', '관광지', 37.481009, 126.88284, '서울특별시 금천구 벚꽃로 309', '28회에서 살인 용의자 강치수가 일상의 일부로 이 식당을 찾아온 가운데 수사관 양(김영웅)이 지켜보고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03155', '여의도따로국밥', '음식점', 37.521378, 126.93022, '서울특별시 영등포구 여의대방로69길 28', '이 식당은 의 25화와 26화에서 여러 번 등장한다. 백범(정재영 분) 법의학과 조교 정성주(고규필 분)와 함께 이곳에 온 것은 바비큐 돼지고기 껍질이 아니라 증거 검사로 생가죽을 얻기 위해서다. 그는 두 번째로 이곳에 와서 검사 은솔(정유미)과 합류하지만, 그는 피부를 얻자마자 떠난다. 성주와 형사 차수호(이이경 분), 독극물학자 스텔라 황(스테파니 리 분), 은솔이 세 번째로 제대로 된 식사를 하러 오는 모습이 이곳에 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03156', '서강껍데기 이촌점', '관광지', 37.530776, 126.95487, '서울특별시 용산구 이촌로 9', '30회에서 법의학 수사관 백범(정재영)과 법의학 조수 정성주(고규필)가 특정 유형을 찾기 위해 찾아온다. 용의자가 살인 무기에 사용했을 수 있는 라이플 클리너 찾는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03157', '이태원시장', '쇼핑', 37.533798, 126.99004, '서울특별시 용산구 이태원로14길 6', '법의학 수사관 백범(정재영)이 이곳을 자주 찾는다. 한 에피소드에서 그는 검사 은솔(정유)에게 이렇게 말한다. 자신의 오른손(교통사고로 다친)이 아직 건재하다는 것을 스스로 증명하기 위해 촬영에 임했다고 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03158', '남대문실탄사격장', '쇼핑', 37.5605491, 126.9775087, '서울특별시 중구 남대문시장길 25-8, 4층', '22화(전체 11화)에서 천미호(박희진)가 정신분열증 환자 조한수의 언니가 운영하는 미용실 ''진헤어''에 잠입하는 모습이 그려졌다. 머리를 손질하던 중 조가 들어와 누나를 공격하려 한다. 미호는 조에게 가위를 내려놓으라고 말하려 하지만 말을 듣지않고, 바로 그때 형사 양수동(김영웅)이 들어와 조가 공격을 가하기도 전에 그를 잡는 데 성공한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03159', '경인종합상가', '관광지', 37.457639, 126.6835, '인천광역시 남구 경인로 392', '검사 은솔(정유미)은 가족과 함께 이 ''아파트''에 살고 있다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03160', '오크우드프리미어 인천', '관광지', 37.389269, 126.64424, '인천광역시 연수구 컨벤시아대로 165', '살인 용의자 강치수가 소유한 스튜디오 ''검법남녀'' 속 ''수포토 스튜디오''. 28회에서는 수사관 양(김영웅)이 스튜디오를 나와 여권 사진을 찍고 있는 손님으로 포즈를 취하고 있다. 29화에서 수사팀은 스튜디오에서 강치수를 체포한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03161', '흑백사진관 우리', '관광지', 37.473816, 126.62016, '인천광역시 중구 신포로27번길 101', '11회에서 수사관 강동식(박준규)은 이 건물을 통해 용의자 김준태(김민규)를 쫓고 철교를 건넜다. 건물 뒤편으로 이어지는 곳. 검사 강현(박은석)과 팀원들이 멀리서 지켜보는 가운데 결국 동식은 반대편에서 준태를 계단 난간에 수갑으로 묶는다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03162', '일해냉동', '관광지', 37.456237, 126.60291, '인천광역시 중구 연안부두로 24-1', '11회에서는 강현(박은석)이 이끄는 팀이 이 건물 앞에 도착하는 모습이 그려졌다. 두 사람은 항구에서 용의자 김준태(김민규)를 쫓던 은솔(정유미)과 강동식(박준규)을 찾기 위해 헤어졌다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03163', '라이크라이크', '관광지', 37.661, 126.76672, '경기도 고양시 일산동구 무궁화로 8-19 삼라 마이다스빌2 101호', '은솔(정유미)은 8화(전체 4화)에서 백범(정재영)과 술을 마실 기회를 잡았다. 두 사람이 함께 있는 모습을 보고 질투하는 샐리(강승현)의 모습이 포착된다. 이로 인해 백범은 떠나고 은솔은 샐리에게 커피를 사러 남게 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03164', '마두역', '관광지', 37.6512534, 126.777172, '경기도 고양시 일산동구 장백로 194', '경찰관들이 전 살인 용의자 오만상(김도현)의 생존 사실을 대중에게 알리기 위해 이 지하철역 2번 출구 앞에서 전단지를 나눠주는 장면이 나온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03165', '부용대', '관광지', 36.542914, 128.51663, '경상북도 안동시 풍천면 광덕솔밭길 72', '검찰과 형사팀이 정신분열증 환자 조한수를 쫓는 장면은 21회에서 나온다. 검사 도지한(오만석 분)이 조승희를 도와줄 사람들이 모두 있다는 것을 납득시키려 해도 결국 조승희는 절벽에서 아래 강으로 뛰어내린다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03166', 'YTN 뉴스퀘어', '관광지', 37.579146, 126.89229, '서울특별시 마포구 상암산로 76', '11회(전체 6회) 이 건물(MBC문화방송본부를 배경으로) 옆면 화면에 ''폭행범'' 소식이 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03167', 'MBC문화방송 본사', '관광지', 37.58105, 126.89056, '서울특별시 마포구 성암로 267', '6화 에서 ''프리킬러''에 대한 뉴스가 이웃 YTN 빌딩의 한켠 화면에 나타나 배경이 되고 있다.4회 에서는 성폭행 피해자 안지혜(김지혜 분)가 자신의 고발자인 아이돌 강준서(전 소년공화국 이수웅 분)에 대한 모든 고소를 취하한다고 선언하는 뉴스 프로그램의 게스트로 이곳 TV 스튜디오에 오는 모습이 그려진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03168', '이대역', '관광지', 37.55675, 126.9459, '서울특별시 마포구 신촌로 180', '16회(전체 8회)에서 한수연(노수산나)이 딸 서정우를 만나러 가는 길에 이 지하철역 6번 출구에서 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03169', 'DMC이안오피스텔', '관광지', 37.577248, 126.89089, '서울특별시 마포구 월드컵북로 361', '24회(전체 12회)에서 그녀가 봉지를 든 남자를 이 건물 밖에서 지나가고 있는 모습이다. 그녀를 제시간에 구하지 못한 것이 안타까운 형사 양수동(김영웅)은 그녀에게 집까지 데려다주겠다고 제안하지만 미호의 낭만적인 인상에 그 제안을 거절한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03170', 'DMC문화공원', '관광지', 37.577736, 126.89216, '서울특별시 마포구 월드컵북로 366', '11화(완전 6화)에서 이곳을 걸으면서 행인들은 ''프리킬러''에 대한 소식을 접한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03171', '서울중앙지방법원', '관광지', 37.496068, 127.01148, '서울특별시 서초구 서초중앙로 157', '은솔(정유미 분), 강현(박은석 분) 등 검찰팀이 근무하는 곳으로, 검법남녀2에서도 더 많은 사건과 싸우기 위해 이곳으로 돌아온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03172', '동작대교', '관광지', 37.51041, 126.981893, '서울특별시 용산구 이촌동 동작대교', '6회에서 장철(노민우)은 이 다리 옆을 걷다가 멈춰 서서 강에 휴대폰을 던진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03173', '광화문역', '관광지', 37.569676, 126.97668, '서울특별시 종로구 세종로 1-80', '14회(전편 7회)에서 경찰관들이 이 지하철역 출구 앞에서 전단지를 나눠주며 전 살인 용의자 오만상(김도현 분)의 생존 사실을 대중에게 알리는 모습이 그려진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03174', '용현1.4동', '관광지', 37.457023, 126.6609, '인천광역시 미추홀구 수봉남로18번길 81-22', '10화(전체 5화)에서 검사 도지한(오만석)과 양수동(김영웅) 수사관이 이 길에서 하차한다', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03175', '팍스타워', '음식점', 37.509924, 127.03674, '서울특별시 강남구 언주로 609', '2회에서 마혜리(김소연)와 서인우가 이 식당에서 만나 과거에 빌려준 돈을 갚는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03176', '오스테리아 꼬또 압구정점', '관광지', 37.52465, 127.0325, '서울특별시 강남구 언주로 835', '마혜리(김소연)와 윤세준(한정수)은 오후 데이트를 위해 이 거리를 찾았다. 혜리는 남자친구가 생기면 하고 싶은 버킷리스트가 있었는데 그 중 하나가 바로 4월 중순에 손을 잡고 벚꽃 길을 걷는 것이었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03177', '이태원랜드', '관광지', 37.534093, 126.99727, '서울특별시 용산구 우사단로14길 34', '마혜리(김소연)는 검사프린세스(SBS, 2010)에서 부모님과 함께 이 저택에 산다. 5화에서 서인우가 그녀를 집에 데려와 그녀가 차 안에서 잠을 자고 있을 때 그가 그녀를 편안하게 하기 위해 그의 가디건을 그녀의 목 아래에 두었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03178', '잠수교', '관광지', 37.514658, 126.996412, '서울특별시 서초구 반포동', '이성민이 천식호흡기를 한강에 던져 버린 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03179', '쉐라톤 그랜드 인천 호텔 ', '숙박', 37.390135, 126.645467, '인천광역시 연수구 컨벤시아대로 153', '7화에서 배타미(임수정)와 박모건(장기용)은 일이 끝난 뒤 데이트를 하러 이 해변에 방문한다', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03180', '익산 교도소 세트장', '관광지', 36.069334, 126.93158, '전라북도 익산시 성당면 함낭로 207', '임수정이 권해효를 만나러 갔다가 장기용과 만난 곳', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03181', '등명해변', '쇼핑', 37.704451, 129.01646, '강원도 강릉시 강동면 정동진리 440-7', '두 사람은 처음에 몰려드는 팬의 숫자에 놀랐지만, 이날 입대하는 한민규(변우석)에게 눈물의 이별을 고하고 있다는 사실을 깨닫는다. 스칼렛은 결국 여운의 입맞춤과 따뜻한 포옹으로 지환을 보낸다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03182', '무아레478&F1', '관광지', 37.666799, 127.385121, '경기도 가평군 청평면 북한강로 1619', '마지막 16회에서 여기 회의실에서 여성들은 정부와 기업의 개입으로부터 사용자를 보호하기 위해 포털 회사의 도덕률을 발표합니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03183', '오릴리도넛', '음식점', 37.675336, 126.7803, '경기도 고양시 일산동구 산두로 215', '4화에서 배타미(임수정)와 이미 전 남자친구인 표준수와 식사를 했다는 사실을 알게 된질투심 많은 박모건(장기용)이 이 식당에서 밥을 먹습니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03184', '일산로', '관광지', 37.67888, 126.75196, '경기도 고양시 일산서구 일산로725번길 5-7', '8화에서 오진우(지승현)는 고려대 본사 로비로 보이는 이 센터 로비 AMG 스피드웨이에서 사장의 아들을 고의로 피하다 마주친다. ', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03185', '킨텍스', '쇼핑', 37.668805, 126.74593, '경기도 고양시 일산서구 킨텍스로 217-60', '7회에서 배타미(임수정)와 잠자는 박모건(장기용)이 차를 몰고 이 다리를 건넌다. 그녀는 그가 그녀와 함께 있어서 기뻤다고 말하면서 잠들었음을 깨닫는다. 잠시 잠에서 깨어나 그녀에게 반복해 달라고 말하고, 그는 그녀의 손을 잡고 다시 잠이 듭니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03186', '수원아이파크시티', '관광지', 37.244965, 127.02723, '경기도 수원시 권선구 동수원로145번길 23', '박모건(장기용 분)이 유니콘 계정을 잃었다는 소식을 들은 배타미(임수정 분)는 3회에서 이 공원에서 박모건과 만난다. 그는 그녀에게 전화와 메시지에 응답하고, 그녀가 보고 싶을 때마다 만나라고만 말합니다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03187', '광교호수공원', '관광지', 37.275851, 127.06379, '경기도 수원시 영통구 광교호수로 57', '3화에서 배타미(임수정 분)가 자신의 생각을 정리하러 오는 장면. 여기에서 그녀는 박모건(장기용)의 전화를 받기 전까지는 휴대폰 서비스를 받을 수 없다. 모건은 비오는 날 그녀를 데리러 여기에 옵니다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03188', '에버랜드 스피드웨이', '관광지', 37.2896511, 127.217242, '경기도 용인시 처인구 포곡읍 에버랜드로 199', '8회 슈퍼레이스 챔피언십을 보기 위해 KU그룹 오진우(지승현)가 경마장을 찾았다. 놀랍게도 그의 아내 송가경(전혜진)이 합류한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03189', '와우정사', '관광지', 37.194157, 127.276751, '경기도 용인시 처인구 해곡로 25-15', '1화, 2화에서는 스님이 아침기도를 마치고 고요한 사찰 밖을 걸어가는 장면이 나온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03190', '파주동화경모공원', '관광지', 37.794331, 126.69739, '경기도 파주시 탄현면 헤이리로 98', '5회에서 가경(전혜진)이 갑자기 나타나 상황을 엿듣는다. 그런 다음 타미는 유리벽에 있는 건물의 특징적인 십자형 계단을 걸어 내려갑니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03191', '뜨인돌출판사', '카페', 37.716021, 126.69167, '경기도 파주시 회동길 337-9', '11회에서 송가경(전혜진)이 차를 타고 이 카페를 지나가다가 스칼렛/차현(이다희)이 카페에 앉아서 열심히 일에 집중하는 모습을 발견한다. 이에 가경은 둘이 학창시절을 보낸 과거를 떠올린다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03192', '아트갤러리카페', '카페', 37.720434, 126.693496, '경기도 파주시 회동길 445-2', '5회 회상장면에서 남일여고 학생이던 차현(이다희)은 이곳에서 송가경(전혜진)을 어떻게 만났는지 회상한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03193', '골프존 조이마루', '관광지', 36.376321, 127.39045, '대전광역시 유성구 엑스포로97번길 40', '드라마에서 바로오피스의 일부로 나온다.', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03194', '어거스트 힐', '음식점', 37.5033475, 127.0275692, '서울특별시 강남구 강남대로106길 25', '7회에서 유니콘의 송가경(전혜진)이 웹툰작가 모임을 이 식당에서 연다.. 배타미(임수정)와 차현(이다희)이 아티스트 중 한 명을 바로로 쟁취할 방법을 찾기 위해 첩보하러 온 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03195', '이구펍 4호점/29펍 4호점', '관광지', 37.503747, 127.02606, '서울특별시 강남구 강남대로110길 14', '1회에서 송가경(전혜진)이 이 술집에 찾아와 여자들과 어울리고 있는 남편 오진우(지승현)를 만난다. 남편에 대한 관심도 애정도 보이지 않는 가경의 모습은 ''일반적인'' 상황인 듯하다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03196', '그랜드힐컨벤션', '관광지', 37.506062, 127.0668, '서울특별시 강남구 대치2동 역삼로 607', '6회 배타미/태미(임수정)와 조아라/엘리(오아연)가 최고 만화 제작자를 만나지 전에 이 컨벤션홀 주차장에 도착해 주차를 하고 있다. 그의 열렬한 팬인 Ellie는 너무 긴장하지 않으려고 노력합니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03197', '강변북로', '관광지', 37.540528, 127.03633, '서울특별시 성동구 옥수동 86', '차현(이다희)의 차로 청문회를 떠난 배타미(임수정)는 성수대교 바로 앞에서 내려달라고 부탁한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03198', '롯데월드타워 아쿠아리움', '쇼핑', 37.512599, 127.102714, '서울특별시 송파구 올림픽로 300 롯데월드몰 B1', '임수정이 장기용에게 전혜진에 대해 털어놓는 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03199', '아이즈빌아울렛', '쇼핑', 37.521801, 126.70363, '인천광역시 부평구 마장로 489', '드라마의 등장하는 등장인물들이 이 지하철역에서 주로 출퇴근 하는 장면을 많이 촬영했다. ''유니콘 본사역'', ''선남역'', ''서울역'' 시리즈에 등장한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03200', '국제업무지구역', '관광지', 37.39981, 126.6296, '인천광역시 연수구 인천타워대로 334', '임수정과 장기용이 처음 만난 로맨틱한 오락실', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03201', '타니스 송도점', '관광지', 37.398392, 126.65134, '인천광역시 연수구 컨벤시아대로 50 송도월드마크푸르지오1단지상가 2층', '아케이드에서 치열한 철권 배틀을 한 뒤 만난 배타미(임수정)와 박모건(장기용)은 1화(2화 회상)에서 이 카페에서 식사를 하고 방금 작곡한 음악을 그녀에게 들려준다. 그들은 또 다른 철권 배틀을 마치고 8화에서 이곳으로 돌아왔다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03202', '맹꽁이 오락실', '관광지', 35.819553, 127.153436, '전라북도 전주시 완산구 동문길 6', '1화에서 UNICON 대표로 배타미/타미(임수정)의 상원 청문회가 본 대학 벤처산업협력동 회의실에서 열린다. 태미는 주변 취재진을 빠져나갈 때 스칼렛이 경쟁사에 다니는 줄도 모르고 차현/스칼렛(이다희)의 차에 뛰어든다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03203', '플뢰르 카페', '카페', 35.820236, 127.15026, '전라북도 전주시 완산구 현무2길 14-23', '영화 검은 사제들 속 강동원의 숙소', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03204', '월배 성당', '관광지', 35.815886, 128.527618, '대구광역시 달서구 월배로 131-5', '박소담이 김윤석에게 테스트를 받는 장소', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03205', '샬트르 성바오로 수녀원', '관광지', 35.86217, 128.585576, '대구광역시 중구 남산로4길 111', '영화 검은 사제들에 나오는 수녀원', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03206', '계산성당', '관광지', 35.867913, 128.587829, '대구광역시 중구 서성로 10', '강동원이 성당으로 들어갈 때 나온 부감 샷', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03207', '행주산성공원', '관광지', 37.598424, 126.81911, '경기도 고양시 덕양구 행주외동 140-8', '6회에서 한지혁(남궁민 분)과 린웨이(옥자연 분)가 이 공원의 ''석주권필 기념비''에 온다. 린웨이는 지혁에게 계속 하지 말라고 경고한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03208', 'JW메리어트 동대문스퀘어서울', '음식점', 37.5703776, 127.008887, '서울특별시 종로구 청계천로 279', '8회에서 린웨이(옥자연)가 이 식당에서 그녀에게 정보를 얻기 위한 만남을 가졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03209', '서울디자인재단', '관광지', 37.566752, 127.0101, '서울특별시 중구 을지로 281', '5화에서 서수연(박하선)과 한지혁(남궁민)이 이곳에서 만난다. 수연은 그들이 과거 나눈 추억에 대해 이야기하기 시작하고 중요한 정보를 공유하려고 할 때 그녀는 지혁 앞에서 총에 맞는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03210', '추암해수욕장', '관광지', 37.47755, 129.1595, '강원도 동해시 촛대바위길 2', '18회에서 데이트 장소로 나온다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03211', '춘천 기와집골 마을', '관광지', 37.886993, 127.72725, '강원도 춘천시 기와집길31번길 2', '첫 두 에피소드에서 고등학생 강준상(배용준)의 어머니가 그를 미국으로 데려오기 전에 사는 곳이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03212', '남이섬', '관광지', 37.789935, 127.52581, '강원도 춘천시 남산면 남이섬길 1', '강준상, 정유진 동상 앞에서 셀카를 찍는다. 이 섬은 강준상(배용준)과 정유진(최지우)의 비밀장소다. 1화에서 처음으로 손을 잡고 첫 키스하고, 2화에서 눈사람을 만든다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03213', '후암동성당', '관광지', 37.552069, 126.97821, '서울특별시 용산구 후암로34길 21-8', '16회에서 이민형(배용준)이 정유진(최지우)에게 별목걸이로 프러포즈한 곳. 그리고 그들은 제단 앞에서 입맞춤을 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03214', '마로니에 공원', '관광지', 37.580499, 127.00244, '서울특별시 종로구 대학로 104', '3회에서 정유진(최지우)이 약혼식장에 가는 길에 이민형(배용준)이 죽은 줄 알았던 곳이기도 하다. 약혼 파티는 까맣게 잊고, 그녀는 미친 듯이 그의 뒤를 쫓아가서 그를 찾으려고 한다. 헛수고다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03215', '더플라자', '숙박', 37.564704, 126.97816, '서울특별시 중구 소공로 119', '이민형/강준상(배용준)은 잠시 이 호텔에 거주한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03216', '경원재 앰배서더 인천', '관광지', 37.391611, 126.63723, '인천광역시 연수구 테크노파크로 200', '2회에서 서준형(이진욱)과 김나은(이연희)의 부모님의 만남은 이곳 이뤄진다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03217', '양평 두물머리', '관광지', 37.532869, 127.31599, '경기도 양평군 양서면 양수리', '4회에서 송지혜(남상미)와 강태욱(김지훈)은 이곳을 산책하며 서로를 알아간다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03218', '제주국제공항', '관광지', 33.506548, 126.49304, '제주특별자치도 제주시 공항로 2', '1회에서 송지혜(남상미)와 김현우(이상우)가 공항에 도착한다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03219', '하우스에딘브로우', '관광지', 37.520323, 127.04457, '서울특별시 강남구 학동로59길 43', '1화에서 판사현(성훈)과 송원(이민영)이 임신 사실을 알게 된 후 그는이 꽃집 앞에 멈춰서 그녀에게 축하 꽃다발을 사달라고 부탁합니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03220', '헌화로드라이브코스', '관광지', 37.664267, 129.05459, '강원도 강릉시 강동면 심곡리 헌화로', '최종화 16화에서 절친 김영희(안은진), 신현재(최찬호), 경우연(신예은), 이수(옹성우), 한진주(백수민), 진상혁(표지훈)이 여행 중 이 길을 따라가는 모습을 볼 수 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03221', '은석교사거리 정류장', '관광지', 37.706728, 126.68646, '경기도 파주시 문발동 은석교사거리 정류장', '8화에서 이수(워너원 옹성우)는 경우연(신예은)을 따라 영화사 미팅을 하지만 계약이 불발되자 슬프고 화가 난 경우연을 위로해주기 위해 이 버스 정류장으로 향한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03222', '청려수련원', '관광지', 37.20499, 127.145909, '경기도 화성시 풀무골로110번길 69', '1회에서는 고교 시절 자원봉사를 위해 고교 동창들과 함께 이곳을 찾은 경우연(신예은)과 이수(옹성우, 전 워너원)', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03223', '울프강 스테이크 하우스', '음식점', 37.5244835, 127.041441, '서울특별시 강남구 선릉로152길 21', '5화에서 경우연(신예은)과 온준수(ZE:A 김동준)가 이 식당에서 저녁을 먹었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03224', '방화대교', '관광지', 37.588281, 126.82685, '서울특별시 강서구 방화동 방화대교', '8회 밤 이 다리에서 이수(워너원 옹성우)가 다리로 나온다. 자신이 찍은 경우연(신예은)의 지갑에 넣고 다니는 것 외의 사진을 불태운다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03225', '동교로46길', '관광지', 37.562063, 126.92624, '서울특별시 마포구 동교로46길', '경우연(신예은)과 이수(워너원 옹성우)는 연남동을 탐험하며 이 거리를 걷는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03226', '엘리카메라', '카페', 37.565476, 126.92217, '서울특별시 마포구 성미산로29길 30-3 102호', '경우연(신예은)과 이수(워너원 옹성우)는 이 ''가게''와 브런치 카페를 지나 이 거리를 걷는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03227', '홍대입구역', '관광지', 37.556815, 126.92373, '서울특별시 마포구 양화로 160 홍대입구역', '경우연(신예은)과 이수(워너원 옹성우)는 연남동 구경한다. ', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03228', '야식포차', '음식점', 37.565931, 126.92784, '서울특별시 서대문구 성산로 337', '1회에서 신현재(최찬호)와 김영희(안은진)가 이 식당에서 심야 회식을 했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03229', '디토', '음식점', 37.48568, 127.0043, '서울특별시 서초구 명달로 94', '9회에서 온준수(김동준)가 이 식당으로 경우연(신예은)을 저녁 데이트에 데려온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03230', '성수역', '관광지', 37.544575, 127.05598, '서울특별시 성동구 아차산로 100', '7회에서 경우연(신예은)과 온준수(ZE:A 김동준)는 이 역 3번 출구 근처 성수동 카페거리를 걸어간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03231', '성수동카페거리', '카페', 37.542965, 127.05659, '서울특별시 성동구 아차산로 92-1', '경우연(신예은)과 온준수(ZE:A 김동준)는 7화에서 신화인쇄사 옆을 지나가고 있다. 이 때, 준수도 바이산이 있는 건물을 사진에 담는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03232', '어니언 성수', '카페', 37.544699, 127.058206, '서울특별시 성동구 아차산로9길 8', '7화에서 경우연(신예은)과 이수(워너원 옹성우)는 이 루프탑 카페에 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03233', '문래역', '관광지', 37.517957, 126.89475, '서울특별시 영등포구 당산로 28', '7회에서 경우연(신예은)과 이수(워너원 옹성우)가 역 1번 출구에서 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03234', '여의도공원', '관광지', 37.5281241, 126.925754, '서울특별시 영등포구 여의공원로 68', '마지막 16회에서 경우연(신예은)과 이수(워너원 옹성우)가 데이트를 위해 이 공원을 찾았다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03235', '해방촌 신흥시장', '쇼핑', 37.545443, 126.98494, '서울특별시 용산구 신흥로 95-9', '경우연(신예은)과 이수(워너원 옹성우)는 후암동 탐방 중 노가리팩토리 등의 가게들을 지나며 이 시장을 걷게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03236', '오리올', '관광지', 37.547369, 126.98406, '서울특별시 용산구 신흥로20길 43', '5화에서 경우연(신예은)과 이수(옹성우)가 후암동 탐방을 마친 후, 그들의 책 ''서울의 이야기''에서 세 번째로 다룬 동네다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03237', '연서로50길', '관광지', 37.641383, 126.93903, '서울특별시 은평구 연서로50길 7-12', '16회 최종회에서 경우연(신예은 분)과 이수(워너원 옹성우 분)가 이 거리를 따라 다투는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03238', '북촌로11길', '관광지', 37.582967, 126.98348, '서울특별시 종로구 북촌로11길 52', '경우연(신예은)과 이수(워너원 옹성우)가  6화에서 자신들의 책 ''서울이야기''에 수록된 다섯 번째 동네인 북촌을 탐험하는 동안 이 거리에서 사진을 찍고 있다. 이수가 우연의 사진을 찍는 곳도 이곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03239', '까페골목숲', '카페', 37.583222, 126.98206, '서울특별시 종로구 삼청로 86-3', '경우연(신예은)과 이수(워너원 옹성우)는 이 카페를 찾는다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03240', '모스버거 명동중앙점', '음식점', 37.565389, 126.984073, '서울특별시 중구 명동9길 37', '김영희(안은진)는 이 패스트푸드점 아르바이트를 하는 모습을 보여준다. 남자친구 신현재(최찬호)는 퇴근 후 그녀를 방문한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03241', '서울파이낸스센터', '음식점', 37.5684113, 126.977714, '서울특별시 중구 세종대로 136', '김영희(안은진)와 신현재(최찬호)는 10회에서 이 식당에서 그의 생일을 축하한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03242', '남산 케이블카', '관광지', 37.556593, 126.98404, '서울특별시 중구 소파로 83', '이곳에서 정우연(신예은)과 이수(옹성우)가 만남을 갖고 주차장에 막 도착하려 할 때 이수는 교통사고를 당한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03243', '카페 4F', '카페', 37.567855, 127.00134, '서울특별시 중구 을지로35길 26-1', '5화에서 경우연(신예은)과 이수(워너원 옹성우)는 이 카페를 찾는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03244', '용마랜드', '관광지', 37.594468, 127.105556, '서울특별시 중랑구 망우로70길 118', '8회에서 경우연(신예은)과 이수(워너원 옹성우)가 책 <서울의 이야기>를 위해 서울을 탐방하던 마지막 장소다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03245', '해든뮤지움', '관광지', 37.61204, 126.5089, '인천광역시 강화군 길상면 장흥로101번길 44', '이수(옹성우)는 이 자리에서 최종회 16회에 전시회를 열고,  경우연(신예은)이 드디어 재회한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03246', '달책빵', '카페', 33.536409, 126.83943, '제주특별자치도 제주시 구좌읍 대수길 10-12', '제주도에 있는 동안 이수(워너원 옹성우)는 이 서점 카페에서 만난다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03247', '임진고택', '숙박', 33.513302, 126.8635, '제주특별자치도 제주시 구좌읍 상도로 16-13', '경우연(신예은)은 2회에서 이 호스텔에서 2주간 알바를 하고 있다. 이곳은 이수(워너원 옹성우)가 제주도에서 화보 촬영 중 머물던 곳이기도 하다. 주인은 이수의 오랜 친구이자 오랜 친구다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03248', '소심한책방', '관광지', 33.491445, 126.90309, '제주특별자치도 제주시 구좌읍 종달동길 29-6', '이수(워너원 옹성우)와 동행한 경우연(신예은)은 2회에서 자신의 서예 엽서 전시 및 판매에 대해 서점에 문의한다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03249', '용눈이오름', '관광지', 33.458681, 126.83005, '제주특별자치도 제주시 구좌읍 종달리 산 38', '2회에서 3년 후 경우연(신예은)과 이수(워너원 옹성우)는 제주도를 탐험하던 중 우연히 이 언덕에서 만난다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03250', '술의 식물원', '관광지', 33.471779, 126.78376, '제주특별자치도 제주시 구좌읍 중산간동로 2253', '2회에서는 이수(워너원 옹성우)가 제주도 여행 중 발목을 삐끗한 경우연(신예은)을 업은 장소로 등장한다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03251', '책방소리소문', '관광지', 33.358009, 126.27169, '제주특별자치도 제주시 한경면 저지동길 8-31', '경우연(신예은)은 2회에서 자신의 서예 엽서 전시 판매에 대해 서점에 문의하고, 예의없는 주인이 이를 알아차린다. 그녀는 떠나면서 온준수(ZE:A의 김동준)와 마주친다. 우연은 자신의 엽서 중 하나가 바닥에 떨어져 상점 주인이 밟고 있는 것을 보고 상점에 다시 들어가 엽서를 가지고 간다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03252', '서쪽가게', '관광지', 33.393359, 126.24059, '제주특별자치도 제주시 한림읍 한림로 372-7', '2회에서 이수(옹성우)와 경우연(신예은)이 가게를 찾았다. 그녀와 함께 다른 서점에 가서 그녀의 캘리그라피 엽서를 전시할 수 있도록 두고간다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03253', '다산교앞 정류장', '관광지', 37.710554, 126.68633, '경기도 파주시 광인사길 68 다산교앞 정류장', '경우연(신예은)은 친구 이상의 사건 14회에서 이수(워너원)와 이별한 뒤 이 버스로 가는 길에 멍하니 앉아 버스를 기다린다. 그녀의 눈에 띄지 않는 온준수(김동준) 그녀를 따라 이곳으로 온 거예요', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03254', '쉴낙원 김포장례식장', '관광지', 37.607202, 126.71541, '경기도 김포시 승가로58번길 7', '1회에서 고(故) 장철정(성지루 분)의 장례에 최장물(안석환 분) 대표가 조문하는 곳으로 나온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03255', '동화컬처빌리지', '쇼핑', 37.659675, 127.37391, '경기도 남양주시 화도읍 북한강로 1708-38', '4회에서 신명희 시장(최광일)이 언론에 정진시의 향후 발전 방향을 언론에 알리는 곳입니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03256', '로케이션 이음 (구 로얄퀘스트)', '관광지', 37.713531, 126.74641, '경기도 파주시 탄현면 새오리로286번길 48-70', '드라마 안에서 등장하는 악마에게 살해를 당하는 전기환 전 태신그룹 회장(이도경)의 사무실로 4-6회에서 자주 등장한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03257', '운산', '음식점', 37.529282, 126.92486, '서울특별시 영등포구 여의공원로 101', '11회에서 가모탁(유준상)은 7년 전 형사 소권(전석호)가 이 식당의 그의 테이블에 합석하여 그에게 신 시장과 김영님 사이의 관계에 대해 알려주던 일을 회상합니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03258', '블루부코', '관광지', 36.32977, 127.4393, '대전광역시 동구 동광장로 16', '오강희(정수정)와 강선호(정진영)는 7회에서 강희의 어머니 재판에 참석한 후 이 ''정원''에 앉아 마음을 터놓고 이야기를 나눈다.', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03259', '서울로7017', '관광지', 37.556524, 126.97375, '서울특별시 중구 청파로 432', '유동만(차태현)은 1회에서 불법 카지노 조직의 흔적을 찾아 이곳에서 잠복 도박을 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03260', '스테이트 타워 남산', '관광지', 37.560342, 126.98297, '서울특별시 중구 퇴계로 100', '2화에서 경찰대학 입학 시험을 위해 강선호(전 B1A4의 정진영)와 그의 동료들이 훈련하는 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03261', '용추폭포', '관광지', 37.855003, 127.48129, '경기도 가평군 가평읍 승안리 산225', '1회에서 정이현(윤현민)과 김금(서지훈)은 선옥남(고두심/문채원)이 선옥남(고두심/문채원)을 우연히 만난다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03262', '동춘상회', '관광지', 37.257691, 127.16008, '경기도 용인시 기흥구 동백죽전대로175번길 6', '최종화 16회에서 이함숙(전수진)이 정이현(윤현민)에게 코트를 사러 왔다. 점원에게 사치스럽지만 시골에서 입기 불편하고 부끄럽다고 말한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03263', '미메시스 아트 뮤지엄', '관광지', 37.716786, 126.68877, '경기도 파주시 문발동 253', '출판사가 회의에서 그녀의 에로스 소설을 출판하고 싶어한다는 사실을 알게 되어 조금 당황스럽습니다. ''점순호랑이'' 기사가 나온 후 출판사 관계자는 금에게 전화를 걸어 ''점순호랑이''라는 기사가 좋은 반응을 보인 탓에 마케팅 활동을 할 의향이 있는지 물었다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03264', '밀양역', '관광지', 35.47456, 128.771186, '경상남도 밀양시 중앙로 62', '3회에서 ''계룡역''에 오선생 삼인조(안길상), 산신/마법사 박(김민규), 선녀 오(황영희)가 등장한다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03265', '함양 함화루', '카페', 35.524592, 127.71884, '경상남도 함양군 함양읍 운림리', '마마요정과 계령의 ''선녀다방''이 있는 곳입니다. 1회에서 정이현(윤현민)과 김금(서지훈)은 우연히 숲 속에 숨겨진 카페를 발견하고 그곳에서 선옥남(고두심/문채)을 만난다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03266', '선릉로157길', '관광지', 37.526147, 127.03769, '서울특별시 강남구 선릉로157길 25', '12회에서 엄경술(유정우)은 학원을 나와 이곳에 왔다. 조봉대(안영미)를 보고 충격받아 가게에서 소시지를 먹고, 경술은 봉대를 즐겁게 하기 위해 비명을 지르며 뛰쳐나갑니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03267', '강북 메가스터디학원', '카페', 37.654197, 127.05905, '서울특별시 노원구 노해로 459', '이는 정이현(윤현민 분)이 강의하는 곳이자 선옥남(고두심 분/문채원 분)이 근무하는 베이반스 커피 카페가 위치한 ''엄마요정과 나무꾼'' 이원대의 배경이다. 2회에서는 옥남과 딸 전섬(구구단 강미나)이 머리 약속을 마치고 카페로 돌아가기 위해 대학 입구를 향해 길을 걷는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03268', '도화소어린이공원', '관광지', 37.540997, 126.94534, '서울특별시 마포구 토정로37길 22', '3회에서 과식비를 내고 간신히 탈출한 정이현(윤현민)과 김금(서지훈)은 이 공원의 쉼터를 찾아온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03269', '이화여대길', '관광지', 37.561923, 126.94703, '서울특별시 서대문구 이화여대길', '2회에서 선옥남(고두심)과 그녀의 딸 전섬(구구단 강미나)은 호기심 어린 시선으로 이 거리를 걷는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03270', '세빛섬', '관광지', 37.512019, 126.9953, '서울특별시 서초구 올림픽대로 683', '11회에서 점순(구구단 강미나)은 세빛섬을 바라보며 데이트를 한다. 16회 마지막회에서 김금(서지훈)은 육식을 금하고 마침내 인간의 모습을 유지한 점순을 만나기 위해 이곳을 찾는다. 푸드트럭에서 소시지를 사고 있던 중 경술은 점순에게 다가가 사과한다. 김금은 천계에서 지상으로 돌아온 선옥남(문채원)과 재회한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03271', '용산역', '관광지', 37.528843, 126.96408, '서울특별시 용산구 한강대로23길 55', '14화에서 구선생(안길상)과 산신/박마법사(김민규)가 계룡으로 돌아가는 기차를 이 역에서 기다린다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03272', '문화역서울284', '관광지', 37.555944, 126.971594, '서울특별시 중구 통일로 1', '3화에서 요정이 인간의 영역에서 어떻게 살고 자신의 정체도 모를 수 있는지에 대한 호기심으로 사람들을 보고있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03273', '목포역', '관광지', 34.791049, 126.38661, '전라남도 목포시 영산로 98', '3화에서는 아직 실현되지 않은 오류의 코미디에서 구사부(안길상), 산신 박(김민규), 오요정(황영희)의 3인조 요정이 역에서 의기양양하게 등장한다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03274', '합동직업소개소', '관광지', 34.786778, 126.38836, '전라남도 목포시 해안로249번길 3', '1회에서 정이현(윤현민)과 김금(서지훈)이 마을 파티에 참석하는 곳이다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03275', '신원사', '관광지', 36.335189, 127.18399, '충청남도 공주시 계룡면 신원사동길 1', '이 정자는 4회에서 머리요정이 선녀의 죽음을 알릴 때 등장합니다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03276', '부소산성', '쇼핑', 36.287052, 126.91527, '충청남도 부여군 부여읍 부소로 15', '13회에서 두 자매인 정수영(이하나)과 정유아(이율음)는 이 시장에서 아이스크림을 사서 비가 그치기를 기다리며 먹는다. 이후 에피소드에서 이민석(서인국)과 수영은 밤에 그녀를 집으로 데려다 줄 때 이곳을 지나간다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03277', '자하슈퍼', '음식점', 37.600253, 126.96281, '서울특별시 종로구 자하문로42길 57', '고독재(이이경) 아버지의 식당이 있는 거리다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03278', '신동카페거리', '카페', 37.247646, 127.04307, '경기도 수원시 영통구 신동 신동카페거리', '최종회 12화에서 마진주(장나라 분), 최반도(손호준 분)가 아들, 부모님과 함께 외식했던 식당이다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03279', '곱창전골', '관광지', 37.554734, 126.92944, '서울특별시 마포구 와우산로29길 8', '2회에서 시간여행을 마치고 참석한 최반도(손호준). 이곳이 처음 만난 곳임을 깨닫고 역사가 되풀이되지 않도록 최선을 다한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03280', '하늘공원', '관광지', 37.567465, 126.88546, '서울특별시 마포구 하늘공원로 95', '4화에서 민서영(고보결)과 최반도(손호준)가 데이트를 하러 이곳에 왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03281', '향꽃', '관광지', 37.558099, 126.93453, '서울특별시 서대문구 연세로7안길 39', '3회에서 1999년으로 돌아가보면 안재우(허정민)와 윤보름(한보름)이 여기서 첫 데이트, 재우가 취해서 기절할 때까지 막걸리를 마신다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03282', '경복궁', '관광지', 37.5806736, 126.976952, '서울특별시 종로구 사직로 161', '2회에서 최반도(손호준)가 마진주(장나라)를 차버렸다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03283', '카페로쏘', '카페', 37.582847, 126.98124, '서울특별시 종로구 삼청로 81-12', '김지후(신현수)와 서윤찬(고민시)은 지후의 사진교실에서 사진을 찍으러 왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03284', '앨리웨이 광교', '관광지', 37.274252, 127.06041, '경기도 수원시 영통구 광교호수공원로 80', '차영민(비/정지훈)과 장세진이 8회에서 유이(Uee)가 故 장광덕(이문수) 회장에게 조의를 표하는 모습.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03285', '청아공원기독교전용관', '카페', 37.719031, 126.80572, '경기도 고양시 일산동구 은마길 129', '11회에서 한승원(태인호)은 이 카페에서 안태현 박사(고상호)를 만나 한 번의 잘못된 움직임이 곧 깨어난 환자가 그렇게 할 수 없도록 합니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03286', '아이스타일카페', '카페', 37.7082492, 126.686674, '경기도 파주시 회동길 160', '11회에서 회상을 하며 차영민(비/정지훈)은 눈물을 흘리는 장세진(유이)에게 어떻게 그의 손이 다쳤는지 설명합니다. - 복면을 쓴 남자에게 맞았다는 것과 같은 중요한 디테일을 빠뜨린채 이 카페 빌딩의 바깥 벤치에 앉아 이야기합니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03287', 'Keepers', '관광지', 37.524091, 127.04099, '서울특별시 강남구 선릉로152길 18', '7,8회에서 이 술집에서 만남을 갖는다. 8회에서는 장민호(이태성)의 계획이 무산되자 승원과 함께 술을 마신다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03288', '그랜드 워커힐 서울', '숙박', 37.555208, 127.111341, '서울특별시 광진구 워커힐로 177', '8화에서 고승탁(김범)이 장광덕(이문수) 회장의 변호사를 만나러 이 호텔 입구로 찾아온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03289', '북촌로5길', '관광지', 37.579567, 126.98216, '서울특별시 종로구 북촌로5길', '2회에서 전 여자친구 장세진(유이)의 문자를 받은 것으로 추정되는 차영민(정지훈)이 만남의 장소로 달려가 그녀를 기다리는 모습이 그려진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03290', '서울 평창동 맨션 566-22', '관광지', 37.609562, 126.96388, '서울특별시 종로구 평창동 566-22', '이 집에서 경제학 교수와 그의 아내가 살해당했다.', '서울');
