INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03382', '아침고요수목원', '관광지', 37.742485, 127.35173, '경기도 가평군 상면 수목원로 432', '이 정원은 왕궁의 일부입니다. 1회에서 이영(박보검)은 자신의 옆에서 즐겁게 식사를 하고 있는 여동생 명은공주에게서 러브레터를 가로챈다. 그리고 3화에서 홍라온(김유정)은 영은공주(허정은)와 함께 이곳에서 정원 가꾸기를 하고 있다. 이영이 다가오고 라온과 라온은 한동안 티격태격하다가 라온에게 "친구라고" 부른다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03383', '화성행궁', '관광지', 37.2818191, 127.013426, '경기도 수원시 팔달구 정조로 825 ', '구르미 그린 달빛 티저영상 장소', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03384', '고성장산숲', '관광지', 35.058982, 128.32671, '경상남도 고성군 마암면 장산리 230-2', '구르미 그린 달빛에서 흙구덩이 함정에 빠진 장소', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03385', '반곡지', '관광지', 35.780498, 128.806454, '경상북도 경산시 남산면 반곡리 246', '차태현과 조여정이 특별 출연한 장소', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03386', '영주소수서원', '관광지', 36.925493, 128.58029, '경상북도 영주시 순흥면 소백로 2740', '김윤성(정진영)이 가장 좋아하는 은신처는 이 장소의 고대 편백나무 아래입니다. 3화에서 홍라온(김유정)에게 보여주고 이후 7화에서 윤성이 그녀를 찾아 선물을 주는 것처럼 고민이 필요할 때 찾아오는 곳이기도 하다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03387', '광화문 광장', '관광지', 37.5706546, 126.976661, '서울특별시 종로구 세종대로 175', '첫 티저에서 효명세자(박보검)가 붐바스틱 댄스를 추는 모습으로 이곳에서 촬영됐다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03388', '창덕궁', '관광지', 37.582757, 126.991295, '서울특별시 종로구 율곡로 99', '2회에서 (박보검) 왕과 내시가 나누는 대화를 엿듣습니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03389', '부안영상테마파크', '관광지', 35.620633, 126.48247, '전라북도 부안군 반석면 격포로 309-64', '왕의 생일 축제는 4화에서 열린다. 솔리스트 리드댄서 애심(차주영 분)이 실종되자 홍라온(김유정 분)이 대신 나서 축하연을 살리고 결국 이영/효명세자(박보검 분)를 마법에 걸리게 된다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03390', '전주향교', '관광지', 35.81291, 127.1572, '전라북도 전주시 완산구 향교길 139', '1화에서 어린 정지운(고우림)이 기 서재 바로 앞에서 어린 담이(최명빈)를 쫓는 장면이 나온다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03391', '칠지공원', '관광지', 36.290688, 126.90089, '충청남도 부여군 규암면 신리 480', '19회에서 이영(박보검 분)과 홍라온(김유정 분)의 데이트 장소로 등장했다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03392', '문헌서원', '관광지', 36.091799, 126.78549, '충청남도 서천군 기산면 서원로172번길 66', '이영/효명세자(박보검)가 정약용(박보검)을 만납니다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03393', '김포 라베니체', '관광지', 37.6433291, 126.6772804, '경기도 김포시 김포한강2로23번길 74', '베네치아를 모티브로 만들어진 드라마 <구미호뎐> 5회 촬영지', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03394', '라베니체 마치에비뉴', '관광지', 40.6406462, 129.678802, '경기도 김포시 김포한강4로 12', '5회에서는 이연(이동욱)과 남지아(조보아)가 맥주보다 좋아하는 것과 선호하는 것에 대해 이야기한다', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03395', '오랑주리', '관광지', 37.778571, 126.935162, '경기도 양주시 백석읍 기산로 423-19', '11회에서 구미호 이랑(김범)이 이연(이동욱)을 이곳으로 초대해 커피를 마시게 했다. 커피에 중독되어 의식을 잃게 만드는 가운데 권해룡(엄효섭)은 주차장에 세워진 자신의 차에 연결된 카메라를 통해 모든 것을 관찰한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03396', '용인 대장금 파크', '관광지', 37.1209396, 127.337296, '경기도 용인시 처인구 백암면 용천드라마길 25', '구미호전/구미호전 2화에서 이연(이동욱)과 남지아(조보아)가 배를 타고 해금강마을(개명 ''어화도'')에 도착한다', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03397', '운정장례식장', '관광지', 37.756052, 126.75281, '경기도 파주시 하늘채길 35', '2회에서는 이연(이동욱)과 남지아(조보아)가 어부가 발견한 잘린 머리의 미스터리를 조사하기 위해 ''어화도''로 여행을 떠난다. 지아 역시 자신이 태어나기 전에 부모님이 이 섬을 찾은 이유에 대한 답을 찾고 있으며, 바다 동굴 앞에 서 있는 부모님 사진을 들고 다닌다. 숲에서 그들은 잊혀진 영혼을 발견하고 지아는 장산사 동굴을 발견한 섬의 북쪽에서 그녀의 답을 찾을 것이라는 말을 듣는다. 지아는 그곳이 예전 사진과 같은 동굴임을 깨닫는다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03398', '해금강마을, 거제도', '관광지', 37.558888, 126.93903, '경상남도 거제시 남부면 갈곶리 해금강마을', '결혼을 앞둔 아홉살배기 여우(이정민)를 쫓기 위해 9살배기 1회에서 이연(이동욱)이 이 결혼식장에 온다. 한편 남지아(조보아 분)는 사연을 위해 이곳에 도착해 복도를 걸어나오면 연을 알아본다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03399', '강변한신코아', '관광지', 37.536275, 126.94394, '서울특별시 마포구 마포대로4다길 18', '4회에서는 이연(이동욱)이 옥상에서 동생 이랑(김범)과 대결을 펼치는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03400', 'CJ ENM', '관광지', 37.578581, 126.89189, '서울특별시 마포구 상암산로 66', '2회에서 이연(이동욱)이 남지아(조보아)와 영원히 이별하고 싶어하지만, 그의 세계에 소개되고 싶어하는 건물 앞이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03401', '아리수 스트로 공연장', '관광지', 37.558898, 126.93903, '서울특별시 서대문구 창천동 31-119', '15회에서는 이연(이동욱)과 남지아(조보아)가 공원에서 만나고 평범한 커플처럼 데이트를 할 계획을 세웁니다. 완벽한 남자친구가 되기 위해 연은 지아를 지키려고 도로쪽에 서서 길을 걷습니다. 나중에 그들은 게임 아케이드에서 실력을 시험하고 아이스크림을 먹습니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03402', '서울기상관측소', '관광지', 37.57143, 126.96623, '서울특별시 종로구 송월길 52', '1화에서 ''내세 출입국 관리소''로 표기로 표기된 이 장소에 간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03403', '한옥찻집', '관광지', 37.5747014, 126.984742, '서울특별시 종로구 인사동14길 12', '이연(이동욱)은 이 찻집(''달팽이 신부''로 출연)의 단골이다. 1화에서 그는 이곳에서 전통 도시락을 먹고 절친이자 동료인 쿠미호 구신주(황희)와 함께 이 곳을 들른다. 주인 복혜자(김수진)는 그에게 수사극 감독 남지아(조보아)를 둘러싸고 조심하라고 말한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03404', '곱분이곱창 청라점', '관광지', 37.532669, 126.65199, '인천광역시 서구 중봉대로586번길 9-19', '14회에서는 남지아(남보아)와 이연(이동욱)은 이무기를 죽이기 위한 최후의 결전을 앞두고 밤에 이 삼겹살 식당에서 식사를 한다', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03405', '망원한강공원', '관광지', 37.55347, 126.89816, '서울특별시 마포구 마포나루길 467', '6회에서 나오는데 이 공원의 성산대교 발 근처에는 방명수(변요한 분)와 김수진(송지효 분)이정기적으로 마음을 터놓고 이야기를 나누는 비밀 장소가 있다. 명수가 수진에게 사랑을 고백하고 12회가 끝날 무렵 두 사람이 키스를 하는 것도 이 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03406', '어텐션', '관광지', 37.550068, 126.9224, '서울특별시 마포구 와우산로17길 11', '7회에서 방명수(변요한)가 술에 취한 장화영(이윤지)을 발견한 술집. 마침내 술을 그만 마시고 집으로 돌려 보내도록 설득하는 데 성공한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03407', '홍대놀이터공원', '관광지', 37.552212, 126.92334, '서울특별시 마포구 와우산로21길 19-3', '라라(류화영)는 11회에서 이 공원에서 촬영을 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03408', '서경대정문.대일외고 버스 정류장', '관광지', 37.613282, 127.01284, '서울특별시 성북구 정릉동 266-620', '비가 내리기 시작할 때 방명수(변요한)는 버스를 타지 않고 이 정류장 벤치에 앉아 김수진(송지효)과 함께 비에 흠뻑 젖은 버스를 기다리던 순간을 회상한다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03409', '이화동 마을박물관', '관광지', 37.577519, 127.00815, '서울특별시 종로구 낙산성곽서1길 14', '이 박물관은 방명수(변요한)의 집으로 등장한다. 2회에서 처음 보여진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03410', '율곡로19길', '관광지', 37.5774144, 127.007971, '서울특별시 종로구 율곡로19길 68-64', '7회에서 방명수(변요한)가 술에 취한 장화영(이윤지)을 발견하고 집으로 돌려보낸다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03411', '충신4나길', '관광지', 37.576428, 127.00771, '서울특별시 종로구 충신4나길', '8회에서는 김수진(송지효)이 이 거리에 멈춰 사진을 찍는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03412', '미추홀타워', '관광지', 37.381795, 126.65339, '인천광역시 연수구 갯벌로 12', '장화영(이윤지)의 직장 ''오즈코퍼레이션 투자''로 나타난다. 예를 들어, 4화에서 방명수(변요한)가 그녀를 찾는 장면에서 볼 수 있습니다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03413', '투다리 양덕원점', '음식점', 37.61606, 127.76864, '강원도 홍천군 남면 양덕원2길 7-2', '한상환(옥택연)과 그의 친구들이 다니는 식당 중 하나다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03414', '하이트장', '숙박', 37.623497, 126.81875, '경기도 고양시 덕양구 토당로 88-16', '양시철이 숨어있는 모텔', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03415', '태하프라자', '관광지', 37.676399, 126.81275, '경기도 고양시 일산동구 위시티2로 19', '15회에서 상진이가 국회의원 출마 동기를 공개하며 정국에게 영감을 준다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03416', '미태리 김포카림애비뉴점', '카페', 37.645917, 126.62918, '경기도 김포시 김포한강4로 487 반도유보라4차 상가동 1094호', '이 카페에서 커피를 사온 양정국(최시원)은 2회에서 사기꾼 강현태(정성호)와 김미영(이유영)의 결혼에 대해 폭언한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03417', '클럽 옥타곤', '숙박', 37.511209, 127.03167, '서울특별시 강남구 논현로 645 뉴힐탑호텔 2', '미영이 바람둥이 남자를 제압하고 신발 한 켤레를 방 너머로 던진 후 정국의 목덜미를 명중한 후 처음으로 눈을 감는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03418', '청담덕영빌딩', '관광지', 37.524555, 127.05273, '서울특별시 강남구 도산대로 540', '6회에서 양정국(최시원)은 납치된 후 그녀에게 마음의 조각을 주기 위해 찾아와 아내 김미영(이유영)에게 가해를 시도하는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03419', '남금사우나', '관광지', 37.489842, 126.85498, '서울특별시 구로구 개봉로15길 15', '김미영(이유영)과 그녀의 팀은 박후자(김민정)의 협력자 중 한 명인 오성택을 잡기 위해 이 사우나(''월철 사우나''로 등장)를 지킨다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03420', '대륭테크노타운', '관광지', 37.46829, 126.88644, '서울특별시 금천구 가산디지털1로 25', '한상진(태인호)이 후자가 자신의 대학 자격을 위조 한 것을 밝히기 위해 기자 회견을 개최합니다. ', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03421', '서울국립현충원', '관광지', 37.500612, 126.97277, '서울특별시 동작구 현충로 210', '12회에서 현충탑(현충탑)에서 조문을 하고 있습니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03422', '곱 마포점', '관광지', 37.5410215, 126.9493516, '서울특별시 마포구 도화길 31-1', '부동산 습격장에서 만난 박후자(김민정)에게 뇌물을 받은 형사 이(최대철)가 팀의 두더지임을 자백하는 곳.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03423', '상장회사회관', '관광지', 37.545453, 126.94464, '서울특별시 마포구 독막로 279', '양정국(최시원)에게 급하게 끌려갔다는 사실을 알게 된 박후자(김민정)와 여동생 박귀남(안은진)은 이 건물로 향하였다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03424', '장수족발', '관광지', 37.545069, 126.953344, '서울특별시 마포구 만리재로 19', '8화에서 박후자(김민정)와 함께 이곳에서 김주명 의원(김의성)을 처음 만나고, 13화와 같이 이곳으로 돌아와 김 의원을 만나거나 홀로 슬픔에 빠진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03425', '별밤', '관광지', 37.548729, 126.92033, '서울특별시 마포구 어울마당로 39', '베네수엘라에서 일하는 사업가 행세를 하는 사기꾼 양정국(최시원)이 이곳에서 박상필(김종구) 회장을 만나 금전거래를 논의한다.거래가 끝난 후, 박 회장의 부하들 중 한 명이 그에게 수백만 달러를 사기당했다고 말하기 위해 술집에 도착한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03426', '마포구청역', '관광지', 37.563515, 126.90337, '서울특별시 마포구 월드컵로 190', '정국이 건너편에서 감시하고 있다는 사실을 그들은 거의 알지 못합니다. 정국의 전화를 받은 노부부가 지하철역으로 들어가고 형사들이 뒤를 쫓는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03427', '명월이네', '관광지', 37.558686, 126.93527, '서울특별시 서대문구 연세로9길 28', '7화에서 정국은 동료 사기꾼 찰스(양동근), 황승이(이주명)와 함께 이곳에 와서 자신의 캠페인을 돕도록 설득하려 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03428', '제일빌딩', '관광지', 37.525731, 126.90937, '서울특별시 영등포구 버드나루로 84', '역에 있던 미영은 구매자가 처음 들어왔을 때 들고 있던 서류가 더 이상 없다는 것을 알게 됩니다. 그녀는 그에게 다가가 충격을 받고 그가 전날 이미 계약서에 서명했다는 것을 알게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03429', '효창공원앞역', '관광지', 37.539246, 126.96139, '서울특별시 용산구 백범로 지하 287', '9회에서 정국은 길가에 주차를 하고 건물 밖에 서서 길가에서 찰스(양동근)에게 전화를 걸어 자신의 상태를 알린다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03430', '무교로', '관광지', 37.567385, 126.97923, '서울특별시 중구 무교동 무교로', '양정국(최시원)이 26회에서 부동산 사기를 당한 성대철과 맞서기 위해 이 건물로 옵니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03431', '네오위즈', '관광지', 37.400557, 127.104395, '경기도 성남시 분당구 대왕판교로645번길 14', '6회에서 도배만(안보현)이 용문구(김영민)를 만난 후 이 건물을 나서고 그를 따라다녔던 차우인(조보아)의 전화를 받는다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03432', '구읍2리마을회관', '카페', 37.95516, 126.92108, '경기도 파주시 적성면 칠중5길 6', '건물 외관은 ''물망초 카페''로 보이며, 차우인(조보아)과 강하준(강영석)이 병무청 검사 비밀 은신처를 두고 있는 곳이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03433', '조이마당스튜디오', '관광지', 37.83256, 126.8035, '경기도 파주시 파주읍 봉서산로 243', '16회에서 윤문구(김영민)와 이재식(남경읍)의 재판이 펼쳐진다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03434', '파라다이스시티', '관광지', 37.437623, 126.45597, '인천광역시 중구 영종해안남로321번길 186', '1회에서 본 클럽 ''카르텔''의 외관입니다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03435', '고성 가진항 (군함도)', '관광지', 38.368921, 128.512494, '강원도 고성군 죽왕면 가진해변길 121-12', '군함도의 포스터를 촬영한 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03436', '명동 닭갈비 골목', '음식점', 37.879342, 127.727625, '강원도 춘천시 금강로62번길 9-1', '춘천에서 배우들의 머리식히는 공간으로 사용된 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03437', '소양강 스카이워크', '관광지', 37.893618, 127.723499, '강원도 춘천시 영서로 2663', '영화의 배경인 인민군의 생활을 엿볼 수 있는 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03438', '인민군사령부 막사', '관광지', 38.177853, 127.546159, '강원도 화천군 상서면 다목리 361-1', '소지섭이 섬을 탈출하는 장면을 찍은 곳', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03439', '동부창고', '음식점', 36.654697, 127.492676, '충청북도 청주시 청원구 덕벌로 30', '8화에서 김도한(주상욱)은 강현태 차장(곽도원)을 이 식당에서 만났다.', '충북');
