INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03441', '하림각', '음식점', 37.5972027, 126.962067, '서울특별시 종로구 자하문로 255', '굿모닝대한민국 454회 게살연두부찜/해물누룽지탕', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03442', '북카페눈', '카페', 37.707591, 126.68719, '경기도 파주시 회동길 125-11', '이 카페는 1회에서 돈세라(권유리)의 절친 사나희(송상은)가 오픈한 베이커리 카페 ''빵야''로 등장한다. 카페가 있는 건물 자체가 2층에 양진모(음문석) 법무법인이 있는 ''SW플라자''로 나온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03443', '서강8경', '음식점', 37.544923, 126.92535, '서울특별시 마포구 토정로 128 8층', '양진모(음문석 분)는 9화에서 자신이 빌려준 이 식당의 사나희(송상은 분)에게 자신의 마음을 고백한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03444', '스위스 그랜드 호텔', '숙박', 37.588838, 126.93403, '서울특별시 서대문구 연희로 353', '1화에서 은선우(정일우 분)가 제보자를 쫓는 ''로열호텔''이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03445', 'IFC서울', '관광지', 37.525023, 126.92565, '서울특별시 영등포구 국제금융로 10', '이곳은 1화에서 은선우 회장(정일우)이 여기 회의에 참석할 때, 3화에서 ''억강공사''로 나타난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03446', '후암동 옥탑방', '관광지', 37.548122, 126.98389, '서울특별시 용산구 두텁바위로60길 78', '이 건물 옥상에는 2회에서 처음 에 단짝 돈세라(유리)와 사나희(송상은)가 살고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03447', '트리플 스트리트', '관광지', 37.379962, 126.66073, '인천광역시 연수구 송도과학로16번길 33-1', '13회에서 장사를 이야기하던 중 옆방에 앉은 윤석호(이상엽)와 변우석(허재호)의 말을 엿듣는다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03448', '압구정나들목', '관광지', 37.373988, 126.43924, '서울특별시 강남구 압구정동 압구정나들목', '3회에서 피철웅(배진웅)이 로커로 소포를 배달하기 위해 이 역으로 파견된다. 6화에서 이 역으로 걸어 들어간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03449', '수락산역', '관광지', 37.677725, 127.05531, '서울특별시 노원구 동일로 지하 1662', '백찬미(최강희)는이 대학을 다녔고 윤석호(이상엽)는 정기적으로 캠퍼스를 방문했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03450', '역사책방', '관광지', 37.579291, 126.97281, '서울특별시 종로구 자하문로10길 24', '16회에서 두 사람이 가출로 처음 만났을 때 왕세자 이신(주지훈)과 민효린(송지효)은 그곳을 다시 찾았던 기억을 떠올리며 이 농장을 찾는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03451', '원당종마목장', '관광지', 37.664249, 126.87342, '경기도 고양시 덕양구 서삼릉길 233-112', '왕세자 이율(김정훈)은 14회에서 왕세자 신채경(윤은혜)을 이 놀이공원으로 데려오고, 왕세자 신채경(윤은혜)은 그녀의 기분을 풀어주려고 한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03452', '동궁과 월지', '관광지', 35.83429, 129.226584, '경상북도 경주시 원화로 102', '왕실이 돌아가며 시를 낭송하는 다과회 장면', '경주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03453', '임피리얼팰리스 서울', '숙박', 37.51401, 127.03585, '서울특별시 강남구 언주로 640', '이율 왕자(김정훈)는 5회를 통해 어머니(서울에 도착했을 때)와 함께 이 호텔 밖에서 리셉션을 위해 온 민효린(송지효)을 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03454', '삼청각', '관광지', 37.597208, 126.98403, '서울특별시 성북구 대사관로 3', '이 단지는 왕궁의 일부로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03455', '선유도공원', '관광지', 37.543688, 126.899705, '서울특별시 영등포구 선유로 343', '신채경 왕세자비(윤은혜)는 14회에서 시간이 필요할 때 혼자 이 공원에 와서 자신을 알아보는 소년에게 풍선을 선물한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03456', '이촌 한강공원', '관광지', 37.5176063, 126.992288, '서울특별시 용산구 서빙고동 287-4', '14화에서 왕자 이율(김정훈)은 왕세자 신채경(윤은혜)을 이 공원의 서쪽 끝으로 데리고 갔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03457', '운현궁', '관광지', 37.575958, 126.986991, '서울특별시 종로구 삼일대로 464', '3회에서 신채경(윤은혜) 왕세자비는 이곳에서 공주 훈련을 받고 도착한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03458', '서울시립미술관', '관광지', 37.564042, 126.97376, '서울특별시 중구 덕수궁길 61', '이 장소에서 새로운 전시회 개막식에 참석한 신채경(윤은혜) 왕세자세자와 이신세자(주지훈).', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03459', '남산공원분수대', '쇼핑', 37.554107, 126.98194, '서울특별시 중구 회현동1가 100-267', '17회에서 친한 친구와 나이트클럽에서 말다툼을 한 후 이신세자(주지훈)가 차를 몰고 공원으로 향한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03460', '씨에스호텔앤리조트', '숙박', 33.243147, 126.42002, '제주특별자치도 서귀포시 중문관광로 196', '5회에서 이신(주지훈)의 생일 파티가 이곳에서 열립니다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03461', '중문관광단지', '숙박', 33.251098, 126.43448, '제주특별자치도 서귀포시 중문동 중문관광단지', '13화에서 이신왕자(주지훈)가 제주도를 방문할 때 이 호텔에 묵는다. 신채경(윤은혜)과 태태 황후(김혜자)가 테디베어 박물관 제주를 찾았다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03462', '덕수궁', '관광지', 37.565924, 126.97501, '서울특별시 중구 세종대로 99', '1화에서 주인공인 한보름(한보름)이 여행 가이드로 일하는 메인 장소로 남자 주인공 라동길(신원호)이 이 궁의 스태프로 합류하면서 드라마가 전개된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03463', '설악한옥민박', '관광지', 38.16512, 128.55112, '강원도 속초시 상도문길 58', '5회에서 오수(조인성)는 바다에서 하룻밤을 보낸다', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03464', '사니다카페', '카페', 37.406814, 127.91437, '강원도 원주시 호저면 칠봉로 109-128', '두 달째, 오영(송혜교)이 이 카페에 온다', '강원');
