INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03466', '카페일루소', '카페', 35.1829572, 128.768384, '경상남도 김해시 대청계곡길 195-108', '오영(송혜교)이 이 카페에 온다', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03467', '디큐브시티 현대백화점', '쇼핑', 37.508892, 126.88942, '서울특별시 구로구 경인로 662', '2회에서 시각장애인 오영(송혜교)의 친구 손미라(임세미)가 오수(조인성)와 공모해 자신을 돌보게 한다 그가 영을 위해 목걸이를 사는 동안, 그녀는 미라를 기다리다가 화가 난 어머니에 의해 바닥으로 밀려난다. 지팡이를 찾으려 발버둥치던 그녀는 겨우 일어나 이 백화점 분수대에 빠진다. 여기가 수가 구조하러 오는 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03468', '송도센트럴파크', '관광지', 37.3924167, 126.639565, '인천광역시 연수구 컨벤시아대로 160', '오영(송혜교)의 형 오수(이재우)는 도박꾼 오수(조인성)와 이곳에서 만난다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03469', '일산호수공원가로수길', '관광지', 37.666173, 126.75655, '경기도 고양시 일산서구 주엽로 80', '12회에서 여하진(문가영)의 팬사인회가 펼쳐진다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03470', '청담로바', '관광지', 37.522877, 127.04213, '서울특별시 강남구 도산대로 420 청담스퀘어 타워빌딩 B동 2층 221호', '방송국에서 만난 이정훈(김동욱), 여하진(문가영), 유태은(윤종훈)은 11회에서 함께 어색한 점심을 먹는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03471', '상암문화광장', '관광지', 37.580159, 126.89138, '서울특별시 마포구 성암로 255', '여하진(문가영 분)이 자신의 영화 ''첫사랑''을 홍보하기 위해 이곳에서 팬 사인회를 열고 있다. 이정훈(김동욱 분)과 조일권(이진혁 분)이 그 지역을 지날 때 그녀를 발견한다. ', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03472', '메가박스 상암', '관광지', 37.568242, 126.89721, '서울특별시 마포구 월드컵로 240', '이정훈(김동욱)은 여하진(문가영)의 새 영화 ''첫사랑''을 보기 위해 이 영화관을 찾았다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03473', '상암월드컵경기장', '관광지', 37.568242, 126.89721, '서울특별시 마포구 월드컵로 240', '이정훈(김동욱)은 7-8화에서 여하진(문가영)의 신작 ''연구를 위한 첫사랑''을 보기 위해 이 영화관에 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03474', '사보이시티DMC', '관광지', 37.581428, 126.88862, '서울특별시 마포구 월드컵북로54길 17', '8회(전체 4회)에서 여하진(문가영)은 이 건물 밖 이 거리에서 이정훈(김동욱)을 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03475', '두텁바위로40길', '관광지', 37.547437, 126.98291, '서울특별시 용산구 두텁바위로40길', '9회(전체 5화)에서 이정훈(김동욱)이 보낸 스토커 사진을 조사하기 위해 이 골목을 걷는다.', '서울');
