INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03477', '카페진선', '카페', 37.581361, 126.98046, '서울특별시 종로구 삼청로 59', '31회(전체 16화)에서 소속사 상사를 만나기 위해 여하경(김슬기)과 함께 이 카페에 왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03478', '광화문교보빌딩', '관광지', 37.570831, 126.97783, '서울특별시 종로구 종로 1 교보생명빌딩 지하1층', '여하진(문가영)은 서점에서 만난 뒤 거리로 나선다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03479', '서울한양도성 서울성곽길 남산(목멱산)구간', '관광지', 37.564486, 127.01016, '서울특별시 중구 남창동 205-179', '이정훈(김동욱 분)과 여하진(문가영 분)은 최종회 32회에서 데이트를 위해 이곳에 오는데, 그녀는 다음에 어떤 영화 프로젝트를 선택해야 할지 그에게 의견을 물어본다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03480', '다산로33길', '관광지', 37.563689, 127.01142, '서울특별시 중구 청구로22길 36', '2회(전체 1회) 회상 장면에서는 이정훈(김동욱)이 첫사랑을 어떻게 만났는지 회상하는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03481', 'CGV 명동역 씨네라이브러리', '관광지', 37.561238, 126.98536, '서울특별시 중구 퇴계로 123', '여하진(문가영 분)이 영화 ''첫사랑''의 공동 출연자이자 감독과 함께 진행하는 기자회견은 3화에서 진행된다. 마지막 16회에서 하진은 영화 ''기억 속의 나를 찾아라''의 기자회견을 위해 이곳으로 돌아오고, 이정훈(김동욱 분)은 관객석에 앉는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03482', '레스케이프 호텔', '숙박', 37.5597171, 126.979505, '서울특별시 중구 퇴계로 67 에이케이타워 B동 지하 8층, 6~25층', '8회에서 이정훈(김동욱)과 여하진(문가영)은 정훈의 뉴스 프로그램 복귀를 축하하기 위해 김철웅(이성준)과 함께 술을 마시러 이 술집에 온다. 술에 취한 뒤 아내 최희상(장영남)이 찾아와 그를 붙잡고 정신을 차린다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03483', '주천강 섶다리', '관광지', 37.29314, 128.3256, '강원도 영월군 주천면 판운리 479', '8회에서 이 밭의 버려진 농장 옆에서 국연수(김다미)와 함께 다큐멘터리의 일부를 촬영', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03484', '라비브북스', '관광지', 37.670444, 126.77701, '경기도 고양시 일산동구 무궁화로141번길 16-7', '솔이가 연수의 집에 머물렀던 다음날, 솔이는 자신의 길을 가기 전에 연수가 최웅(최우식)을 짝사랑하고 있다고 계속 주장한다. 고민에 빠진 연수는 잠시 발길을 멈춘 채 창에 비친 거울을 거울 삼아 생각에 잠긴 채 이 서점을 향한다.', '경기');
