INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03486', '카페화홍', '카페', 37.2864611, 127.0173033, '경기도 수원시 팔달구 수원천로 369', '김다미가 아르바이트를 했던 카페', '수원');
