INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03488', '지동벽화마을', '관광지', 37.283931, 127.02399, '경기도 수원시 팔달구 창룡문로 75-5', '국연수(김다미)가 할머니 강자경(차미경)과 함께 사는 동네다. 하트 벽화 앞에서 말다툼을 벌인 최웅(최우식)은 국연수(김다미)에게 자기 집으로 와줄 의향이 있냐고 묻는다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03489', '행궁파티', '관광지', 37.285957, 127.01088, '경기도 수원시 팔달구 화서문로31번길 22', '이 곳의 외관(정원과 옥상 포함)은 1화에 등장한다.', '수원');
