INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03509', '한강대교', '관광지', 37.517492, 126.95897, '서울특별시 용산구 이촌동 한강대교', '9, 10회에서 윤수림(박수영)이 머쉬앤코 데뷔 쇼케이스 후 강한결(이현우)을 추격한 뒤 한결이 이 다리 위에서 자신이 좋아한다고 고백한다.', '서울');
