INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03519', '청운공원', '관광지', 37.5919695, 126.966814, '서울특별시 종로구 창의문로 119 청운 공원', '11회에서 김신혁(최시원)은 이 박물관에 속한 시인의 언덕이나 윤동주 언덕을 산책하며 남한을 떠나는 것에 대해 고민한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03520', 'G타워', '관광지', 37.396166, 126.63419, '인천광역시 연수구 아트센터대로 175', '이 건물은 혜진이 취업 면접을 보러 오는 1회에서 보듯 지성준(박서준), 김혜진(황정음), 김신혁(최시원)이 일하는 ''진성매거진''의 사옥으로 등장한다.', '인천');
