INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03522', '대현문화공원', '관광지', 37.557639, 126.94551, '서울특별시 서대문구 대현동 146', '5회에서 김정남(김지훈)과 그의 친구(고규필)는 정익수(형원)를 따라 이 거리로 나와 할로윈의 나머지 관중들과 어우러질 수 있도록 분장을 해보자는 생각을 갖고 있다. 이 세 사람은 하영(오하영), 잔(이현재)과 함께 아이스크림을 사기 위해 8화에서 이곳에 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03523', '63스퀘어', '관광지', 37.519811, 126.94017, '서울특별시 영등포구 63로 50', '1회에서 이은비(김소현)와 한이안(남주혁)은 이 건물 밖 공원에서 솜사탕을 산다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03524', '한강철교', '관광지', 37.51938, 126.9512, '서울특별시 용산구 이촌동 한강철교', '1회에서 정익수(몬스타엑스 형원)가 조깅을 하고 있을 때 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03525', '이태원역', '관광지', 37.534461, 126.99391, '서울특별시 용산구 이태원로 177', '1화에서 김정남(김지훈)이 이 지하철역을 향해 조깅하는 모습이 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03526', '춘천역', '관광지', 37.884608, 127.7167, '강원도 춘천시 공지로 591', '차라리(김소혜)와 미경(김우린)은 이 기차역에서 강한솔(나인우), 류하준(빅톤 임세준)을 만나기 시작한다', '강원');
