INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03530', '양재천', '관광지', 37.470194, 127.03079, '서울특별시 강남구 대치동 양재천', '4회에서는 어린이대공원에서 가짜 데이트를 한 후 성덕미(박민영)와 라이언 골드(김재욱)가 시냇물(연인의 정원)을 따라 걷는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03531', '코티레이킷 가구공방', '관광지', 37.529841, 126.84407, '서울특별시 강서구 월정로20길 96', '8회에서 최다인(홍서영)과 라이언 골드(김재욱), 성덕미(박민영)가 등장한다. ), 나무 테이블을 맞춤 제작합니다. 결국 라이언과 덕미는 식탁에서 스스로 일을 하게 되고, 다인은 함께 일하면서 둘 사이의 불꽃을 알아차린다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03532', '서울어린이대공원', '관광지', 37.548162, 127.08086, '서울특별시 광진구 능동 18', '4회에서는 이선주(박진주)가 성덕미(박민영)와 라이언 골드(김재욱)의 가짜 커플 사진을 이 공원에서 찍는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03533', '도봉탑유도관', '관광지', 37.662194, 127.02943, '서울특별시 도봉구 방학로 204 화성빌딩 3층', '남은기(안보현)의 유도 스튜디오 ''최강 유도체육관''입니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03534', '발바닥공원', '관광지', 37.65917, 127.02873, '서울특별시 도봉구 시루봉로6길 33', '11/12회에서 차시안(정제원)의 녹음실 모습으로 나온다. 서울로 돌아온 그의 어머니 공은영(이일화)도 등장한다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03535', '702 레코딩스튜디오', '관광지', 37.55355, 126.91797, '서울특별시 마포구 동교로18길 40 B1F', '마지막 16회에서 라이언 골드(김재욱)와 성덕미(박민영)가 데이트로 이 공원의 이 코너에 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03536', '경의선숲길공원', '관광지', 37.5661595, 126.919015, '서울특별시 마포구 연남동 연남로 80', '6회에서 주혁(유용민)은 이 클럽(이하 ''UG 클럽''으로 등장)에서 밴드 쇼케이스를 갖고 성덕미(박 민영), 남은기(안보현), 이선주(박진주)가 그를 응원하러 온다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03537', '웨스트브릿지 라이브홀', '음식점', 37.553666, 126.92612, '서울특별시 마포구 와우산로25길 6 웨스트브릿지 지하3층', '가구 만들기로 바쁜 하루를 보낸 성덕미(박민영 분), 라이언 골드(김재욱 분), 남은기(안보현 분), 최다인(홍서영 분)이 8회에서 이곳에서 저녁을 먹는다. 식당 밖에서 은기는 다인에게 덕미와 라이언이 지금까지 가짜 연애를 했다고 말한다.', '서울');
