INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03582', '레이지민트', '음식점', 37.386638, 127.12224, '경기도 성남시 분당구 황새울로335번길 8', '29회에서 서풍(이준호)은 단새우(정려원)의 엄마 진정혜(이미)를 만나자고 한다. 서풍(이준호)은 진정혜(이미)에게 자신의 식당에서 일을 그만두게 한 것에 대해 사과했다. 한편 그녀는 자신의 딸을 사랑하지 말아달라고 부탁한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03583', '더발렌티청담', '관광지', 37.523044, 127.05605, '서울특별시 강남구 영동대로 728', '1화에서 이 웨딩홀의 외관은 서풍(이준호)과 석달희(차주영)가 이곳에서 결혼하는 ''M타워 웨딩홀''의 외관으로도 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03584', '밤섬공원', '관광지', 37.542941, 126.93188, '서울특별시 마포구 신정동 76-1', '30회에서 오맹달(조재윤)이 채설자(박지영)의 전 애인 왕춘수(임원희)에게 주먹을 날린 후 둘 다 이 공원으로 달려와 그가 마침내 그녀에게 키스하고 그녀에게 데이트 신청을 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03585', '성수이로7길', '관광지', 37.542826, 127.05326, '서울특별시 성동구 연무장길 36', '5화에서 서풍(이준호)이 강제로 잉크를 칠하게 된 타투샵의 외관이 이 거리에 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03586', '화인빌딩', '음식점', 36.666585, 127.49326, '충청북도 청주시 청원구 충청대로 113', '칠성빌딩으로 보이는 건물은 전 조폭 두칠성(장혁)이 소유하고 있다. 1층에서 중식당 ''배고픈 프라이팬''을 운영하고 있으며 4회 말에서 셰프를 맡은 서풍(이준호)이 16회 ''배고픈 웍''으로 이름을 바꾼다.', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03587', '그랜드플라자 청주호텔', '숙박', 36.666517, 127.49441, '충청북도 청주시 청원구 충청대로 114', '드라마에서 ''자이언트 호텔''로 등장한다', '충북');
