INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03650', '소양강댐', '관광지', 37.9455, 127.81337, '강원도 춘천시 신북읍 천전리 73-18', '1회에서 수도권 호우 예보 발표 여부를 결정할 때 진하경(박민영 분)은 지도를 확대해 호우 가능성이 있는 지 살펴본다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03651', '도산대로', '관광지', 37.524475, 127.03727, '서울특별시 강남구 도산대로49길 22', '3회에서 이시우(송강)가 출근길에 나현빌딩과 베스트 웨스턴 청담 사이 이 길을 건넌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03652', '대충유원지', '관광지', 37.558708, 126.92037, '서울특별시 마포구 월드컵북로6길 37', '1화에서 진하경(박민영)과 한기준(박윤)이 아파트 분할 협상을 위해 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03653', '성북동구포국수', '음식점', 37.592385, 127.00264, '서울특별시 성북구 성북로 52-1', '이시우(송강)는 3화에서 출근길에 이 식당을 지나간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03654', '서울교', '관광지', 37.52106, 126.9165, '서울특별시 영등포구 여의도동', '2회에서 혹독한 기상예보팀장으로 취임한 첫날 이시우(송강)가 이 다리를 건너고 있다. .', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03655', '이치젠덴푸라메시 용산점', '관광지', 37.541202, 126.97382, '서울특별시 용산구 한강대로72길 11-21', '2화에서 이시우(송강)와 진하경(박민영)이 따로 술을 마시러 온 술집이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03656', '삼청동 코리아게스트 하우스', '숙박', 37.581949, 126.98208, '서울특별시 종로구 삼청로4길 12-1', '7회에서 이시우(송강)는 아버지가 모텔로 등장하는 이 게스트하우스로 데려간 어린 시절을 회상한다. 어린시절 아버지는 그에게 밖에서 기다리라고 한다. 오랜 기다림 끝에 꼬마 시우는 마침내 아버지를 찾기로 결심하고 안에서 도박을 하고 있는 아버지를 발견한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03657', '국립기상박물관', '관광지', 37.571417, 126.96625, '서울특별시 종로구 송월길 52', '마지막회, 주인공들이 복잡한 사내 연애로 흔들렸던 마음을 다시 확인하는 장소', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03658', '자하문로', '관광지', 37.594169, 126.96344, '서울특별시 종로구 자하문로 223-1', '퇴근이 늦어진 하경(박민영)은 옷가게 앞 이 거리에서 택시를 부르려고 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03659', '석파랑', '음식점', 37.59932, 126.95872, '서울특별시 종로구 자하문로 309', '이시우(송강 분)는 1회에서 여자친구 채유진(김아영/걸즈데이 유라 분)을 이 식당으로 데려온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03660', '숭례문', '음식점', 37.559956, 126.97529, '서울특별시 중구 세종대로 40', '8화에서 TQ의 두 매니저가 박현도 대표(박영규)와 계약을 해지할 예정이라 이 식당에서 기다린다. 하지만 대신 서율(이준호)이 도착해 그들에게 3년 더 계약을 연장하라고 협박한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03661', '마쯔가제', '숙박', 37.512502, 127.058796, '서울특별시 강남구 테헤란로87길 46 호텔오크우드프리미어 3층', '4회에서는 하경(남상미)이 추 감독(김원해)에게 TQ그룹 창업 이후의 고민을 묻는 식당이다. 감독님은 이실장(권혁) 때문에 묻는다면 그냥 잊어버리고 이성적이고 현실적이라고 말한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03662', '포스코타워송도', '관광지', 37.389269, 126.64424, '인천광역시 연수구 컨벤시아대로 165', '7회에서 김미소(박민영)와 나머지 경영진은 퇴근 후 이 펜션에 묵는다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03663', '헬싱키', '카페', 37.369436, 127.105564, '경기도 성남시 분당구 정자일로213번길 10', '김비서가 왜 그럴까에서 박민영이 친구를 만난 카페', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03664', '안랩 정류장', '관광지', 37.399948, 127.11046, '경기도 성남시 분당구 판교역로 220', '6회에서 이영준(박서준)은 오후 시간에 김미소(박민영)의 계획을 따랐을 때 이 버스 정류장에서 자신을 발견한다. 미소는 서울 일주 버스를 계획하고 시내를 가로질러 이동하는 길이 아니기 때문에 어쨌든 버스를 타지 않을 것이라고 그를 놀린다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03665', '더힐하우스', '관광지', 37.5055573, 127.439871, '경기도 양평군 강하면 강남로 489', '드라마 안에서 이영준(박서준) 가족의 저택으로 등장한다. 은 4화에서 이곳에서 부모님과 저녁을 먹고, 결국 형 이성연(이태환 분)과 대립하게 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03666', '꽃게마을', '음식점', 37.289304, 127.63364, '경기도 여주시 소양로 121', '김비서가 왜 그럴까에서 박서준,박민영이 간 꽃게 맛집', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03667', '플레이버', '카페', 37.321695, 127.10997, '경기도 용인시 기흥구 죽전로15번길 11-2', '김비서가 왜 그럴까에서 박민영,박병은이 간 카페', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03668', '평화로440번길', '관광지', 37.730974, 127.04953, '경기도 의정부시 평화로440번길', '3회에서 김미소(박민영)가 이성연(이태환)을 데리러 오는 길이다. 이 동네가 어린 시절 유괴당한 버려진 장소와 비슷해 기억을 되찾길 바란다고 한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03669', '3.1운동계단', '관광지', 35.8672435, 128.584875, '대구광역시 중구 동산동 881-3', '김비서가 왜 그럴까에서 박서준,박민영이 간 계단', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03670', '서문시장', '쇼핑', 35.868857, 128.580818, '대구광역시 중구 큰장로26길 45 서문시장', '김비서가 왜 그럴까에서 박서준,박민영이 간 전통 시장', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03671', '설화수 도산 플래그십 스토어', '관광지', 37.523503, 127.03546, '서울특별시 강남구 도산대로45길 18', '김미소(박민영)와 이영준(박서준) 점심을 먹으러 이 건물을 지난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03672', '라움', '관광지', 37.508252, 127.0397, '서울특별시 강남구 언주로 564', '1회에서 이영준(박서준)과 김미소(박민영)가 참석한 파티 장소다. 16화에서 건물의 일부는 마스터 디자이너(특별 게스트 이병준)의 패션 디자인 스튜디오 외부로, 영준과 미소가 웨딩 의상 피팅 약속을 했던 곳이다. 그러나 미소는 야근을 해야 했고, 영준을 기다리게 했고, 일을 마치고 달려갔지만 모든 것이 닫혀 있었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03673', '히메시야 서교직영점', '음식점', 37.55558, 126.92679, '서울특별시 마포구 와우산로29마길 7', '김비서가 왜 그럴까에서 박민영,박병은이 간 일식집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03674', '마포빈대떡', '관광지', 37.577393, 126.89533, '서울특별시 마포구 월드컵북로48길 33', '11회에서 이성연(이태환)이 이 거리를 걷다가 잠시 멈춰 섰다. 유괴 사건의 피해자는 자신이 아니라 동생 이영준(박서준)이였다는 사실을 알게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03675', '서울 국립현대미술관', '관광지', 37.579449, 126.980414, '서울특별시 종로구 삼청로 30', '김비서가 왜 그럴까에서 박서준,박민영이 간 미술관', '서울');
