INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03679', '참참참', '관광지', 35.07134, 129.066787, '부산광역시 영도구 중리북로 21', '김재환이 방문해서 재환 정식이 있는 분식집. 김영철의 동네한바퀴', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03680', '명품먹태&노가리', '음식점', 37.563075, 126.810115, '서울특별시 강서구 방화동로 26', '김재환이 워너원 데뷔 전에 알바를 한 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03681', '니가사니', '카페', 37.490666, 127.010993, '서울특별시 서초구 반포대로26길 35 1층', '김재환이 디카페인 아메리카노를 마시고 놀란 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03682', '골드마인', '카페', 37.560871, 126.92286, '서울특별시 마포구 연남로 13', '16회에서 주윤수(노종현)은 탁정은(박아인)이 이 카페(그랜드마마카페)의 창가자리에서 혼자 술을 마시는 것을 목격한다. 그는 그녀와 합류하기 위해 들어왔고 그들이 일에 대해 이야기할 때 그는 그녀에게 키스하기 위해 손을 뻗고 그녀는 보답한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03683', '일광전구 라이트하우스', '관광지', 37.472106, 126.63505, '인천광역시 중구 참외전로174번길 8-1', '3회에서 준수푸드 직원들이 동네 주민들에게 무료 라면박스를 나눠주고 있다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03684', '설악해변', '관광지', 38.131216, 128.62292, '강원도 양양군 강현면 뒷나루2길 5-8', '금잔디(구혜선)와 윤지후(김현중)는 지후의 할아버지가 함께 시간을 보내기 위해 계획하고 만난다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03685', '그리너', '관광지', 37.66716, 126.77236, '경기도 고양시 일산동구 무궁화로93번길 27', '금잔디(구혜선)의 부모인 금일봉(안석환)과 나공주(임예진)가 운영하는 드라이클리닝 배달업체 ''잔디토탈클리닝''이 이 건물에 위치하고 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03686', '닥밭공원', '관광지', 37.667733, 126.7724, '경기도 고양시 일산동구 무궁화로93번길 32', '금잔디(구혜선) 집 앞의 근린공원으로 등장한다. 금잔디(구혜선)의 퇴학 여부를 놓고 경쟁이 벌어지던 중, 구준표(이민호)가 그녀의 집 앞에 뜻밖에 도착한다. 그리고 그들은 이 놀이터에 와서 이야기하고 그는 그녀를 끌어안는다. 9회에서는 준표가 놀이터 전체를 장식하며 이벤트를 준비한 곳 이다. 그렇게 두 사람은 가까워지고 마침내 첫키스를 나눴다. 12화에서 잔디는 여기서 아버지와 마음의 대화를 나눴다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03687', '국제전시장보도육교', '쇼핑', 37.666929, 126.74945, '경기도 고양시 일산서구 대화동 2607-4', '10회에서 구준표(이민호)의 엄마 강희수(이혜영)가 금잔디(구혜선) 집안의 드라이클리닝 사업을 접은 후, 그들은 이 고가 아래에서 떡을 팔았다. 같은 에피소드에서 준표의 어머니가 자신의 회사에 있는 준표가 가족과 함께 이곳에서 일하는 금잔디(구혜선)를 볼 수 있도록 그녀의 운전사를 지나게 하는 곳이기도 하다. 준표는 잔디와 합류하기 위해 차에서 내려 키스를 한다. 잠시 후 두 사람은 이 고가도로를 건너며 어머니 때문에 절대 헤어지지 않겠다고 약속한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03688', '일산서구청사거리', '쇼핑', 37.67543, 126.74932, '경기도 고양시 일산서구 중앙로 1547', '15회에서 금잔디(구혜선)는 이 사거리를 지나 구준표(이민호)를 본다. 이 갈림길 한쪽에 있는 가게의 텔레비전 화면에서 그들의 최근 이별이 진정으로 스며든다. 여기에서 준표의 여동생이 차를 몰고 잔디를 알아보고 멈춰 서서 그녀를 자기 집으로 초대한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03689', '서울 동작구 단독주택', '관광지', 37.510186, 126.95497, '서울특별시 동작구 노량진로26길 32-24', '18회에서 금잔디(구혜선)는 동생 금강산(박지빈)과 함께 이 건물의 옥상으로 이사를 하며 19회까지 머물게 된다. 18화에서 구준표(이민호)는 바로 옆 옥상으로 이사를 온다. 19화에서는 건물이 무너져 예고 없이 이곳을 떠난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03690', '휘닉스제주 섭지코지', '음식점', 33.429078, 126.93397, '제주특별자치도 서귀포시 성산읍 섭지코지로 107', '21회에서 금잔디(구혜선)에게 이 식당을 찾아오게 하고, 그는 구준표(이민호)와 하재경(이민정)의 결혼을 막을 수 있는 마지막 기회라고 주장하면서도 자신의 우정을 쌓아 행복해질 수 있다고 말한다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03691', '독립기념관', '관광지', 36.783538, 127.2232, '충청남도 천안시 동남구 목천읍 삼방로 95', '금강산(박지빈)이 누나 금잔디(구혜선)를 찾아 F4 멤버들을 찾는 곳으로, 1회에서 ''우송박물관''으로 등장한다. 이 박물관은 F4 멤버 소이정(김범)의 할아버지인 독립운동가 소윤허가 소장한 문화재를 전시하고 있다고 설명한다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03692', '운정호수공원', '관광지', 37.71896, 126.7552, '경기도 파주시 경의로 1151', '13회에서 강민주(김희애)와 고상식(지진희)이 이곳에서 산책을 한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03693', '알로하서프', '카페', 37.635477, 129.044679, '강원도 강릉시 옥계면 헌화로 221-4', '4회에서 한소연(고성희)은 하우스메이트인 유람(강승현)과 짧은 여행을 떠난다. 그들은 이 카페에 와서 어울리고 사진을 찍는다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03694', '광교푸르지오월드스퀘어', '관광지', 37.29246, 127.04789, '경기도 수원시 영통구 센트럴타운로 107', '1회에서 고유진(최여진)이 수상한 남자들에게 쫓기는 동안 AI 홀로그램 홀로(윤현민)는 한소연(고성희)이 그들을 지나치는 것을 알아차린다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03695', '사심가득', '카페', 37.545845, 126.94506, '서울특별시 마포구 백범로24길 11-3', '1회에서 한소연(고성희)은 가방에 넣은 안경을 발견하고 커피를 사러 이 카페에 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03696', '정심이네', '음식점', 37.562856, 126.91469, '서울특별시 마포구 월드컵북로16길 7', '11회에서 식사를 위해 한소연(고성희) 어머니의 식당으로 소연이 고난도(윤현민)를 데려온다. 이곳에서 그는 어렸을 때 그를 돌보던 어머니와 재회한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03697', '에코넷센터', '관광지', 37.545065, 127.05271, '서울특별시 성동구 아차산로 78', '1회에서 고난도(윤현민)는 오토바이를 타고 이 터널을 통과한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03698', '자하문터널', '카페', 37.593405, 126.96375, '서울특별시 종로구 부암동 자하문로', '진정이 된 후 흠뻑 젖은 한소연(고성희)은 AI 홀로그램 홀로(윤현민)를 옆에 두고 이 카페 문앞에 앉아 명상을 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03699', '르풀', '관광지', 37.566088, 126.97223, '서울특별시 중구 정동길 33', '이 장소는 1화에서 보듯 강준혁(성훈)의 소속사 ''옥수수 엔터테인먼트''의 본사로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03700', 'JCC 아트센터', '관광지', 37.5871723, 127.001881, '서울특별시 종로구 창경궁로35길 29', '1회에서 강아름(유인나)과 전지훈(문정혁)은 이혼 후 이 교회에서 처음으로 재회한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03701', '천호대교', '관광지', 37.542878, 127.11222, '서울특별시 송파구 풍납동 천호대교', '15회에서 한 제보자가 전지훈(문정혁)과 동행, 강아름(유인나)의 발치에서 증거를 얻는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03702', '유엔빌리지길', '관광지', 37.533436, 127.01244, '서울특별시 용산구 유엔빌리지길', '8회에서 전지훈(문정혁)은 이 거리에 세워둔 자전거에 앉아 생각에 잠겼다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03703', '무원마을단독주택단지', '관광지', 37.61643, 126.83395, '경기도 고양시 덕양구 행신동 무원마을단독주택', '이채록(송강)과 심덕출(박인환)이 훈련을 받기 위해 기승주(김태훈)의 댄스 스튜디오를 오가는 버스를 타는 정류장이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03704', '에어플레인모드', '관광지', 37.557677, 126.93866, '서울특별시 서대문구 연세로4길 36 2,3층', '심덕철(박인환)은 2회부터 나빌레라의 이 공원에서 정기적으로 훈련을 받는다. 4화에서 조카에게 차를 선물하는 것, 8화에서 이채록(송강)을 처음 알아보지 못하는 것, 11화에서 양호범(김권)과 친분을 쌓고 그가 정상 궤도에 오를 수 있도록 응원하는 것도 여기에 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03705', '자매근린공원', '관광지', 37.517512, 126.93019, '서울특별시 영등포구 여의대방로 372-1', '3회에서 이채록(송강)은 이 아파트에 산다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03706', '두손빌딩', '관광지', 37.414305, 126.67569, '인천광역시 연수구 청능대로 93', '2회에서 기승주(김태훈)의 댄스 스튜디오가 있던 곳으로, 이채록(송강)과 심덕출(박인환)이 있는 곳으로 등장한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03707', '잉글랜드돈까스', '음식점', 37.4742001, 126.6309821, '인천광역시 중구 우현로90번길 7 혜성빌딩 2층', '6화에서 심덕출(박인환)과 최해남(나문희)이 결혼기념일에 이 식당에서 외식을 했다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03708', '당진문예의전당', '관광지', 36.890144, 126.63795, '충청남도 당진시 무수동2길 25-21', '1회에서 이채록(송강)과 심덕출(박인환)이 이 장소에서 백조의 호수를 지켜보고 있다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03709', '오봉산 마당바위', '관광지', 35.853269, 129.05014, '경상북도 경주시 서면 천촌리', '1회에서 서휘(양세종)와 남선호(우도환)가 1388년 어린 시절 이 절벽에서 겨루는 장난을 회상한다.', '경주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03710', '영주 무섬마을', '관광지', 36.732678, 128.62112, '경상북도 영주시 문수면 무섬로 238-2', '3화에서 한희재(설현)가 이 마을의 통나무 다리를 건넌다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03711', '나주영상테마파크', '관광지', 34.979823, 126.60098, '전라남도 나주시 공산면 덕음로 450', '2화에서 나오는 군대 선발 시험이 이곳에서 치뤄진다 최종 상대는 서휘(양세종)와 남선호(우도환)로, 후자가 승리한다', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03712', '성흥산 사랑나무', '관광지', 36.1971825, 126.898347, '충청남도 부여군 임천면 성흥로97번길 167', '서휘(양세종)와 한희재(설현)는 제2화에서 서휘의 여동생 서연(조이현)이 궁남지에서 날리다 잃어버린 연을 찾다가 이 나무로 오게 된다. ', '충남');
