INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03714', '코주방', '관광지', 37.668731, 126.774952, '경기도 고양시 일산동구 대산로11번길 5-20', '극 중에서 아이유와 이선균이 자주 가는 술집', '경기');
