INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03716', '세종빌딩', '관광지', 37.297487, 127.4389, '경기도 이천시 증신로 303', '이곳은 형제청소방, 박상훈(박호산)과 박기훈(송새벽) 형제가 운영하는 청소업체 사무실이 있는 곳이다.', '경기');
