INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03718', '퀴즈노스 압구정점', '관광지', 37.52497, 127.02457, '서울특별시 강남구 압구정로 144', '11회에서 이지안(아이유)은 이 곳에서 친구 송기범(안승균)을 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03719', '우덕빌딩', '관광지', 37.513209, 127.01979, '서울특별시 서초구 강남대로 577', '박동훈(이선균)이 근무하는 엔지니어링 회사, 삼안건설 사옥의 외관이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03720', '신정네거리역', '관광지', 37.520098, 126.85293, '서울특별시 양천구 중앙로 261', '7회에서 박동훈(이선균)과 이지안(아이유)이 하차하는 가상의 후계역이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03721', '샛강다리', '관광지', 37.518835, 126.91898, '서울특별시 영등포구 여의도동 39', '박동훈(이선균), 박상훈(박호산), 박기훈(송새벽) 에피소드에서 이 다리 발치에 있는 텐트 바에서 한 잔 한다.', '서울');
