INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03723', '친니', '음식점', 37.572422, 126.976006, '서울특별시 종로구 세종대로 175', '8회에서 상무로 올라가자고 말한 장면인 중식당', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03724', '남산육교', '관광지', 37.557166, 126.97634, '서울특별시 중구 남창동', '9회에서 이지안(아이유)은 박동훈(이선균)과 광일(장기용)의 말다툼을 엿듣고 이 고가도로에서 눈물을 흘린다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03725', 'VIP참치 코리아나호텔점', '숙박', 37.568138, 126.976674, '서울특별시 중구 세종대로 135', '9회에 3형제가 참치 먹은 참치집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03726', '시그니쳐타워', '카페', 37.567606, 126.98844, '서울특별시 중구 청계천로 100 시그니쳐타워 1층', '16회에서 이지안(아이유)은 동료들과 함께 여기에 온다. 카페에 가던 중 우연히 박동훈(이선균 분)과 같은 소리를 하는 사람을 보고 확인하러 올라갔다. 그리고 둘은 1년 만에 서로를 보고 유쾌하게 놀란다. 그들은 카페 밖에서 대화를 나누며 헤어진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03727', '남산 육교', '관광지', 37.557538, 126.976379, '서울특별시 중구 퇴계로 33', '9회에서 아이유가 도청하며 이동하다 오열하는 장소', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03728', '정수사', '관광지', 37.607657, 126.445211, '인천광역시 강화군 화도면 해안남로 1258번길 142', '이선균의 친한 친구인 박해준이 지내는 절', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03729', '정희네', '음식점', 37.482784, 126.61909, '인천광역시 동구 만석동 제물량로341번길 43', '소꿉친구인 정희(오나라)가 운영하는 술집으로 자연스럽게 그 장소는 그녀의 이름을 따서 명명되었다. 그녀는 위층에 머물며 낮에는 박형제의 어머니(고두심)가 일하는 곳이기도 하다. 15회에서는 박동훈(이선균)이 중상을 입은 이지안(아이유)을 이곳으로 데려오고, 정희는 그녀를 기꺼이 받아들인다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03730', '한촌설렁탕 학익점', '음식점', 37.441812, 126.66679, '인천광역시 미추홀구 소성로 166-1', '16회에서 사임 가능성에 대해 이야기했지만, 동훈에게 ''지기 싫다''는 이유로 재검토를 요청한다. 대표이사는 도준영 사장(김민영)과 동훈의 아내(이지아)의 불륜을 알게 됐다고 털어놨다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03731', '자미궁 제빵소', '카페', 37.595838, 126.6944, '인천광역시 서구 원당대로819번길 38', '1회에서 회사 볼링 동호회가 끝난 뒤 동호회 회원들이 이 식당에서 저녁식사를 하는 모습이 그려졌다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03732', '플레이그라운드 브루어리', '카페', 37.667695, 126.70203, '경기도 고양시 일산서구 이산포길 246-11', '8회에서 염기정(이엘)이 니바르나의 네버마인드 음반을 건네주기 위해 이 카페에서 조태훈(이기우)을 만났다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03733', '하우애니', '관광지', 37.580547, 126.98667, '서울특별시 종로구 계동길 73-1', '염미정(김지원), 염창희(이민기), 염기정(이엘) 3남매가 서울로 이사온 후 사는 곳이다. 15,16회에서 볼 수 있듯이 7호에 산다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03734', '옥인 연립', '관광지', 37.582256, 126.96425, '서울특별시 종로구 옥인길 82', '15회에서 염창희(이민기)는 자전거를 타고 이 거리의 도서관에 책을 반납한다.', '서울');
