INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03745', '소리가있는동네', '관광지', 37.656963, 126.76992, '경기도 고양시 일산동구 중앙로1261번길 79 하이베라스 2층', '3회에서 마동찬(지창욱분)과 나하영(윤세아분)이 20년만에 다시만나는 곳이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03746', '포천아트밸리', '관광지', 37.9233996, 127.237461, '경기도 포천시 신북면 아트밸리로 234', '2회에서 오영선(송지은)과 박경자(오하늬)는 고미란(원진아)과 함께 대학 시절 학창 시절을 회상한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03747', '동아디지털미디어센터', '관광지', 37.57832, 126.89285, '서울특별시 마포구 매봉산로 75', '고미란(원진아)과 그녀의 가족은 공원 근처에서 생선구이를 하고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03748', '반포한강공원', '관광지', 37.510507, 126.996054, '서울특별시 서초구 신반포로11길 40', '4회에서 고미란(원진아) 동생 고남태가 그녀를 이 탑의 발치로 데려와 지난 20년간 서울이 얼마나 달라졌는지 보여준다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03749', '롯데월드몰', '쇼핑', 37.512599, 127.102714, '서울특별시 송파구 올림픽로 300', '10화에서 운성회장(김법래)은 황갑수 교수가 아직 살아있다는 정보를 이 건물 옥상에서 입수한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03750', '여의도 금호 리첸시아', '관광지', 37.51852, 126.9397, '서울특별시 영등포구 여의동로 213', '2회에서 마동찬(지창욱)과 고미란(원진아)이 2019년 처음 서울을 재발견한 곳은 바로 이 공원 앞 산책로이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03751', '도원경로당', '쇼핑', 37.293818, 128.24227, '강원도 영월군 무릉도원면 도원안길 19-1', '10회에서 굿나잇 서점 벼룩시장이 열린다. 14회에서는 봄이 오는 것을 축하하기 위해 매년 혜천 떡 축제가 열린다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03752', '도원운학로', '관광지', 37.291724, 128.24224, '강원도 영월군 무릉도원면 도원운학로 255-9', '굿나잇서점 북클럽 회원들과 북현 마을 사람들은 보통 이 길을 다닌다. 또한 이 거리에는 마을버스 정류장 북현삼거리가 있다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03753', '중앙서점', '관광지', 37.182994, 128.46867, '강원도 영월군 영월읍 하송안길 112', '박힌돌(윤상화 분)이 운영하는 ''산들서점''으로 등장한다. 5회에서 임은섭(서강준)은 책을 사러 왔다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03754', '도천마을', '관광지', 37.289395, 128.23141, '강원도 영월군 주천면 도천리 625', '임은섭(서강준)의 비밀장소 숲속 오두막은이 마을의 숲에 있으며 이 마을은 목해원(박민영)이 생을 마감하기 위해 마을에 온 것처럼 어두운 삶의 배경이기도 하다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03755', '제장마을', '관광지', 37.259049, 128.58384, '강원도 정선군 신동읍 제장길 1-38', '3회에서 ''혜천역''으로 나오는 역이다. 심명녀(문정희)와 차윤택(황건)이 만나 명녀가 윤택과 헤어진 이유를 다시 이해해보는 곳이기도 하다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03756', '청춘수산', '관광지', 37.411275, 127.26072, '경기도 광주시 광주대로 52 1층', '11회에서 임은섭(서강준)과 목해원(박민영)과 함께 공원에 오고 그녀는 그에게 자신의 과거를 이야기한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03757', '환벽정', '관광지', 36.750742, 127.83656, '충청북도 괴산군 칠성면 사은리', '이장우(이재욱)와 동료 공무원들은 2020년 새해를 맞아 이 정자까지 하이킹을 한다. 8회에서 임은섭(서강준)과 목해원(박민영)이 처음으로 키스하는 곳이기도 하다.', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03758', '심곡항', '관광지', 37.665245, 129.053082, '강원도 강릉시 강동면 심곡리 157-1', '남자친구에서 박보검이 혼자 간 항구', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03759', '라라무리', '관광지', 37.856793, 128.8181, '강원도 강릉시 연곡면 진고개로 2551-18', '4화에서 차수현(송혜교)을 데리고 커피를 마시러 왔다가 서울에서 여기까지 오면서 그녀의 어깨 위에서 거의 바로 잠이 든다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03760', '외옹치 바다향기로', '관광지', 38.181699, 128.610715, '강원도 속초시 대포동 712', '남자친구에서 송혜교, 박보검이 만난 산책로', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03761', '롯데리조트 속초', '숙박', 38.180679, 128.61177, '강원도 속초시 대포항길 186', '3회에서 이 호텔은 차수현(송혜교)이 묵고 김진혁(박보검)을 만나는 동화호텔 속초점으로 등장한다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03762', '풍경 카페', '카페', 37.38469, 126.8338, '경기도 시흥시 동서로 786', '8회에서 김진혁(박보검)과 차수현(송혜교)이 이별하고 속초로 가기전 이곳에서 데이트를 하는 모습이 그려졌다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03763', '현담원빌딩', '관광지', 37.526357, 127.03394, '서울특별시 강남구 언주로168길 6', '3회에서 겁에 질린 차수현(송혜교)은 술집에서 전남편 정우석(장승조)을 만나 엄마의 재혼 음모를 막고 무고한 직원 김진혁(박보검)의 명예를 훼손하지 말라고 경고한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03764', '커피베이 가산직영점', '카페', 37.477513, 126.88515, '서울특별시 금천구 벚꽃로 254', '11회에서는 차수현(송혜교)과의 관계를 걱정하는 아버지 김장수(신정근)와 함께한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03765', '고고네닭도리탕', '음식점', 37.541545, 126.940417, '서울특별시 마포구 마포대로1길 46', '남자친구에서 박보검, 고창석이 식사한 식당', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03766', '카페 웍소베러 잔다리 (구 카페 요호) ', '카페', 37.555202, 126.915761, '서울특별시 마포구 잔다리로 88', '남자친구에서 송혜교, 김호창이 만난 카페', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03767', '1953연남서서갈비', '음식점', 37.553296, 126.90334, '서울특별시 마포구 희우정로 84', '5회에서 차종현(문성근)은 오랜 친구이자 운전사 남명식(고창석)과 함께 술 한 잔을 하게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03768', '홍남교', '관광지', 37.574984, 126.92529, '서울특별시 서대문구 남가좌동 홍남교', '5화에서 김진혁(박보검)이 차수현(송혜교)을 데리고 산책을 온다. 수현은 진혁이가 어떻게 미술 전시회를 보고 싶다고 말했는지에 대해 크게 궁금해했고, 그는 그녀에게 다리 자체에 미술 전시회가 있다는 것을 보여주었다. 속았다고 주장하면서도 ''홍제동 도감''이 길을 따라 다양한 예술 작품을 계속 설명하자 수현은 진혁의 뒤를 따랐다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03769', '담산 신촌본점', '음식점', 37.5562114, 126.9350443, '서울특별시 서대문구 연세로5다길 5 1층', '남자친구에서 고창석, 김혜은이 간 식당', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03770', '롯데 시그니엘', '숙박', 37.512599, 127.102714, '서울특별시 송파구 올림픽로 300', '10회에서는 김진혁(박보검)이 차수현(송혜교)에게 속초호텔로 보내졌다는 사실을 알게 된 정우석(장승조)이 전처 수현에게 구애하기 위해 ''꽃의 바다'' 캠페인을 펼친다. 그를 거절하기 위해 수현은 일부러 그를 이곳 ''스카이바''에서 몇 시간 동안 기다리게 한다.', '서울');
