INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03774', '아델라베일리', '음식점', 37.595135, 126.97005, '서울특별시 종로구 북악산로 48', '7회에서 정우석(장승조)과 여자친구 수아(장희령)가 이곳에서 식사를 합니다.', '서울');
