INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03782', '웰컴투동막골마을', '관광지', 37.31385, 128.470814, '강원도 평찬군 미탄면 동막골길 122', '남한산성을 촬영한 테마공원', '강원');
