INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03788', '킹스백바버샵', '관광지', 37.384442, 127.11108, '경기 성남시 분당구 판교역로2번길 9-1', '6회에서부터 유지연(임세미)이 이끄는 국정원 ''왕의 가방'' 작전센터가 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03789', 'KT&G서울사옥', '관광지', 37.506558, 127.06523, '서울특별시 강남구 영동대로 416', '이것은 ''J 인터내셔널''이 29층에 사무실을 둔 ''스타 타워'' 빌딩이다. 16회에서는 J인텔 대표 진용태(손호준)가 살인범에게 쫓기며 이 건물을 뛰쳐나오고, 이후 김본(소지섭 분)이 모래시계를 가지러 이곳에 오다가 국정원 요원들에게 쫓기는 장면이 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03790', '더스토리', '관광지', 37.56382, 126.92431, '서울특별시 마포구 성미산로32길 12', '26회에서 김본(소지섭)이 이 곳을 지나간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03791', '평강랜드', '관광지', 38.04957, 127.3039, '경기도 포천시 영북면 우물목길 171-18', '5회에서 이 식물원은 봉영규(정보석)가 일하는 ''예술정원''으로 등장한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03792', '원방빌딩', '카페', 37.526193, 127.03838, '서울특별시 강남구 선릉로157길 18 1~3층', '5화에서 차동주(김재원)가 해외여행을 마치고 서울을 돌아다닐 때 자전거를 타고 이 카페를 지나간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03793', '용평리조트', '숙박', 37.645009, 128.68297, '강원도 평창군 대관령면 올림픽로 715', '강미래(임수향 분), 도경석(아스트로 차은우 분), 현수아(조우리 분)가 화학 전공자로 등록하고 연우영(곽동연 분)이 조교로 활동하는 곳이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03794', '장안공원', '카페', 37.287854, 127.01272, '경기도 수원시 장안구 영화동 349-86', '3회에서 현수아(조우리)는 이 카페에서 아르바이트를 하고 있다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03795', '카페온더플랜 건대점', '카페', 37.545151, 127.07281, '서울특별시 광진구 능동로 161 1~2층', '12회에서 이곳의 버스를 기다리던 강미래(임수향)에게 도경석(아스트로 차은우)이 오더니 그냥 지나친다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03796', '신세계센트럴시티', '관광지', 37.5043439, 127.003599, '서울특별시 서초구 신반포로 176', '1회에서 강미래(임수향)가 아틀리에 코롱 강남점을 찾는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03797', '킨텍스제1전시장', '쇼핑', 37.669337, 126.746033, '경기 고양시 일산서구 킨텍스로 217-60', '차대웅(이승기)이 구미호(신민아)를 처음 만나는 곳이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03798', '코엑스 아쿠아리움', '관광지', 37.510177, 127.05866, '서울특별시 강남구 영동대로 513', '15회에서 현진헌(현빈)은 김삼순(김선아), 현미주(서지희)를 이곳에 데려간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03799', '주문진등대', '관광지', 37.897611, 128.83394, '강원도 강릉시 주문진읍 옛등대길 24-7', '16회에서 오예지(임수향)는 그녀의 삶을 회상하기 위해 이 등대에 온다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03800', '경강역 (폐역)', '관광지', 37.842858, 127.55054, '강원도 춘천시 남산면 서백길 62-52', '4회에서 서진(하석진)이 오예지(임수향)에게 프러포즈하는 장면이 나온다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03801', '파머스빌리지 플러스', '카페', 37.727889, 127.03576, '경기도 의정부시 범골로35번길 78', '13회에서 서환(지수)과 엠버(스테파니리)는 이 카페에서 헤어진다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03802', '루비나빌딩', '관광지', 37.523935, 127.0479, '서울특별시 강남구 도산대로 502', '2회에서 캐리정(황승언)이 이 술집에서 친구들을 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03803', '방주교회', '관광지', 33.30507, 126.3875, '제주특별자치도 서귀포시 안덕면 산록남로762번길 113', '남편 서진(하석진)이 실종된 지 3년 만에 오예지(임수향)는 6~7회에서 신혼여행지인 제주도로 돌아가 이 예배당을 비롯해 그들이 함께 했던 모든 장소로 돌아간다. 서환(지수)이 미국에서 날아온 뒤 처제가 걱정돼 그녀를 발견한 곳이다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03804', '비밀의숲', '관광지', 33.453582, 126.75564, '제주특별자치도 제주시 구좌읍 송당리 2173', '6회에서 오예지(임수향)는 이 숲길을 걷는다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03805', '그시절그바다', '관광지', 33.533586, 126.84001, '제주특별자치도 제주시 구좌읍 해맞이해안로 1178', '6,7회에서는 남편 서진(하석진)이 실종된 지 3년 후 신혼여행지 제주도로 돌아온 오예지(임수향)의 모습이 그려졌다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03806', '김녕해수욕장', '관광지', 33.557718, 126.75956, '제주특별자치도 제주시 구좌읍 해맞이해안로 7-6', '오예지(임수향)는 6회에서 제주도에 머무는 동안 산책로 playground ''오예지''에 찾아와 그리운 남편과 이곳에서 함께했던 시간들을 추억한다. 7화에서 제주도 예지를 깜짝 방문한 서환(지수)은 낚시를 하자고 제안하고 두 사람은 이 해변으로 오게 된다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03807', '북촌로5가길', '관광지', 37.580327, 126.98237, '서울특별시 종로구 북촌로5가길 12-7', '2회에서 공아정(윤은혜)이 이 거리를 걷다가 자신을 따라온 현상희(성준)의 발을 멈추게 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03808', '베어트리파크', '관광지', 36.670592, 127.209267, '세종특별자치시 전동면 신송로 217', '이 공원은 현명진(오미희)의 맨션으로 나온다.', '세종');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03809', '마포공덕시장', '쇼핑', 37.545069, 126.953344, '서울특별시 마포구 만리재로 19', '안상구가 옥상에서 라면을 먹은 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03810', '운보의집운보미술관', '관광지', 36.692197, 127.5651, '충청북도 청주시 청원구 내수읍 형동2길 92-41', '6회에서 이 집에는 한국전쟁 참전용사 이영천(전무송)이 살고 있다.', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03811', '이화벽화마을', '관광지', 37.578224, 127.008009, '서울특별시 종로구 낙산성곽서1길 28', '1화에서 옥황상제(김해숙)가 아침 정기점검차 이곳을 지나가는 장면이 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03812', '백사마을', '관광지', 37.642741, 127.08542, '서울특별시 노원구 중계본동 104-3', '4회에서는 최준웅(김석우/SF9 로운)과 임륭구(윤지온)가 강우진의 사건을 해결하기 위해 연이어 찾아온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03813', '서울책보고', '관광지', 37.522281, 127.104097, '서울특별시 송파구 오금로 1', '4회에서 싱어송라이터 강우진(강승윤)과 허나영(이노아)이 사는 곳으로 최준웅(로운)과 임령구(윤지온)가 강우진의 사건을 해결하기 위해 연이어 찾아온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03814', '소월로 계단 2번', '관광지', 37.54812, 126.98417, '서울특별시 용산구 두텁바위로60길 79', '4회에서 이상엽 마푸구청장 일행이 허나영(이노아)을 찾기 위해 이 계단을 걸어 내려가고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03815', '등대사진관', '관광지', 37.524863, 126.96035, '서울특별시 용산구 이촌로29길 29 1층', '6회 에필로그에서 최준웅(로운)은 한국전쟁 참전용사 이영천(전무송)을 데리고 이 스튜디오로 나와 사진을 찍는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03816', '효자로', '관광지', 37.57934, 126.9738, '서울특별시 종로구 효자로 37', '9회에서 저승사자 임령구(윤지온)가 길 건너편에서 임산부를 지켜보는 장면이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03817', '브롱스 동여의도점', '관광지', 37.5196839, 126.929258, '서울특별시 영등포구 여의대방로65길 17', '27회에서는 강하니(서인아 분)가 이 주점에서 이한결(진주형 분), 황지은(하승리 분)과 만나 이야기를 나눈다. 하니는 술이 너무 많아 박도경(이창욱 분)이 도착하자마자 한결과 티격태격하게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03818', '세라믹팔레스홀', '관광지', 37.485848, 127.08239, '서울특별시 강남구 일원로 90', '한음음대 콘서트홀 중 하나이다. 12회, 13회에서 설내일(심은경)은 이 홀에서 열린 피아노 리사이틀 준결승과 결승에 진출했고 유진(주원)과 윤후(박보검)가 응원하러 왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03819', '카페드롭탑 홍대점', '카페', 37.549298, 126.92054, '서울특별시 마포구 어울마당로 45-1', '유진(주원) 엄마 카페의 배경이 되었다. 외관은 원래 매장의 모습이지만 매장 내부는 세트장에서 촬영되었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03820', '아임홈 백현점', '관광지', 37.383999, 127.111384, '경기도 성남시 분당구 판교역로10번길 3-1', '1회에서 시신이 실린 파손된 자동차와 검은 고양이가 이 자리에 주차되어 있는 모습이 목격된다', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03821', '김천 한국보건대 (폐교)', '관광지', 36.174427, 128.10956, '경상북도 김천시 어모면 옥율1길 94', '6화 이후 눈은 사람에게 미친 짓을 할 구실을 준다고 생각한 강다정(서현진 분)과 주영도(김동욱 분)는 한복 대여점에서 의상을 빌려 입고 거리를 누빈다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03822', '삼청도도한복', '카페', 37.57988, 126.9819, '서울특별시 종로구 북촌로5길 56', '25회에서 남신3(서강준)과 인간 남신(서강준)은 카페 ''채소'' 밖에서 마주친다. 강소봉(공승연)이 안에서 기다리고 있는 모습이 나온다. 이후 남신3은 소봉의 눈을 사로잡았고, 그녀는 카페 발코니에서 소봉에게 말을 건다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03823', '백현동카페거리', '카페', 37.385271, 127.11082, '경기도 성남시 분당구 백현동 567-1', '18~19회에서 서예나(박환희)와 남신3세(서강준)의 결혼식이 치러질 예정인 곳이다. 남신3세가 강소봉(공승연)을 구하기 위해 떠나는 곳.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03824', '조이스커피숍', '카페', 36.603148, 127.29702, '경상북도 경주시 안강읍 안현로 1536', '강소봉(공승연)의 아버지 강재식(김원해)과 그의 두 연습생은 이 카페에서 자신과 남신Ⅲ(서강준)의 관계를 묻는다. ', '경주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03825', '엘리자베스 럭스', '관광지', 37.524171, 127.04192, '서울특별시 강남구 선릉로152길 30 써니빌딩 4층', '15회에서 서예나(박환희)와 로봇 남신Ⅲ(서강준)가 웨딩드레스를 보러 오는 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03826', '복고포차 달동네 문래역점', '관광지', 37.517425, 126.8964798, '서울특별시 영등포구 당산로 34', '11회에서 강소봉(공승연)은 남신Ⅲ(서강준)를 바라보며 식사를 하고 있다. 아줌마는 남신Ⅲ를 초대해달라고 소봉에게 잔소리를 하지만 그녀는 식사를 계속한다. 비가 내리기 시작하고 소봉은 도망치려 하지만 남신Ⅲ는 소봉을 보호하기 위해 우산을 들고 돌아온다. 식당 밖 소봉은 자신의 ''로봇노예''가 되겠다고 말했고, 소봉은 일찍이 청혼을 거절하는 것을 도왔기 때문에 이에 동의한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03827', '기계산업진흥회 (구 기계회관 본관)', '관광지', 37.529414, 126.9226, '서울특별시 영등포구 은행로 37', '강소봉(공승연 분)이 이곳에서 지영훈(이준혁 분)을 만난다. 그녀에게 회장이 로봇으로서 남신Ⅲ(서강준)의 진정한 정체성을 알고 있다고 말한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03828', '큐엘엘에스', '관광지', 37.583689, 126.96897, '서울특별시 종로구 필운대로 108-6', '오로라(김성령)와 데이비드(최덕문)가 혼수상태에 빠진 인간 남신(서강준)을 돌보기 위해 머무르는 은신처', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03829', '호수1교', '관광지', 37.394678, 126.63407, '인천광역시 연수구 송도동', '남신Ⅲ(서강준)는 오토바이를 타고 이 다리를 건너 납치된 강소봉(공승연)을 구한 후 서종길의 에이전트(최병모)를 쫓게 된다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03830', '컨벤시아대로', '관광지', 37.392001, 126.64628, '인천광역시 연수구 컨벤시아대로', '남신Ⅲ(서강준)은 19회에서 납치당한 강소봉(공승연)을 구한 뒤 이 거리에서 서종길의 에이전트(최병모)를 쫓는다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03831', '오라카이 송도파크호텔', '숙박', 37.38809, 126.6408, '인천광역시 연수구 테크노파크로 151', '17회에서 오로라(김성령)가 묵는 호텔이다. 지영훈(이준혁)은 서종길의 스파이가 자신을 호텔까지 미행한 사실도 모르고 남신Ⅲ의 행동에 대해 이야기하기 위해 찾아온다. 이후 로라는 택시를 타고 강소봉(공승연)을 만나기 위해 호텔을 나선다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03832', '미추홀공원', '관광지', 37.382276, 126.649461, '인천광역시 연수구 해송로59', '18회에서 (공승연)이 자전거를 탄 후 남신Ⅲ(서강준)와 전화통화를 하고 있다. ''노예로 돌아가라''고 지영훈(이준혁)과 오로라(김성령)의 말을 듣고 다시는 만나지 않겠다고 한다. 잠시 후 남신Ⅲ는 소봉에게 어머니의 목걸이를 건네주고 마지막 작별인사를 하기 위해 번화한 길을 건너 소봉에게로 간다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03833', '십리포해수욕장', '관광지', 37.281354, 126.48367, '인천광역시 옹진군 영흥면 영흥북로 420-26', '36화 마지막회에서 강소봉(공승연)이 로봇 마이보와 함께 남신Ⅲ(서강준)에게 마지막 작별을 고한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03834', '삼청로', '관광지', 37.582943, 126.98193, '서울특별시 종로구 삼청로 84-1', '1회에서 차지안(장나라)은 이 거리를 따라 택시를 탄 이현(서인국)을 쫓는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03835', '또이마켓', '카페', 37.507667, 126.74938, '경기도 부천시 길주로77번길 19-45 디아뜨갤러리4 1층 109호', '주영(신혜지)이 일하는 카페다. 4화에서 희주(고현정)는 리사(김수안)에게 고장난 후 7화에서 주영을 만나 새 전화기를 선물한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03836', '동백아펠바움', '관광지', 37.26762, 127.1576, '경기도 용인시 기흥구 동백2로32번길 7-16', '이 단지의 입구는 드라마 안에소 안현성의 가족주택이 위치한 주택단지 ''산정''의 일부로 등장한다. 3회에서 희정(고현주)과 해원(신현빈)이 설전을 벌인 장면 볼 수 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03837', '서울한우곰탕', '음식점', 37.557258, 126.91683, '서울특별시 마포구 월드컵북로5나길 18', '1회에서는 정선우(신동욱 분)와 조카 안리사(김수안 분)가 이 식당에서 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03838', '뇨끼바', '관광지', 37.535001, 127.00949, '서울특별시 용산구 한남대로20길 41-4', '신혼부부 정희주(고현정)와 안현성(최원영)의 집이 있는 곳이다. 현성의 어머니 박영선 김보연 분과 여동생 안민서(장혜진 분)는 남편 이형기(홍서준 분)와 함께 같은 주택단지다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03839', '인천건재', '관광지', 37.480242, 126.64303, '인천광역시 동구 안송로 109', '1회에서 해원(신현빈)이 집으로 돌아가는 길에 터널을 걷고 있다', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03840', '도원보행자터널', '관광지', 37.471426, 126.63698, '인천광역시 중구 참외전로 191', '6화에서 봤던 희주(고현정)와 우주(김재영)의 전시가 열리는 미술관 ''화인갤러리''다', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03841', '라페스타', '음식점', 37.661839, 126.76796, '경기도 고양시 일산동구 중앙로 1305-56', '엔씨소프트 식당이 서중대 식당으로 등장한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03842', '소셜베이스 이태원', '음식점', 37.535022, 126.99253, '서울특별시 용산구 이태원로27가길 50 지하 1층', '1회에서 그룹 동료 오미리(김지인), 한대강(NCT 드림 재민), 태민 선배가 이 식당에서 웹툰 그룹 프로젝트 브레인스토밍을 하고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03843', '문발로', '관광지', 37.714588, 126.68758, '경기도 파주시 문발로 234', '이태상 코치(조한철 분)가 박태영을 제지한 후  6회 초반 이 거리를 걷고 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03844', '라멘트럭 상수본점', '음식점', 37.547433, 126.922559, '서울특별시 마포구 독막로 14길 31', '5회에서 육정환(김무준)과 이유민(서지혜)이 이 식당에서 라면을 먹는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03845', '아리스타커피 필동점', '카페', 37.560082, 126.99666, '서울특별시 중구 서애로 30', '물에 빠진 후, 박태양(박주현)과 박태준(채종협)은 이 카페의 지붕 아래에서 피난처를 찾는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03846', '남동체육관', '관광지', 37.434657, 126.73382, '인천광역시 남동구 소래로 500', '1회에서 박태양(박주현)과 박태준(채종협)은 우정을 다시 한 번 이 경기장을 지나며 걷는다. 말다툼을 하던 중 건물 앞 분수대가 출발해 잠시 물놀이를 하고 있다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03847', '오죽헌 경내', '관광지', 37.7775069, 128.877159, '강원도 강릉시 율곡로3139번길 24', '11회에서 유대일(박성준)이 기획한 강릉으로의 배낭여행으로 신입생들이 이곳을 찾는다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03848', '해밀톤 호텔별관', '숙박', 37.535099, 126.99377, '서울특별시 용산구 이태원로27가길 26', '11화에서 민한지(이세미 분)가 조한솔(김권 분)을 위협하는 장면에서 ''클럽알토''로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03849', '영진해변', '관광지', 37.8691601, 128.8365243, '강원도 강릉시 주문진읍 해안로 1609', '너의 결혼식에서 사랑을 확인한 바다', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03850', '산토리니', '카페', 37.8913993, 127.7742846, '강원도 춘천시 동면 순환대로 1154-97', '너의 결혼식에서 김영광이 박보영을 데리고 간 카페', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03851', '창리낚시터', '관광지', 37.1410221, 127.1821976, '경기도 용인시 처인구 남사면 창리 377-7', '너의 결혼식에서 김영광과 박보영이 헤어진 공원', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03852', '솔밭근린공원', '관광지', 37.6529549, 127.0096197, '서울특별시 강북구 삼양로 561 ', '너의 결혼식에서 박보영이 송어 잡는 장면을 찍은 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03853', '부흥송어장횟집', '음식점', 36.6958257, 127.7380049, '충청북도 괴산군 청안면 금평로 322', '너의 결혼식에서 박보영과 김영광이 고기를 먹은 곳', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03854', '벨라시타', '관광지', 37.642338, 126.79177, '경기도 고양시 일산동구 강송로 33', '홍이영(김세정)이 신영필하모닉 오케스트라 플루티스트 왕미향(황효은)과 마주치고 8회에서 빵을 사러 온다. 미향이가 빵집을 나서자 소매치기에게 털리고, 이영은 망설임 없이 미향이를 쫓아간다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03855', '고양아람누리', '관광지', 37.661427, 126.77433, '경기도 고양시 일산동구 중앙로 1286 고양아람누리', '1회와 4회, 7횡에서 ''신영필하모닉''이 연습 중인 ''SY아트센터''로 등장한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03856', '카페 디썸', '카페', 37.671018, 126.74826, '경기도 고양시 일산서구 호수로856번길 8-1', '13화에서 홍이영(김세정)과 하은주(박지연)는 이 카페에서 만난다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03857', '트웰브 청담', '관광지', 37.524819, 127.04501, '서울특별시 강남구 압구정로72길 26 지하1층', '12회(6회)에서 장윤(연우진)은 변호사 친구 최기상(김창회)을 이 술집에서 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03858', '692고기포차', '음식점', 37.583654, 126.99752, '서울특별시 종로구 창경궁로29길 25', '홍이영(구구단 김세정)이 자주 지나치는 식당이다. 2화(전편 1화)에서  남자친구 문재인(김상균)에게 밥을 사줬던 회상이 떠올랐을 때, 밥이 모자랐을 때. 술에 취한 그녀는 바깥에서 장면을 연출하고, 결국 지나가던 그녀를 본 장윤(연우진)에게 끌려간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03859', '좋은이웃카페', '카페', 37.586457, 127.00049, '서울특별시 종로구 혜화로 8 지하1층', '여기가 신영필하모닉오케스트라의 본거지이며, 홍이영(구구단/아이오아이 출신 김세종)이 팀파니 오디션을 하는 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03860', '엘림아트센터', '관광지', 37.531858, 126.63693, '인천광역시 서구 크리스탈로 78', '7화(전체 4화)에서 윤미래(윤주희)가 호텔방에서 전화를 받으며 준비를 하는 모습이 그려졌다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03861', '호텔스카이파크인천송도', '숙박', 37.384681, 126.63887, '인천광역시 연수구 컨벤시아대로 233', '장혜성(이보영)과 동료 변호사 차관우(윤상현)의 사무실은 길 건너편에 있는 법원 바로 앞이다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03862', '인천지방법원 부천지원', '음식점', 37.491876, 126.75758, '경기도 부천시 상일로 129', '너의 목소리가 들려에서 혜성치킨으로 나온 치킨집', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03863', '썬더치킨 수원성균관대점', '음식점', 37.584084, 126.997422, '경기도 수원시 장안구 율전로 102-5', '장혜성(이보영)은 박수하(이종석)와 함께 이 집에 산다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03864', 'KT&G 상상마당 춘천 아트센터', '카페', 37.873744, 127.70273, '강원도 춘천시 스포츠타운길399번길 25', '9-10회에서 그녀의 29번째 생일을 축하하기 위해 루나의 보컬 리더 윤태인(이준영/유키스 준)이 이 카페에 인윤주(정인선)를 데려온다.  그리고 자신의 감정을 고백한다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03865', '카페루헤', '카페', 37.282337, 126.56851, '경기도 안산시 단원구 서위매봉길 32', '3회에서 김유찬(윤지성, 전 워너원) 엄마가 이 가게에서 그를 부른다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03866', '씨호린', '음식점', 37.524947, 127.04367, '서울특별시 강남구 도산대로63길 18', '8회에서 서우연(장동주)은 인윤주(정인선)를 이 식당으로 초대해 저녁식사를 함께 하며, 얼마 전 서점에서 만난 적이 있지만 그녀가 스스로 기억하기를 바라는 마음에 미리 말을 하지 않았다고 털어놓는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03867', '와우어린이공원', '관광지', 37.549026, 126.92539, '서울특별시 마포구 독막로19길 20-13', '3회에서는 밤에 이곳에서 만나고, 4회에서는 이신이 지연의 합류를 밤새도록 기다린다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03868', '참샘골공원', '관광지', 37.614899, 126.97453, '서울특별시 종로구 평창동 470', '10화에서 서우연(장동주)이 인윤주(정인선)를 사채업자로부터 숨길 수 있도록 도와준 후 이 곳에서 우연은 윤주의 비밀을 알게된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03869', '북촌한옥마을', '관광지', 37.580452, 126.98709, '서울특별시 종로구 계동 128-7', '극 중 이규원(박신혜)이 사는 곳으로 10화에서 이신(씨엔블루 정용화 분)이 집 밖에서 기다리고 있는 모습을 볼 수 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI03870', '성산대교', '관광지', 37.552775, 126.89155, '서울특별시 마포구 망원동 성산대교', '최승희(김래원)는 16회에서 이 다리 발치에서 김복실(정려원)에게 프러포즈를 한다.', '서울');
