INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04116', '도하루제과', '관광지', 37.592865, 126.96466, '서울특별시 종로구 창의문로 144', '김보라(성유리)와 한득구(현빈)가 다니는 대학으로 등장한다. 첫째, 득구는 수학 교수(김벌래)가 관심을 가질 때까지 보라의 운전사로 캠퍼스를 배회하고, 득구에게 개인 교습을 주면서 그를 데려간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04117', '강남역', '관광지', 37.493168, 126.43448, '서울특별시 강남구 강남대로 396', '4회에서 김보로(성유리)가 참석한 패션쇼가 열린다. 이곳은 한득구(현빈)가 그녀를 추적하고 사생팬으로부터 그녀를 구하는 곳이기도 합니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04118', '센트럴시티터미널', '관광지', 37.5043439, 127.003599, '서울특별시 서초구 신반포로 176', '1화에서 한득구(현빈)가 이 시장의 헌책방에서 눈의 여왕을 찾는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04119', '평화시장', '쇼핑', 37.569447, 127.00801, '서울특별시 중구 청계천로 274', '1회에서 한태웅(현빈)과 김정규(이선호)가 1위를 다투는 제39회 국제수학올림피아드가 중앙도서관에서 열린다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04120', '연기복싱체육관', '관광지', 36.602961, 127.2973, '세종특별자치시 조치원읍 새내13길 7', '김혜자(김혜자/한지민)의 집으로 등장한다. 그녀의 어머니(이정은)는 미용실 ''행복미용실''을 운영하고 있다. 이곳에는 아버지(안내상)와 형 김영수(손호준)도 살고 있다. 1회에서는 혜자의 절친한 친구 이현주(김가은)와 윤상은(송상은)이 옥상에서 혜자의 데이트를 즐기는 모습이 그려졌다.', '세종');
