INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04181', '인천대공원', '관광지', 37.45671, 126.7579, '인천광역시 남동구 무네미로 236', '김단(인피니트 김명수)의 비밀정원은 인천대공원의 벤치다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04182', '아트센터 인천', '관광지', 37.393315, 126.62613, '인천광역시 연수구 아트센터대로 222', '이 건물은  ''판타지아 발레 극장''으로 등장한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04183', '오크밸리 리조트', '숙박', 37.434485, 127.817496, '강원도 원주시 지정면 오크밸리1길 66', '이 곳은 김달리(박규영)의 집이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04184', '올드스탠드', '관광지', 37.38601, 127.11141, '경기도 성남시 분당구 판교역로10번길 27', '4회에서 진무학(김민재)은 집까지 전 재산을 팔고 혼자 술을 마시러 온 김달리(박규영)와 함께 이 주점을 찾았다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04185', '수정로188번길', '관광지', 37.441931, 127.14145, '경기도 성남시 수정구 수정로188번길', '10회에서는 큐레이터 송사봉(우희진)이 기절한 나공주(송지원)의 집을 찾기 위해 김달리(박규영)와 함께 이 거리를 지나게 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04186', '오스템임플란트 중앙연구소', '관광지', 37.56771, 126.8291, '서울특별시 강서구 마곡중앙12로 3', '이 건물은 돈혼 F&B 사옥으로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04187', '족발야시장 성신여대점', '쇼핑', 37.590649, 127.01735, '서울특별시 성북구 보문로34길 35', '12회에서 성공적인 전시가 끝난 후 진무학(김민재)은 김달리(박규영)와 청송미술관 팀원들을 데리고 이 식당에서 족발식사를 하게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04188', '독서당어린이공원', '관광지', 37.534449, 127.01247, '서울특별시 용산구 한남동 1-32', '8회에서는 김달리(박규영)와 소꿉친구 주원탁(황희)이 놀이터에 합류했다. 그리고 그들은 풍경을 즐기며 마음을 담았다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04189', '동호로17길', '쇼핑', 37.554113, 127.00478, '서울특별시 중구 동호로17길 121', '2회에서 김달리(박규영)는 주원탁(황희)의 집을 찾아 이 거리를 걷는다. 동시에 진무학(김민재)은 그의 비서 여미리(황보라)에게 차를 몰고 집으로 달려가 달리리를 지나쳐 간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04190', '인천타워대로', '관광지', 37.389604, 126.63718, '인천광역시 연수구 인천타워대로', '8회에서 장태진(권율/권세인)은 이 거리를 운전하며 옛 아파트 길을 따라간다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04191', '스위스마을 컬러스테이', '관광지', 33.4940796, 126.677108, '제주특별자치도 제주시 조천읍 함와로 566-27', '이 마을은 네덜란드의 미술관에서 일하며 일하는 김달리(박규영)가 살고 있는 암스테르담의 동네로 등장한다. 2화에서 진무학(김민재)이 그녀를 찾으러 오는 장면이 나온다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04192', '선교장', '관광지', 37.78685, 128.885021, '강원도 강릉시 운정길 63 선교장', '보보경심려 촬영지 중 단연컨대 눈밭 레전드', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04193', '요선암', '관광지', 37.298489, 128.260334, '강원도 영월군 무릉도원면 무릉리', '고려 시대로 온 아이유가 만난 무릉도원', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04194', '효원공원', '관광지', 37.264175, 127.03822, '경기도 수원시 팔달구 동수원로 397', '이 공원은 궁궐의 일부로 등장한다. 5회에서 왕소(이준기)와 해수(이지은/아이유)가 대화를 나누는 곳이다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04195', '효원공원월화원', '관광지', 37.265074, 127.037687, '경기도 수원시 팔달구 동수원로 399', '4황자 왕소가 사랑한 해수의 처소', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04196', '아홉산숲', '관광지', 35.2879959, 129.169638, '부산광역시 기장군 철마면 웅천리 520-10', '4회에서 해수(이지은/아이유)와 왕정(지수)이 결투를 벌이던 남자의 부하들에게 납치되자 유왕후(박지영)는 남자의 팔을 베었다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04197', '세연정', '쇼핑', 34.162527, 126.55593, '전라남도 완도군 보길면 부황길 57', '왕소가 스님들을 몰살시키기전 고민한 곳', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04198', '내소사', '관광지', 35.617773, 126.58724, '전라북도 부안군 진서면 내소사로 243', '고려 황궁 외관도 이곳에서 촬영되었다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04199', '유니버셜아트센터', '관광지', 37.550799, 127.08806, '서울특별시 광진구 천호대로 664', '3회에서 이 건물은 오달자(채림)가 맡고 있는 엄기준(이현우)의 란제리 브랜드 ''더로:'' 런칭쇼가 열리는 장소로 등장한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04200', '명동쇼핑거리', '쇼핑', 37.564111, 126.98609, '서울특별시 중구 명동길 명동쇼핑거리', '2회에서 강태봉(이민기)이 할아버지가 보낸 깡패들로부터 벗어나기 위해 이 거리를 달리고, 뒤에서 눈물을 흘리는 오달자(채림)', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04201', '헬로우apm', '쇼핑', 37.567403, 127.00817, '서울특별시 중구 장충단로 253', '강태봉(이민기)의 절친 춘하(김재욱)가 쇼핑몰에서 일한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04202', '광릉 추모공원', '관광지', 37.771271, 127.198902, '경기도 포천시 내촌면 마명리 134', '태호와 수아가 대화를 나눈 수현의 묘가 있던 장소', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04203', '신선대', '관광지', 34.738334, 128.662565, '경상남도 거제시 남부면 갈곶리 산 21-33', '과거의 연아가 일하는 모습과 돌고래쇼 촬영 장소', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04204', '거제 씨월드', '관광지', 34.835916, 128.70156, '경상남도 거제시 일운면 지세포해안로 15', '수현이 30년 전의 수현과 처음 마주친 부산진역', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04205', '을숙도생태공원 낙동강하구에코센터', '관광지', 35.104728, 128.946017, '부산광역시 사하구 낙동남로 1240', '현재의 수현과 태호의 변치 않는 우정이 담긴 장소', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04206', '광안리해수욕장', '관광지', 35.153308, 129.118862, '부산광역시 수영구 광안해변로 219', '수현과 수아의 시간이 고스란히 담겨있던 집 앞', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04207', '송정해수욕장', '관광지', 35.178583, 129.199702, '부산광역시 해운대구 송정동 712-2', '30년 전의 수현과 태호가 이야기를 나눈 바닷가', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04208', '바세츠아이스크림 양재본점', '관광지', 37.4692, 127.04052, '서울특별시 서초구 동산로 7', '최우진(이상엽)이 실종된 이서연(김소은)을 찾기 위해 찾아왔다. 그리고 이 가게에서의 데이트를 회상하게 된다. 방송에서 이 가게의 이름은 ''젤라또 하우스''입니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04209', '양재시민의숲역', '관광지', 37.469784, 127.03846, '서울특별시 서초구 매헌로 116', '최우진(이상엽)이 여자친구 이서연(김소은)을 찾기 위해 3번 출구 근처 지하철역을 지나고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04210', '아보아보', '쇼핑', 37.520209, 127.02182, '서울특별시 강남구 강남대로160길 40', '26회에서 임다영(우주소녀 보나)과 윤상아(고원희), 강혜주(전수진)는 다영의 데이트 장소인 이곳으로 쇼핑을 하러 갑니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04211', '약사리문화마을', '관광지', 37.875801, 127.72771, '강원도 춘천시 중앙로67번길 56', '남홍주(배수지)가 엄마(황영희)와 함께 사는 집입니다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04212', '라플뢰르디유', '관광지', 37.321687, 127.10998, '경기 성남시 분당구 판교역로2번길 9-1 1F', '13회에서  남홍주(배수지)는 한우탁(정해인)에게 일어난 일에 대해 자책하고 있다. 울다가 우연히 이런 상황을 꿈꾸며 휴지 한 상자를 들고 찾아온 정재찬(이종석)과 마주친다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04213', '상동호수공원', '관광지', 37.503495, 126.745956, '경기도 부천시 원미구 상2동 549', '8회에서 남홍주(배수지)와 정재찬(이종)이 식사를 한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04214', '문스', '음식점', 37.3218388, 127.109973, '경기도 용인시 기흥구 죽전로15번길 15-3', '1회에서 이 식당의 주차장에서  남홍주(배수지), 이유범(이상엽), 정재찬(이종석)의 만난다. 홍주와 유범은 밥을 먹으러 나간다. 이 식당이 아닌 근처에 있는 ''파머스 테이블''에서 먹는다', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04215', '어린이대공원역', '관광지', 37.547117, 127.07395, '서울특별시 광진구 능동로 210', '3회에서 남홍주(배수지)가 이 역 1번 출구에서 지하철을 타고 있습니다. 바로 직전 어린이대공원 입구를 지나고 있는 그녀를 본다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04216', '건대입구역', '관광지', 37.540351, 127.06935, '서울특별시 광진구 아차산로 243', '3회에서 정재찬(이종석)이 이 역에서 지하철을 탄다. 그는 3번 출구로 역에 들어간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04217', '접시고기 망원점', '음식점', 37.560533, 126.90578, '서울특별시 마포구 월드컵로 143', '남홍주(배수지) 어머니의 식당으로 ''홍주삼겹살''이라는 이름으로 등장한다. 7-8화에서 모두에게 중요한 만남의 장소가 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04218', '서대문형무소역사관', '관광지', 37.574692, 126.95649, '서울특별시 서대문구 통일로 251', '24회에서 교도소 앞에서 현(오의식)이 수감자가 스스로 목숨을 끊고 누명을 썼다는 유서를 남겼다고 설명한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04219', '당산철교', '관광지', 37.540968, 126.9079, '서울특별시 영등포구 여의도동 당산철교', '3회에서 남홍주(배수지)와 정재찬(이종석)이 지하철 안에서 이 다리를 건너고 있다. 그곳에서 홍주는 재찬이 꿈에서 이 지하철을 타는 것을 봤다고 말한다', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04220', '토속촌 삼계탕', '음식점', 37.577707, 126.97151, '서울특별시 종로구 자하문로5길 5', '3회에서 홍지아(장나라 분)가 이 식당(''한옥 치킨 수프''로 등장)에서 테이크 아웃을 받는 모습이 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04221', '낙안읍성민속마을', '관광지', 34.906402, 127.341937, '전라남도 순천시 낙안면 충민길 30', '여러가지 체험이 간능한 ''대장금'' 촬영지', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04222', '선운산', '관광지', 35.508249, 126.571123, '전라북도 고창군 심원면 연화리', '대장금 어머니의 돌무덤, 용문굴이 있는 산', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04223', '송악산', '관광지', 33.197979, 126.291896, '제주특별자치도 서귀포시 대정읍 송악관광로 421-1', '검은색 모래가 인상적인 ''대장금'' 촬영지', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04224', '외돌개', '관광지', 33.239982, 126.545446, '제주특별자치도 서귀포시 서홍동 791', '27회에서 최상궁은 궁궐의 모든 부엌을 총괄하는 감독이 되기 위해 음모를 꾸미고, 먹고 병에 걸린 중종을 위해 한상궁(양미경)과 장금(이영애)이 준비한 오리밥을 독살한다. 반역죄로 기소된 두 여인은 구타를 당하고 제주도로 유배되지만 여행 중 한씨는 병에 걸린다. 장금은 그녀를 업고 갈대밭과 낭떠러지 위의 오솔길을 따라가지만 슬프게도 그녀의 스승은 세상을 떠난다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04225', '제주 민속촌', '관광지', 33.322522, 126.841862, '제주특별자치도 서귀포시 표선면 민속해안로 631-34', '대장금'' 소품 전시관이 있는 민속촌', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04226', '성읍민속마을', '관광지', 33.386356, 126.799711, '제주특별자치도 서귀포시 표선면 성읍리 30', '대장금'' 세트장에서 이색 체험 활동을 할 수 있는 곳', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04227', '대부도 메르블루 펜션', '숙박', 37.223668, 126.60441, '경기도 안산시 단원구 부흥로 287-150', '10회(전체 5화)에서 오래 기다리게 한 한산해(신동욱)와 복승아(소녀시대 권유리)에게 사과의 표시로 그들이 기다리던 의뢰인이 하룻밤 숙박을 제안한다. 이후 산해는 동생 진미(이열음)와 정식(김현준)을 불러 저녁식사를 놓치지 않기 위해 차를 몰고 그곳에서 만나자고 한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04228', '모노리스펜션', '숙박', 37.222672, 126.60454, '경기도 안산시 단원구 부흥로 287-73', '한산해(신동욱 분)와 복승아(소녀시대 권유리 분)가 주말에 이 곳에서 외부 클라이언트를 만나기로 하는 모습이 9회(전체 5화)에서 그려졌다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04229', '볼트 스테이크하우스', '음식점', 37.525014, 127.045014, '서울특별시 강남구 압구정로72길 22 2층', '21-22회(전체 11화)에서 한산해(신동욱)는 사무실 선물 교환을 위해 복승아(소녀시대 권유리)가 받기를 바라는 마음으로 이 식당의 상품권을 산다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04230', '부엌쟁이', '관광지', 37.484121, 126.97994, '서울특별시 동작구 동작대로23길 31', '한산해(신동욱)는 복승아(소녀시대 권유리)에 대한 마음을 숨기기 위해 매니저 이나영(정이랑)에게 점심을 먹자고 제안한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04231', '너랑나랑 호프', '음식점', 37.554715, 126.911, '서울특별시 마포구 월드컵로 61 삼미빌딩 1층', '3회(2회 본편)에서 한산해(신동욱)는 복승아(소녀시대 권유리)의 집들이 파티에서 팀을 위해 프라이드 치킨을 사러 오겠다고 제안한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04232', '블룸팔레트', '관광지', 37.582831, 126.8852, '서울특별시 마포구 월드컵북로60길 13', '복승아(권유리)는 4회에서 술에 취한 두 남자에게 들킨다. 몸싸움이 벌어지고 한산해(신동욱)의 재킷이 반으로 찢어진다. 우연히 지나가던 한정식(김현준)이 끼어들려 하지만 구타를 당한다. 한편, 승아는 방금 산 과일을 술주정뱅이들에게 던지면서 유리하게 이용한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04233', '일미칼국수', '음식점', 37.493922, 126.98609, '서울특별시 서초구 방배중앙로 167', '위기에 처할 뻔한 사업을 가까스로 구한 한산해(신동욱)는 신입 복승아(소녀시대 권유리)를 이 식당에 데려오기로 결심한다. 산해는 국수 대신 냉동 삼겹살(특선 메뉴라고 함)을 주문한 후 칼국수를 주문한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04234', '밀면땡기리 자가제면소', '음식점', 37.513734, 126.90066, '서울특별시 영등포구 경인로88길 5-11', '5화(3회)에서 한산해(신동욱)는 신입생 복승아(소녀시대 권유리)를 버킷리스트에 있는 또 다른 식당으로 데려간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04235', '자작나무이야기', '관광지', 37.57864, 126.98183, '서울특별시 종로구 율곡로1길 74-15', '한산해(신동욱)는 가까운 거리에 있는 복승아(권유리)를 따라 점심을 먹으러 가던 중, 17회에서 이 찻집을 지나간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04236', '이태리재', '음식점', 37.578758, 126.98172, '서울특별시 종로구 율곡로1길 74-9', '17-18회(전체 9화)에서 복승아(소녀시대 권유리)는 한산해(신동욱)를 이 식당에 데려오기로 결심한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04237', '복성각 덕수궁점', '관광지', 37.564671, 126.97637, '서울특별시 중구 덕수궁길 7 오천회관빌딩 2층', '16화(전체 8화)에서 복승아(소녀시대 권유리)가 짜장면 먹으라는 이야기를 듣고 한산해(신동욱)는 복승아를 여기로 데려오기로 했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04238', '동원민물장어', '음식점', 37.562562, 126.97786, '서울특별시 중구 세종대로14길 22-6', '한산해(신동욱)는 복승아(소녀시대 권유리)의 고백을 거절한 뒤 다시 복승아(소녀시대 권유리)에게 자신의 상여금으로 ''건강식''을 주기로 결심한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04239', '광화문국밥 본점', '음식점', 37.568968, 126.97541, '서울특별시 중구 세종대로21길 53', '복승아(소녀시대 권유리)는 한산해(신동욱)에게 사촌이기도 한 고객(강남 특별 카메오)을 데려오기 위해 식당을 추천해달라고 부탁하자 뜻밖에도 산해는 점심시간이라 따라가기로 한다. 따로 자리에 앉지만 승아는 산해가 자기 방식대로 주문하고 먹도록 하는 행동 하나하나를 주시한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04240', '서울숲', '관광지', 37.544046, 127.040414, '서울특별시 성동구 뚝섬로 273', '12회에서 고안나(임윤아)가 기절하고 김제하(지창욱)가 그녀를 구한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04241', '기지포해수욕장', '음식점', 36.562608, 126.32187, '충청남도 태안군 안면읍 해안관광로 745-19', '조인성이 뛰어가는 장면에 나온 식당', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04242', '임랑 해수욕장', '관광지', 35.318663, 129.264348, '부산 기장군 장안읍 임랑리 임랑 해수욕장', '더킹에서 류준열과 조인성이 대화를 나눈 곳', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04243', '길천방파제', '관광지', 35.324852, 129.284516, '부산광역시 기장군 장안읍 길천리', '조인성이 더킹에서 다짐을 하며 걸은 곳', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04244', '강촌레일파크', '관광지', 37.8428025, 127.550584, '강원도 춘천시 남산면 서백길 57', '여기는 이림(이정진)이 더 킹에 숨어있는 장소 중 하나로, 10화에서 유경무 (이해영)와 만나는 장면도 촬영되었다', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04245', '미사호수공원', '관광지', 37.563057, 127.1883, '경기도 하남시 망월동 739-1', '9회에서 이곤(이민호)과 태을(김고은)이 육교 옆 광장에서 치맥 데이트를 하는 모습이 그려졌다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04246', '월정교', '관광지', 35.829222, 129.218045, '경상북도 경주시 교동 274', '13회에서 이곤(이민호)이 이림(이정진)의 대나무 숲 조사를 마치고 돌아오는 태을(김고은)을 기다리는 곳이다.', '경주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04247', '중리체육공원', '관광지', 35.861432, 128.54568, '대구광역시 서구 중리동 1136-112', '3회에서 정태을(김고은)과 이곤(이민호)가 정비공을 기다리면서 그들은 공원으로 들어가 단풍 아래를 산책한다.', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04248', '다대포 해수욕장', '쇼핑', 35.046642, 128.964607, '부산광역시 사하구 몰운대1길 14', '이곤이 막시무스를 타고 달린 곳', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04249', '부산 다대포해수욕장', '쇼핑', 35.047244, 128.96727, '부산광역시 사하구 몰운대1길 14', '1회에서 이 해변을 처음으로 보게 되는데, 이 해변은 왕 이곤(이민호)이 말 막시무스를 타고 모래 위를 질주한다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04250', '충무동 새벽시장', '쇼핑', 35.09326, 129.0248, '부산광역시 서구 해안새벽시장길 68', '3회에서 총리 구서령(정은채)이 이 시장에 찾아오는 모습(대단한 수행원과 경호원)이 나온다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04251', '광복로 패션거리', '관광지', 35.09931, 129.02968, '부산광역시 중구 남포동5가 2-6', '강신재가 아이스크림을 물고 걸어다닌 곳', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04252', '영화의전당', '관광지', 35.171178, 129.12715, '부산광역시 해운대구 수영강변대로 120', '대한제국의 왕 이곤(이민호)은 기마 경호원, SWAT 팀과 함께 영화의전당 밖 거리에서 배신자 이림의 부하들과 싸워 정태을(김고)을 구한다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04253', 'APEC 나루공원', '관광지', 35.170641, 129.125569, '부산광역시 해운대구 수영강변대로 93', '태을이 이곤 전시회 포스터를 보게된 곳', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04254', '구남로해운대문화광장', '관광지', 35.16203, 129.16021, '부산광역시 해운대구 우동 해운대구남로 문화광장', '9, 10회에서 더킹 이곤(이민호)이 설날 해운대에서 왕과 함께 산책한다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04255', '벡스코', '관광지', 35.1688706, 129.135456, '부산광역시 해운대구 APEC로 55', '5화에서 태을(김고은)은 이곤의 왕국 코레아를 탐험하고, 서울행 고속열차를 타기 위해 부산역으로 향한다. BEXCO 콤플렉스는 ''부산 CTX 역''으로 나타난다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04256', '트레이드타워', '관광지', 37.510377, 127.06099, '서울특별시 강남구 영동대로 511', '5회 마지막회에서 왕 이곤(이민호)이무자비하게 정태을(김고은)을 데리러 오는 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04257', '미아리고개 예술극장', '관광지', 37.597785, 127.02145, '서울특별시 성북구 동소문로 177', '이 극장 앞은 이림(이정진)의 사옥 비밀 입구로 등장하는 곳으로, 10회에서 그가 자신의 부하 중 한 명을 만난다. 해운대 광장에서 이곤왕(이민호)과 신년 대치 후 추종자들. 이씨는 이씨와 부하들이 정보를 교환하는 서점에 부여군이 찾아갔으나 주인은 우연의 일치라고 생각했다. 반면 이씨는 방문이 운명이라고 생각하지만 운명은 그를 지배할 수 없다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04258', '북촌진곰탕', '음식점', 37.58725, 126.98294, '서울특별시 종로구 북촌로 137-2', '3회에서 이곤(이민호)은 정태을(김고은)과 그녀의 동료 강신재(김경남)를 따라 이 식당으로 가서 신재에게 돈을 달라고 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04259', '태화강 국가정원', '관광지', 35.547724, 129.296188, '울산광역시 중구 태화강국가정원길 154', '14회에서 이 대나무숲은 이곤(이민호)이 태을(김고은)이 기다리고 있는 정확한 대나무숲을 찾기 위해 시간과 평행우주를 뛰어넘어 도착한 곳이다.', '울산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04260', '소금빛서점', '관광지', 37.7448, 126.4856, '인천광역시 남문안길 7', '한국에 며칠간 머무른 후, 왕 이곤 (이민호)은 왕의 3화에서 자신의 왕국으로 돌아갈 때가 되었다고 결정한다. 이곤은 김씨가 그녀의 삶에서 얼마나 중요한지 의문을 제기하고, 이 서점에서 김소월의 진달래라는 시집을 산다. 그가 왕국으로 돌아오는 길에 노법사가 그의 재킷 안에서 책을 발견하고, 그녀는 그것을 보관한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04261', '고스락', '관광지', 36.045436, 126.96126, '전라북도 익산시 함열읍 익산대로 1424-14', '6회에서 노씨(김영옥)와 궁녀들이 기도하는 모습에서 처음 공개된다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04262', '단B커피숍', '카페', 36.967081, 127.92939, '충청북도 충주시 사직산3길 18', '이 넓은 집에서 정태을(김고은)은 아버지와 함께 오랜 세월 동안 살았으며, 그곳은 현재 명나리(김영지)가 카페를 소유하고 있다.', '충북');
