INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04284', '한미서점', '관광지', 37.472555, 126.63665, '인천광역시 동구 금곡로9', '14회에서 김신(공유)과 지은탁(김고은)이 한미 서점에서 만난 후, 김신은 돌아왔지만 은탁은 기억을 잃었다.', '인천');
