INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04287', '청라호수공원', '관광지', 37.533275, 126.63381, '인천광역시 서구 청라커낼로 135', '4회에서는 취한 신이 은탁에게 자신이 처음이자 마지막 신부라는 사실을 알리며 차분한 마음으로 했을 것 같은 자신에 대해 조금 더 이야기한다. 13회에서 은탁은 그를 보고 싶다고 그를 여기로 불렀다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04288', '인천자유공원', '관광지', 37.474776, 126.62373, '인천광역시 중구 송학동1가 1-1', '8화에서 김신(공유)과 지은탁(김고은)이 산책하러 왔다.', '인천');
