INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04291', '자유공원', '관광지', 37.4752537, 126.621846, '인천광역시 중구 제물량로232번길 46', '김고은이 불을 꺼서 공유를 부르던 장소', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04292', '아남타워', '음식점', 37.503716, 127.04485, '서울특별시 강남구 테헤란로 311', '15회에서 구라라(고아라)는 선우준(이재욱)을 처음 만난 게 사실 이 식당에서였다는 사실을 깨닫는다. 그녀는 그에게 문자를 보내면서 바로 이곳으로 온다. 같은 시각 준은 공항으로 가던 중 운전사에게 차를 세워달라고 부탁하고, 라라와 합류하기 위해 나선다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04293', '잠실아르누보팰리스', '관광지', 37.509074, 127.10487, '서울특별시 송파구 석촌호수로 258', '6화에서 호기심 많은 진하영(신은수), 이승기(윤종빈), 진숙경(예지원)이 태그를 붙이며 상황을 지켜본다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04294', '산모퉁이', '관광지', 37.595517, 126.96805, '서울특별시 종로구 백석동길 153', '6화에서 아버지가 어머니에게 우주의 행방을 묻는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04295', '부암동 7번지', '관광지', 37.598022, 126.97348, '서울특별시 종로구 북악산로 147', '1회에서 선우준(이재욱)은 자신이 머물던 곳을 떠나 이 버스 정류장에서 버스를 기다린다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04296', '청춘게스트하우스', '숙박', 34.792199, 126.37692, '전라남도 목포시 달성길 39', '2화부터 샌드위치 가게 ''봄날''에서 아르바이트를 하는 선우준(이재욱)이 등장한다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04297', '서산동 시화골목길', '관광지', 34.781388, 126.375166, '전라남도 목포시 보리마당로 14', '1화에서는 우준이가 집으로 돌아가는 길에 이 길을 달리는 모습이 그려지는데, 이후 고아라(고아라)는 이곳에서 자신의 피아노 학원 ''라라랜드''를 연다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04298', '알마센', '카페', 37.6822654, 126.79219, '경기도 고양시 일산동구 약산길 41', '10회에서 한준희(김지훈)가 이 카페에서 강소주(서주현/소녀시대 서현)와 협상을 시도한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04299', '이이남스튜디오', '관광지', 35.139174, 126.91284, '광주광역시 남구 제중로47번길 10', '16회에서 박재원(지창욱)이 지은 건물로 등장한다.', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04300', '강남파이낸스플라자', '관광지', 37.505835, 127.05217, '서울특별시 강남구 테헤란로 419', '7회에서 박재원(지창욱)은 집으로 돌아가는 길에 비가 많이 내리기 시작하자 이 건물로 피신한다.', '서울');
