INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04551', '안중근의사기념관', '관광지', 37.553577, 126.98035, '서울특별시 중구 소월로 91', '15회에서 주기범(송하윤)과 공마성(최진혁)은 데이트를 위해 이 박물관의 공원에 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04552', '명보사거리', '관광지', 37.564343, 126.99284, '서울특별시 중구 초동 명보사거리', '10회에서 공마성(최진혁)이 사고 전의 기억을 되찾는 곳이 바로 이 갈림길이다.', '서울');
