INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04554', '롯데호텔 제주', '숙박', 33.2483112, 126.410594, '제주특별자치도 서귀포시 중문관광로72번길 35', '설공찬 (이동욱)이 소유한 호텔중 하나로 등장.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04555', '포레스트 리솜', '숙박', 37.15796, 128.04624, '충청북도 제천시 백운면 금봉로 365', '7회에서 조성겸 총지배인(남궁민)이 리조트 운영 방식을 확인하러 온다. 8회에서는 구해영(김지한)과 남상효(유인나)가 가짜 결혼 후 이곳에 방을 예약하고 도망친 신부 정수아(하연주)가 합류하면서 상황은 더욱 복잡해진다.', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04556', '일영허브랜드', '숙박', 37.67548, 126.9237, '경기도 양주시 장흥면 일영로 346-26', '이 정원은 드라마에서 이설(김태희)의 어머니가 운영하는 ''햇볕 가득한 펜션''으로 등장한다. 예를 들어 1화에서는 박해영(송승헌)이 이설을 찾아 이곳에서 그녀를 발견하는 장면이 나온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04557', '국립고궁박물관', '관광지', 37.5764119, 126.976715, '서울특별시 종로구 효자로 12', '1회에서 오윤주(박예진 분)는남정우(류수영 분)에게 이 박물관에서의 전시회를 미리 보여준다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04558', '세이지우드 홍천', '관광지', 37.886097, 128.11847, '강원도 홍천군 두촌면 광석로 898-160', '이 단지의 내부(도서관 및 실내 수영장)는 효원 맨션의 인테리어의 일부로 나타난다. 예를 들어, 1, 4화에서 볼 수 있듯이  5화에서 외관은 서희수(이보영)가 아들의 가정교사 강자에 대해 자세히 알아보기 위해 방문하는 김 대표의 이연 저택으로 등장한다', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04559', '에펠타워', '관광지', 37.716675, 126.76033, '경기도 파주시 경의로 1114', '11회에서 서희수(이보영 분)가 이 건물에 위치한 아크레도 청담점에서 장신구를 구입하는 장면으로 나온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04560', '아크레도 청담점', '관광지', 37.527218, 127.04165, '서울특별시 강남구 압구정로 410', '4회에서 김유연(정이서)의 집으로 등장하며 한수혁(차학연)이 찾아오는 장소다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI04561', '정릉골', '관광지', 37.603161, 127.01374, '서울특별시 성북구 정릉동 정릉골주택재개발지역', '6회에서 성태(이중옥)와 경혜(윤금선)가 금고에 담았던 유명한 블루다이아몬드 목걸이를 훔치는 장면으로 등장한다.', '서울');
