INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05034', '무궁화로', '관광지', 37.667115, 126.77439, '경기도 고양시 일산동구 무궁화로', '7회에서 성예린(우다비)은 이 거리를 건너 전직 교사 한명에게 치일 뻔한다.', '경기');
