INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05336', '화왕산성', '관광지', 35.546106, 128.537389, '경상남도 창녕군 창녕읍 옥천리 산322', '고애신이 총포술을 연습하던 갈대숲', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05337', '삼릉숲', '관광지', 35.798733, 129.208281, '경상북도 경주시 배동', '어린 유진이 추노꾼들을 피해 달아나는 장면의 숲', '경주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05338', '만휴정', '관광지', 36.41043, 128.9099, '경상북도 안동시 길안면 묵계하리길 42', '6회에서 유진은 도예가 은산의 집에서 기다리며 새로운 적 희성을 생각한다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05339', '계명한학촌', '관광지', 35.8555794, 128.484165, '대구광역시 달서구 달구벌대로 1095', '고애신이 ''잉글리시''를 배우겠다 찾아갔던 목화학당', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05340', '한옥카페 선운각', '카페', 37.6549982, 126.999365, '서울특별시 강북구 우이동 265-16', '5화에서 일본군이 일본군에게 피해를 준 미군병을 붙잡기 위해 행사장 밖으로 보이는 미 의회로 행진하는 일본군. 양 당사자의 통역이 일련의 언어 번역을 한 후, 츠다(이정현)는 교전을 선언하고 두 세트의 군인은 서로 무기를 겨누고 있습니다. 유진 최(이병헌)는 일본에게 미국에 선전포고를 했는지 묻는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05341', '구서도역 영상촬영장', '관광지', 35.490738, 127.329307, '전라북도 남원시 사매면 서도길 32', '총 분실로 고애신이 미군에게 모욕을 당한 곳', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05342', '션샤인랜드', '관광지', 36.102621, 127.106021, '충청남도 논산시 연무읍 봉황로 102', 'SBS에서 제작한 미스터 션샤인의 세트장', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05343', '보눔 1957 한옥 앤 부티크', '관광지', 37.5817742, 126.984695, '서울특별시 종로구 북촌로 53', '마지막 16회에서 강태욱(지진희)의 친정집으로 등장한다. 그리고 아버지에게 그가 누군가를 죽였다고 고백한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05344', '설봉공원', '관광지', 37.2766061, 127.4266286, '경기도 이천시 경충대로2709번길 128', '미안하다 사랑한다에서 소지섭이 아침운동 하는 곳', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05345', '아쿠아아트 육교', '관광지', 37.481784, 127.01665, '서울특별시 서초구 서초동 1748-46', '14회에서 차무혁(소지섭)은 고가도로에서 송은채(임수정)에게 전화를 걸어 다음과 같이 말한다. ''건강해요, 좋아해요'' 그녀를 그리워하던 그는 갑자기 그녀를 찾으러 달려갑니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05346', '양지말 화로구이', '음식점', 37.6595147, 127.8312424, '강원도 홍천군 홍천읍 양지말길 17-4', '김희철이 독립 후 아르바이트를 했던 고깃집', '강원');
