INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05362', '만나식당', '음식점', 36.154144, 127.011646, '충청남도 논산시 강경읍 황산리 138-2', '김종국이 방문한 논산 젓갈 식당', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05363', '신전떡볶이 복대점', '음식점', 36.636658, 127.426105, '충청북도 청주시 흥덕구 증안로 23 영조아름다운나날아파트 입구 상가 1층', '미운 우리 새끼 188회에서 김강훈이 방문한 식당', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05364', '노보카인', '음식점', 37.545904, 126.92094, '서울특별시 마포구 와우산로3길 36', '김래완(김선호)의 단골 술집이다. 그의 아티스트 선배인 현지(박효주)가 운영한다. 이곳에서 아르바이트생 서정(권도운)과 대화를 나누며 잠시 데이트를 하게 됐다. 4화에서 한은성(이유영)은 래완과의 대화를 끊은 지 1년 만에 이곳에 와서 그의 개인전을 알게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05365', '사발', '음식점', 37.5737579, 126.9723299, '서울특별시 종로구 사직로8길 34 경희궁의아침 3단지 142호', '민경훈이 식신로드에서 먹었던 이색 국숫집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05366', '서우봉', '관광지', 33.545494, 126.6776, '제주특별자치도 제주시 조천읍 함덕리 169-3', '민경훈 유튜브, 함덕 해변에서 올라간 망오름 정상', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05367', '금능 해수욕장', '관광지', 33.389908, 126.235373, '제주특별자치도 제주시 한림읍 금능길 119-10', '민경훈 유튜브에서 제주도로 와서 최종 목적지', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05368', '한림공원', '관광지', 33.389553, 126.239337, '제주특별자치도 제주시 한림읍 한림로 300', '민경훈 유튜브에서 제주도로 와서 구경한 공원', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05369', '기회송림공원야영장', '관광지', 35.51112, 128.774889, '경상남도 밀양시 산외면 남기리 838-3', '밀양 영화 세트장으로 송강호, 전도연방 있는 곳', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05370', '카페 밀양', '카페', 35.476561, 128.765843, '경상남도 밀양시 중앙로 118-5', '2014년 JTBC ''밀회'' 13회에서 오혜원(김희애)은 이선재(유아인)에게 친구 집에서 사적으로 만나자고 한다. 그녀가 당분간 그와 거리를 둘 것이라고 그에게 말합니다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05371', '헬로우씨 카페', '카페', 38.29637, 128.54763, '강원도 고성군 죽왕면 괘진길 53-11', '1회에서 이수진(김하늘)이 이 카페에 온다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05372', '학전블루소극장', '음식점', 37.582069, 127.00374, '서울특별시 종로구 대학로12길 46', '이곳은 이수진(김하늘)이 생각해낸 화장으로 ''다른 여자''로 변장한 유정과 ''불륜''으로 이혼을 꾀하는 극장. 남편 권도훈(감우성)을 만나 열애 한 달 만에 불륜을 시작하게 된 것. 바람이 분다 5회에서 그는 이날 현장으로 달려갔다. 그러나 그녀는 그를 만나지 않기로 하고 맞은편(13시 20분경) 식당 소바의 온도 위층에서 지켜보고 있다. 그들은 각자의 길을 갑니다. 두 사람은 이혼하고 5년 후 같은 연극 ''도둑들 이야기''를 공연하던 중 우연히 이곳(8화)에서 그를 만나지만 그는 현재 치매에 걸려 처음에는 그녀를 알아보지 못한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05373', '훼릭스', '음식점', 37.647408, 126.86149, '경기도 고양시 덕양구 고양대로 1624', '강여주(조여정)의 ''오싹한 북콘서트'' 후 회식이 이 야외 식당에서 진행된다. 강여주는 그녀의 ''구원자'' 차수호(김영대)와 마주 앉아 있다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05374', '위드뷰티살롱', '관광지', 37.52252, 127.0451, '서울특별시 강남구 도산대로70길 16', '6, 7회에서 한우성(고준)이 고미래(연우/전 모모랜드 이다빈)를 이 장소에 내려주고 미래는 이곳에서 아르바이트를 하고 있다고 설명한다(일반 학생 신분을 속이려는 것이 아니다). 실제로 그녀는 이 미용실의 단골이며 중요한 공식석상을 준비하기 위해 이곳에 약속이 있었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05375', '가라오케 파샤', '관광지', 37.525927, 127.0398, '서울특별시 강남구 선릉로 827', '5회에서 우성이 백수정(홍수현)의 죽음을 알게 된 후 한우성(고준)과 절친 손진호(정상훈)가 술을 마시던 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05376', '신라스테이 삼성', '숙박', 37.509953, 127.06316, '서울특별시 강남구 영동대로 506', '6화에서 강여주(조여정)와 한우성(고준)은 저녁 식사를 한 곳이다. 저녁 식사는 내내 어색했고 그는 이곳이 5년 전 처음으로 키스한 곳이라는 것을 그녀에게 상기시켜위기를 밝게 하려고 노력합니다. 그리고 그녀가 나중에 아이를 낳아야 하는지 묻자 당황합니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05377', '대오 서점', '관광지', 37.579716, 126.96934, '서울특별시 종로구 자하문로7길 55', '7회에서 차수호(김영대)가 절판된 책을 이 가게에서 찾고 있다.', '서울');
