INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05380', '문경활공랜드', '관광지', 36.736658, 128.154239, '경상북도 문경시 문경읍 활공장길 80', '바퀴집 식구들과 아이유가 패러글라이딩을 한 곳', '경북');
