INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05382', '만돌갯벌체험학습장', '관광지', 35.530106, 126.515014, '전라북도 고창군 심원면 애향갯벌로 320', '바퀴달린집 6회의 앞마당이었던 갯벌', '전북');
