INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05384', '지리산 벚꽃 카라반 캠핑장', '관광지', 35.262516, 127.636385, '경상남도 하동군 화개면 화개로 946-8', '배틀트립''에서 박지훈이 묵은 곳', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05385', '카페멘덜리', '카페', 37.632451, 127.01881, '서울특별시 강북구 수유로 18', '박지훈 ''대학내일'' 촬영지', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05386', '정발휴게소', '관광지', 37.668989, 126.77513, '경기도 고양시 일산동구 대산로11번길 5-9', '4회에서 최진무(이승준)와 함께 강인욱(김성규)이 슬픔에 잠기려 찾아온다. 진무는 지나가던 문순호(김하나)를 발견하고 돌연 급한 일이 생겨 그녀가 대신하게 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05387', '김포 금파로', '관광지', 37.623588, 126.7395, '경기도 김포시 고촌읍 향산리 금파로', '10회에서 한서우(채수빈)이 벚꽃이 만발한 거리 모퉁이에서 문하원(정해인)에게 전화를 걸어 만나자고 한다. 그녀가 치유가 필요하기 때문입니다. 잠시 후, 하원은 그녀와 합류하기 위해 와서 꽃 아래에서 포옹을 나눕니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05388', '가톨릭문화원', '관광지', 37.702534, 126.65818, '경기도 김포시 하성면 월하로 970-18', '2회에서 최진무(이승준)가 피아니스트 강인욱(김성규)의 피아노 연주를 도우러 온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05389', '푸라닭치킨 등촌역점', '음식점', 37.552053, 126.86326, '서울특별시 강서구 공항대로 509 107호', '9회에서 문하원(정해인)과 AH연구소 동료들이 점심을 먹으러 왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05390', '우이천로38라길', '관광지', 37.652901, 127.02401, '서울특별시 도봉구 우이천로38라길 28', '이곳에서 서우는 자신에게 접시를 배달하러 온 김지수(박주현)를 처음 만난다. 이어 문하원(정해인)은 이 거리를 지나 집으로 향한다. 4화에서 서우는 가로등 옆에 구불구불한 의자를 놓고 집에 돌아오기를 기다리던 돌아가신 어머니가 놓았다고 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05391', '날아라분식', '음식점', 37.562924, 126.96192, '서울특별시 서대문구 경기대로 39', '6회 회상 장면에서 문순호(이하나)는 문하원(정해인)을 보며 웃는다. 이 식당(본명 ''날아라분식'')에서 순호는 미국에서 돌아온 김지수(박주현)에게 거절당했다고 털어놨다. 순호가 가장 친한 친구를 위해 약혼자에게 거절당하는 자신의 비참함에 뒹굴면서 웃음은 곧 무의식적인 눈물로 바뀐다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05392', '물뛴다', '음식점', 37.563267, 126.96214, '서울특별시 서대문구 경기대로 43', '5화, 10화에서 영화 ''피스''에서 이 식당에서 몇 번이나 만난 문순호(김하나)와 강인욱(김성규).', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05393', '명보빌딩', '카페', 37.537287, 127.00047, '서울특별시 용산구 이태원로 251 한남동빌딩', '11회에서 문순호(김하나)가 강인욱(김성규)을 카페로 데려온다. 문하원(정해인)과 마주한 후 나간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05394', 'FN COFFEE', '카페', 37.581583, 126.97103, '서울특별시 종로구 자하문로 62 1층', '4회에서 문하원(정해인)이 김지수의 한국에서의 마지막 발걸음을 따라 녹음실을 빠져나와 이 거리를 걷고 있다. 스튜디오에서 그를 본 한서우(채수빈)는 그의 뒤를 따르기로 한다. 2화에서 지수는 스튜디오에서 서우를 만난 후 이 거리를 걷는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05395', '방선생웃음밥상', '음식점', 37.588654, 126.99938, '서울특별시 종로구 혜화로 33-1', '4회에서 김창섭(강봉성 분)이 전은주(이상희 분)를 만나 한 끼 식사를 하고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05396', '서울 회현동 민가', '관광지', 37.556279, 126.97781, '서울특별시 중구 퇴계로6가길 34', '한서우(채수빈)와 김지수(박주현)는 1회에서 서우가 지수 목소리 녹음을 마친 후 이 집에서 몇 걸음 떨어진 거리를 걷는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05397', '욕쟁이할머니포차', '음식점', 37.518196, 127.041331, '서울특별시 강남구 선릉로132길 3-3 지하1층', '고수, 한효주가 술 마시러 간 곳', '서울');
