INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05399', '단콩', '카페', 36.613906, 127.28924, '세종특별자치시 조치원읍 섭골길 35-4 단콩', '여기는 강연두(정은지) 엄마의 카페.', '세종');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05400', '세종호수공원', '관광지', 36.497909, 127.2729, '세종특별자치시 호수공원길 155', '아들과 눈을 마주치는 것이 불편한 아버지에게 연두의 어머니가 “미안해요, 고마워요, 사랑해요”라는 말은 아이가 잘 자라기 위해 들어야 할 세 가지 요소라고 설명한다.', '세종');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05401', '녹수원글램핑', '관광지', 36.62859, 126.96982, '충청남도 공주시 유구읍 금계산로 919-11', '8,9회에서 세빛고 치어리딩팀이 여행을 갑니다. 여기서 김열(이원건)은 강연두(정은지)에게 마음을 고백한다. 하지만 그녀가 대답을 하려 하자 서하준(지수)이 다가와 어색하게 만든다. 고백은 캠핑장으로 이어지는 다리에서 이루어졌습니다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05402', '서울 신당동 민가', '관광지', 37.555679, 127.00694, '서울특별시 중구 동호로17길 57-4', '13회에서 왕주현(김정화)은 허초희(김선아)의 아버지가 실종되기 전 마지막으로 만났던 사람을 찾는 상사 강시완(이주현)을 따라갔다. 이를 계기로 이 거리로 오게 된 주현은 평소와 다름없이 일을 진지하게 받아들이지 않고 입구 앞에서 셀카를 찍는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05403', '속삭이는자작나무숲', '관광지', 37.9737439, 128.227423, '강원도 인제군 인제읍 자작나무숲길 760', '아파트 단지에 가족과 함께 사는 윤진아(손예진).', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05404', '탄천 지하보도', '카페', 37.39706, 127.1235, '경기도 성남시 분당구 이매동 144', '이 커피베이 카페에서 서준희(정해인)의 여동생 서경선(장소연)이 운영하는 지점으로 등장한다. 정기적으로 만남의 장소로 등장하며 거의 모든 캐릭터가 이 카페를 지나갑니다. 윤진아(손예진)는 1회에서 전 남자친구가 두 번 있었다는 사실을 알게 된 후 이곳에 와서 술에 취해 한 번도 사랑한 적이 없다는 이야기를 하고 두 사람의 어두운 미래를 그린다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05405', '커피베이 수원망포점', '카페', 37.241358, 127.05948, '경기도 수원시 영통구 영통로154번길 74', '윤진아(손예진)는 12회에서 점심시간에 동료들과 함께 온다.', '수원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05406', '카페누하191', '카페', 37.579236, 126.96867, '서울특별시 종로구 필운대로 35', '카페를 지나는 서준희(정해인)와 윤진아(손예진). 4회에서는 저녁을 함께 먹고 난 직후, 준희가 진아의 손을 잡거나 어깨에 팔을 두르지 않으려고 필사적으로 몸을 움츠렸다. 11화에서는 이 카페를 편안하게 걷고 있는 두 사람의 모습. 팔짱을 끼고 12화에서 여기를 지나가는 사람은 진아 혼자다.. 14화에서 이 카페 앞에서 둘이 말다툼한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05407', '을지로3길', '음식점', 37.567474, 126.98147, '서울특별시 중구 을지로3길 34', '4회에서 서준희(정해인)는 윤진아(손예진)와 마주보고 서서 방금 전에 식당에서 손을 잡은 이유에 대해 묻는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI05408', '무무건축', '숙박', 37.619794, 126.45994, '인천광역시 강화군 화도면 해안남로1066번길 26', '4회에서 윤진아(손예진)와 서준희(정해인)가 하룻밤 묵는다.', '인천');
