INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06010', '타임스퀘어', '쇼핑', 37.517308, 126.9034, '서울특별시 영등포구 영중로 15', '9화에서 공태성(김영대)과 오한별(이성경)은 밤에 이 쇼핑몰 앞에서 만나기로 했다. 하지만 한별이 도착하기도 전에 한 무리의 팬들에게 인질로 잡혀간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06011', '손정완', '관광지', 37.520519, 127.03386, '서울특별시 강남구 언주로 733', '7화 천송이(전지현)가 이 부티크에 초대되어 도민준(김수현)이 천송이를 데려간다. 부티크 안에서 우연히 유세미(유인나)와 마주치며 둘 사이에 불편한 이야기가 이어진다. 건물을 나서던 중 암살자가 옥상에서 송이에게 무거운 유리잔을 떨어뜨리고 민준는 송이를 겨우 구한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06012', 'GT타워', '관광지', 37.498034, 127.02599, '서울특별시 서초구 서초대로 411', '5회에서 천송이(전지현)가 도민준(김수현)에 대해 설명하면서 현재 살고 있는 아파트로 이사한 곳이 바로 이 건물이다. 그녀의 아파트 발코니에서 그와 합류. 천송이에 따르면 이곳은 빌보드를 위한 가장 비싼 장소이며 이 나라에서 가장 핫한 스타가 여기에 삽니다(현재 그녀입니다).', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06013', '엔그릴', '관광지', 37.551246, 126.988216, '서울특별시 용산구 남산공원길 105 N서울타워 7F', '1회와 10회에서 도민준(김수현)과 변호사 친구 장영목(김창완)이 이곳에서 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06014', '학림', '관광지', 37.581892, 127.00167, '서울특별시 종로구 대학로 119 2층', '20화에서 김민준(김수현)은 힘이 약해지면서 이 공원으로 순간이동한다. 그는 추위에 떱니다. 급하게 달려온 변호사 장영목(김창완)에게 전화를 걸고 민준은 이곳이 장영목을 처음 만난 공원이었다는 사실을 기억한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06015', '봉은사', '관광지', 37.5151248, 127.056921, '서울특별시 강남구 봉은사로 531', '안은영(정유미)과 홍인표(남주혁)가 등장한다. 2화에서 이 사찰에 기도하러 갔더니 둘 다 친구가 없다는 사실을 알게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06016', '오보코갤러리', '관광지', 37.596848, 126.99576, '서울특별시 성북구 선잠로5길 15', '2화, 18화에서 차지헌(지성)은 아버지 차봉 회장과 함께 이곳에 산다.', '서울');
