INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06032', '신촌 박스퀘어', '관광지', 37.559006, 126.94294, '서울특별시 서대문구 신촌역로 22-5', '4회에서 화난 강복수(유승호)가 밤에 이 쇼핑몰을 지나간다. 혼잣말을 하며 그는 자신의 과거를 회상하고 이전과 같은 사람들에 의해 자신의 삶이 다시 망가지는 것처럼 보인다.', '서울');
