INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06050', '성동구립도서관', '관광지', 37.559202, 127.03497, '서울특별시 성동구 고산자로10길 9', '4에서 이정인(한지민)은 이 도서관에서 일하고, 유지호(정해인)는 아들 유은우(하이)와 함께 찾아온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06051', '가야랑빌딩', '관광지', 37.540098, 126.99385, '서울특별시 용산구 회나무로 66', '6회에서 저녁을 먹으러 이정인(한지민)과 권기석(김준한)이 여기에 온다. 기석은 결혼을 언급하며 다른 사람에게 끌리는지 묻는데 그녀의 강한 거부에 의심을 한다.', '서울');
