INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI06247', '커피스미스 이천 로데오점', '카페', 37.280371, 127.44459, '경기도 이천시 어재연로37번길 20', '차현태(박성근)는 1회에서 유명한 설교자 행세를 하며 이 교회 건물로 끌려온다. 대본을 잃어버렸음에도 불구하고 격앙된 설교를 하고, 이후에도 많은 설교가 이어지며 교인들이 교회 건축 기금에 아낌없이 기부할 것을 독려한다.', '경기');
