INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI07477', '현대골든텔2오피스텔', '관광지', 37.5516, 127.111, '서울특별시 광진구 광장동 아차산로78길 102', '1회에서 고등학생 차현수(송강)는 자살 충동을 느끼며 이 건물 옥상으로 올라온다. 그러나 근처 옥상에서 발레 연습을 하고 있는 이은유(고민시)를 발견하고 마음을 바꾼다', '서울');
