INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI07487', '투썸플레이스 내방역점', '카페', 37.487801, 126.99302, '서울특별시 서초구 서초대로 99', '12에서 정사하(Stephanie Lee)는 이 가게를 지나가다가 아이스 바닐라 라떼 1+1 프로모션을 발견한다. 이철산(유수빈)을 염두에 두고 그녀는 바닐라라떼를 사러 갔다가 서달미(배수지)와 남도산(남주혁)과 마주치게 된다. 14회에서는 철산(유수빈)과 사하가 삼산테크팀의 신사업 편입을 논의하기 위해 찾아왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI07488', '동대문B동신발종합상가', '관광지', 37.57005, 127.0123, '서울특별시 종로구 청계천로 307', '1,2회에서 볼 수 있듯이 이 건물 옥상에는 남도산(남주혁)이 운영하는 삼산테크 사무실이 있다.', '서울');
