INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08245', '제물포 시장', '쇼핑', 37.463043, 126.657309, '인천광역시 미추홀구 숭의동 27-58', '이곳은 한정연(공승연)의 집으로 등장하며, 그녀와 김우진(여진구)이 한교수의 서재에서 무언가를 찾기 위해 찾아온 곳이다.', '인천');
