INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08256', '괴산호', '관광지', 36.753677, 127.835418, '충청북도 괴산군 청천면', '영화 아가씨에서 보트타고 호수를 건너는 곳', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08257', '커피네츄럴스페셜티', '카페', 37.61768, 126.8348, '경기도 고양시 덕양구 용현로53번길 16-1 1층', '13회에서 우진의 엄마(이정은)는 집 밖에서 차주혁(지성)을 이 카페로 데려온다. 그녀가그에게 제품을 판매합니다. 반면에 주혁은 그녀의 건강한 모습을 보고 기뻐하며 그녀의 제품을 사게 되어 기쁘다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08258', '대동슈퍼', '쇼핑', 37.587, 126.8017, '서울특별시 강서구 개화길 54', '드라마에서 두 주인공 서우진(한지민) 과 혁(지성)이 가끔 손을 잡고 집으로 가는 길에 이 마트를 여러 번 지나간다 .', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08259', '또또분식', '음식점', 37.47977, 126.6452, '인천광역시 동구 샛골로193번길 4', '12회에서 차주혁(지성)이 과자와 소주 한 병을 들고 의문의 남자를 찾아 지하철역으로 온다. 주혁은 자신이 주변 사람들을 불행하게 만든다는 사실을 깨닫고 자신이 (다른 우주에서) 겪고 있는 것은 욕심이 너무 많은 것에 대한 "하늘의 징벌"이었다는 것을 어떻게 깨닫는지 이야기한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08260', '빅토리아펜션', '숙박', 36.4241, 126.3607, '충청남도 태안군 고남면 큰장돌길 283-42', '11회에서 이순재(류시원)는 친아버지가 누구인지 알게 된 후 여행을 가기로 결심한다. 상황의 심각성을 이해한 김연수(최지우)는 그에게 작별인사를 하러 찾아와 이민철(이병헌)의 중요한 저녁 초대를 무시한다. 결국 순재는 여행을 가지 않기로 하고 연수와 함께 역에서 나와 역 앞 택시 승강장에서 잠시 이야기를 나눈다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08261', '서강 껍데기 합정점', '음식점', 37.55268, 126.9125, '서울특별시 마포구로 36', '30년의 여름, 신솔이(소주연), 우대성(여회현), 강하영(조혜주), 정진환(정진환)은 20회에서 식당에서 재회한다. 진환은 한 사람이 없어졌다고 말하고, 그래서 차헌(WEi의 김요한)에게 전화를 걸었고, 결국 차헌이 나타난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08262', '이정희떡볶이', '음식점', 37.5780735, 126.923326, '서울특별시 서대문구 증가로10길 14', '2회에서 신솔이(소주연)는 차헌(WEi 김요한)과 같은 식당에서 그의 ''후광''을 보게 되는 꿈을 꾼다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08263', '탑정호수변생태공원', '관광지', 36.19184, 127.1724, '충청남도 논산시 부적면 충곡리 287-8', '차헌(WE 김요한)은 2회에서 어린 시절 길을 잃은 차헌(김요한)이 다리를 건너 그를 찾았다고 회상했다.', '충남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08264', '강릉 소돌항', '관광지', 37.90507, 128.8305, '강원도 강릉시 주문진읍 주문리 791-23', '오동희(박은빈)가 잠시 살고 있는 주문진읍 항구입니다. 집에서 항구가 보이고, 특히 한성준(이태환)이 보고 싶을 때 자주 온다. 동희가 도망친 곳을 성준이 알게 되면서 두 사람이 만나는 곳이기도 하다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08265', 'KstarROAD', '관광지', 37.52756, 127.0423, '서울특별시 강남구 압구정동 516', '13회에서 한성준(이태환)과 오동희(박은빈)가 데이트를 하러 왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08266', '카페 릴리블랑', '카페', 37.477636, 127.03814, '서울특별시 서초구 양재천로19길 52', '5회에서 오동희(박주혁) 은빈과 한성준(이태환)이 만난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08267', '아스달 연대기 드라마세트장', '관광지', 37.17935, 127.0638, '경기도 오산시 내삼미동 240', '아스달 연대기 (tvN, 2019)에 나오는 가상의 마을 ''아스달''을 배경으로 한 촬영장입니다.', '경기');
