INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08315', '정동진해수욕장', '관광지', 37.690392, 129.03358, '강원도 강릉시 강동면 정동진리 257-2', '3화에서 강진구(김영광), 마세영(경수진) 일할 곳을 찾을 때 바닷가 레스토랑에서 식사를 했다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08316', '에이엠브레드앤커피', '카페', 37.772384, 128.947504, '강원도 강릉시 창해로14번길 24', '3회에서 출장 중 마세영(경수진)과 강진구(김영광)는 이 카페에서 잠시 휴식을 취한다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08317', '묵호등대전망대', '관광지', 37.554268, 129.1185, '강원도 동해시 해맞이길 289', '3회에서도 마세영(경수진 분)과 강진구(김영광 분)가 여행으로 이곳에 온다. 사실 그들은 여행사에 여행 제의를 받으러 왔다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08318', '아트벙커 B39', '관광지', 37.521593, 126.76734, '경기도 부천시 삼작로 53', '12~13회에서 정선아(김민정)는 지성(강요한)을 이 복합문화공간으로 오라 명령하고 절친의 목숨을 위협한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08319', '와드로브', '관광지', 37.539199, 126.99007, '서울특별시 용산구 회나무로12길 3-11', '이 건물의 외관은 제2화에서 사람미디어그룹과 사회책임재단이 공동 주최하는 자선 패션쇼가 열리는 장소로 등장한다. 이 행사의 명예 게스트로는 강요한(지성)과 리얼리티 텔레비전 쇼 ''라이브 코트 쇼''의 동료 심사위원 오진주(김재경)가 나온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08320', '대통령기록관', '카페', 36.501678, 127.27309, '세종특별자치시 다솜로 250 대통령기록관', '백희성(이준기)은 딸 은하(정서연)에게 이 카페에서 에그타르트를 먹게 한다. 2회에서 유치원에서 데리러 온 후 일찍이 난투극을 벌이던 아버지가 급우의 편을 드는 모습에 당황한 은하는 그녀가 가장 좋아하는 디저트를 먹기를 거부한다.', '세종');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08321', '모립', '카페', 33.462997, 126.309776, '제주특별자치도 제주시 애월읍 애월로 1길 26-7', '7화에서 공미자(남기애)는 찢어진 워크북을 보고 하소연한 후 백은하(정서연)를 행복하게 해 주기 위해 백은하(정서연)를 이 카페로 데려간다', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08322', '뜨랑블랑', '카페', 37.5374, 126.9453, '서울특별시 마포구 마포대로4나길 42', '16회에 이 카페에서 도현수(이준기)와 차지원(문채원)은 도해수(장희진)의 증언을 위해 양진태(이현균)를 설득하려 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08323', '한성교회', '쇼핑', 37.51116, 126.8426, '서울특별시 양천구 신정로13길 21', '최종회 16회에서는 도현수(이준기)와 차지원(문채원)이 아파트 3동에 모인 모습이 그려졌다. 촌장의 조카인 양진태에게 도해수(장희진)를 위해 법정에서 증언해달라고 부탁하기 위해. 지원은 진태로부터 증언을 하지 않겠다는 문자를 받았지만 집에 올 때까지 기다리기로 한다. 진태는 도착했지만 현수를 보고 도망친다. 현수와 지원은 둘 다 그를 쫓고 엘리베이터에서 그를 궁지에 몰아넣는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08324', '북경원', '음식점', 37.62101, 126.9164, '서울특별시 은평구 갈현로 271', '2회에서 자신이 운영하는 중식당 남순길(이규복)이 김무진(서현우)의 연주연쇄살인 기사를 읽는 모습이 그려졌다. 그가 무진에게 음성사서함을 남기고 있을 때 검은색 후드티를 입은 인물이 식당으로 걸어들어가 칼을 뽑아 그를 찔러 죽인다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08325', '달콤한 게으름 놀이터', '관광지', 37.4540764, 126.702084, '인천광역시 남동구 예술로226번길 4 남문빌딩', '12회에서는 도현수(이준기)와 형사 최영주(최영주)가 현수의 예감에 대해 비밀리에 이 식당으로 향하는 모습이 그려졌다. 그를 죽이기 위해 염상철(김기무)과 협정을 맺었다. 현수는 상철에게 그를 죽일 수 있는 절호의 기회를 주려는 계획에 따라 경찰이 그를 붙잡고 모든 배후의 범인을 알아낼 수 있도록 최형사에게 도움을 청하게 된다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08326', '선갑도', '관광지', 37.09755, 126.0772, '인천광역시 옹진군 자월면 승봉리 산240', '현수(이준기)는 옛집에서 백희성(김지훈)과 대면하고, 자신이 아내 차지원(문채원)을 죽였다고 생각하고, 15회에서 그를 죽이려 한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08327', '직탕폭포', '관광지', 38.20945, 127.2655, '강원도 철원군 동송읍 장흥리 336-1', '11회에서 한밤중에 우호성(나철)이 무거운 가방을 끌고 이 폭포의 절벽에서 밀어내는 모습이 그려졌다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08328', '의림지', '관광지', 37.17197, 128.2093, '충청북도 제천시 모산동 241', '1화에서 어린 송하영이 어머니와 함께 오리배를 타고 오다가 사고로 물에 빠진다.', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08329', '소풍정원', '관광지', 37.01151, 127.0214, '경기도 평택시 고덕면 궁리 424-25', '13회에서는 한유현(김영광), 한유현(김영광), 안소니(안소니)/양춘식(음문석)이 소풍을 하러 공원을 찾는 모습이 그려졌다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08330', '호텔더디자이너스 리즈강남프리미어', '숙박', 37.50518, 127.02591, '서울특별시 강남구 봉은사로 113', '6회에서 앤서니(음문석)은 고등학생 시절 이곳에서 반하니(이레)와 함께 사진을 찍었던 추억이 생각났다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08331', '엔투라지 바버샵', '관광지', 37.48301, 127.0445, '서울특별시 강남구 논현로26길 27', '알고있지만 2회에서 유나비(한소희)가 이 클럽에서 박재언(송강)과 합류했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08332', '트랙', '관광지', 37.551131, 126.9206, '서울특별시 마포구 잔다리로 20-5', '서지완(윤서아 분)은 3회에서 이 장소에서 소개팅과 함께 영화를 보고, 절친 윤솔(이호정 분)도 즐겼을 것이라고 말한다. ', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08333', '3917마중', '관광지', 35.0334303, 126.7107561, '전라남도 나주시 향교길 42-16', '조소과 MT 장소 촬영지였던 나주 한옥마을 복합문화공간', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08334', '홀통캠핑장', '관광지', 35.0605698, 126.3311024, '전라남도 무안군 현경면 홀통길 183', '유나비와 양도혁이 캠핑을 했던 해수욕장 캠핑장', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08335', '여수 전통시장', '쇼핑', 34.740533, 127.72817, '전라남도 여수시 서교동 중앙로3', '6, 7회에서는 유나비(한소희)가 양도혁(채종협)의 선배 준비를 도와주는 모습이 그려졌다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08336', '만성리 해수욕장', '관광지', 34.7773829, 127.736133, '전라남도 여수시 서교연등천길 43', '유나비와 양도혁이 자전거를 타고 돌아다닌 여수 데이트 장소', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08337', '토담순두부', '음식점', 37.791072, 128.910468, '강원도 강릉시 난설헌로193번길 1-19', '강릉 편에서 방문한 순두부 맛집', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08338', '벅수다찌', '음식점', 34.84091, 128.423783, '경상남도 통영시 동충2길 41-5', '멤버들이 모여 식사를 한 다찌 맛집', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08339', '심가네해물짬뽕', '음식점', 34.841566, 128.420668, '경상남도 통영시 서호동 163-35', '김영하가 방문한 짬뽕 맛집', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08340', '용궁 뚝배기', '관광지', 34.84182, 128.422232, '경상남도 통영시 통영시 항남3길 17', '유시민과 유희열이 방문한 해물 전문점', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08341', '경주 동궁원', '카페', 35.85071, 129.264506, '경상북도 경주시 북군동 보문로 74-14', '김영하가 방문한 루프탑 카페', '경주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08342', '카페오하이', '카페', 35.836533, 129.209768, '경상북도 경주시 황남동 포석로 1070', '<태백산맥> 소설 속 장소이자 <알쓸신잡> 촬영지', '경주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08343', '보성여관', '숙박', 34.8438889, 127.3433333, '전라남도 보성군 벌교읍 태백산맥길 19', '극중 유진우(현빈)가 이 호텔에 거주한다. 15화에서 진우가 치료받는 곳이고 같은 에피소드에서 차병준 교수(김의성)가 살해당하는 장소다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08344', '씨마크 호텔', '숙박', 37.79799, 128.9154, '강원도 강릉시 해안로406번길 2', '9, 10회에서 엠마의 기타 워크샵을 여는 정희주(박신혜) 할머니 오영심(김용림)의 한국 집으로 등장한다. ', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08345', '흥인지문', '관광지', 37.57112, 127.0096, '서울특별시 종로구 종로 288', '마지막 16회 엔딩 장면에서 정희주(박신혜)는 유진우(현빈)가 여기 있을 수 있습니다. 이 게이트 앞 횡단보도를 건너면 AR 게임 넥스트에 진입하고, 진우는 이 게이트 건너편에 있는 공원에서 넥스트에서 적들을 쏘고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08346', '황매산 군립 공원', '관광지', 35.495254, 127.97467, '경상남도 합천군 가회면 둔내리 산 219', '억새가 아름다운 암살 촬영지', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08347', '오웬 기념각', '관광지', 35.138288, 126.915896, '광주광역시 남구 백서로70번길 6', '암살을 촬영한 광주의 이국적 기념관', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08348', '한남 북엇국', '음식점', 37.53389, 127.008054, '서울특별시 용산구 독서당로 65-7', '암살 감독이 단골인 맛집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08349', '백인제 가옥', '관광지', 37.580639, 126.98407, '서울특별시 종로구 북촌로7길 16', '영화 암살속 강인국과 미츠코의 집', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08350', '압구정역', '관광지', 37.52639, 127.0285, '서울특별시 강남구 압구정로 지하 172', '1회에서 백야/백순동(박하나)은 백영준(심형탁)과 저녁 술 한잔하러 이 출구 앞에서 기다리고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08351', '물미수상레저', '관광지', 37.72464, 127.5238, '경기도 가평군 설악면 미사리로645번길 258', '이 다리(연꽃호수교)는 2007년 강신우(이정신)가 한지수(이열음)를 만나기로 했던 ''반딧불이 다리''로 등장한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08352', '쏠비치 삼척', '숙박', 37.47189, 129.1645, '강원도 삼척시 수로부인길 453', '1회에서 진욱은 아버지가 호텔 하나를 물려받아 일하라고 명령하고, 유미는 어머니의 두번째 결혼에 참석하기 위해 와서 차진욱(성훈)과 이유미(송지은)가 함께 머무르게 된다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08353', '삼척시 증산 버스정류장', '쇼핑', 37.4746, 129.1609, '강원도 삼척시 증산동 30-27', '1회에서 이 버스 정류장에 있었다. 차진욱이 차를 몰고 갔을 때 그녀는 삼각 김밥을 먹으려 하고 있었다. 그는 멈춰 서서 그녀를 태워 주었다. 두 사람은 다시 말다툼을 했지만 유미는 버스가 멈춘다는 소식을 듣고 진욱의 차에 탔다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08354', '카나', '관광지', 37.5405946, 126.942816, '서울특별시 마포구 토정로 303', '박진겸(주원) )과 윤태이(김희선)는 5,6회에서 이곳에서 만나 술을 마시며 이야기를 나눈다. 태이는 이곳에서 진겸에게 자신의 어린 시절을 이야기한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08355', '청담배수지공원', '관광지', 37.521, 127.0615, '서울특별시 강남구 삼성동 79-1', '10화에서 탁동경(박보영)은 밤에 멸망(서인국)의 생일을 축하하기 위해 멸망(서인국)을 이 공원으로 데려온다. 14화에서 두 사람은 이 공원의 다른 부분에 와서 다시 사랑을 확인한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08356', '딜라이트 스퀘어 감성타코 합정점', '음식점', 37.54967, 126.9122, '서울특별시 마포구 월드컵로1길 14 지하1층', '6회에서 멸망(서인국)이 탁동경(박보영)의 소개팅을 이 ''아시안 퓨전 펍'' 지점에서 충돌시킨다. 그리고 그 자리에 있던 다른 두 명을 잠들게 한 후 상황에서 그녀를 끌고 나왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08357', '미스터케이무지개문구', '관광지', 37.43863, 126.6713, '인천광역시 미추홀구 매소홀로446번길 22', '6회에서 이 가게 앞에서 만난 멸망(서인국)과 소녀신(정지소). 그리고 탁동경(박보영)에 대한 그의 사랑이 잘 될 것인지 묻는다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08358', '카페 913', '카페', 37.44762, 126.6519, '인천광역시 미추홀구 소성로 20', '멸망(서인국)은 탁동경(박보영)을 이 카페에 데려온다. 13화에서 그녀에게 소녀신(정지소)을 만났는지 묻는다. 그녀는 ''사람''이라는 이름으로 저장한 특정 번호로 최근에 전화를 거는 음성을 그에게 알려준다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08359', '벤처로', '관광지', 37.37349, 126.6445, '인천광역시 연수구 벤처로100번길 34', '탁동경(박보영 분)이 운명을 결정하는곳 바로 앞 횡단보도다. 1-2화에서 도착한 ''운명의 트럭'' 앞에서 멸망과 손을 잡는다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08360', '자유공원남로', '관광지', 37.47403, 126.6236, '인천광역시 중구 자유공원남로 35', '6-7화에서 이 거리로 이어지는 계단을 오르면 탁동경(박보영)이 멸망(서인국)은 그녀와 사랑에 빠졌고, 그 전에 키스로 대답했다. 그리고 그는 갑자기 사라집니다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08361', '까페돔바니', '관광지', 37.47676, 126.6204, '인천광역시 중구 자유공원서로 27', '탁동경(박보영)과 그녀의 남동생 탁선경(다원)은 이 집 옥상 아파트에 산다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08362', '바보라면', '음식점', 33.54162, 126.8312, '제주특별자치도 제주시 구좌읍 해맞이해안로 1016 바보라면', '11회에서 탁동경(박보영)과 멸망(서인국)은 이 식당에서 점심을 먹는다. 그리고 그는 그녀가 평소처럼 잔소리 하는 것에 놀란다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08363', '한담해안산책로', '관광지', 33.45463, 126.3074, '제주특별자치도 제주시 애월읍 곽지리 1359', '5화에서 멸망(서인국)은 동경(박보영)에게 어리둥절해 하며 그녀를 관찰하고 그녀를 알아내려 한다. 한동안 그녀를 따라다니던 그는 그녀가 슬픔의 무거운 짐을 지고 있다는 것을 깨닫고 그녀의 짐을 가볍게 하고 싶어한다. 그가 그녀의 눈을 가리고, 해안 산책로를 따라 자리잡은 제주도의 동경의 특별한 해변으로 그녀를 이끈다. 그녀는 그녀가 어렸을 때 매일 이곳에 와서 울고 싶었다고 말하고, 그녀의 어린 시절 이야기를 공유한다. 그들은 어색하게 키스를 하고는 아무일도 일어나지 않은 것처럼 집에 돌아온다. 이후 10화와 11화에서 동경이 서울을 떠나면서 가족과 친구들을 그리워하며 이곳에서 그녀를 발견하게 되고, 그녀는 마침내 헤어지고 자신의 소원이 사는 것임을 인정한다. 멸망은자신도 살고 싶고, 마지막까지 동경과 함께 하고 싶다고 고백한다.', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08364', '말로나스테이', '관광지', 33.44607, 126.2949, '제주특별자치도 제주시 한림읍 귀덕11길 29', '10회와 11회에서 탁동경(박보영)은 고향 제주도로 도망친다. 그녀는 이모 강수자(우희진)가 “언제나 살 집”을 위해 남겨준 이 별장에 머물고 있다. 그녀를 발견한 멸망(서인국)은 자신의 정신 건강을 걱정하며 가족과 가장 친한 친구에게 자신의 위치를 알리고 그녀를 지원하기 위해 도착한다', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08365', '서울 본동 단독주택', '관광지', 37.510387, 126.95657, '서울특별시 동작구 노량진로32길 78', '1회 김현수(김수현)와 홍국화(황세온)는 아이스크림 가판대에서 식사를 한 후 이 공원에서 한강 파라다이스를 지나쳐 달려간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08366', 'CGV 압구정점', '관광지', 37.52429, 127.0294, '서울특별시 강남구 신사동 602', '3회에서 이도하(이상윤)와 최미카(이성경)가 영화를 관람했다. 그녀는 필사적으로 그의 손을 만지려고 노력하며, 그녀의 ''자연 시계''가 그를 만질 때 정말로 위쪽으로 카운트하는지 확인한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08367', '투썸플레이스 세관사거리점', '카페', 37.51581, 127.035, '서울특별시 강남구 언주로 703', '11회에서 이도하(이상윤)와 베스(임세미)가 이 카페에서 만나 마침내 그의 청혼을 받아들인다. 그러나 도하는 그녀에게 더 이상 결혼할 생각이 없다고 말하고 다시 만나지 말라고 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08368', '뷰티앤뷰빌딩', '관광지', 37.56219, 126.9216, '서울특별시 마포구 연남로 29', '13회에서 배수봉(임세미)과 이도하(이상윤)가 만나는 곳이다. 도하는 그녀에게 만나자고 전화를 걸어 가족들의 결혼식을 취소하자고 한다. 그는 그녀가 이미 거절을 했는데도 왜 계속 결혼을 고집하는지 묻는다. 그녀는 그가 정말로 그녀와 결혼하고 싶지 않다면 그가 가진 모든 것을 포기하고 도망갈 수 있다고 말합니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08369', '국립민속박물관', '관광지', 37.51369, 127.0605, '서울특별시 종로구 삼청로 37', '6화에서 이 버스 정류장을 향하는 박물관 이름이다. 이도하(이상윤)의 집에서 나가라는 베스의 경고가 생각난다. 이 버스 정류장에서 도하는 그녀에게 전화를 걸었지만 그녀가 받지 않아 그녀가 어디에 있고 왜 그의 전화를 받지 않는지 묻는 문자를 보낸다. 그녀는 그의 회사 건물 근처 버스 정류장에 있다고 거짓말하지만 실제로는 그가 있는 곳에 있습니다. 그는 그녀의 손을 잡고 그들은 함께 버스를 타고 집으로 돌아갑니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08370', '비와별닭갈비 본점', '음식점', 37.849816, 127.748959, '강원도 춘천시 스무숲길 5', '어서와 한국은 처음이지 16회에서 찾은 춘천닭갈비', '강원');
