INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08377', '임피리얼팰리스부티크호텔', '숙박', 37.535291, 126.99835, '서울특별시 용산구 이태원로 221', '어서와 한국은 처음이지 독일편 이태원 숙소', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08378', '옥정호 구절초테마공원', '관광지', 35.55317, 127.0191, '전라북도 정읍시 산내면 매죽리 571', '22회(전체 11회)에서 하루(로운)은 고려시대의 추억을 기억하고, 그는 백경(이재욱)이 은단오(김혜윤)를 이 공원으로 데려온 방법과 또 다른 시간에 백경의 배우자로 그녀를 어떻게 동행하는지 기억한다.', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08379', '두일약초마을', '관광지', 37.688419, 128.560323, '강원도 평창군 진부면 방아다리로 348', '샤오가 나온 아재목장에 배경이 된 마을', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08380', '버찌와 타로여행', '관광지', 37.515252, 127.102476, '경기도 하남시 미사강변동로 121 더랜드시티 315호', '업텐션이 콘서트에 쓴 서프라이즈 촬영', '경기');
