INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08384', '코드이스케이프 대구점', '관광지', 35.858603, 128.641766, '대구광역시 수성구 달구벌대로 2552', '에릭남이 우결 출연 당시 방문했던 방탈출카페', '대구');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08385', '샌드커피 논탄토', '카페', 37.520876, 127.023907, '서울특별시 강남구 도산대로17길 35', '에릭남이 터키식 커피를 마시기 위해 방문했던 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08386', '보보리스네트웍', '관광지', 37.52319, 127.03452, '서울특별시 강남구 언주로154길 14', '에릭남이 이용하는 청담의 샵', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08387', '규방도감', '음식점', 37.58151, 126.981464, '서울특별시 종로구 북촌로5가길 44-5', '에릭남이 예능 촬영을 위해 운영한 식당이 있던 곳', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08388', '남산골한옥마을', '관광지', 37.559307, 126.994476, '서울특별시 중구 퇴계로34길 28', '에릭남이 무도투어에서 통역사로 함께 투어했던 곳', '서울');
