INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08390', '1913 송정역 시장', '쇼핑', 35.1364035, 126.791996, '광주광역시 광산구 송정로8번길 13', '에버글로우LAND에서 아샤와 이런이 간 곳', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08391', '갱소년', '카페', 35.136559, 126.79221, '광주광역시 광산구 송정로8번길 7-4', '아샤와 이런이 방문한 젤리양갱 디저트 카페', '광주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08392', '수서역', '관광지', 37.487472, 127.101321, '서울특별시 강남구 밤고개로 99 수서역사', '아샤와 이런이 미션을 수행하기 위해 간 곳', '서울');
