INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08425', '소무의도 인도교', '관광지', 37.37399, 126.4392, '인천광역시 중구 무의동 산369', '19회에서 윤수완(구혜선)이 자전거를 타고 소무의도에서 마을 노인들을 섬기는 다리를 건넜다.', '인천');
