INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08427', '명봉역', '관광지', 34.827785, 127.075526, '전라남도 보성군 노동면 예재로 384', '13회에서 이수호(아스트로 차은우)가 임주경(문가영)을 찾아 공원길을 달리는 모습', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08428', '킨텍스 온누리공원', '관광지', 37.66326, 126.7464, '경기도 고양시 일산서구 대화동 2721', '7화에서 고장난 엘리베이터를 탈출하고 급히 화장실로 달려간 임주경(문가영)은 이 건물에서 나와 눈이 내리기 시작했다는 것을 알게 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08429', '현대프리미엄아울렛스페이스원', '쇼핑', 37.61632, 127.1521, '경기도 남양주시 다산순환로 50', '드라마에서에서 이수호(차은우)가 사는 곳입니다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08430', '설리스카이워크', '관광지', 34.70878, 128.0226, '경상남도 남해군 미조면 송정리 산352-4', '14회에서 이수호(아스트로 차은우)와 임주경(문가영)이 데이트를 하러 왔다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08431', '성산빌딩', '카페', 37.52584, 127.0389, '서울특별시 강남구 도산대로53길 39', '마지막회 16회에서 임주경(문가영)과 한서준(황인엽)은 이 카페에서 의기투합한다. 진정한 미녀/여신강림(tvN, 2020-21)의 여신강림(여신강림)에서 그녀는 자신의 감정에 보답하지 못한 그에게 사과하고, 그녀를 혼란스럽게 만든 그는 차례로 사과하는 모습을 보여준다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08432', '하노', '관광지', 37.56376, 126.9235, '서울특별시 마포구 동교로41길 32', '11회에서 회상으로 이수호(아스트로 차은우), 한서준(황인엽), 정세연(강찬희/SF9 찬희)이 가게 밖에서 물건을 둘러보는 모습이 나온다. 세연은 그들 모두를 위해 팔찌를 선택하고, 수호와 서준에게 항상 착용해야 한다고 말한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08433', '공룡슈퍼 홍대점', '음식점', 37.55027, 126.9225, '서울특별시 마포구 와우산로17길 10', '15회에서 새봄고 동문들이 이 식당에 모여 식사를 하고 있다. 임주경(문가영)이 술에 취해 기절하자 한서준(황인엽)이 나타나 그녀를 도왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08434', '피카디리국제미술관', '관광지', 37.570962, 126.99117, '서울특별시 종로구 돈화문로5가길 1', '4회에서 임주경(문가영)은 영화를 보기 위해 대학 데이트를 하고 이 영화관에 온다. 이수호(아스트로 차은우)는 두 사람을 알아보기 위해 같은 영화관에 왔지만, 결국 다른 커플로 착각하게 된다. 건물 밖에서 수호는 이미 다른 사람을 만나고 있던 주경의 대학 시절이 거짓말을 했다는 사실을 알게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08435', '남도분식 익선점', '음식점', 37.57315, 126.9901, '서울특별시 종로구 수표로28길 33', '9회에서는 화보 촬영 후 임주경(문가영)이 한서준(황인엽)에게 식사를 대접하는 모습이 그려졌다. 그들이 떠날 때 서준은 주경을 집에 데려다 주겠다고 제안한다. 하지만 그녀는 이미 이수호(차은우)와 통화 중이어서 눈치채지 못했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08436', '창의문로', '관광지', 37.59043, 126.9705, '서울특별시 종로구 청운동', '2회에서 임주경(문가영)은 그녀를 지나칠 때 이 거리에 위치한 (가짜) 버스 정류장에서 버스를 기다립니다. (그녀의 외모에 매료된) 버스에 있는 남자들은 운전사가 버스를 멈출 수 있도록 주의를 집중시켜 그녀가 여전히 들어갈 수 있도록 관리합니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08437', '거북이슈퍼', '음식점', 37.573427, 126.98945, '서울특별시 종로구 수표로28길 17-25', '3번째 예고편에서 이수연(이제훈 분)이 이 식당 앞을 지나간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08438', '마이포에트리', '음식점', 37.572915, 126.989821, '서울특별시 종로구 수표로28길 23', '이곳의 외관은 한여름(채수빈)의 아버지 한재영(최원영)이 운영하던 예전 술집 ''여우각시별''로 현재는 장씨의 식당, 집, 진료소로 변신했다. 이수연(이제훈)의 은밀한 곳이었다. 어린 시절 ''형'' 서인우(이동건)와 함께 이곳에 자주 왔던 청년(남다름)이 한여름(채수빈)의 모습을 본 곳이기도 하다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08439', '오이도빨강등대', '관광지', 37.345438, 126.68744, '경기도 시흥시 오이도로 175', '2회에서 고병희(고현정)가 오고 등대 앞에서 석양을 바라본다.', '경기');
