INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08453', '섬진강 기차마을', '관광지', 35.279115, 127.307561, '전라남도 곡성군 오곡면 기차마을로 232', '이 대학의 일부는 ''한얼체육대''로 등장.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08454', '라부티크블루', '관광지', 37.53787, 126.9989, '서울특별시 용산구 이태원로55길 45', '3화의 역도요정 김복주(역도요정 김복주) 내 이 건물에 정재이(이재윤)가 운영하는 ''제이비만클리닉''이 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08455', '옥순봉', '관광지', 36.93968, 128.2393, '충청북도 제천시 수산면 옥순봉로 342', '3회에서 김복주(이성경) 대학이 등반 경주를 벌이던 곳. 복주는 의사재이(이재윤)의 프로그램에 등록하기 위해 가장 먼저 산에 오른 사람의 상금을 타기 위해 열성적으로 시작했고 심지어 친구들을 버리고 떠났다. 불행히도 정준형(남주혁)은 그녀를 발견하고 그녀를 따라가서 그녀를 놀리다가 정상에 오르던 도중 복주를 결국 경주에서 지게 만들었습니다.', '충북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08456', '죽주산성', '관광지', 37.08915, 127.4316, '경기도 안성시 죽산면 죽양대로 111-71', '이곳은 왕세자 이휘(박은빈)의 비밀 장소이자 6화에서 자은/이현(남윤수)이 합류하는 곳이다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08457', '이태사랑바위', '관광지', 35.758791, 127.8482068, '경상남도 거창군 위천면 황산리 40-1', '두 주인공이 재회 후 처음 만난 기억이 담긴 장소', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08458', '거창 이태 사랑바위', '쇼핑', 35.75816, 127.8343, '경상남도 거창군 위천면 황산리 산40-1', '3회에서 정지운(로운)과 이휘세자(박은빈)는 이 절벽에서 왕실 근위병들에게 궁지에 몰리다 탈출하기 위해 아래의 강으로 결국 뛰어내린다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08459', '성주한개마을', '관광지', 35.9284529, 128.325599, '경상북도 성주군 월항면 한개2길 8-5', '1,2회에서 어린 정지운(고우림)이 어린 담이(고우림)를 찾는 모습에서 볼 수 있듯이, 이곳은 궁녀들의 숙소로 보인다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08460', '원과호펜션', '숙박', 37.786099, 126.699964, '경기도 파주시 탄현면 헤이리마을길 48-99', '연애의 발견에서 둘러본 예쁜 펜션', '경기');
