INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08463', '산장', '관광지', 37.550582, 126.9236, '서울특별시 마포구 와우산로18길 10 1층', '술에 취한 전 남자친구 강태하(에릭)는 한여름(정유미)에게 새로운 사랑을 고백하고, 그녀는 나중에 친구들에게 남하진(성준)을 남자친구로 소개한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08464', '카페 자유인들', '카페', 37.55098, 126.9241, '서울특별시 마포구 와우산로22길 34', '10화에서 화난 강태하(에릭)가 친한 친구 윤정목(이승준)과 함께 대전 야구장 홍대에 찾아온다. 정목이 마침내 태하에게 그만하라고 설득했을 때, 둘은 그 곳 바로 앞 거리에서 진심 어린 이야기를 나눴다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08465', '애쉬&블룸', '관광지', 37.55602, 126.9275, '서울특별시 마포구 와우산로29길 48-15', '1회 회상회에서는 한여름(정유미)과 강태하(에릭)가 한 겨울에 이곳에 찾아온 모습이 그려졌다. 그녀는 그에게 선물로 나무 커플링 한 쌍을 줍니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08466', '엔터식스 왕십리역점', '관광지', 37.56203, 127.0384, '서울특별시 성동구 왕십리광장로 17', '9화에서 한여름(정유미)과 강태하(신화 에릭)가 만난 후 점심을 먹기 위해 이 쇼핑몰에 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08467', '카페아라', '카페', 37.558389, 126.607463, '인천광역시 서구 정서진  651로 41 24층', '연애의 발견에서 이승준,정수영이 간 식당', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08468', '게스트하우스 파자마파티', '숙박', 37.5649, 126.92368, '서울특별시 마포구 성미산로 157-6', '1회에서 공유영(박지훈)이 이 게스트하우스로 이사한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08469', '정동진역', '관광지', 37.69142, 129.0329, '강원도 강릉시 강동면 정동역길 17', '2회에서 한유경(한승연)이 12일 오전 동작대교에서 일출을 찍기 위해 이 버스 정류장에서 내린다. 2010년 서울에서 4일간의 짧은 체류 셋째 날의 장면이다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08470', '동작대교전망카페', '카페', 37.50583, 126.9803, '서울특별시 동작구 동작동 316-3', '이곳은 이백만(장현성)이 운영하는 게스트하우스 ''재회''로 등장한다. 거의 다 여기에서 하룻밤 묵는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08471', '북촌마을안내소', '관광지', 37.57954, 126.9832, '서울특별시 종로구 북촌로5길 48', '10회에서 ''운좋은 드라이클리닝''으로 등장한다. 윤찬(김도완)은 ''절친'' 천다영(한다솔)과 함께 어머니에게 생일 선물로 받은 니트 스웨터를 이곳에서 드라이클리닝한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08472', '올리바가든', '관광지', 37.57757, 126.97252, '서울특별시 종로구 자하문로 16', '4회에서는 절친 강석(김영준)과 이 곳을 거닐며 서울에 머물기로 한 차현오(신현수)와 강석이 찾아온다. 강석은 여자들과도 1년이 지나면 서울에서 다시 만나기로 약속했기 때문에 현오의 상황을 잘 알고 있다고 말한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08473', '럭키크리닝상사', '관광지', 37.58131, 126.9892, '서울특별시 종로구 창덕궁길 85', '4회에서 차현오(신현수)는 명동에서 식사와 오후 시간을 보낸 후 이 역 6번 출구에서 친구 박선주(한지은)에게 작별 인사를 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08474', '마를리', '카페', 37.54269, 127.0547, '서울특별시 성동구 연무장길 47', '1회에서 유수빈(김향기)은 친구들과 방과 후 카페에 찾아와 친구들과 수다를 떨고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08475', '무니', '카페', 37.547168, 126.983921, '서울특별시 용산구 신흥로20길 37', '여기는 최준우(옹성우)와 유수빈(김향기)는 12회에서 두 사람은 데이트를 위해 이 카페 옥상에 왔는데, 준우가 키스를 하려고 하자 수빈의 아버지가 전화를 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08476', '삼경빌딩', '관광지', 37.556741, 126.99589, '서울특별시 중구 필동로 53 라비두스 별관 3층/루프탑', '12회에서 그는 그녀에게 이혼을 요구하지만 그녀는 이를 거절한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08477', '킨텍스로 육교', '관광지', 37.66714, 126.7524, '경기도 고양시 일산동구 장항1동 킨덱스로 1043-1', '38회 초반, 결연한 김해일(김남길)이 이 고가도로를 걸어 이중권(김민재)과 맞붙는다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08478', '대영로243번길', '관광지', 35.11505, 129.0387, '부산광역시 동구 중앙대로195번길 14', '이 거리는 극 중 파트너 형사 구대영(김성균)과 서승아(금새록)의 주 관할로 부분적으로 등장한다.', '부산');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08479', '차이룡', '음식점', 37.519404, 126.903561, '서울특별시 영등포구 영등포로36길 8', '태국 청년 안창환이 근무하던 중식당', '서울');
