INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08655', '뽀모도로', '관광지', 37.668444, 126.77508, '경기도 고양시 일산동구 대산로11번길 5-21', '엘리베이터 키스로 유명해진 도서관이다. 4회에서 김붕도(지현우)와 최희진(유인나)이 자신의 시대를 읽기 위해 찾아온다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08656', '다성빌딩', '카페', 37.553145, 126.92562, '서울특별시 마포구 와우산로 110', '5회에서 최희진(유인나)은 매니저 조수경(가득희)과 함께 카페에 앉아 있다. 휴대폰으로 김붕도(지현우)에게 걸려온 전화. 수경은 처음에 전화를 받지 말라고 경고했지만 희진은 결국 전화를 받고 그가 제주도에 있다는 것을 알게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08657', '트루텍빌딩', '관광지', 37.581081, 126.88797, '서울특별시 마포구 월드컵북로56길 12', '1회에서 최희진(유인나)은 오디션에 한 시간 늦었다고 생각하며 이 건물로 달려간다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08658', '기찻길주점', '관광지', 37.52507, 126.9606, '서울특별시 용산구 이촌로29길 35', '길공태 그는 2화에서 술을 마시러 왔다가 9화에서 두 자녀와 함께 이곳으로 돌아옵니다. 마지막 16화에서 그와 장순결(윤균상)은 여기에서 하트 투 하트 이야기를 나눕니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08659', '카페파랑돌', '카페', 37.474689, 126.62577, '인천광역시 중구 송학로 53', '13회에서 일리의 여동생 김이리(한의덤)가 일하는 김일리(이시영) 친구가 운영하는 카페', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08660', '동안교', '관광지', 37.39816, 127.10962, '경기도 성남시 분당구 삼평동 동안교', '육교를 건너야 한다는 이지혜(강말금)에게 다리를 함께 걸을 때 김안나(고원희)는 제안한다.  그러나 그들은 ''고가도로''가 다리의 한쪽 끝에서 다른 쪽 끝으로만 이동한다는 것을 알고, 기묘한 상황에 웃으면서 다리가 내려다보이는 공원의 풍경을 감상하기 위해 잠시 멈춰 선다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08661', '우림WCITY', '쇼핑', 37.403959, 127.09996, '경기도 성남시 분당구 판교로255번길 9-22', '김안나(고원희)가 일하는 온라인 리테일 플랫폼 ''우동시장''의 사무실이 위치한 건물이다.', '경기');
