INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08669', '염해등대', '쇼핑', 34.863793, 127.810929, '경상남도 남해군 서면 노구리 산174-2', '왕정애(강혜정)와 아들 건우(정준원)가 살았던 곳이다. 15회에서 황보율(이원근)이 휴가를 마치고 찾아온다. 그가 그녀의 집에서 장면을 만들고 있다는 사실에 불만을 품은 정애는 일어나서 자리를 떴고, 율은 그녀를 뒤따랐다. 밖에서 이야기를 나누는 동안 황보 일가의 간부는 몰래 그들의 대화를 지켜본다.', '경남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08670', '아프리카박물관', '관광지', 33.239688, 126.42943, '제주특별자치도 서귀포시 이어도로 49', '9회에서 좌윤이(백진희)가 설날에 남치원(최다니엘)을 찾으러온 곳', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08671', 'DW 디자인 레지던스', '관광지', 37.558374, 126.92058, '서울특별시 마포구 동교로25길 35', '이 집에는 좌윤이(백진희)가 살고 있다. 3화에서 남치원의 상사가 옥상으로 이사를 온다. 알고 보니 이곳은 사고로 가족이 사망한 후 삼촌과 함께 살았던 어린 시절 집이었다. 치원은 어린 시절 집에 불이 났을 때 삼촌의 죽음을 목격한 과거의 트라우마와 맞서고 극복하기 위해 이사를 가기로 했다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08672', '지중해마을', '관광지', 36.797302, 127.06058, '충청남도 아산시 탕정면 탕정면로8번길 55-7', '1회(전체 1회) 우도희(서지혜)는 시작 부분에서 클래식 영화 ''티파니에서 아침을 먹으며'' 가장 좋아했던 장면에 대해 이야기한다.', '충남');
