INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08811', '서달산', '관광지', 37.497352, 126.961819, '서울특별시 동작구 흑석동 서달로', '정용화의 우결신혼집 주변에 나온 뒷동산', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08812', '서삼릉길', '카페', 37.654558, 126.87629, '경기도 고양시 덕양구 서삼릉길', '10회에서 이솜(E-som) 이영재와 온준영이 두 번째로 이별하는 장면이 나온다. 방금 일어난 일을 부인한 준영은 영재를 카페로 데려오고 싶어 화제를 돌리거나 상황을 진정시키려 한다. 그는 거리에 있는 여러 카페로 달려가지만 그곳에 도달하면 각 카페의 불을 끕니다. 그 순간 영재는 그들의 시즌이 끝났다는 것을 알았다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08813', '비안코이탈리아 청담점', '카페', 37.525621, 127.04739, '서울특별시 강남구 도산대로81길 19', '6회에서 암벽등반을 마친 백주란(이윤지 분)과 강철남(이하율 분)은 이곳 ''펫카페''로 식사를 하러 온다. 주란은 운동이나 애완동물에 대해 특별히 관심이 있는 것은 아니지만 철남이가 그 이야기를 꺼낼 때면 그들에게 관심이 있는 척한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08814', '브라이덜공', '관광지', 37.525654, 127.0413, '서울특별시 강남구 선릉로158길 15 1층', '4회에서 이영재(이솜)가 홍 디자이너(최병모)의 쇼케이스 헤어 디자인에 대해 논의하기 위해 이곳을 찾았다. 그곳에서 그녀는 김소희(신도현)가 이벤트의 메인 모델임을 알게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08815', '노박빌딩', '관광지', 37.546264, 126.91262, '서울특별시 마포구 성지길 58', '13회에서 공개된 현재 온리원(박규영 분)의 부동산 사무실 외관이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08816', '3rd뮤지엄', '쇼핑', 37.551639, 126.91912, '서울특별시 마포구 잔다리로3길 4', '10회에서 강력범죄3팀은 이 가게를 몰래 찾아오는 ''스네이크헤드''라는 수배범을 잡기 위해 이 가게를 측설합니다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08817', '성우빌딩', '관광지', 37.566166, 127.00125, '서울특별시 중구 을지로36길 12', '8회에서 강력범죄단이 내세우는 ''스카라'' 당구장이 위치한 건물로 민세은 경관(김윤혜) 잠입. 측설 중 준영은 오랜만에 수배범 ''뱀머리''를 잡을 수 있을지가 불안해 영재(이솜)에게 전화를 걸어 그녀의 목소리를 듣게 된다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08818', '외포리선착장', '관광지', 37.700637, 126.38152, '인천광역시 강화군 내가면 해안서로 883', '9회에서 주랑 드 보떼와 HC 성형외과 팀이 자원봉사 목적지로 가는 페리에 탑승하기 전에 이곳에서 만난다. 온준영(서강준)는 이영재(이솜),백주란(이윤지), 이수재(양동근), 최호철(민우혁)을 따라 이 여정에 합류한다.', '인천');
