INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08903', '아틀리에', '관광지', 37.535036, 126.9933, '서울특별시 용산구 이태원로27가길 36', '5회에서 진정(도경수/디오)과 그의 팀은 이 클럽애서 마약 조직원을 추적한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08904', '서운산자연휴양림', '관광지', 36.9422, 127.31372, '경기도 안성시 금광면 배티로 185-39', '8회에서 법무법인 올웨이즈 팀이 워크숍을 위해 찾아왔다. 권정록(이동욱)과 오윤서(유인나)는 잠을 이루지 못하고 우연히 숙소 밖에서 만나 첫키스를 하게 된다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08905', '목우촌가든', '음식점', 37.520414, 126.93039, '서울특별시 영등포구 여의대방로67길 18 스타빌딩', '최종회 16회에서 오윤서(유인나)의 드라마 ''사랑은 아파요''의 출연진과 제작진이 이 바베큐 식당에서 랩 파티를 가졌다.', '서울');
