INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08907', '구리 한강 시민공원', '관광지', 37.574523, 127.136239, '경기도 구리시 코스모스길14번길 249', '질투의 화신에서 공효진이 일기예보 찍은 공원', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08908', '구리시민한강공원', '관광지', 37.575383, 127.14016, '경기도 구리시 토평동 829', '이곳은 코스모스 꽃 축제가 열리는 곳으로, 13회에서 표나리(공효진)가 일기예보를 촬영하라는 지시를 받은 곳이다. 결국 아나운서 테스트 캐스팅에 참여하지 못함에도 불구하고, 이화신(조정석)은 나리가 제시간에 SBC 방송국에 도착할 수 있도록 헬리콥터로 그녀를 태운다', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08909', '물빛문화공원', '관광지', 37.579633, 126.89341, '서울특별시 마포구 상암동 1609', 'SBC 빌딩에서 일하는 모든 사람들이 퇴근 후 앉아서 술을 마시는 포장마차, 이 공원의 북동쪽에 SBS 프리즘타워가 마주보고 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08910', '홍익숯불갈비소금구이', '음식점', 37.556232, 126.92621, '서울특별시 마포구 어울마당로 146-1', '7회 마지막에서 표나리(공효진), 이화신(조정석), 고정원(고경표)이 식사를 하고 있다.', '서울');
