INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08913', '갤러리아백화점 WEST점', '쇼핑', 37.528406, 127.04007, '서울특별시 강남구 압구정로 343', '극중 의뢰인(건물 벽화를 그려준 청년)의 아버지, 사라진 화가가 평소 좋아하는 곳이라 그림으로 그렸다는 연못', '서울');
