INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08918', '병산서원', '관광지', 36.54056, 128.55275, '경상북도 안동시 풍천면 병산길 386', '김소용(신혜선)과 철종(김정현)은 이곳에서 차를 마시다 스핀킥으로 침입자로부터 자신을 보호하는 모습에 심장이 조금 뛴다.', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08919', '최인아 책방', '관광지', 37.506026, 127.047895, '서울특별시 강남구 선릉로 521', '6회에서 윤태오(지수)는 류세현(홍지윤)과 함께 책을 사기 위해 온다. 여기에서 세현은 아버지 태오에게 출판된 사진집을 보여주며 지혜의 진주 중 하나를 공유한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08920', '전원빌딩', '카페', 37.550197, 126.92324, '서울특별시 마포구 와우산로 64', '윤태오(지수)가 선배에게 괴롭힘을 당하는 한송이(정채연)를 구한 후, 둘 다 9회에서 술을 마시러 카페로 향한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08921', '빽다방 신사사거리점', '카페', 37.515833, 127.01927, '서울특별시 서초구 강남대로 605 휴먼타워 1층', '첫사랑은 처음이라서의 4화에서 윤태오(지수)는 한송이(정채연)를 쫓는다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08922', '인왕산 한양도성산책로 계단', '관광지', 37.577928, 126.96162, '서울특별시 종로구 무악동 통일로18나길', '6회에서 긴 스쿠터를 탄 후 윤태오(지수)와 서도현(진영)이 이곳에 들러 담소를 나눴다.', '서울');
