INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08925', '달맞이근린공원', '관광지', 37.543241, 127.02081, '서울특별시 성동구 금호동4가 27', '14회에서는 사혜준(박보검)이 부자 친구 원해효(변우석)에게 자신의 삶에 대해 이야기하는 모습이 그려졌다. 16화에서 혜준은 다시 옥상에 올라가 그 아래 펼쳐진 한남동을 바라보며 자신이 꿈을 이뤘음을 깨닫고 마지막으로 해야 할 일인 입대를 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08926', '혜성마켓', '관광지', 37.533395, 126.99895, '서울특별시 용산구 대사관로6길 32', '1회에서 사혜준(박보검)은 친구 김진우(권수현)를 속여 저녁 조깅을 하게 된다. 이 동네에 사는 이 건물을 지나갈 때, 원해효(변우석)와 합류한다.', '서울');
