INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08935', '플레이스 캠프', '관광지', 33.450048, 126.91844, '제주특별자치도 서귀포시 성산읍 동류암로 20', '체리블렛 멤버들이 캠핑을 즐긴 곳', '제주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08936', '노량진 수산시장', '쇼핑', 37.515417, 126.94083, '서울특별시 동작구 노들로 674', '지원과 메이가 방문한 소품샵', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08937', '봄밤달', '관광지', 37.579569, 126.969924, '서울특별시 마포구 성미산로 172 1층', '21화(전체 11화)에서 기대주(구자성)가 캡핑 낚시 여행을 오고 베로니카 박(김재경)이 그의 마음을 얻기 위해 서프라이즈로 합류한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08938', '정도리구계등', '관광지', 34.297867, 126.70842, '전라남도 완도군 완도읍 정도리 152', '12회에서 문차영(하지원)이 이강(윤계상)을 기다리며 벤치에서 잠드는 ''해변공원''이다. 그가 그녀를 찾으러 왔을 때, 그녀는 여전히 자고 있다. 그는 그녀를 재킷으로 덮고 그녀가 깨어날 때까지 4시간 동안 어깨에 기대고 계속 자게 한다.', '전남');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08939', '거진해수욕장', '관광지', 38.443074, 128.45517, '강원도 고성군 거진읍 거진리 22-59', '16회에서는 현수(윤정일)가 어머니(이항나)에게 강수(고경표)의 집에 있는 이유를 놓고 대립하는 장면이 그려졌다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08940', '거탄진로209번길', '쇼핑', 38.448897, 128.46331, '강원도 고성군 거진읍 거탄진로209번길 5-4', '16회에서 회사의 생계를 위협하는 큰 어려움에 직면한 후 위안을 찾기 위해 최강수(고경표)가 고향으로 돌아온다. 이단아(채수빈)는 서울로 돌아가라고 설득하기 위해 찾아오고, 그의 어머니(이항나)도 그의 상황을 듣고 몰래 그를 방문하려 한다.', '강원');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08941', '우리동네슈퍼', '쇼핑', 37.647812, 126.78913, '경기도 고양시 일산동구 강송로88번길 7-1', '4회에서 강수(고경표)는 마트 밖에서 공지(김기두)와 그의 부하들을 만난다. 공지는 강수를 한양 설렁탕에서 만찬에 초대하여 그를 환영한다. 그러나 강수는 그에게 한양이 임시로 문을 닫았다고 알린다. 이어 주인의 손자인 현수(윤정일)의 사고 소식을 전한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08942', '하우정숯불구이', '음식점', 37.201256, 127.07328, '경기도 화성시 노작로 149', '이 식당은 최강수(고경표)의 주적 역으로 ''정패밀리 설렁탕''의 한 지점으로 등장한다. 이지윤(고원희)의 어머니가 운영하는 체인으로, 오진규(김선호)가 6회부터 지점장으로 일하다가 11회에서 그만둔다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08943', '동탄반송길', '관광지', 37.209463, 127.06384, '경기도 화성시 동탄반송길', '5회에서는 최강수(고경표)와 배달부들이 현수(윤정일)의 히트작을 알아보기 위해 거리를 행진하는 모습이 그려졌다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08944', '매향리평화역사관', '관광지', 37.047902, 126.76345, '경기도 화성시 우정읍 기아자동차로 199', '12회에서 최강 배달꾼 팀이 민찬(허지원)의 고향인 매향리에서 MT를 하던 중 이곳에 들렀다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08945', '팔선생 중화요리', '음식점', 37.528607, 127.12463, '서울특별시 강동구 성내로8길 9-19', '동네 배달부 단장 백공기(김기두)의 본거지인 중국집 ''성국''이다. 1회 말과 2회 초반에 최강수(고경표)와 대결을 펼치는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08946', '이수연플라워', '관광지', 37.540148, 127.12761, '서울특별시 강동구 천호대로157길 53', '이곳은 16회에서 성재(김경남)가 고객층을 확대한 후 배달을 위해 꽃을 줍던 꽃집이었다. 배달을 좀 더 친절한 얼굴로 받아 달라는 플로리스트의 요청에 그는 이곳에서 묘한 미소를 지었다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08947', '이차전', '관광지', 37.539166, 127.12794, '서울특별시 강동구 천호대로159길 35', '최강수(고경표)와 이단아(채수빈)가 일하는 곳이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08948', '21세기문구', '관광지', 37.582211, 126.90549, '서울특별시 은평구 증산서길 62', '최강수(고경표)의 엄마 가게이다. 최강수는 11회에서 좋은 친구(나중에 이복형제임을 알게 됨)를 방문하기 위해 이곳에 왔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08949', '서울약령시장', '쇼핑', 37.578341, 127.0368, '서울특별시 동대문구 약령중앙로 10', '15회에서 자신의 진료소에 약초를 사러 갔다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08950', '춘원당 한방박물관', '관광지', 37.571731, 126.99033, '서울특별시 종로구 돈화문로9길 27', '윤필주(윤계상)의 진료소로 등장한다. 1,2,9,13화에서 볼 수 있다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08951', '김종영미술관', '관광지', 37.612925, 126.97757, '서울특별시 종로구 평창32길 30', '13화에서 윤필주(윤계상)와 전 걸그룹 국보녀(내셔널 트레져걸스)의 한미나(배슬기)를 만나러 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08952', '뀌숑', '카페', 37.384927, 127.111419, '경기도 성남시 분당구 판교역로14번길 16', '1화에서 프러포즈가 실패한 뒤 이 카페를 지나기 직전 형사 하완승(권상우)과 유설옥(최강희)이 보니스팍스 백현동점을 지나게 된다. 그 동안 둘 다 손을 잡고 싶지만 이루어지지 않는다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08953', '찜닭마루', '음식점', 37.279133, 127.15334, '경기도 용인시 기흥구 평촌2로1번길 35-1', '김경미(김현숙)의 식당으로 등장한다. 그녀의 가장 친한 친구인 유설옥(최강희)은 이곳에서 아르바이트를 한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08954', '안도르', '관광지', 36.331374, 127.42335, '대전광역시 중구 선화로 148', '8회에서 유괴범이 유설옥(최강희)의 시어머니를 데려온 곳이다. 그녀는 낭만적인 데이트 중이라고 생각한다. 이를 알게 된 설옥은 유괴범에게 기절당하고 결국 자신의 뒤를 쫓던 하완승(권상우)에게 구출된다', '대전');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08955', '선재도', '관광지', 37.229269, 126.53284, '인천광역시 옹진군 영흥면 선재리', '2회에서 형사 하완승(권상우)과 유설옥(최강희)은 이 장소에서 어린이 연극 공연 중 발생하는 잠재적 방화 사건을 저지하려고 시도한다. 하지만 이곳에서 방화범을 잡겠다는 제보를 받은 계성우 팀장(오민석)과 육승화 형사(홍기준)를 만난다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08956', '쿠바데히론', '관광지', 37.651184, 126.66108, '경기도 김포시 김포한강4로212번길 51', '11회에서 구세라(임진아/애프터스쿨 나나)와 서공명(박성훈)은 각각 503번지 동네 대표 집을 방문한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08957', '동구 어린이 교통공원', '관광지', 37.478016, 126.66968, '인천광역시 동구 방축로177번길 31', '4화에서 구세라(나나)는 어린이 운전사들이 길을 건너는 것을 바라보며 서공명(박성훈)에게 엉뚱한 말을 한다. 여기서 그녀는 마원구가 적자로, 직원이나 시의원에게 급여를 지급하지 못할 수도 있음을 알게 된다. 에피소드의 에필로그 후반부에서 공명은 세라에게 의회에서의 결정이 얼마나 큰 일인지 설명하려고 하며, 공명은 취임 후 자신의 유일한 목표는 많은 돈을 버는 것이었음을 상기시킨다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08958', '미술관 구월점', '관광지', 37.446273, 126.70238, '인천광역시 동구 성말로13번길 20', '구세라(임진아는 서공명을 만난다. 28회에서 박정래 할머니(강애심)를 생각한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08959', '인형문구완구', '관광지', 37.456049, 126.67905, '인천광역시 미추홀구 경인로354번길 54', '2화(전체 1화)에서 구세라(애프터스쿨 임진아/나나)는 이 문구점 바로 앞 아케이드 게임에서 김자룡(최고)을 무자비하게 이긴다. 져주지 않는 어른을 소년이 한탄하자 세라는 아이들도 사회의 어려움을 맛봐야 한다고 반박한다. 9화(전체 5화)에서 세라가 학대를 당할 가능성이 있는 아동을 보호하기 위한 비밀 이웃 요원 육성에 관한 조례 법안에 대해 이야기하는 장면이 다시 등장한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08960', '서곶근린공원', '관광지', 37.54648, 126.68025, '인천광역시 서구 심곡로 151', '서강준이 김고은에게 콩쿨을 보러오라고 말한 길', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08961', '제물량로', '관광지', 37.470995, 126.62273, '인천광역시 중구 제물량로 196', '4화 회상씬에서 송소은(이유영)은 가해자가 판결을 받은 후 언니 송지연(곽선영)과 함께 이곳에 왔고, 언니는 그녀에게 가장 끔찍한 것은 심판이 끝난 후 그가 웃는 모습을 보는 것이 가장 끔찍했다고 말한다.', '인천');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08962', '대둔산 금강구름다리', '관광지', 36.123133, 127.32339, '전라북도 완주군 운주면 산북리', '박찬욱감독 및 영화인들의 단골 레스토랑', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08963', '헤이리 식물감각', '음식점', 37.787514, 126.698718, '경기도 파주시 탄현면 헤이리마을길 48-8', '수요미식회에도 나온 박찬욱 단골 라멘집', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08964', '멘야하나비 잠실', '음식점', 37.510977, 127.107764, '서울특별시 송파구 백제고분로45길 38', '박찬욱감독이 단골인 일본 가마메시 전문 식당', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08965', '도도야', '관광지', 37.579961, 127.004303, '서울특별시 종로구 동숭길 39', '친절한 금자씨와 무한도전등 각종 촬영지', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08966', '손가맥집', '카페', 35.835185, 129.212281, '경상북도 경주시 첨성로 81번길 22-15', '교련복 입고 와서 피자를 먹었던 카페 앤 펍', '경주');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08967', '구산오토캠핑장', '관광지', 36.752274, 129.466542, '경상북도 울진군 기성면 기성로 108', '울진에 위치한 캠핑 클럽의 3번째 정박지인 캠핑장', '경북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08968', '용담섬바위 오토캠핑장', '관광지', 35.952922, 127.528627, '전라북도 진안군 안천면 안용로 832-23', '진안에 위치한 캠핑 클럽의 1번째 정박지인 캠핑장', '전북');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08969', '조커피', '카페', 37.753117, 127.03741, '경기도 의정부시 의정로198번길 81', '박석(박호산)이 운영하는 ''2세대 다방''으로 등장. 2화에서 강고비(옹성우)가 바리스타 일을 시작하는 곳이기도 하다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI08970', '의정부 젊음의거리', '카페', 37.740861, 127.04935, '경기도 의정부시 행복로 28', '3회에서 이후 ''투커피''의 고객이 된 성민(이규형)은 할리스커피와 에스마켓 의정부점을 지나 이 거리를 지나며 설명한다.', '경기');
