INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09053', '한채당', '음식점', 37.570818, 127.20158, '경기도 하남시 미사동로 38', '15회에서 오윤희(유진)가 이 식당에서 천서진(김소연)을 만나자고 한다. 21화에서는 주단태가 같은 방에서 한 의원을 만난다.', '경기');
