INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09060', '군자대한곱창 신촌점', '음식점', 37.5570753, 126.9336242, '서울특별시 서대문구 연세로5나길 8 1~2층', '12회에서 유연주(한선화)는 조승준(도상우)과 이 식당에서 저녁을 먹던 중 전화를 받고 서둘러 떠난다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09061', '이촌부대찌개', '음식점', 37.5207462, 126.9654478, '서울특별시 용산구 이촌로54길 13', '9, 10회 뒷골목 유연주(한선화)가 이 곳에서 최대현(지창욱)을 만나 이별을 고한다. 그렇게 한 뒤 그녀는 조승준(도상우)의 차에 태워진다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09062', '블루스퀘어', '관광지', 37.540833, 127.002233, '서울특별시 용산구 이태원로 294', '최대현(지창욱)과 부모님이 사는 집, 8화에서 유연주(한선화)가 깜짝 방문하는 장면을 볼 수 있다.', '서울');
