INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09064', '스타필드 하남', '쇼핑', 37.545529, 127.22356, '경기도 하남시 미사대로 750', '1회에서 심청(지안나 준)과 허준재(이민호)가 방문하는 스페인 쇼핑몰로 등장한다.', '경기');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09065', '핸드픽트호텔', '숙박', 37.5012, 126.93353, '서울특별시 동작구 상도로 120', '14회에서 심청(지안나 준)과 허준재(이민호)가 데이트를 하는 곳이다. 또한 준재는 정에게 계속해서 행복하게 살겠다고 약속하고 그가 갑자기 죽으면 새로운 파트너를 찾을 것을 부탁하기 때문에 둘의 데이트가 돌연 끝나는 곳이기도 하다. 그녀는 평생 단 한 사람만을 사랑할 수 있기 때문에 인어로서 할 수 없는 일이다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09066', '재단법인 아름지기', '관광지', 37.577581, 126.9739, '서울특별시 종로구 효자로 17', '6화에서는 박리환(이동욱)과 김행아(정려원)가 데이트를 하며 이 거리를 산책하는 모습이 그려졌다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09067', '소파로', '관광지', 37.555114, 126.98129, '서울특별시 중구 소파로 41', '7회에서는 윤재희(전도연)가 최상현(김주혁)에게 이 공원에서 만나자고 제안했다. 그녀는 처음에는 (야근을 해야 한다는 핑계를 대며) 거절하지만 결국 포기하고 나타납니다.', '서울');
