INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09117', '양재역(서초구청)', '관광지', 37.484457, 127.03412, '서울특별시 서초구 남부순환로 2585', '11회에서 표인숙(안은진)과 민우천(김경남)은 이 역(''고산역''으로 나타남)의 10번 출구로 나오며, 그들과 교류를 원하는 다양한 사람들에게 즉시 다가가는데, 그런 다음 그들은 12번 출구를 통과하여 차에 치인 소년을 간신히 구한다.', '서울');
