INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09291', '마들역', '관광지', 37.665272, 127.05762, '서울특별시 노원구 동일로 1530-1', '1화에서 지하철에서 장만월(이지은)을 만난 후 놀란 구찬성(여진구)이 지하철역에 내린다.', '서울');
