INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09296', '이음더플레이스', '숙박', 37.581996, 126.98238, '서울특별시 종로구 북촌로11나길 21', '이 한옥은 5, 8, 12회에서 볼 수 있듯이 호텔 델루나에서 산체스의 집으로 등장한다. 여기에 구찬성(여진구)도 살고, 8화에서는 이미라(박유나)도 이사를 온다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09297', '삼청로5길', '관광지', 37.583011, 126.98027, '서울특별시 종로구 삼청로5길 30', '1회에서 구찬성(여진구)은 여자 귀신을 탈출하기 위해 이 거리를 질주하고 버려진 물건들을 덮는 모습을 그린다. 장만월(아이유/이지은)은 건물의 벽 너머로 숨어있는 찬성을 내려다보더니 조약돌을 던지고 다시 뛰게 하여 그를 놀라게 한다.', '서울');
