INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09319', '조계종학림사', '관광지', 37.682123, 127.07735, '서울특별시 노원구 덕릉로129가길 241', '6회에서 한재현(진영)은 수배 명단에 이름을 올린 뒤 이 절에 피난처를 찾아온다. 그의 친구 주영우(병훈)와 성화진(한지원)이 그를 찾아온다. 떠나기 전 화진은 전화카드를 건네주며 윤지수(전소니)에게 전화하라고 한다.', '서울');
INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09320', '성미약수터 정류장', '관광지', 37.562467, 126.91415, '서울특별시 마포구 성산1동 성미약수터 정류장', '화양연화 8회에서 윤지수(이보영)는 한재현(유지태)이 지나가는 줄도 모르고 버스정류장 인근 횡단보도에 하차해 멍하니 서 있다.', '서울');
