INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09322', '밤노을', '카페', 37.524786, 126.96021, '서울특별시 용산구 이촌로29길 25-1', '최종회 16회에서 윤지수(이보영 분)가 이세훈(김영훈 분)을 간접적으로 공격한 혐의로 기소된 후 이 카페에서 만난다.', '서울');
