INSERT INTO places (place_id, name_ko, category, lat, lon, address, description, region) VALUES ('POI09324', '엔틱스토리', '관광지', 37.532093, 126.99495, '서울특별시 용산구 보광로 104', '2회에서 귀신들린 꼭두각시가 가게에 앉아 있었다. 여기에서 귀신은 젊은 여자를 소유하고 나중에 손오공(이승기)은 두 번째 꼭두각시 귀신의 행방을 찾기 위해 이 가게를 방문한다.', '서울');
